-- =============================================================================
-- Schema-Squash Baseline v2 (public-only, supabase db reset compatible)
-- Assembled from a READ-ONLY `--schema public` production dump. Contains NO
-- platform schema DDL (storage/auth/graphql_public/realtime), NO ownership of
-- platform objects, NO production data, NO secrets. Applied by the `postgres`
-- migration role under `supabase db reset`.
--
-- Layout:
--   [1] private schema + private.dispatch_notification_push()  (referenced by a
--       public trigger; not emitted by a public-only dump)
--   [2] full public schema (verbatim dump: extensions refs, types, tables,
--       functions, views, RLS, policies, grants, triggers)
--   [3] storage.objects RLS policies (27, verbatim from prod; a public-only
--       dump omits them — they are application-owned config on a platform table)
--   [4] storage buckets + cron jobs + realtime publication membership (config
--       rows; see 080_storage_cron.sql source of truth)
-- =============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- [1] private schema (prepended; public trigger notifications_dispatch_push
--     references private.dispatch_notification_push())
-- ─────────────────────────────────────────────────────────────────────────────
create schema if not exists private;
create or replace function private.dispatch_notification_push()
 returns trigger language plpgsql security definer set search_path to 'public','extensions'
as $function$
declare v_project_url text; v_internal_secret text;
begin
  select decrypted_secret into v_project_url from vault.decrypted_secrets where name='push_project_url' order by created_at desc limit 1;
  select decrypted_secret into v_internal_secret from vault.decrypted_secrets where name='push_internal_secret' order by created_at desc limit 1;
  if nullif(trim(v_project_url),'') is null or nullif(v_internal_secret,'') is null then
    raise warning 'Push dispatch skipped: Vault secrets are not configured'; return new;
  end if;
  perform net.http_post(url:=rtrim(v_project_url,'/')||'/functions/v1/send-push-notification',
    headers:=jsonb_build_object('Content-Type','application/json','x-push-secret',v_internal_secret),
    body:=jsonb_build_object('notification_id',new.id), timeout_milliseconds:=5000);
  return new;
exception when others then raise warning 'Push dispatch failed for notification %', new.id; return new;
end; $function$;

-- ─────────────────────────────────────────────────────────────────────────────
-- [2] full public schema (verbatim production dump, --schema public)
-- ─────────────────────────────────────────────────────────────────────────────



