CREATE OR REPLACE FUNCTION "public"."_activate_approved_host"("p_user_id" "uuid", "p_approver" "uuid", "p_application_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.approved_hosts (
    user_id, status, approved_by, application_id, approved_at, updated_at
  )
  values (
    p_user_id, 'active', p_approver, p_application_id, now(), now()
  )
  on conflict (user_id) do update
    set status = 'active',
        approved_by = excluded.approved_by,
        application_id = excluded.application_id,
        approved_at = excluded.approved_at,
        updated_at = now();
$$;


