CREATE OR REPLACE FUNCTION "public"."_agency_grant_membership"("p_application_id" "uuid", "p_approver" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_app public.agency_applications;
begin
  select * into v_app from public.agency_applications where id = p_application_id;
  if v_app.id is null then raise exception 'application_not_found'; end if;
  if v_app.agency_id is null then return; end if;
  update public.agency_hosts set status = 'transferred', left_at = now()
   where host_user_id = v_app.user_id and status = 'active' and agency_id <> v_app.agency_id;
  if not exists (select 1 from public.agency_hosts
      where host_user_id = v_app.user_id and status = 'active' and agency_id = v_app.agency_id) then
    insert into public.agency_hosts (agency_id, host_user_id, status, approved_by, application_id)
    values (v_app.agency_id, v_app.user_id, 'active', p_approver, v_app.id);
  end if;
  if not exists (select 1 from public.agency_members where agency_id = v_app.agency_id and user_id = v_app.user_id) then
    insert into public.agency_members (agency_id, user_id, role, status, joined_at)
    values (v_app.agency_id, v_app.user_id, 'host', 'active', now());
  else
    update public.agency_members set status = 'active', updated_at = now()
     where agency_id = v_app.agency_id and user_id = v_app.user_id;
  end if;
  perform public._agency_audit(p_approver, 'host_assigned', v_app.agency_id, v_app.user_id, v_app.id, '{}'::jsonb);
end; $$;


