CREATE OR REPLACE FUNCTION "public"."_crash_rocket_multiplier_at"("p_fly_started_at" timestamp with time zone, "p_at" timestamp with time zone) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select least(
    1000.00,
    greatest(
      1.00,
      floor(
        exp(
          least(
            ln(1000.00),
            0.09 * greatest(
              0,
              extract(epoch from p_at - p_fly_started_at)
            )
          )
        ) * 100
      ) / 100
    )
  )::numeric(12,2);
$$;


ALTER FUNCTION "public"."_crash_rocket_multiplier_at"("p_fly_started_at" timestamp with time zone, "p_at" timestamp with time zone) OWNER TO "postgres";


