CREATE OR REPLACE FUNCTION "public"."_create_crash_rocket_round"("p_room_id" "uuid") RETURNS "public"."crash_rocket_rounds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_round public.crash_rocket_rounds;
  v_seed text := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash text := encode(extensions.digest(v_seed, 'sha256'), 'hex');
  v_roll bigint;
  v_u numeric;
  v_target numeric;
begin
  v_roll := ('x' || substr(v_hash, 1, 13))::bit(52)::bigint;
  v_u := v_roll::numeric / 4503599627370496::numeric;
  v_target := least(1000.00, greatest(1.00,
    floor((0.97 / greatest(0.000001, 1 - v_u)) * 100) / 100));

  insert into public.crash_rocket_rounds (
    room_id, status, starts_at, betting_closes_at, crash_seed_hash
  ) values (
    p_room_id, 'betting_open', now(), now() + interval '8 seconds', v_hash
  ) returning * into v_round;

  insert into public.crash_rocket_round_secrets (
    round_id, crash_seed_secret, target_multiplier
  ) values (v_round.id, v_seed, v_target);
  insert into public.crash_rocket_round_events(round_id,event_type,payload)
  values (v_round.id,'round_opened',jsonb_build_object(
    'round_number',v_round.round_number,'betting_closes_at',v_round.betting_closes_at
  ));
  return v_round;
end;
$$;


ALTER FUNCTION "public"."_create_crash_rocket_round"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_derive_crash_multiplier"("p_seed" "text", "p_round_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hash  bytea;
  v_int   bigint;
  v_rand  float8;
  v_crash numeric(10,2);
begin
  v_hash := digest(p_seed || p_round_id::text, 'sha256');
  -- Treat first 8 bytes as an unsigned 64-bit int (positive range only)
  v_int  := abs(('x' || encode(substring(v_hash from 1 for 8), 'hex'))::bit(64)::bigint);
  v_rand := v_int::float8 / 9223372036854775807::float8; -- 0..1

  if v_rand < 0.01 then
    v_crash := 1.00;
  else
    v_crash := round((0.99 / (1.0 - v_rand))::numeric, 2);
    v_crash := greatest(1.00::numeric(10,2), least(1000.00::numeric(10,2), v_crash));
  end if;
  return v_crash;
end;
$$;


ALTER FUNCTION "public"."_derive_crash_multiplier"("p_seed" "text", "p_round_id" "uuid") OWNER TO "postgres";


