    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "room_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "duration_seconds" integer NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "finished_at" timestamp with time zone,
    "team_a_score" bigint DEFAULT 0 NOT NULL,
    "team_b_score" bigint DEFAULT 0 NOT NULL,
    "team_a_gift_count" integer DEFAULT 0 NOT NULL,
    "team_b_gift_count" integer DEFAULT 0 NOT NULL,
    "winner_team" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "room_team_pk_sessions_duration_check" CHECK (("duration_seconds" = ANY (ARRAY[300, 600, 1800]))),
    CONSTRAINT "room_team_pk_sessions_gift_count_a_check" CHECK (("team_a_gift_count" >= 0)),
    CONSTRAINT "room_team_pk_sessions_gift_count_b_check" CHECK (("team_b_gift_count" >= 0)),
    CONSTRAINT "room_team_pk_sessions_score_a_check" CHECK (("team_a_score" >= 0)),
    CONSTRAINT "room_team_pk_sessions_score_b_check" CHECK (("team_b_score" >= 0)),
    CONSTRAINT "room_team_pk_sessions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'finished'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "room_team_pk_sessions_winner_check" CHECK ((("winner_team" IS NULL) OR ("winner_team" = ANY (ARRAY['a'::"text", 'b'::"text", 'draw'::"text"]))))
);

ALTER TABLE ONLY "public"."room_team_pk_sessions" REPLICA IDENTITY FULL;


ALTER TABLE "public"."room_team_pk_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_finish_team_pk_internal"("p_session_id" "uuid") RETURNS "public"."room_team_pk_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.room_team_pk_sessions;
  v_winner  text;
begin
  select * into v_session
  from public.room_team_pk_sessions
  where id = p_session_id
  for update;

  if v_session is null then
    raise exception 'pk_session_not_found';
  end if;

  -- Already resolved — return current state without touching it.
  if v_session.status in ('finished', 'cancelled') then
    return v_session;
  end if;

  -- Determine winner.
  v_winner := case
    when v_session.team_a_score > v_session.team_b_score then 'a'
    when v_session.team_b_score > v_session.team_a_score then 'b'
    else 'draw'
  end;

  update public.room_team_pk_sessions
  set status      = 'finished',
      winner_team = v_winner,
      finished_at = now(),
      updated_at  = now()
  where id = p_session_id
  returning * into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "public"."_finish_team_pk_internal"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_gen_agency_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare v_code text;
begin
  loop
    v_code := upper(substr(md5(gen_random_uuid()::text), 1, 6));
    exit when not exists (select 1 from public.agencies where agency_code = v_code);
  end loop;
  return v_code;
end; $$;


