CREATE OR REPLACE FUNCTION "public"."add_charm_xp"("p_user_id" "uuid", "p_xp" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_new_xp    bigint;
  v_new_level integer;
  v_new_tier  integer;
begin
  if p_user_id is null or coalesce(p_xp, 0) <= 0 then return; end if;

  insert into public.user_charm (user_id) values (p_user_id)
  on conflict (user_id) do nothing;

  update public.user_charm
  set charm_xp   = charm_xp + p_xp,
      last_xp_at = now(),
      updated_at = now()
  where user_id = p_user_id
  returning charm_xp into v_new_xp;

  select level, tier_number
  into   v_new_level, v_new_tier
  from   public.charm_level_rules
  where  required_xp <= v_new_xp and is_active = true
  order  by required_xp desc
  limit  1;

  update public.user_charm
  set charm_level = coalesce(v_new_level, 1),
      tier_number = coalesce(v_new_tier, 1),
      updated_at  = now()
  where user_id = p_user_id;
end;
$$;


ALTER FUNCTION "public"."add_charm_xp"("p_user_id" "uuid", "p_xp" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_room_music_track"("p_room_id" "uuid", "p_title" "text", "p_track_url" "text", "p_artist" "text" DEFAULT NULL::"text", "p_storage_path" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'upload'::"text", "p_duration_seconds" integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result json;
  v_title text := trim(coalesce(p_title, ''));
  v_url text := trim(coalesce(p_track_url, ''));
  v_source text := lower(trim(coalesce(p_source, 'upload')));
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if not public.is_room_manager(p_room_id, v_uid) then
    raise exception 'not_room_manager';
  end if;
  if length(v_title) not between 1 and 200 then
    raise exception 'invalid_track_title';
  end if;
  if v_url !~ '^https?://' or length(v_url) > 2048 then
    raise exception 'invalid_track_url';
  end if;
  if v_source not in ('upload', 'url') then
    raise exception 'invalid_track_source';
  end if;
  if p_duration_seconds is not null
     and p_duration_seconds not between 1 and 86400 then
    raise exception 'invalid_track_duration';
  end if;
  if v_source = 'upload' and (
    p_storage_path is null
    or split_part(p_storage_path, '/', 1) <> v_uid::text
    or split_part(p_storage_path, '/', 2) <> p_room_id::text
  ) then
    raise exception 'invalid_storage_path';
  end if;

  insert into public.room_music_tracks (
    room_id, uploaded_by, title, artist, track_url,
    storage_path, source, duration_seconds
  )
  values (
    p_room_id, v_uid, v_title,
    nullif(trim(coalesce(p_artist, '')), ''),
    v_url, p_storage_path, v_source, p_duration_seconds
  )
  returning to_json(room_music_tracks.*) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."add_room_music_track"("p_room_id" "uuid", "p_title" "text", "p_track_url" "text", "p_artist" "text", "p_storage_path" "text", "p_source" "text", "p_duration_seconds" integer) OWNER TO "postgres";


