    "xp" bigint DEFAULT 0 NOT NULL,
    "total_spent_coins" bigint DEFAULT 0 NOT NULL,
    "total_received_gifts_value" bigint DEFAULT 0 NOT NULL,
    "total_room_minutes" bigint DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "total_gifts_sent" bigint DEFAULT 0 NOT NULL,
    "total_gifts_received" bigint DEFAULT 0 NOT NULL,
    "last_xp_at" timestamp with time zone,
    CONSTRAINT "user_levels_level_check" CHECK (("level" >= 1)),
    CONSTRAINT "user_levels_total_gifts_received_check" CHECK (("total_gifts_received" >= 0)),
    CONSTRAINT "user_levels_total_gifts_sent_check" CHECK (("total_gifts_sent" >= 0)),
    CONSTRAINT "user_levels_total_received_gifts_value_check" CHECK (("total_received_gifts_value" >= 0)),
    CONSTRAINT "user_levels_total_room_minutes_check" CHECK (("total_room_minutes" >= 0)),
    CONSTRAINT "user_levels_total_spent_coins_check" CHECK (("total_spent_coins" >= 0)),
    CONSTRAINT "user_levels_xp_check" CHECK (("xp" >= 0))
);


ALTER TABLE "public"."user_levels" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_xp"("p_user_id" "uuid", "p_xp" bigint, "p_source" "text" DEFAULT NULL::"text") RETURNS "public"."user_levels"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_level     public.user_levels;
  v_new_level integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_user_id <> auth.uid() AND NOT public.profile_hub_admin_access() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  INSERT INTO public.user_levels (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.user_levels
  SET
    xp          = xp + GREATEST(COALESCE(p_xp, 0), 0),
    last_xp_at  = now(),
    updated_at  = now()
  WHERE user_id = p_user_id
  RETURNING * INTO v_level;

  SELECT COALESCE(MAX(level), 1)
  INTO   v_new_level
  FROM   public.level_rules
  WHERE  is_active
    AND  required_xp <= v_level.xp;

  UPDATE public.user_levels
  SET
    level      = GREATEST(level, v_new_level),
    updated_at = now()
  WHERE user_id = p_user_id
  RETURNING * INTO v_level;

  RETURN v_level;
END;
$$;


ALTER FUNCTION "public"."add_user_xp"("p_user_id" "uuid", "p_xp" bigint, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_wealth_xp"("p_user_id" "uuid", "p_xp" bigint, "p_source" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_new_xp    bigint;
  v_new_level integer;
  v_new_tier  integer;
begin
  if p_xp <= 0 then return; end if;

  -- Upsert user_wealth row and accumulate XP.
  insert into public.user_wealth (user_id, wealth_xp, last_xp_at, updated_at)
  values (p_user_id, p_xp, now(), now())
  on conflict (user_id) do update
    set wealth_xp   = public.user_wealth.wealth_xp + p_xp,
        last_xp_at  = now(),
        updated_at  = now();

  -- Also increment the split counter based on source.
  if p_source = 'recharge' then
    update public.user_wealth
    set total_recharged_xp = total_recharged_xp + p_xp
    where user_id = p_user_id;
  elsif p_source = 'gift_sent' then
    update public.user_wealth
    set total_spent_gift_xp = total_spent_gift_xp + p_xp
    where user_id = p_user_id;
  end if;

  -- Read updated total XP.
  select wealth_xp into v_new_xp
  from public.user_wealth
  where user_id = p_user_id;

  -- Calculate new level from XP table.
  select level, tier_number
  into   v_new_level, v_new_tier
  from   public.wealth_level_rules
  where  required_xp <= v_new_xp
    and  is_active = true
  order  by required_xp desc
  limit  1;

  -- Default to level 1 / tier 1 if somehow no rule matched.
  v_new_level := coalesce(v_new_level, 1);
  v_new_tier  := coalesce(v_new_tier,  1);

  -- Persist the recalculated level and tier.
  update public.user_wealth
  set    wealth_level = v_new_level,
         tier_number  = v_new_tier,
         updated_at   = now()
  where  user_id = p_user_id;
end;
$$;


ALTER FUNCTION "public"."add_wealth_xp"("p_user_id" "uuid", "p_xp" bigint, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_add_user_note"("p_user_id" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.has_admin_access() then
    raise exception 'not_authorized';
  end if;

  insert into public.admin_user_notes (user_id, note, created_by)
  values (p_user_id, trim(p_note), auth.uid())
  returning id into v_id;

  perform public.admin_record_audit(
    'add_user_note',
    'admin_user_notes',
    v_id::text,
    p_user_id,
    '{}'::jsonb
  );

  return v_id;
end;
$$;


