CREATE OR REPLACE FUNCTION "public"."admin_apply_moderation_action"("p_target_user_id" "uuid", "p_action_type" "text", "p_reason" "text", "p_room_id" "uuid" DEFAULT NULL::"uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_event_id" "uuid" DEFAULT NULL::"uuid", "p_report_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
begin
  if v_admin_id is null then raise exception 'not_authenticated'; end if;
  if not public.has_admin_access() then
    raise exception 'permission_denied: admin access required';
  end if;

  -- Apply restriction (warning and dismissed don't add a row)
  if p_action_type in ('chat_mute', 'account_ban', 'gift_block') then
    -- Deactivate existing active restriction of same type first
    update public.admin_user_restrictions
    set    is_active = false, updated_at = now()
    where  user_id = p_target_user_id
      and  restriction_type = p_action_type
      and  is_active = true;

    insert into public.admin_user_restrictions
      (user_id, restriction_type, is_active, reason, expires_at, created_by)
    values
      (p_target_user_id, p_action_type, true, p_reason, p_expires_at, v_admin_id);
  end if;

  -- Mark moderation event reviewed
  if p_event_id is not null then
    update public.moderation_events
    set status = case when p_action_type = 'dismissed' then 'dismissed' else 'reviewed' end,
        action_taken = p_action_type
    where id = p_event_id;
  end if;

  -- Mark report resolved/rejected
  if p_report_id is not null then
    update public.user_reports
    set status      = case when p_action_type = 'dismissed' then 'rejected' else 'resolved' end,
        resolved_by = v_admin_id,
        resolved_at = now(),
        resolution_note = p_action_type || ': ' || p_reason
    where id = p_report_id;
  end if;

  -- Audit log
  insert into public.admin_audit_logs
    (admin_user_id, target_user_id, action, entity_type, metadata)
  values
    (v_admin_id, p_target_user_id, 'moderation_action', 'moderation', jsonb_build_object(
      'action_type', p_action_type,
      'reason',      p_reason,
      'room_id',     p_room_id,
      'expires_at',  p_expires_at,
      'event_id',    p_event_id,
      'report_id',   p_report_id
    ));
end;
$$;


ALTER FUNCTION "public"."admin_apply_moderation_action"("p_target_user_id" "uuid", "p_action_type" "text", "p_reason" "text", "p_room_id" "uuid", "p_expires_at" timestamp with time zone, "p_event_id" "uuid", "p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_payout_request"("p_request_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id  uuid := auth.uid();
  v_request   record;
  v_balance   numeric(12,2);
begin
  if v_admin_id is null or not public.has_finance_access() then
    raise exception 'finance_access_required';
  end if;

  -- Lock the payout request row to prevent concurrent processing.
  select id, user_id, amount_usd, status
  into   v_request
  from   public.payout_requests
  where  id = p_request_id
  for update;

  if not found then
    raise exception 'payout_request_not_found';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'payout_request_not_pending: current status is %', v_request.status;
  end if;

  -- Lock income_accounts and re-check balance server-side.
  select available_balance_usd
  into   v_balance
  from   public.income_accounts
  where  user_id = v_request.user_id
  for update;

  if not found then
    raise exception 'income_account_not_found';
  end if;

  if v_request.amount_usd > v_balance then
    raise exception 'insufficient_balance: requested % but available %',
      v_request.amount_usd, v_balance;
  end if;

  -- Deduct the approved amount from available balance.
  update public.income_accounts
  set    available_balance_usd = available_balance_usd - v_request.amount_usd,
         updated_at             = now()
  where  user_id = v_request.user_id;

  -- Mark payout request approved.
  update public.payout_requests
  set    status      = 'approved',
         admin_note  = coalesce(p_note, admin_note),
         reviewed_at = now(),
         reviewed_by = v_admin_id
  where  id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."admin_approve_payout_request"("p_request_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_approve_withdrawal"("p_request_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request public.withdrawal_requests;
begin
  if v_admin_id is null or not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select * into v_request
  from public.withdrawal_requests
  where id = p_request_id
  for update;

  if v_request is null then raise exception 'request_not_found'; end if;
  if v_request.status != 'pending' then raise exception 'request_not_pending'; end if;

  update public.withdrawal_requests
  set status = 'approved', admin_note = p_admin_note,
      processed_at = now(), processed_by = v_admin_id
  where id = p_request_id;

  -- Credit the agency owner their commission share in diamonds.
  if v_request.agency_owner_user_id is not null
     and v_request.agency_share_diamonds > 0 then
    insert into public.wallets (user_id, diamonds_balance, lifetime_diamonds_earned)
    values (v_request.agency_owner_user_id, v_request.agency_share_diamonds, v_request.agency_share_diamonds)
    on conflict (user_id) do update
      set diamonds_balance = public.wallets.diamonds_balance + v_request.agency_share_diamonds,
          lifetime_diamonds_earned = public.wallets.lifetime_diamonds_earned + v_request.agency_share_diamonds,
          updated_at = now();

    insert into public.wallet_transactions (
      user_id, type, direction, coins_delta, diamonds_delta, agency_id, note
    )
    values (
      v_request.agency_owner_user_id, 'agency_commission', 'credit',
      0, v_request.agency_share_diamonds, v_request.agency_id,
      'Agency commission share of host withdrawal'
    );
  end if;

  perform public.admin_record_audit(
    'withdrawal_approved', 'withdrawal_requests', p_request_id::text, v_request.user_id,
    jsonb_build_object(
      'diamonds', v_request.diamonds,
      'host_share_usd', v_request.host_share_usd,
      'agency_share_usd', v_request.agency_share_usd,
      'platform_share_usd', v_request.platform_share_usd));

  return true;
end;
$$;


ALTER FUNCTION "public"."admin_approve_withdrawal"("p_request_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_archive_room"("p_room_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
begin
  -- Any recognised admin who has room-management rights can archive.
  if not (
    public.has_admin_access()
    or public.has_room_admin_access()
    or public.has_app_role('o_super_admin')
    or public.has_app_role('p_super_admin')
    or public.has_app_role('support_admin')
  ) then
    raise exception 'not_authorized';
  end if;

  update public.rooms
  set
    archived_at    = v_now,
    archived_by    = auth.uid(),
    archive_reason = nullif(trim(coalesce(p_reason, '')), ''),
    -- Archiving also closes the room so no one can join.
    is_closed      = true,
    closed_at      = coalesce(closed_at, v_now),
    closed_reason  = coalesce(closed_reason, 'archived'),
    updated_at     = v_now
  where id = p_room_id;

  if not found then
    raise exception 'room_not_found';
  end if;

  perform public.admin_record_audit(
    'archive_room'::text,
    'rooms'::text,
    p_room_id::text,
    auth.uid()::uuid,
    jsonb_build_object('reason', p_reason)::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."admin_archive_room"("p_room_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assign_host_to_agency"("p_agency_id" "uuid", "p_host_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_admin uuid := auth.uid(); v_agency public.agencies;
begin
  if v_admin is null or not public.profile_hub_admin_access() then raise exception 'not_authorized'; end if;
  select * into v_agency from public.agencies where id = p_agency_id and status = 'active';
  if v_agency.id is null then raise exception 'agency_not_found_or_inactive'; end if;
  if v_agency.owner_user_id = p_host_user_id then raise exception 'cannot_assign_owner_as_host'; end if;
  update public.agency_hosts set status = 'transferred', left_at = now()
   where host_user_id = p_host_user_id and status = 'active' and agency_id <> p_agency_id;
  if not exists (select 1 from public.agency_hosts where host_user_id = p_host_user_id and status = 'active' and agency_id = p_agency_id) then
    insert into public.agency_hosts (agency_id, host_user_id, status, approved_by) values (p_agency_id, p_host_user_id, 'active', v_admin);
  end if;
  if not exists (select 1 from public.agency_members where agency_id = p_agency_id and user_id = p_host_user_id) then
    insert into public.agency_members (agency_id, user_id, role, status, joined_at) values (p_agency_id, p_host_user_id, 'host', 'active', now());
  else
    update public.agency_members set status = 'active', updated_at = now() where agency_id = p_agency_id and user_id = p_host_user_id;
  end if;
  perform public._agency_audit(v_admin, 'host_assigned', p_agency_id, p_host_user_id, null, jsonb_build_object('by','admin'));
  return true;
end; $$;


ALTER FUNCTION "public"."admin_assign_host_to_agency"("p_agency_id" "uuid", "p_host_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assign_user_role"("p_user_id" "uuid", "p_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_role text := public.get_admin_role(auth.uid());
BEGIN
  -- Only o_super_admin can assign roles
  IF v_actor_role IS DISTINCT FROM 'o_super_admin' THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  -- Cannot assign o_super_admin (there can be only one owner)
  IF p_role = 'o_super_admin' THEN
    RAISE EXCEPTION 'cannot_assign_o_super_admin';
  END IF;

  -- Validate role
  IF p_role NOT IN ('p_super_admin', 'super_admin', 'admin') THEN
    RAISE EXCEPTION 'invalid_role';
  END IF;

  -- Deactivate any existing record first (enforce one active per user)
  UPDATE public.admin_users
  SET is_active = false, updated_at = now()
  WHERE user_id = p_user_id AND is_active = true;

  -- Insert new record
  INSERT INTO public.admin_users (user_id, role, is_active, created_by)
  VALUES (p_user_id, p_role, true, auth.uid());

  -- Audit
  PERFORM public.admin_record_audit(
    'assign_admin_role',
    'user',
    p_user_id::text,
    NULL,
    jsonb_build_object('role', p_role)
  );
END;
$$;


ALTER FUNCTION "public"."admin_assign_user_role"("p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bd_report"("p_from" timestamp with time zone DEFAULT "date_trunc"('day'::"text", "now"()), "p_to" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("agency_id" "uuid", "agency_name" "text", "agency_code" "text", "agent_id" "uuid", "agent_name" "text", "agent_code" "text", "approved_count" bigint, "coins_charged" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    ra.id,
    ra.name,
    ra.code,
    rag.id,
    rag.name,
    rag.code,
    count(rr.id),
    coalesce(sum(rr.requested_coins), 0)::bigint
  from public.recharge_requests rr
  left join public.recharge_agencies ra on ra.id = rr.agency_id
  left join public.recharge_agents rag on rag.id = rr.agent_id
  where public.has_admin_access()
    and rr.status = 'approved'
    and rr.approved_at >= p_from
    and rr.approved_at < p_to
  group by ra.id, ra.name, ra.code, rag.id, rag.name, rag.code
  order by coalesce(sum(rr.requested_coins), 0) desc;
$$;


ALTER FUNCTION "public"."admin_bd_report"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_charisma_cancel_challenge"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id    uuid := auth.uid();
  v_challenge  charisma_challenges;
  v_has_admin  boolean;
  v_is_creator boolean;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.app_user_roles
    WHERE user_id = v_user_id AND role IN ('super_admin', 'admin')
  ) INTO v_has_admin;

  SELECT EXISTS (
    SELECT 1 FROM charisma_challenges
    WHERE id = p_challenge_id AND created_by = v_user_id
  ) INTO v_is_creator;

  IF NOT v_has_admin AND NOT v_is_creator THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  SELECT * INTO v_challenge FROM charisma_challenges
  WHERE id = p_challenge_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'challenge_not_found'; END IF;
  IF v_challenge.status IN ('crowned', 'cancelled') THEN
    RAISE EXCEPTION 'challenge_already_finalized: %', v_challenge.status;
  END IF;

  UPDATE charisma_challenges
  SET status = 'cancelled', updated_at = now()
  WHERE id = p_challenge_id;

  INSERT INTO charisma_admin_audit_logs (admin_id, challenge_id, action)
  VALUES (v_user_id, p_challenge_id, 'cancel_challenge');

  RETURN jsonb_build_object('challenge_id', p_challenge_id, 'status', 'cancelled');
END;
$$;


ALTER FUNCTION "public"."admin_charisma_cancel_challenge"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_charisma_create_challenge"("p_title" "text", "p_title_ar" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'official'::"text", "p_agency_id" "uuid" DEFAULT NULL::"uuid", "p_starts_at" timestamp with time zone DEFAULT "now"(), "p_ends_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval), "p_reward_coins" integer DEFAULT 100000, "p_reward_frame_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_is_admin  boolean;
  v_challenge charisma_challenges;
  v_status    text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.app_user_roles
    WHERE user_id = v_user_id AND role IN ('super_admin', 'admin')
  ) INTO v_is_admin;

  IF p_scope = 'official' AND NOT v_is_admin THEN
    RAISE EXCEPTION 'insufficient_permissions: official challenges require admin role';
  END IF;
  IF p_scope NOT IN ('agency', 'official') THEN
    RAISE EXCEPTION 'invalid_scope: %', p_scope;
  END IF;
  IF p_scope = 'agency' AND p_agency_id IS NULL THEN
    RAISE EXCEPTION 'agency_id_required_for_agency_scope';
  END IF;
  IF p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'ends_at_must_be_after_starts_at';
  END IF;

  v_status := CASE
    WHEN p_starts_at <= now() AND p_ends_at > now() THEN 'active'
    WHEN p_starts_at > now()                         THEN 'scheduled'
    ELSE 'ended'
  END;

  INSERT INTO charisma_challenges (
    title, title_ar, scope, agency_id, created_by,
    starts_at, ends_at, reward_coins, reward_frame_id, status
  ) VALUES (
    p_title, p_title_ar, p_scope, p_agency_id, v_user_id,
    p_starts_at, p_ends_at, p_reward_coins, p_reward_frame_id, v_status
  )
  RETURNING * INTO v_challenge;

  INSERT INTO charisma_admin_audit_logs (admin_id, challenge_id, action, new_value)
  VALUES (v_user_id, v_challenge.id, 'create_challenge',
          jsonb_build_object('title', p_title, 'scope', p_scope, 'status', v_status));

  RETURN jsonb_build_object(
    'id',           v_challenge.id,
    'title',        v_challenge.title,
    'scope',        v_challenge.scope,
    'status',       v_challenge.status,
    'starts_at',    v_challenge.starts_at,
    'ends_at',      v_challenge.ends_at,
    'reward_coins', v_challenge.reward_coins
  );
END;
$$;


ALTER FUNCTION "public"."admin_charisma_create_challenge"("p_title" "text", "p_title_ar" "text", "p_scope" "text", "p_agency_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_reward_coins" integer, "p_reward_frame_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_charisma_crown_winner"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_challenge charisma_challenges;
  v_winner    charisma_entries;
  v_has_admin boolean;
  v_is_creator boolean;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.app_user_roles
    WHERE user_id = v_user_id AND role IN ('super_admin', 'admin')
  ) INTO v_has_admin;

  SELECT EXISTS (
    SELECT 1 FROM charisma_challenges
    WHERE id = p_challenge_id AND created_by = v_user_id
  ) INTO v_is_creator;

  IF NOT v_has_admin AND NOT v_is_creator THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  SELECT * INTO v_challenge
  FROM charisma_challenges
  WHERE id = p_challenge_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'challenge_not_found'; END IF;
  IF v_challenge.status NOT IN ('active', 'ended') THEN
    RAISE EXCEPTION 'challenge_cannot_be_crowned: status is %', v_challenge.status;
  END IF;

  -- Top participant by votes, earliest join breaks ties
  SELECT * INTO v_winner
  FROM charisma_entries
  WHERE challenge_id = p_challenge_id AND status != 'disqualified'
  ORDER BY vote_count DESC, joined_at ASC
  LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_participants'; END IF;

  -- Mark winner
  UPDATE charisma_entries SET status = 'winner' WHERE id = v_winner.id;

  -- Crown the challenge
  UPDATE charisma_challenges
  SET winner_user_id = v_winner.user_id,
      status         = 'crowned',
      crowned_at     = now(),
      updated_at     = now()
  WHERE id = p_challenge_id;

  -- Credit coins — upsert wallet to be safe
  INSERT INTO wallets (user_id, coins_balance)
  VALUES (v_winner.user_id, v_challenge.reward_coins)
  ON CONFLICT (user_id) DO UPDATE
    SET coins_balance = wallets.coins_balance + v_challenge.reward_coins,
        updated_at    = now();

  -- Wallet transaction record
  INSERT INTO wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  VALUES (
    v_winner.user_id, 'charisma_reward', 'credit',
    v_challenge.reward_coins, 0,
    'Charisma Challenge winner – ' || v_challenge.title,
    jsonb_build_object(
      'challenge_id', p_challenge_id,
      'scope',        v_challenge.scope,
      'vote_count',   v_winner.vote_count
    )
  );

  -- Reward record (coins granted; frame remains pending until frame system grants it)
  INSERT INTO charisma_rewards
    (challenge_id, user_id, reward_coins, reward_frame_id,
     reward_status, granted_at, metadata)
  VALUES (
    p_challenge_id, v_winner.user_id,
    v_challenge.reward_coins, v_challenge.reward_frame_id,
    'granted', now(),
    jsonb_build_object(
      'coins_granted', true,
      'frame_status', CASE
        WHEN v_challenge.reward_frame_id IS NOT NULL THEN 'pending'
        ELSE 'none'
      END
    )
  );

  -- Audit
  INSERT INTO charisma_admin_audit_logs (admin_id, challenge_id, action, new_value)
  VALUES (v_user_id, p_challenge_id, 'crown_winner',
          jsonb_build_object(
            'winner_user_id', v_winner.user_id,
            'vote_count',     v_winner.vote_count,
            'reward_coins',   v_challenge.reward_coins
          ));

  RETURN jsonb_build_object(
    'winner_user_id',  v_winner.user_id,
    'vote_count',      v_winner.vote_count,
    'reward_coins',    v_challenge.reward_coins,
    'challenge_status', 'crowned'
  );
END;
$$;


ALTER FUNCTION "public"."admin_charisma_crown_winner"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_charisma_get_challenges"("p_scope" "text" DEFAULT NULL::"text", "p_agency_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result  jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Auto-advance scheduled/ended statuses before reporting
  UPDATE charisma_challenges
  SET status = 'active', updated_at = now()
  WHERE status = 'scheduled' AND starts_at <= now() AND ends_at > now();

  UPDATE charisma_challenges
  SET status = 'ended', updated_at = now()
  WHERE status = 'active' AND ends_at < now();

  SELECT jsonb_agg(
    jsonb_build_object(
      'id',               c.id,
      'title',            c.title,
      'title_ar',         c.title_ar,
      'scope',            c.scope,
      'agency_id',        c.agency_id,
      'created_by',       c.created_by,
      'status',           c.status,
      'starts_at',        c.starts_at,
      'ends_at',          c.ends_at,
      'reward_coins',     c.reward_coins,
      'reward_frame_id',  c.reward_frame_id,
      'winner_user_id',   c.winner_user_id,
      'crowned_at',       c.crowned_at,
      'created_at',       c.created_at,
      'updated_at',       c.updated_at,
      'participant_count', (
        SELECT COUNT(*) FROM charisma_entries e
        WHERE e.challenge_id = c.id AND e.status != 'disqualified'
      )
    ) ORDER BY c.created_at DESC
  ) INTO v_result
  FROM charisma_challenges c
  WHERE c.status != 'cancelled'
    AND (p_scope IS NULL OR c.scope = p_scope)
    AND (p_agency_id IS NULL OR c.agency_id = p_agency_id)
  ;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."admin_charisma_get_challenges"("p_scope" "text", "p_agency_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_check_golden_id_available"("p_public_user_id" "text", "p_exclude_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users
    WHERE user_id = auth.uid() AND is_active = true
  ) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;
  RETURN NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE public_user_id = p_public_user_id
      AND (p_exclude_user_id IS NULL OR id != p_exclude_user_id)
  );
END;
$$;


ALTER FUNCTION "public"."admin_check_golden_id_available"("p_public_user_id" "text", "p_exclude_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_clear_hungry_cat_forced_result"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin uuid := auth.uid();
  v_prev  text;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  select forced_next_result into v_prev
  from public.game_settings
  where game_key = 'hungry_cat';

  update public.game_settings
  set forced_next_result             = null,
      forced_next_result_expires_at  = null,
      forced_next_result_by          = null,
      updated_at                     = now()
  where game_key = 'hungry_cat';

  insert into public.admin_audit_logs
    (admin_user_id, action, entity_type, entity_id, metadata)
  values
    (v_admin, 'hungry_cat_forced_result_cleared', 'game_settings', 'hungry_cat',
     jsonb_build_object('cleared_outcome', v_prev));

  return jsonb_build_object('ok', true, 'cleared', v_prev);
end;
$$;


ALTER FUNCTION "public"."admin_clear_hungry_cat_forced_result"() OWNER TO "postgres";


