CREATE OR REPLACE FUNCTION "public"."admin_close_room"("p_room_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
begin
  if not public.has_room_admin_access() then
    raise exception 'not_authorized';
  end if;

  update public.rooms
  set is_closed = true,
      closed_at = v_now,
      closed_by = auth.uid(),
      closed_reason = nullif(trim(coalesce(p_reason, '')), '')
  where id = p_room_id;

  if not found then
    raise exception 'room_not_found';
  end if;

  update public.room_members
  set is_muted = true,
      seat_number = null,
      left_at = v_now,
      last_seen_at = v_now
  where room_id = p_room_id
    and left_at is null;

  perform public.admin_record_audit(
    'close_room',
    'rooms',
    p_room_id::text,
    null,
    jsonb_build_object('reason', p_reason)
  );
end;
$$;


ALTER FUNCTION "public"."admin_close_room"("p_room_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_recharge_agency"("p_name" "text", "p_code" "text", "p_country" "text" DEFAULT NULL::"text", "p_whatsapp" "text" DEFAULT NULL::"text", "p_commission_rate" numeric DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  insert into public.recharge_agencies (name, code, country, whatsapp, commission_rate)
  values (
    trim(p_name),
    upper(trim(p_code)),
    nullif(trim(coalesce(p_country, '')), ''),
    nullif(trim(coalesce(p_whatsapp, '')), ''),
    coalesce(p_commission_rate, 0)
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_create_recharge_agency"("p_name" "text", "p_code" "text", "p_country" "text", "p_whatsapp" "text", "p_commission_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_create_recharge_agent"("p_agency_code" "text", "p_name" "text", "p_code" "text", "p_whatsapp" "text" DEFAULT NULL::"text", "p_commission_rate" numeric DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_agency_id uuid;
  v_id uuid;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  select id into v_agency_id
  from public.recharge_agencies
  where upper(code) = upper(trim(p_agency_code))
  limit 1;

  if v_agency_id is null then
    raise exception 'agency_not_found';
  end if;

  insert into public.recharge_agents (agency_id, name, code, whatsapp, commission_rate)
  values (
    v_agency_id,
    trim(p_name),
    upper(trim(p_code)),
    nullif(trim(coalesce(p_whatsapp, '')), ''),
    coalesce(p_commission_rate, 0)
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_create_recharge_agent"("p_agency_code" "text", "p_name" "text", "p_code" "text", "p_whatsapp" "text", "p_commission_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dashboard_overview"() RETURNS TABLE("pending_recharge_count" bigint, "approved_recharge_count_today" bigint, "total_coins_charged_today" bigint, "total_gift_coins_spent_today" bigint, "total_diamonds_earned_today" bigint, "total_gift_transactions_today" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    (select count(*) from public.recharge_requests where status = 'pending'),
    (select count(*) from public.recharge_requests where status = 'approved' and approved_at >= date_trunc('day', now())),
    coalesce((select sum(requested_coins)::bigint from public.recharge_requests where status = 'approved' and approved_at >= date_trunc('day', now())), 0),
    coalesce((select abs(sum(coins_delta))::bigint from public.wallet_transactions where type = 'gift_sent' and created_at >= date_trunc('day', now())), 0),
    coalesce((select sum(diamonds_delta)::bigint from public.wallet_transactions where type = 'gift_received' and created_at >= date_trunc('day', now())), 0),
    (select count(*) from public.gift_transactions where created_at >= date_trunc('day', now()))
  where public.has_admin_access();
$$;


ALTER FUNCTION "public"."admin_dashboard_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_promo_banner"("p_banner_id" "uuid", "p_confirm_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slide_key    text;
  v_expected_key text;
BEGIN
  PERFORM public._admin_assert_banners_role();

  SELECT slide_key INTO v_slide_key
  FROM public.promo_banners WHERE id = p_banner_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banner_not_found';
  END IF;

  v_expected_key := 'DELETE BANNER ' || v_slide_key;
  IF p_confirm_key IS DISTINCT FROM v_expected_key THEN
    RAISE EXCEPTION 'confirmation_mismatch';
  END IF;

  DELETE FROM public.promo_banners WHERE id = p_banner_id;
  RETURN jsonb_build_object('success', true, 'slide_key', v_slide_key);
END;
$$;


ALTER FUNCTION "public"."admin_delete_promo_banner"("p_banner_id" "uuid", "p_confirm_key" "text") OWNER TO "postgres";


