CREATE OR REPLACE FUNCTION "public"."admin_fetch_withdrawal_history"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null or not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select coalesce(jsonb_agg(row_to_json(t) order by t.created_at desc), '[]'::jsonb)
  into v_result
  from (
    select
      w.id,
      w.user_id,
      p.public_user_id,
      p.display_name,
      w.diamonds,
      w.gross_usd,
      w.host_share_usd,
      w.agency_share_usd,
      w.platform_share_usd,
      w.method,
      w.account_details,
      w.notes,
      w.status,
      w.created_at
    from public.withdrawal_requests w
    left join public.profiles p on p.id = w.user_id
    where w.status in ('approved', 'rejected')
    order by w.created_at desc
    limit greatest(p_limit, 0)
  ) t;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_fetch_withdrawal_history"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fetch_withdrawal_requests"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  -- Server-side authorization - identical gate to the approve/reject RPCs.
  if auth.uid() is null or not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select coalesce(jsonb_agg(row_to_json(t) order by t.created_at desc), '[]'::jsonb)
  into v_result
  from (
    select
      w.id,
      w.user_id,
      p.public_user_id,
      p.display_name,
      w.diamonds,
      w.gross_usd,
      w.host_share_usd,
      w.agency_share_usd,
      w.platform_share_usd,
      w.method,
      w.account_details,
      w.notes,
      w.status,
      w.created_at
    from public.withdrawal_requests w
    left join public.profiles p on p.id = w.user_id
    where w.status = p_status
    order by w.created_at desc
    limit greatest(p_limit, 0)
  ) t;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_fetch_withdrawal_requests"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finance_report"("p_from" timestamp with time zone DEFAULT "date_trunc"('day'::"text", "now"()), "p_to" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("approved_recharges" bigint, "rejected_recharges" bigint, "pending_recharges" bigint, "coins_charged" bigint, "gift_transactions" bigint, "gift_coins_spent" bigint, "diamonds_earned" bigint, "manual_adjustment_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    (select count(*) from public.recharge_requests where status = 'approved' and approved_at >= p_from and approved_at < p_to),
    (select count(*) from public.recharge_requests where status = 'rejected' and rejected_at >= p_from and rejected_at < p_to),
    (select count(*) from public.recharge_requests where status = 'pending'),
    coalesce((select sum(requested_coins)::bigint from public.recharge_requests where status = 'approved' and approved_at >= p_from and approved_at < p_to), 0),
    (select count(*) from public.gift_transactions where created_at >= p_from and created_at < p_to),
    coalesce((select sum(gift_price_coins)::bigint from public.gift_transactions where created_at >= p_from and created_at < p_to), 0),
    coalesce((select sum(diamonds_delta)::bigint from public.wallet_transactions where type = 'gift_received' and created_at >= p_from and created_at < p_to), 0),
    (select count(*) from public.wallet_transactions where type = 'admin_adjustment' and created_at >= p_from and created_at < p_to)
  where public.has_admin_access();
$$;


ALTER FUNCTION "public"."admin_finance_report"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_find_user_for_grants"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("user_id" "uuid", "username" "text", "display_name" "text", "golden_id" "text", "avatar_url" "text", "vip_level" integer, "vip_until" timestamp with time zone, "is_golden_id" boolean, "golden_id_expires_at" timestamp with time zone, "golden_id_style" "text", "golden_id_frame" "text", "country" "text", "country_code" "text", "country_flag_style" "text", "country_flag_frame" "text", "country_flag_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_query   text    := trim(coalesce(p_query, ''));
  v_limit   int     := greatest(1, least(coalesce(p_limit, 10), 50));
  v_is_uuid boolean;
BEGIN
  IF NOT public.has_admin_access() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF v_query = '' THEN
    RETURN;
  END IF;

  v_is_uuid := v_query ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  RETURN QUERY
  SELECT
    p.id,
    p.username,
    p.display_name,
    p.public_user_id,
    p.avatar_url,
    COALESCE(p.vip_level, 0),
    p.vip_expires_at,
    COALESCE(p.is_golden_id, false),
    p.golden_id_expires_at,
    COALESCE(p.golden_id_style, 'gold'),
    COALESCE(p.golden_id_frame, 'classic'),
    p.country,
    p.country_code,
    COALESCE(p.country_flag_style, 'normal'),
    COALESCE(p.country_flag_frame, 'classic'),
    p.country_flag_expires_at
  FROM public.profiles p
  WHERE
    CASE
      WHEN v_is_uuid THEN
        p.id = v_query::uuid
      WHEN p.public_user_id = v_query THEN
        true
      ELSE
        p.public_user_id ilike '%' || v_query || '%'
        OR p.username     ilike '%' || v_query || '%'
        OR p.display_name ilike '%' || v_query || '%'
        OR p.id::text     ilike '%' || v_query || '%'
    END
  ORDER BY
    (p.public_user_id = v_query) DESC,
    (v_is_uuid AND p.id = v_query::uuid) DESC,
    p.created_at DESC
  LIMIT v_limit;
END;
$_$;


ALTER FUNCTION "public"."admin_find_user_for_grants"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_hungry_cat_audit_log"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "admin_id" "uuid", "action" "text", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  return query
  select
    al.id,
    al.admin_user_id,
    al.action,
    al.metadata,
    al.created_at
  from public.admin_audit_logs al
  where al.entity_type = 'game_settings'
    and al.entity_id   = 'hungry_cat'
    and al.action like 'hungry_cat%'
  order by al.created_at desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."admin_get_hungry_cat_audit_log"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_hungry_cat_game_config"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.game_settings;
begin
  if not public.has_app_role('super_admin') then
