CREATE OR REPLACE FUNCTION "public"."admin_get_moderation_events"("p_limit" integer DEFAULT 100, "p_status" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "user_name" "text", "room_id" "uuid", "source" "text", "violation_type" "text", "severity" integer, "original_text" "text", "matched_rule" "text", "action_taken" "text", "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.has_admin_access() then
    raise exception 'permission_denied: admin access required';
  end if;

  return query
  select
    me.id,
    me.user_id,
    coalesce(p.display_name, p.username, 'Unknown'),
    me.room_id,
    me.source,
    me.violation_type,
    me.severity,
    me.original_text,
    me.matched_rule,
    me.action_taken,
    me.status,
    me.created_at
  from   public.moderation_events me
  left   join public.profiles p on p.id = me.user_id
  where  (p_status is null or me.status = p_status)
  order by me.created_at desc
  limit  p_limit;
end;
$$;


ALTER FUNCTION "public"."admin_get_moderation_events"("p_limit" integer, "p_status" "text") OWNER TO "postgres";


