CREATE OR REPLACE FUNCTION "public"."admin_get_staff"() RETURNS TABLE("id" "uuid", "user_id" "uuid", "role" "text", "display_name" "text", "is_active" boolean, "created_at" timestamp with time zone, "username" "text", "avatar_url" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_o_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  RETURN QUERY
    SELECT
      au.id,
      au.user_id,
      au.role,
      au.display_name,
      au.is_active,
      au.created_at,
      p.username,
      p.avatar_url
    FROM public.admin_users au
    LEFT JOIN public.profiles p ON p.id = au.user_id
    ORDER BY
      CASE au.role
        WHEN 'o_super_admin' THEN 1
        WHEN 'p_super_admin' THEN 2
        WHEN 'super_admin'   THEN 3
        WHEN 'admin'         THEN 4
      END,
      au.created_at;
END;
$$;


ALTER FUNCTION "public"."admin_get_staff"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_grant_vip"("p_user_id" "uuid", "p_vip_level" integer, "p_days" integer DEFAULT 30, "p_title" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_level integer := greatest(0, least(coalesce(p_vip_level, 0), 9));
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('support_admin')) then
    raise exception 'not_authorized';
  end if;

  update public.profiles
  set vip_level = v_level,
      vip_started_at = case when v_level > 0 then now() else null end,
      vip_expires_at = case
        when v_level > 0 then now() + make_interval(days => greatest(coalesce(p_days, 30), 1))
        else null
      end,
      vip_title = nullif(trim(coalesce(p_title, '')), '')
  where id = p_user_id;

  perform public.admin_record_audit(
    'grant_vip',
    'profiles',
    p_user_id::text,
    p_user_id,
    jsonb_build_object('vip_level', v_level, 'days', p_days, 'title', p_title)
  );
end;
$$;


ALTER FUNCTION "public"."admin_grant_vip"("p_user_id" "uuid", "p_vip_level" integer, "p_days" integer, "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_hungry_cat_stats"() RETURNS TABLE("total_spins" bigint, "total_bet" bigint, "total_reward" bigint, "net_platform_coins" bigint, "biggest_win" integer, "spins_today" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  return query select
    count(*)::bigint,
    coalesce(sum(s.bet_amount), 0)::bigint,
    coalesce(sum(s.reward_amount), 0)::bigint,
    coalesce(sum(s.bet_amount) - sum(s.reward_amount), 0)::bigint,
    coalesce(max(s.reward_amount), 0)::integer,
    count(*) filter (where s.created_at >= date_trunc('day', now()))::bigint
  from public.hungry_cat_spins s;
end;
$$;


ALTER FUNCTION "public"."admin_hungry_cat_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_kick_room_member"("p_room_id" "uuid", "p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
begin
  if not public.has_room_admin_access() then
    raise exception 'not_authorized';
  end if;

  update public.room_members
  set is_muted = true,
      seat_number = null,
      left_at = v_now,
      last_seen_at = v_now
  where room_id = p_room_id
    and user_id = p_user_id
    and left_at is null;

  perform public.admin_record_audit(
    'kick_room_member',
    'room_members',
    p_room_id::text,
    p_user_id,
    jsonb_build_object('reason', p_reason)
  );
end;
$$;


ALTER FUNCTION "public"."admin_kick_room_member"("p_room_id" "uuid", "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_audit_logs"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "admin_user_id" "uuid", "admin_public_user_id" "text", "admin_name" "text", "target_user_id" "uuid", "target_public_user_id" "text", "target_name" "text", "action" "text", "entity_type" "text", "entity_id" "text", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    al.id,
    al.admin_user_id,
    ap.public_user_id,
    coalesce(nullif(ap.display_name, ''), nullif(ap.username, '')),
    al.target_user_id,
    tp.public_user_id,
    coalesce(nullif(tp.display_name, ''), nullif(tp.username, '')),
    al.action,
    al.entity_type,
    al.entity_id,
    al.metadata,
    al.created_at
  from public.admin_audit_logs al
  left join public.profiles ap on ap.id = al.admin_user_id
  left join public.profiles tp on tp.id = al.target_user_id
  where public.has_admin_access()
  order by al.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;


