CREATE OR REPLACE FUNCTION "public"."admin_list_host_agency_applications"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("application_id" "uuid", "user_id" "uuid", "display_name" "text", "avatar_url" "text", "application_type" "text", "agency_id" "uuid", "agency_name" "text", "agency_code" "text", "requested_agency_name" "text", "status" "text", "message" "text", "phone" "text", "country" "text", "experience" "text", "admin_reply" "text", "created_at" timestamp with time zone, "reviewed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin uuid := auth.uid();
begin
  if v_admin is null or not public.profile_hub_admin_access() then
    raise exception 'not_authorized';
  end if;

  return query
  select
    ap.id,
    ap.user_id,
    p.display_name,
    p.avatar_url,
    ap.application_type,
    ap.agency_id,
    ag.name,
    ag.agency_code,
    ap.agency_name,
    ap.status,
    ap.message,
    ap.phone,
    ap.country,
    ap.experience,
    ap.admin_reply,
    ap.created_at,
    ap.reviewed_at
  from public.agency_applications ap
  left join public.profiles p on p.id = ap.user_id
  left join public.agencies ag on ag.id = ap.agency_id
  where ap.application_type in (
    'become_host', 'join_agency', 'create_agency'
  )
    and (p_status is null or ap.status = p_status)
  order by ap.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;


ALTER FUNCTION "public"."admin_list_host_agency_applications"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_payout_requests"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "user_id" "uuid", "public_user_id" "text", "display_name" "text", "amount_usd" numeric, "method" "text", "account_details" "text", "status" "text", "admin_note" "text", "requested_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "reviewed_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.has_finance_access() then
    raise exception 'finance_access_required';
  end if;

  return query
    select
      pr.id,
      pr.user_id,
      p.public_user_id,
      coalesce(p.display_name, p.username) as display_name,
      pr.amount_usd,
      pr.method,
      pr.account_details,
      pr.status,
      pr.admin_note,
      pr.requested_at,
      pr.reviewed_at,
      pr.reviewed_by
    from   public.payout_requests pr
    left join public.profiles p on p.id = pr.user_id
    where  (p_status is null or pr.status = p_status)
    order  by pr.requested_at desc
    limit  p_limit;
end;
$$;


