CREATE OR REPLACE FUNCTION "public"."admin_list_promo_banners"("p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._admin_assert_banners_role();
  RETURN COALESCE(
    (
      SELECT jsonb_agg(
        row_to_json(b.*)::jsonb
        ORDER BY b.sort_order ASC NULLS LAST
      )
      FROM (SELECT * FROM public.promo_banners LIMIT p_limit) b
    ),
    '[]'::jsonb
  );
END;
$$;


