CREATE OR REPLACE FUNCTION "public"."admin_list_recharge_requests"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "user_id" "uuid", "public_user_id" "text", "nickname" "text", "requested_coins" integer, "requested_amount_usd" numeric, "method" "text", "reference_code" "text", "agent_code" "text", "status" "text", "created_at" timestamp with time zone, "agency_name" "text", "agent_name" "text")
