CREATE OR REPLACE FUNCTION "public"."admin_list_reports"("p_limit" integer DEFAULT 100, "p_status" "text" DEFAULT NULL::"text", "p_target_type" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "reporter_id" "uuid", "reporter_public_user_id" "text", "reporter_name" "text", "target_type" "text", "target_id" "text", "reason" "text", "details" "text", "status" "text", "resolved_by" "uuid", "resolved_by_name" "text", "resolved_at" timestamp with time zone, "resolution_note" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    r.id,
    r.reporter_id,
    null::text as reporter_public_user_id,
    null::text as reporter_name,
    case
      when r.reported_user_id is not null then 'user'
      when r.room_id is not null then 'room'
      else 'other'
    end::text as target_type,
    coalesce(r.reported_user_id::text, r.room_id::text, '')::text as target_id,
    coalesce(r.reason, '')::text as reason,
    null::text as details,
    coalesce(r.status, 'pending')::text as status,
    null::uuid as resolved_by,
    null::text as resolved_by_name,
    null::timestamptz as resolved_at,
    null::text as resolution_note,
    r.created_at
  from public.user_reports r
  where public.is_admin_staff(auth.uid())
    and (p_status is null or r.status = p_status)
    and (
      p_target_type is null
      or (p_target_type = 'user' and r.reported_user_id is not null)
      or (p_target_type = 'room' and r.room_id is not null)
      or (
        p_target_type = 'other'
        and r.reported_user_id is null
        and r.room_id is null
      )
    )
  order by r.created_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
$$;


ALTER FUNCTION "public"."admin_list_reports"("p_limit" integer, "p_status" "text", "p_target_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_rooms"("p_limit" integer DEFAULT 50, "p_include_deleted" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "owner_id" "uuid", "owner_public_user_id" "text", "owner_name" "text", "language" "text", "max_seats" integer, "is_private" boolean, "is_locked" boolean, "is_closed" boolean, "closed_at" timestamp with time zone, "closed_reason" "text", "active_members" bigint, "public_room_code" "text", "archived_at" timestamp with time zone, "deleted_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    r.id,
    r.name,
    r.description,
    r.owner_id,
    p.public_user_id,
    coalesce(nullif(p.display_name, ''), nullif(p.username, '')),
    r.language,
    coalesce(r.max_seats, r.max_members, 12),
    coalesce(r.is_private, false),
    coalesce(r.is_locked, false),
    coalesce(r.is_closed, false),
    r.closed_at,
    r.closed_reason,
    (
      select count(*)
      from public.room_members rm
      where rm.room_id = r.id
        and rm.left_at is null
        and rm.last_seen_at >= now() - interval '60 seconds'
    )::bigint,
    r.public_room_code,
    r.archived_at,
    r.deleted_at,
    r.created_at
  from public.rooms r
  left join public.profiles p on p.id = r.owner_id
  where public.has_admin_access()
    and (p_include_deleted or r.deleted_at is null)
  order by r.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;


