CREATE OR REPLACE FUNCTION "public"."admin_loto_force_settle_draw"("p_draw_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('finance_admin')) then
    raise exception 'permission_denied';
  end if;

  -- Force draw_at to now so settle picks it up
  update public.loto_draws
  set draw_at = now() - interval '1 second'
  where id = p_draw_id and status = 'open';

  perform public.loto_settle_due_draws();

  insert into public.loto_admin_audit_logs (admin_id, action, new_value)
  values (v_admin_id, 'force_settle_draw',
          jsonb_build_object('draw_id', p_draw_id));

  return jsonb_build_object('ok', true, 'draw_id', p_draw_id);
end;
$$;


ALTER FUNCTION "public"."admin_loto_force_settle_draw"("p_draw_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_loto_get_draw_summary"("p_draw_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('finance_admin')) then
    raise exception 'permission_denied';
  end if;

  return (
    select jsonb_build_object(
      'draw',         to_jsonb(d),
      'ticket_stats', jsonb_build_object(
        'total',    count(t.id),
        'active',   count(t.id) filter (where t.status = 'active'),
        'won',      count(t.id) filter (where t.status = 'won'),
        'lost',     count(t.id) filter (where t.status = 'lost'),
        'refunded', count(t.id) filter (where t.status = 'refunded'),
        'match_3',  count(t.id) filter (where t.matched_count = 3),
        'match_4',  count(t.id) filter (where t.matched_count = 4),
        'match_5',  count(t.id) filter (where t.matched_count = 5),
        'match_6',  count(t.id) filter (where t.matched_count = 6),
        'total_prize_paid', coalesce(sum(t.prize_coins),0)
      )
    )
    from public.loto_draws d
    left join public.loto_tickets t on t.draw_id = d.id
    where d.id = p_draw_id
    group by d.id, d.draw_number, d.status, d.opens_at, d.closes_at, d.draw_at,
             d.winning_numbers, d.seed_hash, d.seed_reveal, d.total_tickets,
             d.total_sales_coins, d.total_payout_coins, d.jackpot_pool_before,
             d.jackpot_pool_after, d.created_at, d.settled_at
  );
end;
$$;


ALTER FUNCTION "public"."admin_loto_get_draw_summary"("p_draw_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_loto_update_settings"("p_is_enabled" boolean DEFAULT NULL::boolean, "p_ticket_price_coins" integer DEFAULT NULL::integer, "p_number_min" integer DEFAULT NULL::integer, "p_number_max" integer DEFAULT NULL::integer, "p_numbers_per_ticket" integer DEFAULT NULL::integer, "p_draw_interval_minutes" integer DEFAULT NULL::integer, "p_match_3_prize" bigint DEFAULT NULL::bigint, "p_match_4_prize" bigint DEFAULT NULL::bigint, "p_match_5_prize" bigint DEFAULT NULL::bigint, "p_match_6_prize" bigint DEFAULT NULL::bigint, "p_progressive_jackpot_enabled" boolean DEFAULT NULL::boolean, "p_jackpot_contribution_pct" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_old      jsonb;
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('finance_admin')) then
    raise exception 'permission_denied';
  end if;

  select to_jsonb(s) into v_old from public.loto_settings s where game_key = 'srood_loto';

  update public.loto_settings set
    is_enabled                  = coalesce(p_is_enabled,                  is_enabled),
    ticket_price_coins          = coalesce(p_ticket_price_coins,          ticket_price_coins),
    number_min                  = coalesce(p_number_min,                  number_min),
    number_max                  = coalesce(p_number_max,                  number_max),
    numbers_per_ticket          = coalesce(p_numbers_per_ticket,          numbers_per_ticket),
    draw_interval_minutes       = coalesce(p_draw_interval_minutes,       draw_interval_minutes),
    match_3_prize               = coalesce(p_match_3_prize,               match_3_prize),
    match_4_prize               = coalesce(p_match_4_prize,               match_4_prize),
    match_5_prize               = coalesce(p_match_5_prize,               match_5_prize),
    match_6_prize               = coalesce(p_match_6_prize,               match_6_prize),
    progressive_jackpot_enabled = coalesce(p_progressive_jackpot_enabled, progressive_jackpot_enabled),
    jackpot_contribution_pct    = coalesce(p_jackpot_contribution_pct,    jackpot_contribution_pct),
    updated_at                  = now(),
    updated_by                  = v_admin_id
  where game_key = 'srood_loto';

  insert into public.loto_admin_audit_logs (admin_id, action, old_value, new_value)
  values (v_admin_id, 'update_settings', v_old,
          (select to_jsonb(s) from public.loto_settings s where game_key = 'srood_loto'));

  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."admin_loto_update_settings"("p_is_enabled" boolean, "p_ticket_price_coins" integer, "p_number_min" integer, "p_number_max" integer, "p_numbers_per_ticket" integer, "p_draw_interval_minutes" integer, "p_match_3_prize" bigint, "p_match_4_prize" bigint, "p_match_5_prize" bigint, "p_match_6_prize" bigint, "p_progressive_jackpot_enabled" boolean, "p_jackpot_contribution_pct" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_loto_void_draw"("p_draw_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_ticket   record;
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('finance_admin')) then
    raise exception 'permission_denied';
  end if;

  -- Refund all active tickets
  for v_ticket in
    select * from public.loto_tickets
    where draw_id = p_draw_id and status = 'active'
  loop
    update public.wallets
    set coins_balance = coins_balance + v_ticket.ticket_price_coins, updated_at = now()
    where user_id = v_ticket.user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_ticket.user_id, 'srood_loto_refund', 'credit', v_ticket.ticket_price_coins, 0,
       'Srood Loto refund – voided draw',
       jsonb_build_object('draw_id', p_draw_id, 'ticket_id', v_ticket.id));

    update public.loto_tickets set status = 'refunded' where id = v_ticket.id;
  end loop;

  update public.loto_draws set status = 'voided' where id = p_draw_id;

  insert into public.loto_admin_audit_logs (admin_id, action, new_value)
  values (v_admin_id, 'void_draw', jsonb_build_object('draw_id', p_draw_id));

  perform public.loto_create_next_draw_if_needed();

  return jsonb_build_object('ok', true, 'draw_id', p_draw_id);
end;
$$;


ALTER FUNCTION "public"."admin_loto_void_draw"("p_draw_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."wallets" (
    "user_id" "uuid" NOT NULL,
    "coins_balance" integer DEFAULT 0 NOT NULL,
    "diamonds_balance" integer DEFAULT 0 NOT NULL,
    "lifetime_coins_charged" integer DEFAULT 0 NOT NULL,
    "lifetime_coins_spent" integer DEFAULT 0 NOT NULL,
    "lifetime_diamonds_earned" integer DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "wallets_coins_balance_non_negative" CHECK (("coins_balance" >= 0)),
    CONSTRAINT "wallets_diamonds_balance_non_negative" CHECK (("diamonds_balance" >= 0)),
    CONSTRAINT "wallets_lifetime_coins_charged_non_negative" CHECK (("lifetime_coins_charged" >= 0)),
    CONSTRAINT "wallets_lifetime_coins_spent_non_negative" CHECK (("lifetime_coins_spent" >= 0)),
    CONSTRAINT "wallets_lifetime_diamonds_earned_non_negative" CHECK (("lifetime_diamonds_earned" >= 0))
);


ALTER TABLE "public"."wallets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_manual_wallet_adjustment"("p_user_id" "uuid", "p_coins_delta" integer DEFAULT 0, "p_diamonds_delta" integer DEFAULT 0, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."wallets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_wallet public.wallets;
  v_coins_delta integer := coalesce(p_coins_delta, 0);
  v_diamonds_delta integer := coalesce(p_diamonds_delta, 0);
  -- 1 billion coins absolute cap per single admin operation
  c_max_abs_delta constant integer := 1000000000;
begin
  if v_admin_id is null then
    raise exception 'not_authenticated';
  end if;

  if not (public.has_app_role('super_admin') or public.has_app_role('finance_admin')) then
    raise exception 'not_authorized';
  end if;

  if p_user_id is null then
    raise exception 'missing_user_id';
  end if;

  if v_coins_delta = 0 and v_diamonds_delta = 0 then
    raise exception 'empty_adjustment';
  end if;

  if abs(v_coins_delta) > c_max_abs_delta then
    raise exception 'coins_delta_exceeds_maximum';
  end if;

  if abs(v_diamonds_delta) > c_max_abs_delta then
    raise exception 'diamonds_delta_exceeds_maximum';
  end if;

  insert into public.wallets (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select *
  into v_wallet
  from public.wallets
  where user_id = p_user_id
  for update;

  if v_wallet.coins_balance + v_coins_delta < 0
     or v_wallet.diamonds_balance + v_diamonds_delta < 0 then
    raise exception 'negative_balance_not_allowed';
  end if;

  update public.wallets
  set coins_balance = coins_balance + v_coins_delta,
      diamonds_balance = diamonds_balance + v_diamonds_delta,
      lifetime_coins_charged = lifetime_coins_charged + greatest(v_coins_delta, 0),
      lifetime_diamonds_earned = lifetime_diamonds_earned + greatest(v_diamonds_delta, 0),
      updated_at = now()
  where user_id = p_user_id
  returning * into v_wallet;

  insert into public.wallet_transactions (
    user_id,
    type,
    direction,
    coins_delta,
    diamonds_delta,
    balance_coins_after,
    balance_diamonds_after,
    note,
    metadata
  )
  values (
    p_user_id,
    'admin_adjustment',
    case
      when v_coins_delta > 0 or v_diamonds_delta > 0 then 'credit'
      when v_coins_delta < 0 or v_diamonds_delta < 0 then 'debit'
      else 'neutral'
    end,
    v_coins_delta,
    v_diamonds_delta,
    v_wallet.coins_balance,
    v_wallet.diamonds_balance,
    nullif(trim(coalesce(p_note, '')), ''),
    jsonb_build_object('admin_user_id', v_admin_id)
  );

  perform public.admin_record_audit(
    'admin_wallet_adjustment',
    'wallets',
    p_user_id::text,
    p_user_id,
    jsonb_build_object(
      'coins_delta', v_coins_delta,
      'diamonds_delta', v_diamonds_delta,
      'balance_coins_after', v_wallet.coins_balance,
      'balance_diamonds_after', v_wallet.diamonds_balance,
      'note', p_note
    )
  );

  return v_wallet;
end;
$$;


ALTER FUNCTION "public"."admin_manual_wallet_adjustment"("p_user_id" "uuid", "p_coins_delta" integer, "p_diamonds_delta" integer, "p_note" "text") OWNER TO "postgres";


