     and now() > v_row.forced_crash_multiplier_expires_at then
    return jsonb_build_object(
      'test_mode',         v_row.test_mode,
      'forced_multiplier', null,
      'expires_at',        null,
      'note',              'expired'
    );
  end if;

  return jsonb_build_object(
    'test_mode',         v_row.test_mode,
    'forced_multiplier', v_row.forced_crash_multiplier,
    'expires_at',        v_row.forced_crash_multiplier_expires_at,
    'set_by',            v_row.forced_crash_multiplier_by
  );
end;
$$;


ALTER FUNCTION "public"."admin_preview_rocket_crash_result"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_record_audit"("p_action" "text", "p_target_type" "text" DEFAULT NULL::"text", "p_target_id" "text" DEFAULT NULL::"text", "p_old_value" "jsonb" DEFAULT NULL::"jsonb", "p_new_value" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.admin_audit_logs (
    actor_id, actor_role, action, target_type, target_id, old_value, new_value
  )
  VALUES (
    auth.uid(),
    public.get_admin_role(auth.uid()),
    p_action,
    p_target_type,
    p_target_id,
    p_old_value,
    p_new_value
  );
END;
$$;


ALTER FUNCTION "public"."admin_record_audit"("p_action" "text", "p_target_type" "text", "p_target_id" "text", "p_old_value" "jsonb", "p_new_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_record_audit"("p_action" "text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "text" DEFAULT NULL::"text", "p_target_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.has_admin_access() then
    raise exception 'not_authorized';
  end if;

  insert into public.admin_audit_logs (
    admin_user_id,
    target_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  )
  values (
    auth.uid(),
    p_target_user_id,
    p_action,
    p_entity_type,
    p_entity_id,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_record_audit"("p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_target_user_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_payout_request"("p_request_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request  record;
begin
  if v_admin_id is null or not public.has_finance_access() then
    raise exception 'finance_access_required';
  end if;

  select id, status
  into   v_request
  from   public.payout_requests
  where  id = p_request_id
  for update;

  if not found then
    raise exception 'payout_request_not_found';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'payout_request_not_pending: current status is %', v_request.status;
  end if;

  update public.payout_requests
  set    status      = 'rejected',
         admin_note  = coalesce(p_reason, admin_note),
         reviewed_at = now(),
         reviewed_by = v_admin_id
  where  id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."admin_reject_payout_request"("p_request_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_withdrawal"("p_request_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request public.withdrawal_requests;
begin
  if v_admin_id is null or not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select * into v_request
  from public.withdrawal_requests
  where id = p_request_id
  for update;

  if v_request is null then
    raise exception 'request_not_found';
  end if;

  if v_request.status != 'pending' then
    raise exception 'request_not_pending';
  end if;

  update public.withdrawal_requests
  set status = 'rejected',
      admin_note = p_admin_note,
      processed_at = now(),
      processed_by = v_admin_id
  where id = p_request_id;

  -- Refund the held diamonds
  update public.wallets
  set diamonds_balance = diamonds_balance + v_request.diamonds,
      updated_at = now()
  where user_id = v_request.user_id;

  insert into public.wallet_transactions (
    user_id, type, direction, coins_delta, diamonds_delta, note
  )
  values (
    v_request.user_id, 'withdrawal_refund', 'credit',
    0, v_request.diamonds, 'Withdrawal request rejected — diamonds refunded'
  );

  perform public.admin_record_audit(
    'withdrawal_rejected',
    'withdrawal_requests',
    p_request_id::text,
    v_request.user_id,
    jsonb_build_object('diamonds', v_request.diamonds, 'note', p_admin_note)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."admin_reject_withdrawal"("p_request_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_remove_host_from_agency"("p_host_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_admin uuid := auth.uid(); v_agency uuid;
begin
  if v_admin is null or not public.profile_hub_admin_access() then raise exception 'not_authorized'; end if;
  select agency_id into v_agency from public.agency_hosts where host_user_id = p_host_user_id and status = 'active' limit 1;
  update public.agency_hosts set status = 'left', left_at = now() where host_user_id = p_host_user_id and status = 'active';
  update public.agency_members set status = 'removed', updated_at = now() where user_id = p_host_user_id and status = 'active';
  perform public._agency_audit(v_admin, 'host_removed', v_agency, p_host_user_id, null, jsonb_build_object('reason', p_reason));
  return true;
end; $$;


ALTER FUNCTION "public"."admin_remove_host_from_agency"("p_host_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_remove_user_role"("p_user_id" "uuid", "p_role" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_role text;
BEGIN
  -- Only o_super_admin can remove roles
  IF NOT public.is_o_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  -- Get target's current role
  SELECT role INTO v_target_role
  FROM public.admin_users
  WHERE user_id = p_user_id AND is_active = true;

  IF v_target_role IS NULL THEN
    RAISE EXCEPTION 'user_not_admin';
  END IF;

  -- Cannot remove o_super_admin (owner protection)
  IF v_target_role = 'o_super_admin' THEN
    RAISE EXCEPTION 'cannot_remove_o_super_admin';
  END IF;

  -- Deactivate
  UPDATE public.admin_users
  SET is_active = false, updated_at = now()
  WHERE user_id = p_user_id AND is_active = true;

  -- Audit
  PERFORM public.admin_record_audit(
    'remove_admin_role',
    'user',
    p_user_id::text,
    jsonb_build_object('role', v_target_role),
    NULL
  );
END;
$$;


ALTER FUNCTION "public"."admin_remove_user_role"("p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


