CREATE OR REPLACE FUNCTION "public"."admin_review_agency_application"("p_application_id" "uuid", "p_approve" boolean, "p_reply" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin uuid := auth.uid();
  v_app public.agency_applications;
  v_agency_id uuid;
begin
  if v_admin is null or not public.profile_hub_admin_access() then
    raise exception 'not_authorized';
  end if;

  select *
  into v_app
  from public.agency_applications
  where id = p_application_id
  for update;

  if v_app.id is null then raise exception 'application_not_found'; end if;
  if v_app.status <> 'pending' then raise exception 'application_not_pending'; end if;

  if p_approve then
    if v_app.application_type = 'join_agency' then
      perform public._agency_grant_membership(v_app.id, v_admin);
      perform public._activate_approved_host(v_app.user_id, v_admin, v_app.id);
    elsif v_app.application_type = 'become_host' then
      perform public._activate_approved_host(v_app.user_id, v_admin, v_app.id);
    elsif v_app.application_type = 'create_agency' then
      perform pg_advisory_xact_lock(
        hashtextextended(v_app.user_id::text, 0)
      );
      if nullif(trim(coalesce(v_app.agency_name, '')), '') is null then
        raise exception 'agency_name_required';
      end if;
      if exists (
        select 1 from public.agencies
        where owner_user_id = v_app.user_id and status in ('pending', 'active')
      ) then
        raise exception 'agency_already_owned';
      end if;

      insert into public.agencies (
        name, owner_user_id, country, status, agency_code
      )
      values (
        trim(v_app.agency_name),
        v_app.user_id,
        nullif(trim(coalesce(v_app.country, '')), ''),
        'active',
        public._gen_agency_code()
      )
      returning id into v_agency_id;

      insert into public.agency_members (
        agency_id, user_id, role, status, joined_at
      )
      values (
        v_agency_id, v_app.user_id, 'owner', 'active', now()
      )
      on conflict (agency_id, user_id) do update
        set role = 'owner', status = 'active', updated_at = now();

      update public.agency_applications
      set agency_id = v_agency_id
      where id = v_app.id;

      perform public._agency_audit(
        v_admin, 'agency_created', v_agency_id, v_app.user_id, v_app.id,
        jsonb_build_object('name', trim(v_app.agency_name))
      );
    else
      raise exception 'unsupported_application_type';
    end if;

    update public.agency_applications
    set status = 'approved',
        admin_reply = p_reply,
        reviewed_by = v_admin,
        reviewed_at = now(),
        updated_at = now()
    where id = v_app.id;

    perform public._agency_audit(
      v_admin, 'application_approved',
      coalesce(v_agency_id, v_app.agency_id),
      v_app.user_id, v_app.id,
      jsonb_build_object('type', v_app.application_type)
    );
  else
    update public.agency_applications
    set status = 'rejected',
        admin_reply = p_reply,
        reviewed_by = v_admin,
        reviewed_at = now(),
        updated_at = now()
    where id = v_app.id;

    perform public._agency_audit(
      v_admin, 'application_rejected',
      v_app.agency_id, v_app.user_id, v_app.id,
      jsonb_build_object('type', v_app.application_type)
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."admin_review_agency_application"("p_application_id" "uuid", "p_approve" boolean, "p_reply" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_startup_promo"("p_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_image_url" "text" DEFAULT NULL::"text", "p_storage_path" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT false, "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_duration_seconds" integer DEFAULT 5, "p_frequency" "text" DEFAULT 'once_per_day'::"text", "p_priority" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_actor uuid := auth.uid();
begin
  if not public.has_admin_access() then
    raise exception 'not_authorized';
  end if;

  if p_id is not null then
    update public.startup_promos
    set
      title            = coalesce(p_title, title),
      image_url        = coalesce(p_image_url, image_url),
      storage_path     = coalesce(p_storage_path, storage_path),
      is_active        = p_is_active,
      starts_at        = p_starts_at,
      ends_at          = p_ends_at,
      duration_seconds = p_duration_seconds,
      frequency        = p_frequency,
      priority         = p_priority,
      updated_at       = now()
    where id = p_id
    returning id into v_id;
  else
    insert into public.startup_promos (
      title, image_url, storage_path, is_active,
      starts_at, ends_at, duration_seconds, frequency, priority, created_by
    ) values (
      p_title, p_image_url, p_storage_path, p_is_active,
      p_starts_at, p_ends_at, p_duration_seconds, p_frequency, p_priority, v_actor
    )
    returning id into v_id;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_save_startup_promo"("p_id" "uuid", "p_title" "text", "p_image_url" "text", "p_storage_path" "text", "p_is_active" boolean, "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_duration_seconds" integer, "p_frequency" "text", "p_priority" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_users"("p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "display_name" "text", "username" "text", "avatar_url" "text", "vip_level" integer, "coins_balance" integer, "diamonds_balance" integer, "roles" "text"[], "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    p.public_user_id,
    p.display_name,
    p.username,
    p.avatar_url,
    coalesce(p.vip_level, 0),
    coalesce(w.coins_balance, 0),
    coalesce(w.diamonds_balance, 0),
    coalesce(
      array_remove(array_agg(distinct aur.role), null),
      array[]::text[]
    ),
    p.created_at
  from public.profiles p
  left join public.wallets w on w.user_id = p.id
  left join public.app_user_roles aur on aur.user_id = p.id
  where public.has_admin_access()
    and (
      nullif(trim(coalesce(p_query, '')), '') is null
      or p.public_user_id ilike '%' || trim(p_query) || '%'
      or p.display_name ilike '%' || trim(p_query) || '%'
      or p.username ilike '%' || trim(p_query) || '%'
      or p.id::text ilike '%' || trim(p_query) || '%'
    )
  group by
    p.id,
    p.public_user_id,
    p.display_name,
    p.username,
    p.avatar_url,
    p.vip_level,
    w.coins_balance,
    w.diamonds_balance,
    p.created_at
  order by p.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;


ALTER FUNCTION "public"."admin_search_users"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


