CREATE OR REPLACE FUNCTION "public"."admin_set_room_golden_id"("p_room_id" "uuid", "p_golden_id" "text" DEFAULT NULL::"text", "p_is_golden" boolean DEFAULT true, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_golden text := nullif(trim(coalesce(p_golden_id, '')), '');
begin
  if not (
    public.has_app_role('super_admin')
    or public.has_app_role('support_admin')
  ) then
    raise exception 'not_authorized';
  end if;

  -- If revoking, clear all three fields together.
  if not coalesce(p_is_golden, true) then
    update public.rooms
    set    golden_room_id        = null,
           is_golden_room        = false,
           golden_room_expires_at = null,
           updated_at            = now()
    where  id = p_room_id;
    return;
  end if;

  -- Granting: golden_id is required.
  if v_golden is null then
    raise exception 'golden_room_id_required';
  end if;

  update public.rooms
  set    golden_room_id         = v_golden,
         is_golden_room         = true,
         golden_room_expires_at = p_expires_at,
         updated_at             = now()
  where  id = p_room_id;

  perform public.admin_record_audit(
    'set_room_golden_id',
    'rooms',
    p_room_id::text,
    auth.uid(),
    jsonb_build_object(
      'golden_room_id', v_golden,
      'is_golden',      true,
      'expires_at',     p_expires_at
    )
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_room_golden_id"("p_room_id" "uuid", "p_golden_id" "text", "p_is_golden" boolean, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_room_public_code"("p_room_id" "uuid", "p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if not (
    public.has_app_role('super_admin')
    or public.has_app_role('support_admin')
  ) then
    raise exception 'not_authorized';
  end if;

  if p_code !~ '^[1-9][0-9]{4}$' then
    raise exception 'invalid_room_code: must be a 5-digit number between 10000 and 99999';
  end if;

  if not exists (select 1 from public.rooms where id = p_room_id) then
    raise exception 'room_not_found';
  end if;

  update public.rooms
  set public_room_code = p_code,
      updated_at       = now()
  where id = p_room_id;

  perform public.admin_record_audit(
    'set_room_public_code'::text,
    'rooms'::text,
    p_room_id::text,
    auth.uid()::uuid,
    jsonb_build_object('public_room_code', p_code)::jsonb
  );
end;
$_$;


