CREATE OR REPLACE FUNCTION "public"."admin_set_user_restriction"("p_user_id" "uuid", "p_restriction_type" "text", "p_is_active" boolean, "p_reason" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor_id   uuid := auth.uid();
  v_actor_role text := public.get_admin_role(v_actor_id);
BEGIN
  -- Must be admin staff
  IF v_actor_role IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- UNBAN (removing account_ban) = o_super_admin only
  IF p_restriction_type = 'account_ban' AND p_is_active = false THEN
    IF NOT public.can_unban_users(v_actor_id) THEN
      RAISE EXCEPTION 'only_o_super_admin_can_unban';
    END IF;
  END IF;

  -- Permanent ban requires permission
  IF p_restriction_type = 'account_ban' AND p_is_active = true THEN
    IF NOT public.has_admin_permission('users.permanent_ban', v_actor_id) THEN
      RAISE EXCEPTION 'insufficient_permissions';
    END IF;
  END IF;

  -- Temp bans and other restrictions require temp_ban permission
  IF p_restriction_type IN ('room_ban', 'chat_mute', 'gift_block') AND p_is_active = true THEN
    IF NOT public.has_admin_permission('users.temp_ban', v_actor_id) THEN
      RAISE EXCEPTION 'insufficient_permissions';
    END IF;
  END IF;

  -- Apply restriction
  IF p_is_active THEN
    INSERT INTO public.admin_user_restrictions (
      user_id, restriction_type, reason, is_active, expires_at, created_by
    )
    VALUES (
      p_user_id, p_restriction_type, p_reason, true, p_expires_at, v_actor_id
    )
    ON CONFLICT (user_id, restriction_type)
    DO UPDATE SET
      is_active  = true,
      reason     = COALESCE(EXCLUDED.reason, public.admin_user_restrictions.reason),
      expires_at = EXCLUDED.expires_at,
      updated_at = now();
  ELSE
    UPDATE public.admin_user_restrictions
    SET
      is_active  = false,
      updated_at = now()
    WHERE user_id = p_user_id
      AND restriction_type = p_restriction_type;
  END IF;

  -- Audit
  PERFORM public.admin_record_audit(
    CASE WHEN p_is_active THEN 'restrict_user' ELSE 'unrestrict_user' END,
    'user',
    p_user_id::text,
    NULL,
    jsonb_build_object(
      'restriction_type', p_restriction_type,
      'is_active', p_is_active,
      'reason', p_reason
    )
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_user_restriction"("p_user_id" "uuid", "p_restriction_type" "text", "p_is_active" boolean, "p_reason" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_soft_delete_room"("p_room_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
begin
  -- Soft-delete is restricted to the highest admin tiers only.
  if not (
    public.has_app_role('super_admin')
    or public.has_app_role('o_super_admin')
  ) then
    raise exception 'not_authorized';
  end if;

  update public.rooms
  set
    deleted_at    = v_now,
    deleted_by    = auth.uid(),
    delete_reason = nullif(trim(coalesce(p_reason, '')), ''),
    is_closed     = true,
    closed_at     = coalesce(closed_at, v_now),
    closed_reason = 'deleted',
    updated_at    = v_now
  where id = p_room_id;

  if not found then
    raise exception 'room_not_found';
  end if;

  perform public.admin_record_audit(
    'soft_delete_room'::text,
    'rooms'::text,
    p_room_id::text,
    auth.uid()::uuid,
    jsonb_build_object('reason', p_reason)::jsonb
  );
end;
$$;


