CREATE OR REPLACE FUNCTION "public"."admin_update_avatar_frame"("p_frame_key" "text", "p_name" "text", "p_category" "text", "p_vip_level" integer DEFAULT NULL::integer, "p_required_vip_level" integer DEFAULT NULL::integer, "p_asset_url" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT true, "p_is_featured" boolean DEFAULT false, "p_sort_order" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('content_admin')) then
    raise exception 'not_authorized';
  end if;

  insert into public.avatar_frames (
    frame_key,
    name,
    category,
    vip_level,
    required_vip_level,
    asset_url,
    is_active,
    is_featured,
    sort_order
  )
  values (
    lower(trim(p_frame_key)),
    trim(p_name),
    lower(trim(p_category)),
    p_vip_level,
    p_required_vip_level,
    nullif(trim(coalesce(p_asset_url, '')), ''),
    coalesce(p_is_active, true),
    coalesce(p_is_featured, false),
    coalesce(p_sort_order, 0)
  )
  on conflict (frame_key) do update set
    name = excluded.name,
    category = excluded.category,
    vip_level = excluded.vip_level,
    required_vip_level = excluded.required_vip_level,
    asset_url = excluded.asset_url,
    is_active = excluded.is_active,
    is_featured = excluded.is_featured,
    sort_order = excluded.sort_order
  returning id into v_id;

  perform public.admin_record_audit(
    'update_avatar_frame',
    'avatar_frames',
    lower(trim(p_frame_key)),
    null,
    jsonb_build_object('name', p_name, 'category', p_category)
  );

  return v_id;
end;
$$;


