CREATE OR REPLACE FUNCTION "public"."admin_update_gift"("p_gift_id" "uuid" DEFAULT NULL::"uuid", "p_code" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_arabic_name" "text" DEFAULT NULL::"text", "p_price_coins" integer DEFAULT NULL::integer, "p_icon" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT 'hot'::"text", "p_is_active" boolean DEFAULT true, "p_sort_order" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.has_content_admin_access() then
    raise exception 'not_authorized';
  end if;

  if p_gift_id is null then
    insert into public.gifts (
      code,
      name,
      arabic_name,
      price_coins,
      icon,
      category,
      is_active,
      sort_order
    )
    values (
      lower(trim(coalesce(p_code, ''))),
      trim(coalesce(p_name, 'Gift')),
      nullif(trim(coalesce(p_arabic_name, '')), ''),
      greatest(coalesce(p_price_coins, 1), 1),
      nullif(trim(coalesce(p_icon, '')), ''),
      lower(trim(coalesce(p_category, 'hot'))),
      coalesce(p_is_active, true),
      coalesce(p_sort_order, 0)
    )
    on conflict (code) do update set
      name = excluded.name,
      arabic_name = excluded.arabic_name,
      price_coins = excluded.price_coins,
      icon = excluded.icon,
      category = excluded.category,
      is_active = excluded.is_active,
      sort_order = excluded.sort_order
    returning id into v_id;
  else
    update public.gifts
    set code = lower(trim(coalesce(p_code, code))),
        name = trim(coalesce(p_name, name)),
        arabic_name = nullif(trim(coalesce(p_arabic_name, arabic_name, '')), ''),
        price_coins = greatest(coalesce(p_price_coins, price_coins), 1),
        icon = nullif(trim(coalesce(p_icon, icon, '')), ''),
        category = lower(trim(coalesce(p_category, category, 'hot'))),
        is_active = coalesce(p_is_active, is_active),
        sort_order = coalesce(p_sort_order, sort_order)
    where id = p_gift_id
    returning id into v_id;
  end if;

  perform public.admin_record_audit(
    'update_gift'::text,
    'gifts'::text,
    v_id::text,
    null::uuid,
    jsonb_build_object(
      'code', p_code,
      'name', p_name,
      'price_coins', p_price_coins
    )::jsonb
  );

  return v_id;
end;
$$;


