CREATE OR REPLACE FUNCTION "public"."admin_update_user_profile"("p_user_id" "uuid", "p_display_name" "text" DEFAULT NULL::"text", "p_username" "text" DEFAULT NULL::"text", "p_avatar_url" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text", "p_vip_level" integer DEFAULT NULL::integer, "p_gender" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_gender  text := nullif(trim(coalesce(p_gender,  '')), '');
  v_country text := nullif(trim(coalesce(p_country, '')), '');
begin
  if not (
    public.has_app_role('super_admin')
    or public.has_app_role('support_admin')
  ) then
    raise exception 'not_authorized';
  end if;

  update public.profiles
  set
    display_name  = coalesce(p_display_name, display_name),
    username      = coalesce(p_username,     username),
    avatar_url    = coalesce(p_avatar_url,   avatar_url),
    bio           = coalesce(p_bio,          bio),
    vip_level     = coalesce(p_vip_level,    vip_level),
    vip_started_at = case
      when p_vip_level is null then vip_started_at
      when p_vip_level > 0 and vip_level <> p_vip_level then now()
      when p_vip_level = 0 then null
      else vip_started_at
    end,
    vip_expires_at = case
      when p_vip_level is null then vip_expires_at
      when p_vip_level = 0 then null
      else vip_expires_at
    end,
    -- Admin override: set value and reset the one-time lock so user can still change once.
    gender               = case when v_gender  is not null then v_gender  else gender  end,
    gender_changed_once  = case when v_gender  is not null then false      else gender_changed_once  end,
    gender_changed_at    = case when v_gender  is not null then now()      else gender_changed_at    end,
    country              = case when v_country is not null then v_country  else country end,
    country_changed_once = case when v_country is not null then false      else country_changed_once end,
    country_changed_at   = case when v_country is not null then now()      else country_changed_at   end,
    updated_at = now()
  where id = p_user_id;

  perform public.admin_record_audit(
    'update_user_profile',
    'profiles',
    p_user_id::text,
    p_user_id,
    jsonb_build_object(
      'vip_level', p_vip_level,
      'gender',    v_gender,
      'country',   v_country
    )
  );
end;
$$;


ALTER FUNCTION "public"."admin_update_user_profile"("p_user_id" "uuid", "p_display_name" "text", "p_username" "text", "p_avatar_url" "text", "p_bio" "text", "p_vip_level" integer, "p_gender" "text", "p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_vip_package"("p_vip_level" integer, "p_code" "text", "p_name" "text", "p_arabic_name" "text" DEFAULT NULL::"text", "p_price_coins" integer DEFAULT 0, "p_duration_days" integer DEFAULT 30, "p_badge_label" "text" DEFAULT NULL::"text", "p_entrance_banner_key" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT true, "p_sort_order" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_level integer := greatest(1, least(coalesce(p_vip_level, 1), 9));
begin
  if not (public.has_app_role('super_admin') or public.has_app_role('content_admin')) then
    raise exception 'not_authorized';
  end if;

  insert into public.vip_packages (
    vip_level, code, name, arabic_name, price_coins, duration_days,
    badge_label, entrance_banner_key, is_active, sort_order, updated_at
  )
  values (
    v_level,
    lower(trim(p_code)),
    trim(p_name),
    nullif(trim(coalesce(p_arabic_name, '')), ''),
    greatest(coalesce(p_price_coins, 0), 0),
    greatest(coalesce(p_duration_days, 30), 1),
    nullif(trim(coalesce(p_badge_label, '')), ''),
    nullif(trim(coalesce(p_entrance_banner_key, '')), ''),
    coalesce(p_is_active, true),
    coalesce(p_sort_order, 0),
    now()
  )
  on conflict (vip_level) do update set
    code = excluded.code,
    name = excluded.name,
    arabic_name = excluded.arabic_name,
    price_coins = excluded.price_coins,
    duration_days = excluded.duration_days,
    badge_label = excluded.badge_label,
    entrance_banner_key = excluded.entrance_banner_key,
    is_active = excluded.is_active,
    sort_order = excluded.sort_order,
    updated_at = now()
  returning id into v_id;

  perform public.admin_record_audit(
    'update_vip_package',
    'vip_packages',
    v_level::text,
    null,
    jsonb_build_object('vip_level', v_level, 'price_coins', p_price_coins)
  );

  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_update_vip_package"("p_vip_level" integer, "p_code" "text", "p_name" "text", "p_arabic_name" "text", "p_price_coins" integer, "p_duration_days" integer, "p_badge_label" "text", "p_entrance_banner_key" "text", "p_is_active" boolean, "p_sort_order" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_daily_reward_rule"("p_day_number" integer, "p_enabled" boolean, "p_reward_type" "text", "p_title" "text", "p_description" "text", "p_amount" bigint, "p_duration_days" integer, "p_image_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null
     or not (public.is_o_super_admin(auth.uid())
             or public.is_p_super_admin(auth.uid())
             or public.is_super_admin(auth.uid())) then
    raise exception 'not_authorized';
  end if;

  if p_day_number < 1 or p_day_number > 7 then raise exception 'invalid_day'; end if;
  -- Only coins are safely supported at the moment.
  if p_reward_type <> 'coins' then raise exception 'unsupported_reward_type'; end if;
  if coalesce(p_amount, 0) < 0 then raise exception 'invalid_amount'; end if;

  insert into public.daily_reward_rules
    (day_number, enabled, reward_type, title, description, amount, duration_days, image_url, sort_order, updated_at)
  values
    (p_day_number, p_enabled, p_reward_type, coalesce(p_title, 'Day ' || p_day_number),
     p_description, coalesce(p_amount, 0), p_duration_days, p_image_url, p_day_number, now())
  on conflict (day_number) do update
    set enabled       = excluded.enabled,
        reward_type   = excluded.reward_type,
        title         = excluded.title,
        description   = excluded.description,
        amount        = excluded.amount,
        duration_days = excluded.duration_days,
        image_url     = excluded.image_url,
        updated_at    = now();
end;
$$;


