CREATE OR REPLACE FUNCTION "public"."admin_user_detail"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "email" "text", "public_user_id" "text", "display_name" "text", "username" "text", "avatar_url" "text", "bio" "text", "date_of_birth" "date", "gender" "text", "country" "text", "vip_level" integer, "vip_title" "text", "vip_started_at" timestamp with time zone, "vip_expires_at" timestamp with time zone, "selected_avatar_frame_key" "text", "coins_balance" integer, "diamonds_balance" integer, "lifetime_coins_charged" integer, "lifetime_coins_spent" integer, "lifetime_diamonds_earned" integer, "roles" "text"[], "active_restrictions" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    u.email::text,
    p.public_user_id,
    p.display_name,
    p.username,
    p.avatar_url,
    p.bio,
    p.date_of_birth,
    p.gender,
    p.country,
    coalesce(p.vip_level, 0),
    p.vip_title,
    p.vip_started_at,
    p.vip_expires_at,
    p.selected_avatar_frame_key,
    coalesce(w.coins_balance, 0),
    coalesce(w.diamonds_balance, 0),
    coalesce(w.lifetime_coins_charged, 0),
    coalesce(w.lifetime_coins_spent, 0),
    coalesce(w.lifetime_diamonds_earned, 0),
    coalesce(array_remove(array_agg(distinct aur.role), null), array[]::text[]),
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', r.id,
            'type', r.restriction_type,
            'reason', r.reason,
            'expires_at', r.expires_at,
            'created_at', r.created_at
          )
          order by r.created_at desc
        )
        from public.admin_user_restrictions r
        where r.user_id = p.id
          and r.is_active
          and (r.expires_at is null or r.expires_at > now())
      ),
      '[]'::jsonb
    ),
    p.created_at
  from public.profiles p
  left join auth.users u on u.id = p.id
  left join public.wallets w on w.user_id = p.id
  left join public.app_user_roles aur on aur.user_id = p.id
  where public.has_admin_access()
    and p.id = p_user_id
  group by p.id, u.email, p.public_user_id, p.display_name, p.username,
           p.avatar_url, p.bio, p.date_of_birth, p.gender, p.country,
           p.vip_level, p.vip_title, p.vip_started_at, p.vip_expires_at,
           p.selected_avatar_frame_key, w.coins_balance, w.diamonds_balance,
           w.lifetime_coins_charged, w.lifetime_coins_spent,
           w.lifetime_diamonds_earned, p.created_at;
$$;


