CREATE OR REPLACE FUNCTION "public"."admin_user_gift_transactions"("p_user_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "direction" "text", "room_id" "uuid", "other_user_id" "uuid", "other_public_user_id" "text", "gift_name" "text", "gift_code" "text", "gift_price_coins" integer, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    gt.id,
    case when gt.sender_id = p_user_id then 'sent' else 'received' end,
    gt.room_id,
    case when gt.sender_id = p_user_id then gt.receiver_id else gt.sender_id end,
    op.public_user_id,
    gt.gift_name,
    gt.gift_code,
    gt.gift_price_coins,
    gt.created_at
  from public.gift_transactions gt
  left join public.profiles op
    on op.id = case when gt.sender_id = p_user_id then gt.receiver_id else gt.sender_id end
  where public.has_admin_access()
    and (gt.sender_id = p_user_id or gt.receiver_id = p_user_id)
  order by gt.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;


