CREATE OR REPLACE FUNCTION "public"."admin_void_hungry_cat_round"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin         uuid := auth.uid();
  v_round         public.hungry_cat_rounds;
  v_refund_total  integer := 0;
  v_bet           record;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  select * into v_round
  from public.hungry_cat_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'round_not_found';
  end if;

  if v_round.status = 'voided' then
    raise exception 'already_voided';
  end if;

  if v_round.status = 'completed' then
    raise exception 'round_already_completed: cannot void a settled round';
  end if;

  -- Refund all pending bets to their respective users
  for v_bet in (
    select b.*, b.user_id as bet_user_id
    from public.hungry_cat_bets b
    where b.round_id = p_round_id and b.status = 'pending'
    for update
  ) loop
    update public.wallets
    set coins_balance = coins_balance + v_bet.bet_amount,
        updated_at    = now()
    where user_id = v_bet.bet_user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_bet.bet_user_id, 'hungry_cat_refund', 'credit', v_bet.bet_amount, 0,
       'Hungry Cat round voided by admin',
       jsonb_build_object(
         'round_id', p_round_id,
         'bet_id',   v_bet.id,
         'voided_by', v_admin
       ));

    update public.hungry_cat_bets
    set status = 'refunded'
    where id = v_bet.id;

    v_refund_total := v_refund_total + v_bet.bet_amount;
  end loop;

  -- Mark round voided
  update public.hungry_cat_rounds
  set status       = 'voided',
      completed_at = now()
  where id = p_round_id;

  insert into public.admin_audit_logs
    (admin_user_id, action, entity_type, entity_id, metadata)
  values
    (v_admin, 'hungry_cat_round_voided', 'hungry_cat_rounds', p_round_id::text,
     jsonb_build_object(
       'round_id',      p_round_id,
       'refund_total',  v_refund_total,
       'round_owner',   v_round.user_id
     ));

  return jsonb_build_object(
    'ok',           true,
    'round_id',     p_round_id,
    'refund_total', v_refund_total
  );
end;
$$;


ALTER FUNCTION "public"."admin_void_hungry_cat_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_void_rocket_crash_round"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin        uuid := auth.uid();
  v_round        public.crash_rounds;
  v_refund_total integer := 0;
  v_bet          record;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  select * into v_round
  from public.crash_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'round_not_found';
  end if;

  if v_round.status = 'voided' then
    raise exception 'already_voided';
  end if;

  if v_round.status = 'crashed' then
    raise exception 'round_already_completed: cannot void a settled round';
  end if;

  -- Refund all pending/running bets
  for v_bet in (
    select b.*
    from public.crash_bets b
    where b.round_id = p_round_id
      and b.status in ('pending', 'running')
    for update
  ) loop
    update public.wallets
    set coins_balance = coins_balance + v_bet.bet_amount,
        updated_at    = now()
    where user_id = v_bet.user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_bet.user_id, 'crash_rocket_refund', 'credit', v_bet.bet_amount, 0,
       'Rocket Crash round voided by admin',
       jsonb_build_object(
         'round_id',  p_round_id,
         'bet_id',    v_bet.id,
         'voided_by', v_admin
       ));

    update public.crash_bets
    set status = 'refunded'
    where id = v_bet.id;

    v_refund_total := v_refund_total + v_bet.bet_amount;
  end loop;

  update public.crash_rounds
  set status     = 'voided',
      crashed_at = now()
  where id = p_round_id;

  insert into public.admin_audit_logs
    (admin_user_id, action, entity_type, entity_id, metadata)
  values
    (v_admin, 'rocket_crash_round_voided', 'crash_rounds', p_round_id::text,
     jsonb_build_object(
       'round_id',     p_round_id,
       'refund_total', v_refund_total,
       'round_owner',  v_round.user_id
     ));

  return jsonb_build_object(
    'ok',           true,
    'round_id',     p_round_id,
    'refund_total', v_refund_total
  );
end;
$$;


ALTER FUNCTION "public"."admin_void_rocket_crash_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_wallet_lookup_by_public_id"("p_public_user_id" "text") RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "nickname" "text", "avatar_url" "text", "coins_balance" integer, "diamonds_balance" integer, "lifetime_coins_charged" integer, "lifetime_coins_spent" integer, "lifetime_diamonds_earned" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    p.public_user_id,
    coalesce(nullif(p.display_name, ''), nullif(p.username, '')) as nickname,
    p.avatar_url,
    coalesce(w.coins_balance, 0),
    coalesce(w.diamonds_balance, 0),
    coalesce(w.lifetime_coins_charged, 0),
