CREATE OR REPLACE FUNCTION "public"."advance_crash_rocket_round"("p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_round public.crash_rocket_rounds;
  v_secret public.crash_rocket_round_secrets;
  v_now timestamptz := clock_timestamp();
  v_current numeric;
  v_bet public.crash_rocket_bets;
  v_payout integer;
  v_balance integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(
    'srood_rocket:' || coalesce(p_room_id::text, 'global'), 0
  ));

  select * into v_round from public.crash_rocket_rounds
  where room_id is not distinct from p_room_id
    and status in ('waiting','betting_open','flying','crashed')
  order by round_number desc limit 1 for update;

  if v_round.id is null then
    v_round := public._create_crash_rocket_round(p_room_id);
  end if;

  select * into v_secret from public.crash_rocket_round_secrets
  where round_id = v_round.id for update;

  if v_round.status = 'betting_open' and v_now >= v_round.betting_closes_at then
    update public.crash_rocket_rounds set
      status = 'flying',
      fly_started_at = v_round.betting_closes_at,
      updated_at = v_now
    where id = v_round.id returning * into v_round;
    update public.crash_rocket_round_secrets set
      target_crashed_at = v_round.fly_started_at
        + (ln(v_secret.target_multiplier) / 0.09) * interval '1 second'
    where round_id = v_round.id returning * into v_secret;
    insert into public.crash_rocket_round_events(round_id,event_type,payload)
    values (v_round.id,'flight_started',jsonb_build_object(
      'fly_started_at',v_round.fly_started_at
    ));
  end if;

  if v_round.status = 'flying' then
    v_current := least(v_secret.target_multiplier,
      public._crash_rocket_multiplier_at(v_round.fly_started_at, v_now));

    -- Auto-cashout is settled server-side and locked per bet.
    for v_bet in
      select * from public.crash_rocket_bets
      where round_id = v_round.id and status = 'placed'
        and auto_cashout_multiplier is not null
        and auto_cashout_multiplier <= v_current
        and auto_cashout_multiplier < v_secret.target_multiplier
      order by id for update
    loop
      v_payout := floor(v_bet.amount * v_bet.auto_cashout_multiplier)::integer;
      update public.wallets set
        coins_balance = coins_balance + v_payout, updated_at = v_now
      where user_id = v_bet.user_id returning coins_balance into v_balance;
      update public.crash_rocket_bets set
        status='cashed_out',
        cashout_multiplier=v_bet.auto_cashout_multiplier,
        payout_amount=v_payout,
        cashed_out_at=v_now
      where id=v_bet.id;
      insert into public.wallet_transactions(
        user_id,type,direction,coins_delta,diamonds_delta,
        balance_coins_after,note,metadata
      ) values (
        v_bet.user_id,'crash_rocket_cashout','credit',v_payout,0,v_balance,
        'Srood Rocket auto cashout',
        jsonb_build_object('round_id',v_round.id,'bet_id',v_bet.id,
          'multiplier',v_bet.auto_cashout_multiplier)
      );
      insert into public.crash_rocket_round_events(round_id,event_type,payload)
      values (v_round.id,'bet_cashed_out',jsonb_build_object(
        'bet_id',v_bet.id,'user_id',v_bet.user_id,
        'payout_amount',v_payout,'cashout_multiplier',v_bet.auto_cashout_multiplier
      ));
    end loop;

    if v_now >= v_secret.target_crashed_at then
      update public.crash_rocket_rounds set
        status='crashed',
        crashed_at=v_secret.target_crashed_at,
        crash_multiplier=v_secret.target_multiplier,
        crash_seed_reveal=v_secret.crash_seed_secret,
        updated_at=v_now
      where id=v_round.id returning * into v_round;
      update public.crash_rocket_bets set status='lost'
      where round_id=v_round.id and status='placed';
      insert into public.crash_rocket_round_events(round_id,event_type,payload)
      values (v_round.id,'round_crashed',jsonb_build_object(
        'crash_multiplier',v_secret.target_multiplier,
        'crashed_at',v_secret.target_crashed_at
      ));
    end if;
  end if;

  if v_round.status = 'crashed'
     and v_now >= v_round.crashed_at + interval '4 seconds' then
    update public.crash_rocket_rounds set status='settled',updated_at=v_now
    where id=v_round.id returning * into v_round;
    insert into public.crash_rocket_round_events(round_id,event_type,payload)
    values (v_round.id,'round_settled','{}');
  end if;

  return jsonb_build_object('round_id',v_round.id,'status',v_round.status);
end;
$$;


ALTER FUNCTION "public"."advance_crash_rocket_round"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_fish_hunt_round"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_round_id     uuid;
  v_alive_count  integer;
  v_target_count constant integer := 8;
  v_to_spawn     integer;
  v_fish_type    text;
  v_multiplier   numeric;
  v_hit_prob     numeric;
  v_roll         double precision;
begin
  -- Expire fish whose window has passed.
  update public.fish_hunt_fish
  set status = 'expired'
  where status = 'alive'
    and expires_at <= now();

  -- Ensure a single global active round exists (room_id stays null — Fish
  -- Hunt currently runs one shared board, matching fish_hunt_get_state's
  -- "most recent active round" lookup when p_room_id is null).
  select id
  into v_round_id
  from public.fish_hunt_rounds
  where status = 'active'
    and room_id is null
  order by started_at desc
  limit 1;

  if v_round_id is null then
    insert into public.fish_hunt_rounds (room_id, status)
    values (null, 'active')
    returning id into v_round_id;
  end if;

  select count(*)
  into v_alive_count
  from public.fish_hunt_fish
  where round_id = v_round_id
    and status = 'alive';

  v_to_spawn := greatest(v_target_count - v_alive_count, 0);

  for i in 1..v_to_spawn loop
    v_roll := random();
    if v_roll < 0.55 then
      v_fish_type := 'small';
      v_multiplier := 1.5 + random() * 1.0;   -- 1.5x - 2.5x
      v_hit_prob := 0.55 + random() * 0.15;   -- 55% - 70%
    elsif v_roll < 0.85 then
      v_fish_type := 'medium';
      v_multiplier := 3.0 + random() * 2.0;   -- 3x - 5x
      v_hit_prob := 0.30 + random() * 0.15;   -- 30% - 45%
    else
      v_fish_type := 'large';
      v_multiplier := 6.0 + random() * 6.0;   -- 6x - 12x
      v_hit_prob := 0.10 + random() * 0.10;   -- 10% - 20%
    end if;

    insert into public.fish_hunt_fish (
      round_id, fish_type, reward_multiplier, hit_probability,
      spawned_at, expires_at
    )
    values (
      v_round_id, v_fish_type, v_multiplier, v_hit_prob,
      now(), now() + interval '20 seconds'
    );
  end loop;
end;
$$;


ALTER FUNCTION "public"."advance_fish_hunt_round"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_rocket_crash_rounds"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now        timestamptz := now();
  v_round      public.rocket_crash_global_rounds;
  v_bet        record;
  v_win        integer;
  v_rand       numeric;
  v_crash      numeric;
  v_secret_cm  numeric;
  v_rnum       bigint;
  v_settled    int := 0;
  v_flew       int := 0;
  v_created    boolean := false;
  c_bet_s      constant int := 8;
begin
  perform pg_advisory_xact_lock(hashtext('rocket_crash_global_round'));

  -- (1) Settle due flying rounds using the secret multiplier.
  for v_round in
    select r.*
    from public.rocket_crash_global_rounds r
    where r.status = 'flying'
      and exists (
        select 1 from public.rocket_crash_round_secrets s
        where s.round_id = r.id
          and v_now >= r.flight_starts_at
                       + (ln(s.crash_multiplier::float8) / 0.055) * interval '1 second'
      )
    order by r.created_at
    for update of r
  loop
    select s.crash_multiplier into v_secret_cm
    from public.rocket_crash_round_secrets s where s.round_id = v_round.id;

    if v_secret_cm is null then
      continue;
    end if;

    for v_bet in
      select b.* from public.rocket_crash_global_bets b
      where b.round_id = v_round.id
        and b.status = 'active'
        and b.auto_cashout_multiplier is not null
        and b.auto_cashout_multiplier <= v_secret_cm
    loop
      v_win := floor(v_bet.bet_amount * v_bet.auto_cashout_multiplier)::integer;
      update public.rocket_crash_global_bets
      set status='cashed_out', cashout_multiplier=v_bet.auto_cashout_multiplier,
          win_amount=v_win, cashed_out_at=now()
      where id = v_bet.id;
      update public.wallets
      set coins_balance = coins_balance + v_win, updated_at = now()
      where user_id = v_bet.user_id;
      insert into public.wallet_transactions
        (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
      values
        (v_bet.user_id, 'crash_rocket_win', 'credit', v_win, 0,
         'Rocket Crash auto-cashout at ' || v_bet.auto_cashout_multiplier || 'x',
         jsonb_build_object('bet_id', v_bet.id, 'round_id', v_round.id,
                            'multiplier', v_bet.auto_cashout_multiplier,
                            'auto', true, 'settled_by', 'cron'));
    end loop;

    update public.rocket_crash_global_bets
    set status = 'lost'
    where round_id = v_round.id and status = 'active';

    update public.rocket_crash_global_rounds
    set status = 'crashed', crashed_at = now(), crash_multiplier = v_secret_cm
    where id = v_round.id;

    v_settled := v_settled + 1;
  end loop;

  -- (2) betting -> flying: secret only, public crash_multiplier stays NULL.
  for v_round in
    select *
    from public.rocket_crash_global_rounds
    where status = 'betting'
      and betting_ends_at <= v_now
      and betting_ends_at >  v_now - interval '2 minutes'
    order by created_at
    for update
  loop
    if v_round.status <> 'betting' then
      continue;
    end if;

    v_rand := random();
    if v_rand < 0.04 then
      v_crash := 1.00;
    elsif v_rand < 0.08 then
      v_crash := round((1.00 + random() * 0.04)::numeric, 2);
    else
      v_crash := round(greatest(1.01, least(200.00, 0.96 / (1 - v_rand)))::numeric, 2);
    end if;

    update public.rocket_crash_global_rounds
    set status = 'flying', flight_starts_at = v_now
    where id = v_round.id and status = 'betting';

    insert into public.rocket_crash_round_secrets (round_id, crash_multiplier)
    values (v_round.id, v_crash)
    on conflict (round_id) do nothing;

    v_flew := v_flew + 1;
  end loop;

  -- (3) Ensure an active round exists.
  if not exists (
    select 1 from public.rocket_crash_global_rounds
    where status = 'betting' and betting_ends_at > v_now
  ) and not exists (
    select 1 from public.rocket_crash_global_rounds
    where status = 'flying'
      and flight_starts_at > v_now - interval '120 seconds'
  ) then
    v_rnum := nextval('public.rocket_crash_round_seq');
    insert into public.rocket_crash_global_rounds
      (round_number, status, betting_starts_at, betting_ends_at)
    values
      (v_rnum, 'betting', v_now, v_now + (c_bet_s || ' seconds')::interval);
    v_created := true;
  end if;

  return jsonb_build_object(
    'settled', v_settled, 'flew', v_flew, 'created', v_created,
    'now', extract(epoch from v_now) * 1000
  );
end;
$$;


ALTER FUNCTION "public"."advance_rocket_crash_rounds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_roulette_round"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_round             public.roulette_rounds;
  v_betting_duration   constant interval := interval '15 seconds';
  v_spin_duration      constant interval := interval '4 seconds';
begin
  select *
  into v_round
  from public.roulette_rounds
  where status <> 'settled'
  order by created_at desc
  limit 1
  for update;

  if not found then
    insert into public.roulette_rounds (room_id, status, betting_closes_at)
    values (null, 'betting_open', now() + v_betting_duration);
    return;
  end if;

  if v_round.status = 'betting_open' and v_round.betting_closes_at <= now() then
    update public.roulette_rounds
    set status = 'locked'
    where id = v_round.id;
    return;
  end if;

  if v_round.status = 'locked' then
    update public.roulette_rounds
    set status = 'spinning',
        winning_number = floor(random() * 37)::int,
        server_seed_hash = encode(
          extensions.digest(extensions.gen_random_bytes(32), 'sha256'), 'hex'
        )
    where id = v_round.id;
    return;
  end if;

  if v_round.status = 'spinning'
     and v_round.started_at + v_betting_duration + v_spin_duration <= now() then
    perform public.settle_roulette_round(v_round.id);
    return;
  end if;
end;
$$;


ALTER FUNCTION "public"."advance_roulette_round"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agency_owner_list_hosts"() RETURNS TABLE("user_id" "uuid", "display_name" "text", "avatar_url" "text", "status" "text", "joined_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception 'not_authenticated'; end if;
  return query
  select h.host_user_id, p.display_name, p.avatar_url, h.status, h.joined_at
  from public.agency_hosts h
  join public.agencies a on a.id = h.agency_id and a.owner_user_id = v_owner
  left join public.profiles p on p.id = h.host_user_id
  where h.status = 'active'
  order by h.joined_at desc;
end; $$;


ALTER FUNCTION "public"."agency_owner_list_hosts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agency_owner_list_pending_applications"() RETURNS TABLE("application_id" "uuid", "user_id" "uuid", "display_name" "text", "avatar_url" "text", "message" "text", "phone" "text", "country" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception 'not_authenticated'; end if;
  return query
  select ap.id, ap.user_id, p.display_name, p.avatar_url, ap.message, ap.phone, ap.country, ap.created_at
  from public.agency_applications ap
  join public.agencies a on a.id = ap.agency_id and a.owner_user_id = v_owner
  left join public.profiles p on p.id = ap.user_id
  where ap.application_type = 'join_agency' and ap.status = 'pending'
  order by ap.created_at desc;
end; $$;


ALTER FUNCTION "public"."agency_owner_list_pending_applications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agency_owner_review_application"("p_application_id" "uuid", "p_approve" boolean, "p_reply" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid := auth.uid();
  v_app public.agency_applications;
  v_agency public.agencies;
begin
  if v_owner is null then raise exception 'not_authenticated'; end if;

  select *
  into v_app
  from public.agency_applications
  where id = p_application_id
  for update;

  if v_app.id is null then raise exception 'application_not_found'; end if;
  if v_app.application_type <> 'join_agency' or v_app.agency_id is null then
    raise exception 'not_owner_reviewable';
  end if;

  select *
  into v_agency
  from public.agencies
  where id = v_app.agency_id
    and status = 'active';

  if v_agency.id is null or v_agency.owner_user_id is distinct from v_owner then
    raise exception 'not_agency_owner';
  end if;
  if v_app.status <> 'pending' then raise exception 'application_not_pending'; end if;

  if p_approve then
    perform public._agency_grant_membership(v_app.id, v_owner);
    perform public._activate_approved_host(v_app.user_id, v_owner, v_app.id);
  end if;

  update public.agency_applications
  set status = case when p_approve then 'approved' else 'rejected' end,
      admin_reply = p_reply,
      reviewed_by = v_owner,
      reviewed_at = now(),
      updated_at = now()
  where id = v_app.id;

  perform public._agency_audit(
    v_owner,
    case when p_approve then 'application_approved' else 'application_rejected' end,
    v_app.agency_id,
    v_app.user_id,
    v_app.id,
    jsonb_build_object('by', 'owner')
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."agency_owner_review_application"("p_application_id" "uuid", "p_approve" boolean, "p_reply" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."answer_gold_ladder_question"("p_run_id" "uuid", "p_question_id" "uuid", "p_selected_option" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id      uuid := auth.uid();
  v_run          public.gold_ladder_runs;
  v_q            public.gold_ladder_questions;
  v_is_correct   boolean;
  v_next_num     integer;
  v_next_q       record;
  v_cashout      integer := 0;
  v_new_balance  integer;
  v_prizes       numeric[] := array[1,1.5,2,3,5,7,10,15,20,30,50,100];
  v_safe_qs      integer[] := array[5,10];
  v_safe_payouts integer[] := array[5, 30]; -- multipliers for safe q5 and q10
  v_new_safe     integer;
  i              integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  if p_selected_option not in ('a','b','c','d') then
    raise exception 'invalid_option';
  end if;

  -- Lock and fetch run
  select * into v_run
  from public.gold_ladder_runs
  where id = p_run_id and user_id = v_user_id
  for update;

  if not found then raise exception 'run_not_found'; end if;
  if v_run.status != 'active' then raise exception 'run_not_active'; end if;

  -- Verify question matches current slot
  if v_run.question_ids[v_run.current_question_num] != p_question_id then
    raise exception 'wrong_question';
  end if;

  -- Fetch correct answer
  select * into v_q from public.gold_ladder_questions where id = p_question_id;

  v_is_correct := (v_q.correct_option = p_selected_option);

  if v_is_correct then
    -- ── Correct ─────────────────────────────────────────────────────────────
    v_next_num := v_run.current_question_num + 1;

    -- Check if this question was a safe point
    v_new_safe := v_run.highest_safe_question;
    if v_run.current_question_num = any(v_safe_qs) then
      v_new_safe := greatest(v_new_safe, v_run.current_question_num);
    end if;

    if v_run.current_question_num = 12 then
      -- ── Won! ────────────────────────────────────────────────────────────
      v_cashout := (v_run.entry_fee * 100)::integer;

      update public.wallets
      set coins_balance = coins_balance + v_cashout, updated_at = now()
      where user_id = v_user_id
      returning coins_balance into v_new_balance;

      insert into public.wallet_transactions
        (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
      values
        (v_user_id, 'gold_ladder_win', 'credit', v_cashout, 0,
         'Gold Ladder Quiz — completed all 12 questions',
         jsonb_build_object('run_id', p_run_id, 'entry_fee', v_run.entry_fee));

      insert into public.gold_ladder_answers
        (run_id, question_id, question_number, selected_option, is_correct)
      values (p_run_id, p_question_id, v_run.current_question_num, p_selected_option, true);

      update public.gold_ladder_runs
      set status = 'completed', current_question_num = 13,
          highest_safe_question = 10, cashout_amount = v_cashout
      where id = p_run_id;

      return jsonb_build_object(
        'correct',          true,
        'correct_option',   v_q.correct_option,
        'explanation',      v_q.explanation,
        'question_number',  v_run.current_question_num,
        'is_completed',     true,
        'is_eliminated',    false,
        'cashout_amount',   v_cashout,
        'new_balance',      v_new_balance,
        'current_prize',    v_cashout,
        'second_chance_triggered', false
      );

    else
      -- ── Advance to next question ─────────────────────────────────────────
      insert into public.gold_ladder_answers
        (run_id, question_id, question_number, selected_option, is_correct)
      values (p_run_id, p_question_id, v_run.current_question_num, p_selected_option, true);

      update public.gold_ladder_runs
      set current_question_num = v_next_num,
          highest_safe_question = v_new_safe,
          second_chance_active = false
      where id = p_run_id;

      -- Fetch next question (no correct_option)
      select id, text, text_ar,
             option_a, option_b, option_c, option_d,
             option_a_ar, option_b_ar, option_c_ar, option_d_ar,
             difficulty
      into v_next_q
      from public.gold_ladder_questions
      where id = v_run.question_ids[v_next_num];

      return jsonb_build_object(
        'correct',          true,
        'correct_option',   v_q.correct_option,
        'explanation',      v_q.explanation,
        'question_number',  v_run.current_question_num,
        'is_completed',     false,
        'is_eliminated',    false,
        'second_chance_triggered', false,
        'next_question_number', v_next_num,
        'current_prize',    (v_run.entry_fee * v_prizes[v_run.current_question_num])::integer,
        'next_question', jsonb_build_object(
          'id',          v_next_q.id,
          'text',        v_next_q.text,
          'text_ar',     v_next_q.text_ar,
          'option_a',    v_next_q.option_a,
          'option_b',    v_next_q.option_b,
          'option_c',    v_next_q.option_c,
          'option_d',    v_next_q.option_d,
          'option_a_ar', v_next_q.option_a_ar,
          'option_b_ar', v_next_q.option_b_ar,
          'option_c_ar', v_next_q.option_c_ar,
          'option_d_ar', v_next_q.option_d_ar,
          'difficulty',  v_next_q.difficulty
        )
      );
    end if;

  else
    -- ── Wrong answer ─────────────────────────────────────────────────────────

    -- Check second chance
    if v_run.second_chance_active then
      -- Give another attempt; don't record or reveal correct answer
      update public.gold_ladder_runs
      set second_chance_active = false
      where id = p_run_id;

      return jsonb_build_object(
        'correct',          false,
        'correct_option',   null,  -- not revealed yet
        'question_number',  v_run.current_question_num,
        'is_eliminated',    false,
        'is_completed',     false,
        'second_chance_triggered', true,
        'current_prize',    (v_run.entry_fee * v_prizes[v_run.current_question_num])::integer
      );
    end if;

    -- Record wrong answer
    insert into public.gold_ladder_answers
      (run_id, question_id, question_number, selected_option, is_correct)
    values (p_run_id, p_question_id, v_run.current_question_num, p_selected_option, false);

    -- Pay out safe amount
    if v_run.highest_safe_question = 5 then
      v_cashout := (v_run.entry_fee * 5)::integer;
    elsif v_run.highest_safe_question = 10 then
      v_cashout := (v_run.entry_fee * 30)::integer;
    else
      v_cashout := 0;
    end if;

    if v_cashout > 0 then
      update public.wallets
      set coins_balance = coins_balance + v_cashout, updated_at = now()
      where user_id = v_user_id
      returning coins_balance into v_new_balance;

      insert into public.wallet_transactions
        (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
      values
        (v_user_id, 'gold_ladder_safe_payout', 'credit', v_cashout, 0,
         'Gold Ladder Quiz — safe point payout',
         jsonb_build_object('run_id', p_run_id, 'safe_q', v_run.highest_safe_question));
    else
      select coins_balance into v_new_balance
      from public.wallets where user_id = v_user_id;
    end if;

    update public.gold_ladder_runs
    set status = 'eliminated', cashout_amount = v_cashout
    where id = p_run_id;

    return jsonb_build_object(
      'correct',         false,
      'correct_option',  v_q.correct_option,
      'explanation',     v_q.explanation,
      'question_number', v_run.current_question_num,
      'is_eliminated',   true,
      'is_completed',    false,
      'second_chance_triggered', false,
      'cashout_amount',  v_cashout,
      'new_balance',     v_new_balance,
      'current_prize',   (v_run.entry_fee * v_prizes[v_run.current_question_num])::integer
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."answer_gold_ladder_question"("p_run_id" "uuid", "p_question_id" "uuid", "p_selected_option" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_to_become_host"("p_message" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_experience" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_uid uuid := auth.uid(); v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if exists (select 1 from public.agency_applications where user_id = v_uid and application_type = 'become_host' and status = 'pending')
    then raise exception 'duplicate_pending_application'; end if;
  insert into public.agency_applications (user_id, application_type, status, message, phone, country, experience)
  values (v_uid, 'become_host', 'pending', p_message, p_phone, p_country, p_experience) returning id into v_id;
  perform public._agency_audit(v_uid, 'application_submitted', null, v_uid, v_id, jsonb_build_object('type','become_host'));
  return v_id;
end; $$;


ALTER FUNCTION "public"."apply_to_become_host"("p_message" "text", "p_phone" "text", "p_country" "text", "p_experience" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_to_create_agency"("p_message" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_experience" "text" DEFAULT NULL::"text", "p_agency_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_name text := nullif(trim(coalesce(p_agency_name, '')), '');
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text, 0));
  if v_name is null or length(v_name) not between 3 and 80 then
    raise exception 'invalid_agency_name';
  end if;
  if exists (
    select 1 from public.agencies
    where owner_user_id = v_uid and status in ('pending', 'active')
  ) then
    raise exception 'agency_already_owned';
  end if;
  if exists (
    select 1 from public.agency_applications
    where user_id = v_uid
      and application_type = 'create_agency'
      and status = 'pending'
  ) then
    raise exception 'duplicate_pending_application';
  end if;

  insert into public.agency_applications (
    user_id, application_type, agency_name, status,
    message, phone, country, experience
  )
  values (
    v_uid, 'create_agency', v_name, 'pending',
    p_message, p_phone, p_country, p_experience
  )
  returning id into v_id;

  perform public._agency_audit(
    v_uid, 'application_submitted', null, v_uid, v_id,
    jsonb_build_object('type', 'create_agency')
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."apply_to_create_agency"("p_message" "text", "p_phone" "text", "p_country" "text", "p_experience" "text", "p_agency_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_to_join_agency"("p_agency_code" "text", "p_message" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_experience" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_uid uuid := auth.uid(); v_agency public.agencies; v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_agency_code is null or length(trim(p_agency_code)) = 0 then raise exception 'agency_code_required'; end if;
  select * into v_agency from public.agencies where agency_code = upper(trim(p_agency_code)) and status = 'active';
  if v_agency.id is null then raise exception 'invalid_or_inactive_agency'; end if;
  if v_agency.owner_user_id = v_uid then raise exception 'cannot_join_own_agency'; end if;
  if exists (select 1 from public.agency_applications where user_id = v_uid and application_type = 'join_agency' and status = 'pending')
    then raise exception 'duplicate_pending_application'; end if;
  insert into public.agency_applications (user_id, agency_id, application_type, status, message, phone, country, experience)
  values (v_uid, v_agency.id, 'join_agency', 'pending', p_message, p_phone, p_country, p_experience) returning id into v_id;
  perform public._agency_audit(v_uid, 'application_submitted', v_agency.id, v_uid, v_id, jsonb_build_object('type','join_agency','code',v_agency.agency_code));
  return v_id;
end; $$;


ALTER FUNCTION "public"."apply_to_join_agency"("p_agency_code" "text", "p_message" "text", "p_phone" "text", "p_country" "text", "p_experience" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_vip_recharge_exp"("p_user_id" "uuid", "p_recharged_coins" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now              timestamptz := now();
  v_new_lifetime     bigint;
  v_new_monthly      bigint;
  v_monthly_before   bigint;   -- monthly EXP before this recharge (for threshold-crossing check)
  v_current_level    int;
  v_current_exp      timestamptz;
  v_earned_tier      int := 0;
  v_maintain_exp     bigint;
  v_new_expires      timestamptz;
BEGIN
  -- Guard: nothing to do for zero or negative coins
  IF p_recharged_coins <= 0 THEN
    RETURN;
  END IF;

  -- ── a+b+c  Accumulate EXP ─────────────────────────────────────────────────
  UPDATE public.profiles
  SET
    vip_recharge_exp     = vip_recharge_exp + p_recharged_coins,
    vip_monthly_exp      = vip_monthly_exp  + p_recharged_coins,
    vip_last_recharge_at = v_now,
    vip_cycle_started_at = COALESCE(vip_cycle_started_at, v_now)
  WHERE id = p_user_id
  RETURNING vip_recharge_exp, vip_monthly_exp, vip_level, vip_expires_at
  INTO v_new_lifetime, v_new_monthly, v_current_level, v_current_exp;

  -- User row must exist; if not, silently exit (no profile = no VIP to grant)
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Derive what monthly EXP was immediately before this recharge
  v_monthly_before := v_new_monthly - p_recharged_coins;

  -- ── d  Find highest earned tier ───────────────────────────────────────────
  SELECT COALESCE(MAX(level), 0)
  INTO   v_earned_tier
  FROM   public.vip_levels
  WHERE  is_active = true
    AND  required_recharge_exp IS NOT NULL
    AND  required_recharge_exp <= v_new_lifetime;

  -- No tier earned yet — nothing more to do
  IF v_earned_tier = 0 THEN
    RETURN;
  END IF;

  -- ── e  Upgrade path (earned_tier > current level) ─────────────────────────
  IF v_earned_tier > COALESCE(v_current_level, 0) THEN

    v_new_expires := v_now + interval '30 days';

    -- Deactivate any current recharge-exp subscriptions (not admin grants)
    UPDATE public.user_vip_subscriptions
    SET    is_active = false
    WHERE  user_id = p_user_id
      AND  is_active = true
      AND  payment_source = 'recharge_exp';

    -- Update profile
    UPDATE public.profiles
    SET
      vip_level      = v_earned_tier,
      vip_started_at = v_now,
      vip_expires_at = v_new_expires
    WHERE id = p_user_id;

    -- Subscription audit row
    -- ends_at mirrors expires_at (original NOT NULL column, kept in sync)
    INSERT INTO public.user_vip_subscriptions
      (user_id, vip_level, started_at, expires_at, ends_at, is_active, payment_source)
    VALUES
      (p_user_id, v_earned_tier, v_now, v_new_expires, v_new_expires, true, 'recharge_exp');

    RETURN;
  END IF;

  -- ── f  Renewal path (earned_tier = current level, monthly EXP threshold
  --       crossed by THIS recharge) ───────────────────────────────────────────
  --
  -- The threshold-crossing guard (v_monthly_before < v_maintain_exp AND
  -- v_new_monthly >= v_maintain_exp) ensures renewal fires exactly ONCE per
  -- cycle — the moment the user's monthly EXP crosses the maintain threshold.
  -- Subsequent recharges in the same cycle leave the expiry unchanged until
  -- Phase J resets vip_monthly_exp at the start of a new cycle.
  IF v_earned_tier = COALESCE(v_current_level, 0) THEN

    -- Look up the maintain threshold for this tier
    SELECT COALESCE(monthly_maintain_exp, required_recharge_exp, 0)
    INTO   v_maintain_exp
    FROM   public.vip_levels
    WHERE  level = v_earned_tier
      AND  is_active = true
    LIMIT  1;

    -- Only renew when this specific recharge crosses the threshold
    IF v_monthly_before < v_maintain_exp AND v_new_monthly >= v_maintain_exp THEN

      -- Extend from max(current expiry, now) to avoid shrinking a long-running grant
      v_new_expires := GREATEST(COALESCE(v_current_exp, v_now), v_now)
                       + interval '30 days';

      UPDATE public.profiles
      SET    vip_expires_at = v_new_expires
      WHERE  id = p_user_id;

      -- Deactivate old recharge-exp subscription for this tier (if any)
      UPDATE public.user_vip_subscriptions
      SET    is_active = false
      WHERE  user_id = p_user_id
        AND  is_active = true
        AND  payment_source = 'recharge_exp'
        AND  vip_level = v_earned_tier;

      -- Subscription audit row
      -- ends_at mirrors expires_at (original NOT NULL column, kept in sync)
      INSERT INTO public.user_vip_subscriptions
        (user_id, vip_level, started_at, expires_at, ends_at, is_active, payment_source)
      VALUES
        (p_user_id, v_earned_tier, v_now, v_new_expires, v_new_expires, true, 'recharge_exp');

    END IF;
  END IF;

  -- ── g  No downgrade — tiers above earned are left untouched ───────────────
  -- (expire_old_vips handles expiry for admin-granted levels the user no longer earns)
END;
$$;


ALTER FUNCTION "public"."apply_vip_recharge_exp"("p_user_id" "uuid", "p_recharged_coins" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_payout_request"("p_request_id" "uuid", "p_admin_reply" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request public.payout_requests;
  v_account public.income_accounts;
begin
  if v_admin_id is null then
    raise exception 'not_authenticated';
  end if;
  if not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select * into v_request from public.payout_requests where id = p_request_id for update;
  if not found then
    raise exception 'payout_request_not_found';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'payout_request_not_pending';
  end if;

  select * into v_account from public.income_accounts where user_id = v_request.user_id for update;
  if coalesce(v_account.pending_balance_usd, 0) < v_request.amount_usd then
    raise exception 'pending_balance_mismatch';
  end if;

  update public.income_accounts
  set pending_balance_usd = pending_balance_usd - v_request.amount_usd,
      updated_at = now()
  where user_id = v_request.user_id;

  update public.payout_requests
  set status = 'paid',
      admin_reply = nullif(trim(coalesce(p_admin_reply, '')), ''),
      updated_at = now()
  where id = v_request.id;

  perform public.admin_record_audit(
    'approve_payout', 'payout_requests', v_request.id::text, v_request.user_id,
    jsonb_build_object('amount_usd', v_request.amount_usd, 'method', v_request.method)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."approve_payout_request"("p_request_id" "uuid", "p_admin_reply" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_recharge_request"("p_request_id" "uuid", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
  v_request  public.recharge_requests;
  v_wallet   public.wallets;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF NOT public.has_finance_access() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  SELECT *
  INTO   v_request
  FROM   public.recharge_requests rr
  WHERE  rr.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recharge_request_not_found';
  END IF;

  -- Double-apply guard: only pending requests can be approved
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'recharge_request_not_pending';
  END IF;

  -- ── Coin credit (unchanged) ───────────────────────────────────────────────

  INSERT INTO public.wallets (user_id)
  VALUES (v_request.user_id)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.wallets
  SET    coins_balance          = coins_balance          + v_request.requested_coins,
         lifetime_coins_charged = lifetime_coins_charged + v_request.requested_coins,
         updated_at             = now()
  WHERE  user_id = v_request.user_id
  RETURNING * INTO v_wallet;

  UPDATE public.recharge_requests
  SET    status        = 'approved',
         admin_user_id = v_admin_id,
         admin_note    = NULLIF(TRIM(COALESCE(p_admin_note, '')), ''),
         approved_at   = now(),
         updated_at    = now()
  WHERE  id = v_request.id;

  INSERT INTO public.wallet_transactions (
    user_id,
    type,
    direction,
    coins_delta,
    balance_coins_after,
    balance_diamonds_after,
    related_recharge_request_id,
    agency_id,
    agent_id,
    note
  )
  VALUES (
    v_request.user_id,
    CASE WHEN v_request.agent_id IS NULL THEN 'recharge_request' ELSE 'agency_recharge' END,
    'credit',
    v_request.requested_coins,
    v_wallet.coins_balance,
    v_wallet.diamonds_balance,
    v_request.id,
    v_request.agency_id,
    v_request.agent_id,
    p_admin_note
  );

  -- ── VIP EXP hook ─────────────────────────────────────────────────────────
  PERFORM public.apply_vip_recharge_exp(
    v_request.user_id,
    v_request.requested_coins::bigint
  );

  -- ── Wealth XP side-effect ─────────────────────────────────────────────────
  -- 1 recharged coin = 1 wealth XP.
  -- Swallowed so it can never break the recharge approval.
  BEGIN
    PERFORM public.add_wealth_xp(
      v_request.user_id,
      v_request.requested_coins::bigint,
      'recharge'
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."approve_recharge_request"("p_request_id" "uuid", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_recharge_transaction"("p_transaction_id" "uuid", "p_payment_reference" "text" DEFAULT NULL::"text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
  v_tx       public.recharge_transactions;
  v_wallet   public.user_wallets;
  v_before   bigint;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF NOT public.has_finance_access() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  SELECT *
  INTO   v_tx
  FROM   public.recharge_transactions
  WHERE  id = p_transaction_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'recharge_transaction_not_found';
  END IF;

  -- Double-apply guard: only pending transactions can be approved
  IF v_tx.status <> 'pending' THEN
    RAISE EXCEPTION 'recharge_transaction_not_pending';
  END IF;

  -- ── Coin credit (unchanged) ───────────────────────────────────────────────

  PERFORM public.ensure_user_wallet(v_tx.user_id);

  SELECT *
  INTO   v_wallet
  FROM   public.user_wallets
  WHERE  user_id = v_tx.user_id
  FOR UPDATE;

  v_before := v_wallet.coin_balance;

  UPDATE public.user_wallets
  SET    coin_balance          = coin_balance          + v_tx.total_coins,
         total_recharged_usd   = total_recharged_usd   + v_tx.price_usd,
         total_recharged_coins = total_recharged_coins + v_tx.total_coins,
         updated_at            = now()
  WHERE  user_id = v_tx.user_id
  RETURNING * INTO v_wallet;

  -- Sync legacy wallets table (unchanged)
  INSERT INTO public.wallets (user_id)
  VALUES (v_tx.user_id)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.wallets
  SET    coins_balance          = v_wallet.coin_balance::integer,
         diamonds_balance       = v_wallet.diamond_balance::integer,
         lifetime_coins_charged = v_wallet.total_recharged_coins::integer,
         updated_at             = now()
  WHERE  user_id = v_tx.user_id;

  UPDATE public.recharge_transactions
  SET    status            = 'approved',
         payment_reference = COALESCE(
           NULLIF(TRIM(COALESCE(p_payment_reference, '')), ''),
           payment_reference
         ),
         admin_note        = NULLIF(TRIM(COALESCE(p_admin_note, '')), ''),
         approved_at       = now(),
         approved_by       = v_admin_id
  WHERE  id = v_tx.id;

  INSERT INTO public.coin_transactions (
    user_id,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    source_type,
    source_id,
    description,
    created_by
  )
  VALUES (
    v_tx.user_id,
    'recharge',
    v_tx.total_coins,
    v_before,
    v_wallet.coin_balance,
    'recharge_transactions',
    v_tx.id,
    'Recharge approved',
    v_admin_id
  );

  -- ── VIP EXP hook (new) ────────────────────────────────────────────────────
  -- Uses total_coins (coins_amount + bonus_coins) — the full credited amount.
  -- This mirrors how lifetime_coins_charged / total_recharged_coins are updated
  -- above, so EXP accounting stays consistent with the wallet.

  PERFORM public.apply_vip_recharge_exp(
    v_tx.user_id,
    v_tx.total_coins
  );

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."approve_recharge_transaction"("p_transaction_id" "uuid", "p_payment_reference" "text", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."are_mutual_friends"("user_a" "uuid", "user_b" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_follows
    WHERE follower_id = user_a AND following_id = user_b
  ) AND EXISTS (
    SELECT 1 FROM public.user_follows
    WHERE follower_id = user_b AND following_id = user_a
  );
$$;


ALTER FUNCTION "public"."are_mutual_friends"("user_a" "uuid", "user_b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arm_crash_bet"("p_amount" integer, "p_slot_index" integer DEFAULT 0) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         uuid    := auth.uid();
  v_balance     integer;
  v_bet_id      uuid;
  v_new_balance integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_amount <= 0    THEN RAISE EXCEPTION 'invalid_amount';  END IF;

  SELECT coins_balance INTO v_balance
  FROM wallets WHERE user_id = v_uid FOR UPDATE;

  IF NOT FOUND             THEN RAISE EXCEPTION 'wallet_not_found';    END IF;
  IF v_balance < p_amount  THEN RAISE EXCEPTION 'insufficient_coins';  END IF;

  UPDATE wallets
  SET    coins_balance = coins_balance - p_amount
  WHERE  user_id = v_uid;

  v_new_balance := v_balance - p_amount;

  INSERT INTO crash_bets (user_id, bet_amount, mode, status)
  VALUES (v_uid, p_amount, 'manual', 'pending')
  RETURNING id INTO v_bet_id;

  RETURN json_build_object(
    'bet_id',      v_bet_id,
    'new_balance', v_new_balance
  );
END;
$$;


ALTER FUNCTION "public"."arm_crash_bet"("p_amount" integer, "p_slot_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_room_team_pk_member"("p_pk_session_id" "uuid", "p_user_id" "uuid", "p_team" "text", "p_seat_index" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_session   public.room_team_pk_sessions;
  v_member    public.room_team_pk_members;
begin
  if v_caller_id is null then raise exception 'not_authenticated'; end if;
  if p_team not in ('a', 'b')   then raise exception 'invalid_team'; end if;

  select * into v_session
  from public.room_team_pk_sessions
  where id = p_pk_session_id;

  if v_session is null then raise exception 'session_not_found'; end if;
  if v_session.status <> 'active' then raise exception 'session_not_active'; end if;

  if not public.is_room_manager(v_session.room_id, v_caller_id) then
    raise exception 'not_authorized';
  end if;

  insert into public.room_team_pk_members (
    pk_session_id, room_id, user_id, seat_index, team, assigned_by
  ) values (
    p_pk_session_id, v_session.room_id, p_user_id, p_seat_index, p_team, v_caller_id
  )
  on conflict (pk_session_id, user_id) do update
    set team       = excluded.team,
        seat_index = coalesce(excluded.seat_index, room_team_pk_members.seat_index),
        assigned_by = excluded.assigned_by,
        updated_at  = now()
  returning * into v_member;

  return row_to_json(v_member)::jsonb;
end;
$$;


ALTER FUNCTION "public"."assign_room_team_pk_member"("p_pk_session_id" "uuid", "p_user_id" "uuid", "p_team" "text", "p_seat_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ban_room_member"("p_room_id" "uuid", "p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_owner  uuid;
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;

  select owner_id into v_owner from public.rooms where id = p_room_id;

  if v_owner is null then
    raise exception 'room_not_found';
  end if;

  if v_owner != v_caller then
    raise exception 'not_room_owner';
  end if;

  if p_user_id = v_caller then
    raise exception 'cannot_ban_self';
  end if;

  insert into public.room_bans (room_id, user_id, banned_by, reason, expires_at)
  values (p_room_id, p_user_id, v_caller, p_reason, p_expires_at)
  on conflict (room_id, user_id) do update
    set reason     = excluded.reason,
        expires_at = excluded.expires_at,
        banned_by  = excluded.banned_by,
        created_at = now();

  -- Kick from room if currently present
  update public.room_members
  set is_muted = true, seat_number = null,
      left_at = now(), last_seen_at = now(), updated_at = now()
  where room_id = p_room_id and user_id = p_user_id and left_at is null;
end;
$$;


ALTER FUNCTION "public"."ban_room_member"("p_room_id" "uuid", "p_user_id" "uuid", "p_reason" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ban_room_member"("p_room_id" "uuid", "p_user_id" "uuid", "p_reason" "text", "p_expires_at" timestamp with time zone) IS 'Room owner bans a user. Auto-kicks them if present. Verifies ownership.';



CREATE OR REPLACE FUNCTION "public"."block_user"("p_blocked_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;
  if p_blocked_id is null or p_blocked_id = v_user_id then
    raise exception 'invalid_target';
  end if;

  insert into public.user_blocks (blocker_id, blocked_id)
  values (v_user_id, p_blocked_id)
  on conflict (blocker_id, blocked_id) do nothing;

  -- Remove any follow relationship in both directions.
  delete from public.user_follows
  where (follower_id = v_user_id and following_id = p_blocked_id)
     or (follower_id = p_blocked_id and following_id = v_user_id);
end;
$$;


ALTER FUNCTION "public"."block_user"("p_blocked_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_prediction_points"("p_match_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match     wc_matches%ROWTYPE;
  v_settings  prediction_settings%ROWTYPE;
  v_actual_winner text;
  v_pred      wc_predictions%ROWTYPE;
  v_pts       integer;
  v_result    text;
  v_updated   integer := 0;
BEGIN
  SELECT * INTO v_match FROM wc_matches WHERE id = p_match_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Match not found');
  END IF;
  IF v_match.status != 'completed' OR v_match.home_score IS NULL OR v_match.away_score IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Match not completed or missing scores');
  END IF;

  SELECT * INTO v_settings FROM prediction_settings WHERE id = 1;
  IF NOT FOUND THEN
    v_settings.winner_points     := 3;
    v_settings.draw_points       := 3;
    v_settings.exact_score_bonus := 5;
    v_settings.stacking_mode     := 'exact_score_plus_winner';
  END IF;

  IF v_match.home_score > v_match.away_score THEN
    v_actual_winner := 'home';
  ELSIF v_match.home_score < v_match.away_score THEN
    v_actual_winner := 'away';
  ELSE
    v_actual_winner := 'draw';
  END IF;

  FOR v_pred IN
    SELECT * FROM wc_predictions
    WHERE match_id = p_match_id AND result_status = 'pending'
  LOOP
    v_pts    := 0;
    v_result := 'wrong';

    IF v_pred.home_score = v_match.home_score AND v_pred.away_score = v_match.away_score THEN
      v_result := 'correct_exact';
      CASE v_settings.stacking_mode
        WHEN 'exact_score_only' THEN
          v_pts := v_settings.exact_score_bonus;
        ELSE
          v_pts := (CASE WHEN v_actual_winner = 'draw' THEN v_settings.draw_points ELSE v_settings.winner_points END)
                   + v_settings.exact_score_bonus;
      END CASE;
    ELSIF v_pred.predicted_winner = v_actual_winner THEN
      v_result := 'correct_winner';
      IF v_settings.stacking_mode != 'exact_score_only' THEN
        v_pts := CASE WHEN v_actual_winner = 'draw' THEN v_settings.draw_points ELSE v_settings.winner_points END;
      END IF;
    END IF;

    v_pts := ROUND(v_pts * v_match.bonus_multiplier);

    UPDATE wc_predictions
    SET points_awarded = v_pts, result_status = v_result, updated_at = now()
    WHERE id = v_pred.id;

    IF v_pts > 0 THEN
      PERFORM increment_points(v_pred.phone, v_pts);
    END IF;

    v_updated := v_updated + 1;
  END LOOP;

  UPDATE wc_matches SET points_calculated = true, updated_at = now() WHERE id = p_match_id;

  RETURN jsonb_build_object('ok', true, 'predictions_processed', v_updated);
END;
$$;


ALTER FUNCTION "public"."calculate_prediction_points"("p_match_id" "text") OWNER TO "postgres";


