CREATE OR REPLACE FUNCTION "public"."cancel_room_game_round"("p_round_id" "uuid", "p_reason" "text" DEFAULT 'cancelled_by_host'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid           uuid := auth.uid();
  v_round         record;
  v_bet           record;
  v_refunded_bets int     := 0;
  v_total_refund  bigint  := 0;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select r.* into v_round
  from public.room_game_rounds r
  where r.id = p_round_id
  for update;

  if not found then raise exception 'round_not_found'; end if;

  if not exists (
    select 1 from public.rooms where id = v_round.room_id and owner_id = v_uid
  ) then
    raise exception 'not_room_host';
  end if;

  if v_round.status in ('finished','cancelled') then
    raise exception 'round_already_ended';
  end if;

  -- Refund all non-settled bets
  for v_bet in
    select * from public.room_game_bets
    where round_id = p_round_id
      and status in ('pending','running')
    for update
  loop
    update public.room_game_bets
    set status = 'refunded', settled_at = now()
    where id = v_bet.id;

    update public.wallets
    set coins_balance = coins_balance + v_bet.bet_amount, updated_at = now()
    where user_id = v_bet.user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_bet.user_id, 'room_game_refund', 'credit', v_bet.bet_amount, 0,
       'Room game refund Ã¢â‚¬â€ ' || p_reason,
       jsonb_build_object('round_id', p_round_id, 'bet_id', v_bet.id));

    v_refunded_bets  := v_refunded_bets + 1;
    v_total_refund   := v_total_refund + v_bet.bet_amount;
  end loop;

  update public.room_game_rounds
  set status      = 'cancelled',
      finished_at = now(),
      updated_at  = now(),
      result_json = jsonb_build_object('cancelled', true, 'reason', p_reason)
  where id = p_round_id;

  return jsonb_build_object(
    'ok',             true,
    'refunded_bets',  v_refunded_bets,
    'total_refund',   v_total_refund
  );
end;
$$;


ALTER FUNCTION "public"."cancel_room_game_round"("p_round_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_room_team_pk"("p_pk_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_session   public.room_team_pk_sessions;
begin
  if v_caller_id is null then raise exception 'not_authenticated'; end if;

  select * into v_session
  from public.room_team_pk_sessions
  where id = p_pk_session_id;

  if v_session is null     then raise exception 'session_not_found'; end if;
  if v_session.status <> 'active' then
    -- Already resolved — return current state.
    return row_to_json(v_session)::jsonb;
  end if;

  if not public.is_room_manager(v_session.room_id, v_caller_id) then
    raise exception 'not_authorized';
  end if;

  update public.room_team_pk_sessions
  set status      = 'cancelled',
      finished_at = now(),
      updated_at  = now()
  where id = p_pk_session_id
  returning * into v_session;

  return row_to_json(v_session)::jsonb;
end;
$$;


ALTER FUNCTION "public"."cancel_room_team_pk"("p_pk_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cash_out_rocket_crash_bet"("p_bet_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_bet         public.rocket_crash_global_bets;
  v_round       public.rocket_crash_global_rounds;
  v_elapsed     numeric;
  v_current_m   numeric;
  v_win         integer;
  v_new_balance integer;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- Fetch bet (not locked yet — just to get round_id)
  select * into v_bet
  from public.rocket_crash_global_bets
  where id = p_bet_id and user_id = v_uid;

  if not found then raise exception 'bet_not_found'; end if;

  -- Lock round first to prevent deadlock with settle (settle also locks round)
  select * into v_round
  from public.rocket_crash_global_rounds
  where id = v_bet.round_id for update;

  if v_round.id is null then raise exception 'round_not_found'; end if;

  -- Now lock the bet row
  select * into v_bet
  from public.rocket_crash_global_bets
  where id = p_bet_id and user_id = v_uid for update;

  -- Idempotent: already settled
  if v_bet.status <> 'active' then
    return json_build_object(
      'status',             v_bet.status,
      'cashout_multiplier', v_bet.cashout_multiplier,
      'win_amount',         v_bet.win_amount
    );
  end if;

  -- Round crashed before cashout arrived
  if v_round.status = 'crashed' then
    update public.rocket_crash_global_bets set status = 'lost' where id = p_bet_id;
    return json_build_object('status', 'lost', 'cashout_multiplier', null, 'win_amount', 0);
  end if;

  if v_round.status <> 'flying' then raise exception 'round_not_flying'; end if;

  -- Server-calculated multiplier: exp(0.055 * elapsed_seconds)
  v_elapsed   := greatest(0, extract(epoch from (now() - v_round.flight_starts_at)));
  v_current_m := round(exp(0.055 * v_elapsed)::numeric, 2);

  -- Cashout arrived after crash point (race with settle)
  if v_current_m >= v_round.crash_multiplier then
    update public.rocket_crash_global_bets set status = 'lost' where id = p_bet_id;
    return json_build_object('status', 'lost', 'cashout_multiplier', null, 'win_amount', 0);
  end if;

  v_win := floor(v_bet.bet_amount * v_current_m)::integer;

  update public.rocket_crash_global_bets
  set status             = 'cashed_out',
      cashout_multiplier = v_current_m,
      win_amount         = v_win,
      cashed_out_at      = now()
  where id = p_bet_id;

  update public.wallets
  set coins_balance = coins_balance + v_win, updated_at = now()
  where user_id = v_uid
  returning coins_balance into v_new_balance;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_uid, 'crash_rocket_win', 'credit', v_win, 0,
     'Rocket Crash cashout at ' || v_current_m || '×',
     jsonb_build_object('bet_id', p_bet_id, 'round_id', v_bet.round_id, 'multiplier', v_current_m));

  return json_build_object(
    'status',             'cashed_out',
    'cashout_multiplier', v_current_m,
    'win_amount',         v_win,
    'new_balance',        v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."cash_out_rocket_crash_bet"("p_bet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cashout_crash_bet"("p_bet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id      uuid := auth.uid();
  v_bet          public.crash_bets%rowtype;
  v_started_at   timestamptz;
  v_crash_at     numeric;
  v_round_status text;
  v_elapsed      numeric;
  v_current_m    numeric;
  v_win          integer;
  v_new_balance  integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  -- Lock the bet row to prevent concurrent cashouts
  select * into v_bet
  from public.crash_bets
  where id = p_bet_id and user_id = v_user_id
  for update;

  if not found then raise exception 'bet_not_found'; end if;

  -- Idempotent: already settled
  if v_bet.status != 'running' then
    return jsonb_build_object(
      'status',             v_bet.status,
      'cashout_multiplier', v_bet.cashout_multiplier,
      'win_amount',         coalesce(v_bet.win_amount, 0)
    );
  end if;

  -- Fetch round metadata (no lock needed here — we have the bet lock)
  select crash_multiplier, started_at, status
  into v_crash_at, v_started_at, v_round_status
  from public.crash_rounds
  where id = v_bet.round_id;

  -- Compute server-side multiplier using same formula as client
  v_elapsed   := greatest(0, extract(epoch from (now() - v_started_at)));
  v_current_m := round(exp(0.15 * v_elapsed)::numeric, 2);

  -- Crashed before cashout request arrived
  if v_round_status = 'crashed' or v_current_m >= v_crash_at then
    update public.crash_bets
    set status = 'lost', win_amount = 0
    where id = p_bet_id;

    return jsonb_build_object(
      'status',             'lost',
      'cashout_multiplier', null,
      'win_amount',         0
    );
  end if;

  -- Cash out at current server multiplier
  v_win := floor(v_bet.bet_amount * v_current_m)::integer;

  update public.crash_bets
  set status             = 'cashed_out',
      cashout_multiplier = v_current_m,
      win_amount         = v_win
  where id = p_bet_id;

  update public.wallets
  set coins_balance = coins_balance + v_win, updated_at = now()
  where user_id = v_user_id
  returning coins_balance into v_new_balance;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'crash_rocket_win', 'credit', v_win, 0,
     'Crash Rocket cashout at ' || v_current_m || '×',
     jsonb_build_object('round_id', v_bet.round_id, 'bet_id', p_bet_id,
                        'multiplier', v_current_m));

  return jsonb_build_object(
    'status',             'cashed_out',
    'cashout_multiplier', v_current_m,
    'win_amount',         v_win,
    'new_balance',        v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."cashout_crash_bet"("p_bet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cashout_crash_bet_local"("p_bet_id" "uuid", "p_multiplier" numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_bet         crash_bets;
  v_win_amount  integer;
  v_new_balance integer;
BEGIN
  IF v_uid IS NULL       THEN RAISE EXCEPTION 'not_authenticated';  END IF;
  IF p_multiplier < 1.0  THEN RAISE EXCEPTION 'invalid_multiplier'; END IF;

  SELECT * INTO v_bet
  FROM crash_bets
  WHERE id = p_bet_id AND user_id = v_uid
  FOR UPDATE;

  IF NOT FOUND                            THEN RAISE EXCEPTION 'bet_not_found';       END IF;
  IF v_bet.status NOT IN ('pending','running')
                                          THEN RAISE EXCEPTION 'bet_already_settled'; END IF;

  v_win_amount := floor(v_bet.bet_amount::numeric * p_multiplier)::integer;

  UPDATE wallets
  SET    coins_balance = coins_balance + v_win_amount
  WHERE  user_id = v_uid
  RETURNING coins_balance INTO v_new_balance;

  UPDATE crash_bets
  SET    status             = 'cashed_out',
         cashout_multiplier = p_multiplier,
         win_amount         = v_win_amount
  WHERE  id = p_bet_id;

  RETURN json_build_object(
    'win_amount',  v_win_amount,
    'new_balance', v_new_balance,
    'multiplier',  p_multiplier
  );
END;
$$;


ALTER FUNCTION "public"."cashout_crash_bet_local"("p_bet_id" "uuid", "p_multiplier" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cashout_crash_rocket_bet"("p_bet_id" "uuid", "p_client_cashout_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_bet public.crash_rocket_bets;
  v_round public.crash_rocket_rounds;
  v_secret public.crash_rocket_round_secrets;
  v_now timestamptz := clock_timestamp();
  v_multiplier numeric;
  v_payout integer;
  v_balance integer;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if length(trim(coalesce(p_client_cashout_id,''))) not between 8 and 100 then
    raise exception 'invalid_client_cashout_id';
  end if;
  select * into v_bet from public.crash_rocket_bets where id=p_bet_id for update;
  if v_bet.id is null or v_bet.user_id<>v_uid then raise exception 'bet_not_found'; end if;
  if v_bet.status='cashed_out' then
    select coins_balance into v_balance from public.wallets where user_id=v_uid;
    return jsonb_build_object('bet',to_jsonb(v_bet),
      'wallet_balance',coalesce(v_balance,0),'idempotent',true);
  end if;
  if v_bet.status<>'placed' then raise exception 'bet_not_cashable'; end if;

  select * into v_round from public.crash_rocket_rounds
  where id=v_bet.round_id for update;
  select * into v_secret from public.crash_rocket_round_secrets
  where round_id=v_round.id for update;
  if v_round.status<>'flying' or v_now>=v_secret.target_crashed_at then
    perform public.advance_crash_rocket_round(v_round.room_id);
    raise exception 'round_crashed';
  end if;
  v_multiplier := least(v_secret.target_multiplier,
    public._crash_rocket_multiplier_at(v_round.fly_started_at,v_now));
  v_payout := floor(v_bet.amount*v_multiplier)::integer;
  update public.wallets set coins_balance=coins_balance+v_payout,updated_at=v_now
  where user_id=v_uid returning coins_balance into v_balance;
  update public.crash_rocket_bets set
    status='cashed_out',cashout_multiplier=v_multiplier,payout_amount=v_payout,
    client_cashout_id=trim(p_client_cashout_id),cashed_out_at=v_now
  where id=v_bet.id returning * into v_bet;
  insert into public.wallet_transactions(
    user_id,type,direction,coins_delta,diamonds_delta,
    balance_coins_after,note,metadata
  ) values (
    v_uid,'crash_rocket_cashout','credit',v_payout,0,v_balance,
    'Srood Rocket cashout',jsonb_build_object(
      'round_id',v_round.id,'bet_id',v_bet.id,'multiplier',v_multiplier
    )
  );
  insert into public.crash_rocket_round_events(round_id,event_type,payload)
  values (v_round.id,'bet_cashed_out',jsonb_build_object(
    'bet_id',v_bet.id,'user_id',v_uid,'payout_amount',v_payout,
    'cashout_multiplier',v_multiplier
  ));
  return jsonb_build_object('bet',to_jsonb(v_bet),
    'wallet_balance',v_balance,'idempotent',false);
exception when unique_violation then
  select * into v_bet from public.crash_rocket_bets
  where user_id=v_uid and client_cashout_id=p_client_cashout_id;
  select coins_balance into v_balance from public.wallets where user_id=v_uid;
  return jsonb_build_object('bet',to_jsonb(v_bet),
    'wallet_balance',coalesce(v_balance,0),'idempotent',true);
end;
$$;


ALTER FUNCTION "public"."cashout_crash_rocket_bet"("p_bet_id" "uuid", "p_client_cashout_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cashout_crash_rocket_bet"("p_bet_id" "uuid", "p_client_cashout_id" "text") IS 'Atomic idempotent server-time cashout; client multiplier is never accepted.';



CREATE OR REPLACE FUNCTION "public"."cashout_gold_ladder_run"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_run         public.gold_ladder_runs;
  v_cashout     integer;
  v_new_balance integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  select * into v_run
  from public.gold_ladder_runs
  where id = p_run_id and user_id = v_user_id
  for update;

  if not found then raise exception 'run_not_found'; end if;
  if v_run.status != 'active' then raise exception 'run_not_active'; end if;

  if v_run.highest_safe_question = 5 then
    v_cashout := (v_run.entry_fee * 5)::integer;
  elsif v_run.highest_safe_question = 10 then
    v_cashout := (v_run.entry_fee * 30)::integer;
  else
    v_cashout := 0;
  end if;

  if v_cashout > 0 then
    update public.wallets
    set coins_balance = coins_balance + v_cashout, updated_at = now()
    where user_id = v_user_id
    returning coins_balance into v_new_balance;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_user_id, 'gold_ladder_safe_payout', 'credit', v_cashout, 0,
       'Gold Ladder Quiz — voluntary cash out',
       jsonb_build_object('run_id', p_run_id));
  else
    select coins_balance into v_new_balance
    from public.wallets where user_id = v_user_id;
  end if;

  update public.gold_ladder_runs
  set status = 'cashed_out', cashout_amount = v_cashout
  where id = p_run_id;

  return jsonb_build_object(
    'cashout_amount', v_cashout,
    'new_balance',    v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."cashout_gold_ladder_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cashout_room_crash_bet"("p_bet_id" "uuid", "p_multiplier" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid       uuid := auth.uid();
  v_bet       record;
  v_round     record;
  v_secret    record;
  v_current_m numeric(10,2);
  v_elapsed   float8;
  v_win       bigint;
  v_new_bal   bigint;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_multiplier < 1.0 then raise exception 'invalid_multiplier'; end if;

  select * into v_bet
  from public.room_game_bets
  where id = p_bet_id and user_id = v_uid
  for update;

  if not found then raise exception 'bet_not_found'; end if;
  if v_bet.status = 'cashed_out' then
    return jsonb_build_object('status', 'cashed_out', 'already_settled', true,
                              'payout_amount', v_bet.payout_amount);
  end if;
  if v_bet.status != 'running' then raise exception 'bet_not_cashable'; end if;

  select r.* into v_round
  from public.room_game_rounds r
  where r.id = v_bet.round_id;

  if v_round.status != 'running' then raise exception 'round_not_running'; end if;

  -- Compute server-authoritative current multiplier
  v_elapsed   := greatest(0, extract(epoch from (now() - v_round.started_at)));
  v_current_m := round(exp(0.15 * v_elapsed)::numeric, 2);

  -- Check pre-committed crash point
  select crash_multiplier into v_secret.crash_multiplier
  from public.room_game_round_secrets where round_id = v_bet.round_id;

  if v_current_m >= v_secret.crash_multiplier then
    -- Already crashed Ã¢â‚¬â€ mark as lost
    update public.room_game_bets
    set status = 'lost', payout_amount = 0, settled_at = now()
    where id = p_bet_id;
    return jsonb_build_object('status', 'lost', 'crash_multiplier', v_secret.crash_multiplier);
  end if;

  -- Client-submitted multiplier must not exceed server's current value (prevent cheating)
  declare v_safe_m numeric(10,2);
  begin
    v_safe_m := least(p_multiplier::numeric(10,2), v_current_m);
    v_win    := floor(v_bet.bet_amount::float * v_safe_m::float)::bigint;
  end;

  update public.room_game_bets
  set status             = 'cashed_out',
      cashout_multiplier = v_safe_m,
      payout_amount      = v_win,
      settled_at         = now()
  where id = p_bet_id;

  update public.wallets
  set coins_balance = coins_balance + v_win, updated_at = now()
  where user_id = v_uid
  returning coins_balance into v_new_bal;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_uid, 'room_game_win', 'credit', v_win, 0,
     'Room Crash cashout at ' || v_safe_m || 'Ãƒâ€”',
     jsonb_build_object('round_id', v_bet.round_id, 'bet_id', p_bet_id,
                        'multiplier', v_safe_m));

  return jsonb_build_object(
    'status',             'cashed_out',
    'cashout_multiplier', v_safe_m,
    'payout_amount',      v_win,
    'new_balance',        v_new_bal
  );
end;
$$;


ALTER FUNCTION "public"."cashout_room_crash_bet"("p_bet_id" "uuid", "p_multiplier" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charisma_get_active_challenges"("p_scope" "text" DEFAULT NULL::"text", "p_agency_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result  jsonb;
BEGIN
  -- Auto-activate scheduled challenges whose window has started
  UPDATE charisma_challenges
  SET status = 'active', updated_at = now()
  WHERE status = 'scheduled' AND starts_at <= now() AND ends_at > now();

  -- Auto-end active challenges whose window has closed
  UPDATE charisma_challenges
  SET status = 'ended', updated_at = now()
  WHERE status = 'active' AND ends_at < now();

  SELECT jsonb_agg(
    jsonb_build_object(
      'challenge', jsonb_build_object(
        'id',               c.id,
        'title',            c.title,
        'title_ar',         c.title_ar,
        'scope',            c.scope,
        'agency_id',        c.agency_id,
        'status',           c.status,
        'starts_at',        c.starts_at,
        'ends_at',          c.ends_at,
        'reward_coins',     c.reward_coins,
        'reward_frame_id',  c.reward_frame_id,
        'winner_user_id',   c.winner_user_id,
        'crowned_at',       c.crowned_at,
        'created_at',       c.created_at,
        'created_by',       c.created_by
      ),
      'participant_count', (
        SELECT COUNT(*)
        FROM   charisma_entries e
        WHERE  e.challenge_id = c.id AND e.status != 'disqualified'
      ),
      'my_entry', (
        SELECT jsonb_build_object(
          'id',           e.id,
          'challenge_id', e.challenge_id,
          'user_id',      e.user_id,
          'status',       e.status,
          'vote_count',   e.vote_count,
          'joined_at',    e.joined_at,
          'performed_at', e.performed_at
        )
        FROM charisma_entries e
        WHERE e.challenge_id = c.id AND e.user_id = v_user_id
        LIMIT 1
      )
    ) ORDER BY c.starts_at DESC
  ) INTO v_result
  FROM charisma_challenges c
  WHERE c.status IN ('active', 'ended', 'crowned')
    AND (p_scope IS NULL OR c.scope = p_scope)
    AND (
      p_agency_id IS NULL
      OR c.agency_id = p_agency_id
      OR c.scope = 'official'
    )
    -- Show crowned only if crowned within last 48 hours
    AND (c.status != 'crowned' OR c.crowned_at > now() - interval '48 hours')
  ;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."charisma_get_active_challenges"("p_scope" "text", "p_agency_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charisma_get_leaderboard"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result  jsonb;
BEGIN
  WITH ranked AS (
    SELECT
      e.*,
      ROW_NUMBER() OVER (ORDER BY e.vote_count DESC, e.joined_at ASC) AS rank
    FROM charisma_entries e
    WHERE e.challenge_id = p_challenge_id
      AND e.status != 'disqualified'
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'rank',         r.rank,
      'entry_id',     r.id,
      'user_id',      r.user_id,
      'status',       r.status,
      'vote_count',   r.vote_count,
      'joined_at',    r.joined_at,
      'performed_at', r.performed_at,
      'has_voted', EXISTS (
        SELECT 1 FROM charisma_votes v
        WHERE  v.entry_id = r.id AND v.voter_id = v_user_id
      ),
      'is_me', r.user_id = v_user_id,
      'profile', jsonb_build_object(
        'display_name',              p.display_name,
        'username',                  p.username,
        'avatar_url',                p.avatar_url,
        'selected_avatar_frame_key', p.selected_avatar_frame_key,
        'public_user_id',            p.public_user_id,
        'vip_level',                 p.vip_level
      )
    ) ORDER BY r.rank
  ) INTO v_result
  FROM ranked r
  JOIN profiles p ON p.id = r.user_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."charisma_get_leaderboard"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charisma_join_challenge"("p_challenge_id" "uuid", "p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_challenge charisma_challenges;
  v_entry_id  uuid;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_challenge
  FROM charisma_challenges
  WHERE id = p_challenge_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'challenge_not_found'; END IF;
  IF v_challenge.status != 'active' THEN
    RAISE EXCEPTION 'challenge_not_active: %', v_challenge.status;
  END IF;

  -- unique constraint catches race conditions; give a nicer error first
  IF EXISTS (
    SELECT 1 FROM charisma_entries
    WHERE challenge_id = p_challenge_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'already_joined';
  END IF;

  INSERT INTO charisma_entries (challenge_id, user_id, room_id, agency_id)
  VALUES (p_challenge_id, v_user_id, p_room_id, v_challenge.agency_id)
  RETURNING id INTO v_entry_id;

  RETURN jsonb_build_object(
    'entry_id',    v_entry_id,
    'challenge_id', p_challenge_id,
    'user_id',     v_user_id,
    'status',      'joined'
  );
END;
$$;


ALTER FUNCTION "public"."charisma_join_challenge"("p_challenge_id" "uuid", "p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charisma_vote"("p_entry_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_voter_id uuid := auth.uid();
  v_entry    charisma_entries;
  v_challenge charisma_challenges;
  v_new_count int;
BEGIN
  IF v_voter_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_entry FROM charisma_entries WHERE id = p_entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'entry_not_found'; END IF;
  IF v_entry.user_id = v_voter_id THEN RAISE EXCEPTION 'self_vote'; END IF;

  SELECT * INTO v_challenge
  FROM   charisma_challenges
  WHERE  id = v_entry.challenge_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'challenge_not_found'; END IF;
  IF v_challenge.status != 'active' THEN RAISE EXCEPTION 'challenge_not_active'; END IF;

  -- Use unique constraint to prevent duplicate votes atomically
  BEGIN
    INSERT INTO charisma_votes
      (challenge_id, entry_id, voter_id, participant_user_id)
    VALUES
      (v_entry.challenge_id, p_entry_id, v_voter_id, v_entry.user_id);
  EXCEPTION
    WHEN unique_violation THEN RAISE EXCEPTION 'already_voted';
  END;

  UPDATE charisma_entries
  SET    vote_count = vote_count + 1
  WHERE  id = p_entry_id
  RETURNING vote_count INTO v_new_count;

  RETURN jsonb_build_object(
    'entry_id',      p_entry_id,
    'new_vote_count', v_new_count,
    'voter_id',      v_voter_id
  );
END;
$$;


ALTER FUNCTION "public"."charisma_vote"("p_entry_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_user_active_mute"("p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_expires_at  timestamptz;
  v_reason      text;
  v_force_muted boolean;
begin
  if v_user_id is null then
    return jsonb_build_object('muted', false);
  end if;

  -- Check system-level chat_mute
  select expires_at, reason
  into   v_expires_at, v_reason
  from   public.admin_user_restrictions
  where  user_id         = v_user_id
    and  restriction_type = 'chat_mute'
    and  is_active        = true
    and  (expires_at is null or expires_at > now())
  order by created_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'muted',      true,
      'type',       'chat_mute',
      'expires_at', v_expires_at,
      'reason',     v_reason
    );
  end if;

  -- Check room-level force_muted
  if p_room_id is not null then
    select force_muted
    into   v_force_muted
    from   public.room_members
    where  user_id = v_user_id
      and  room_id = p_room_id;

    if v_force_muted = true then
      return jsonb_build_object(
        'muted',      true,
        'type',       'force_muted',
        'expires_at', null,
        'reason',     'Muted by room owner'
      );
    end if;

    -- Check room ban
    if exists (
      select 1 from public.room_bans
      where user_id = v_user_id
        and room_id = p_room_id
        and (expires_at is null or expires_at > now())
    ) then
      select expires_at, reason
      into   v_expires_at, v_reason
      from   public.room_bans
      where  user_id = v_user_id
        and  room_id = p_room_id
        and  (expires_at is null or expires_at > now())
      order by created_at desc limit 1;

      return jsonb_build_object(
        'muted',      true,
        'type',       'room_ban',
        'expires_at', v_expires_at,
        'reason',     v_reason
      );
    end if;
  end if;

  return jsonb_build_object('muted', false);
end;
$$;


ALTER FUNCTION "public"."check_user_active_mute"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_daily_checkin"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  v_result := public.claim_daily_reward();
  -- Remap to the legacy claim-response shape.
  return jsonb_build_object(
    'reward_type',   v_result->'reward_type',
    'reward_amount', v_result->'amount',
    'streak',        v_result->'streak_count'
  );
end;
$$;


ALTER FUNCTION "public"."claim_daily_checkin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_daily_reward"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid    uuid := auth.uid();
  v_cfg    public.daily_reward_config;
  v_row    public.user_daily_rewards;
  v_today  date := (now() at time zone 'utc')::date;
  v_claim_day integer;
  v_new_streak integer;
  v_cycle_inc  integer := 0;
  v_rule   public.daily_reward_rules;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_cfg from public.daily_reward_config where id = 1;
  if not coalesce(v_cfg.enabled, false) then raise exception 'daily_reward_disabled'; end if;

  -- Lock / create the user's row.
  insert into public.user_daily_rewards (user_id) values (v_uid)
  on conflict (user_id) do nothing;
  select * into v_row from public.user_daily_rewards where user_id = v_uid for update;

  if v_row.last_claim_date is not null and v_row.last_claim_date = v_today then
    raise exception 'already_claimed_today';
  end if;

  -- Determine the day to claim + streak.
  if v_row.last_claim_date = (v_today - 1) and v_row.current_day between 1 and 6 then
    v_claim_day  := v_row.current_day + 1;
    v_new_streak := coalesce(v_row.streak_count, 0) + 1;
  elsif v_row.last_claim_date = (v_today - 1) and v_row.current_day = 7 then
    v_claim_day  := 1;                 -- new cycle after completing day 7
    v_new_streak := 1;
    v_cycle_inc  := 1;
  else
    v_claim_day  := 1;                 -- first claim / missed a day -> reset
    v_new_streak := 1;
  end if;

  select * into v_rule from public.daily_reward_rules where day_number = v_claim_day;
  if v_rule.id is null or not v_rule.enabled then
    raise exception 'reward_day_disabled';
  end if;

  -- Apply reward (server-trusted amount from the rule; never the client).
  if v_rule.reward_type = 'coins' then
    if v_rule.amount > 0 then
      insert into public.wallets (user_id) values (v_uid) on conflict (user_id) do nothing;
      update public.wallets
      set coins_balance = coins_balance + v_rule.amount, updated_at = now()
      where user_id = v_uid;

      insert into public.wallet_transactions
        (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
      values
        (v_uid, 'daily_reward', 'credit', v_rule.amount, 0,
         'Daily reward - day ' || v_claim_day,
         jsonb_build_object('day', v_claim_day, 'rule_id', v_rule.id));
    end if;
  else
    raise exception 'unsupported_reward_type';
  end if;

  -- Record the claim (unique (user_id, claimed_date) blocks any double claim).
  insert into public.daily_reward_claims
    (user_id, claimed_day, reward_rule_id, reward_type, reward_key, amount, duration_days, claimed_date)
  values
    (v_uid, v_claim_day, v_rule.id, v_rule.reward_type, v_rule.reward_key,
     v_rule.amount, v_rule.duration_days, v_today);

  update public.user_daily_rewards
  set current_day           = v_claim_day,
      streak_count          = v_new_streak,
      last_claim_date       = v_today,
      cycle_completed_count = cycle_completed_count + v_cycle_inc,
      updated_at            = now()
  where user_id = v_uid;

  return jsonb_build_object(
    'success',       true,
    'claimed_day',   v_claim_day,
    'reward_type',   v_rule.reward_type,
    'title',         v_rule.title,
    'amount',        v_rule.amount,
    'duration_days', v_rule.duration_days,
    'streak_count',  v_new_streak
  );
exception
  when unique_violation then
    raise exception 'already_claimed_today';
end;
$$;


ALTER FUNCTION "public"."claim_daily_reward"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_red_envelope"("p_envelope_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_env        public.red_envelopes;
  v_remaining  integer;
  v_slots_left integer;
  v_coins      integer;
  v_wallet     public.wallets;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Lock envelope row atomically.
  SELECT * INTO v_env
  FROM public.red_envelopes
  WHERE id = p_envelope_id
  FOR UPDATE;

  IF NOT FOUND                THEN RAISE EXCEPTION 'envelope_not_found'; END IF;
  IF v_env.is_expired         THEN RAISE EXCEPTION 'envelope_expired'; END IF;
  IF v_env.expires_at < now() THEN RAISE EXCEPTION 'envelope_expired'; END IF;
  IF v_env.claimed_count >= v_env.envelope_count THEN
    RAISE EXCEPTION 'envelope_full';
  END IF;

  -- Prevent duplicate claim.
  IF EXISTS (
    SELECT 1 FROM public.red_envelope_claims
    WHERE envelope_id = p_envelope_id AND claimer_id = v_uid
  ) THEN
    RAISE EXCEPTION 'already_claimed';
  END IF;

  -- Claimer must be in the room.
  IF NOT EXISTS (
    SELECT 1 FROM public.room_members
    WHERE room_id = v_env.room_id AND user_id = v_uid AND left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'not_room_member';
  END IF;

  -- Calculate coins: random share, at least 1, at most remaining-1 (unless last slot).
  v_remaining  := v_env.total_coins - (
    SELECT COALESCE(SUM(coins_received), 0)
    FROM public.red_envelope_claims WHERE envelope_id = p_envelope_id
  );
  v_slots_left := v_env.envelope_count - v_env.claimed_count;

  IF v_slots_left = 1 THEN
    v_coins := v_remaining;
  ELSE
    v_coins := GREATEST(1, LEAST(
      v_remaining - (v_slots_left - 1),
      1 + floor(random() * (2 * v_remaining / v_slots_left - 1))::integer
    ));
  END IF;

  -- Record claim.
  INSERT INTO public.red_envelope_claims (envelope_id, claimer_id, coins_received)
  VALUES (p_envelope_id, v_uid, v_coins);

  -- Update envelope claimed count / expiry flag.
  UPDATE public.red_envelopes
  SET claimed_count = claimed_count + 1,
      is_expired    = (claimed_count + 1 >= envelope_count)
  WHERE id = p_envelope_id;

  -- Ensure claimer wallet exists, then credit.
  INSERT INTO public.wallets (user_id) VALUES (v_uid)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.wallets
  SET coins_balance = coins_balance + v_coins,
      updated_at    = now()
  WHERE user_id = v_uid
  RETURNING * INTO v_wallet;

  -- Record wallet transaction.
  INSERT INTO public.wallet_transactions (
    user_id, type, direction, coins_delta,
    balance_coins_after, balance_diamonds_after,
    related_room_id, note
  ) VALUES (
    v_uid, 'red_envelope_claimed', 'credit', v_coins,
    v_wallet.coins_balance, v_wallet.diamonds_balance,
    v_env.room_id,
    'Red envelope claim'
  );

  RETURN v_coins;
END;
$$;


ALTER FUNCTION "public"."claim_red_envelope"("p_envelope_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_speaker_seat"("p_room_id" "uuid", "p_seat_number" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_owner_id uuid;
  v_max_seats integer;
  v_is_closed boolean;
  v_access_mode text;
  v_role text;
  v_force_muted boolean;
  v_is_moderator boolean := false;
  v_seat_user_id uuid;
  v_seat_last_seen timestamptz;
  v_result jsonb;
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;

  select owner_id, max_seats, is_closed, coalesce(access_mode, 'open')
  into v_owner_id, v_max_seats, v_is_closed, v_access_mode
  from public.rooms
  where id = p_room_id;

  if v_max_seats is null then
    raise exception 'room_not_found';
  end if;

  if v_is_closed then
    raise exception 'room_closed';
  end if;

  if p_seat_number < 1 or p_seat_number > v_max_seats then
    raise exception 'invalid_seat_number';
  end if;

  select role, force_muted
  into v_role, v_force_muted
  from public.room_members
  where room_id = p_room_id
    and user_id = v_caller
    and left_at is null;

  if v_role is null then
    raise exception 'not_in_room';
  end if;

  v_is_moderator := exists (
    select 1
    from public.room_moderators
    where room_id = p_room_id
      and user_id = v_caller
  );

  if v_access_mode = 'watch'
     and v_role <> 'host'
     and v_caller <> v_owner_id
     and not v_is_moderator then
    raise exception 'watch_mode_enabled';
  end if;

  if v_role != 'host' and v_force_muted then
    raise exception 'force_muted';
  end if;

  if v_role != 'host' and exists (
    select 1
    from public.room_bans
    where room_id = p_room_id
      and user_id = v_caller
      and (expires_at is null or expires_at > now())
  ) then
    raise exception 'banned_from_room';
  end if;

  select user_id, last_seen_at
  into v_seat_user_id, v_seat_last_seen
  from public.room_members
  where room_id = p_room_id
    and seat_number = p_seat_number
    and left_at is null;

  if v_seat_user_id is not null and v_seat_user_id != v_caller then
    if v_seat_last_seen < now() - interval '45 seconds' then
      update public.room_members
      set left_at = now(),
          seat_number = null,
          is_muted = true,
          last_seen_at = now(),
          updated_at = now()
      where room_id = p_room_id
        and user_id = v_seat_user_id
        and left_at is null;
    else
      raise exception 'seat_taken';
    end if;
  end if;

  begin
    update public.room_members
    set role = case when v_role = 'host' then 'host' else 'speaker' end,
        seat_number = p_seat_number,
        updated_at = now()
    where room_id = p_room_id
      and user_id = v_caller
      and left_at is null
    returning jsonb_build_object(
      'user_id', user_id,
      'room_id', room_id,
      'role', role,
      'seat_number', seat_number
    ) into v_result;
  exception
    when unique_violation then
      raise exception 'seat_taken';
  end;

  if v_result is null then
    raise exception 'update_failed';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."claim_speaker_seat"("p_room_id" "uuid", "p_seat_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_speaker_seat"("p_room_id" "uuid", "p_seat_number" integer) IS 'Allows a listener to self-promote to speaker and claim a seat. Verifies membership, bans, force-mute, seat availability, and seat capacity entirely server-side. Never trusts a client-provided role value.';



CREATE OR REPLACE FUNCTION "public"."claim_task_reward"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid:=auth.uid();
  v_daily_key text:=to_char(current_date,'YYYY-MM-DD');
  v_weekly_key text:=to_char(current_date,'IYYY-"W"IW');
  v_task tasks%rowtype; v_progress user_task_progress%rowtype; v_period_key text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_task from tasks where id=p_task_id and is_active=true;
  if not found then raise exception 'task_not_found'; end if;
  v_period_key:=case v_task.task_type when 'daily' then v_daily_key when 'weekly' then v_weekly_key else v_daily_key end;
  select * into v_progress from user_task_progress
  where user_id=v_uid and task_id=p_task_id and period_key=v_period_key for update;
  if not found or not v_progress.completed then raise exception 'task_not_completed'; end if;
  if v_progress.claimed then raise exception 'reward_already_claimed'; end if;
  update user_task_progress set claimed=true where id=v_progress.id;
  insert into wallets(user_id) values(v_uid) on conflict(user_id) do nothing;
  if v_task.reward_type='coins' then
    update wallets set coins_balance=coins_balance+v_task.reward_amount,updated_at=now() where user_id=v_uid;
    insert into wallet_transactions(user_id,type,direction,coins_delta,note)
    values(v_uid,'system','credit',v_task.reward_amount,'Task reward: '||v_task.title);
  elsif v_task.reward_type='diamonds' then
    update wallets set diamonds_balance=diamonds_balance+v_task.reward_amount,
      lifetime_diamonds_earned=lifetime_diamonds_earned+v_task.reward_amount,updated_at=now() where user_id=v_uid;
    insert into wallet_transactions(user_id,type,direction,diamonds_delta,note)
    values(v_uid,'system','credit',v_task.reward_amount,'Task reward: '||v_task.title);
  end if;
  return jsonb_build_object('reward_type',v_task.reward_type,'reward_amount',v_task.reward_amount);
end;$$;


ALTER FUNCTION "public"."claim_task_reward"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_empty_rooms"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH empty_rooms AS (
    SELECT r.id
    FROM public.rooms r
    WHERE r.is_closed       = false
      AND r.is_personal_room = false   -- personal rooms are never auto-closed
      AND NOT EXISTS (
        SELECT 1 FROM public.room_members m
        WHERE m.room_id = r.id AND m.left_at IS NULL
      )
  )
  UPDATE public.rooms
  SET
    is_closed     = true,
    closed_at     = now(),
    closed_reason = 'auto-closed: no active members'
  WHERE id IN (SELECT id FROM empty_rooms);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."close_empty_rooms"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_recharge_transaction"("p_package_id" "uuid", "p_payment_method" "text", "p_payment_reference" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_package public.recharge_packages;
  v_method text := lower(trim(coalesce(p_payment_method, '')));
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if v_method not in ('cash', 'omt', 'wish', 'usdt', 'manual_admin', 'card_later') then
    raise exception 'invalid_payment_method';
  end if;

  select *
  into v_package
  from public.recharge_packages
  where id = p_package_id
    and is_active
  limit 1;

  if not found then
    raise exception 'recharge_package_not_found';
  end if;

  insert into public.recharge_transactions (
    user_id,
    package_id,
    price_usd,
    coins_amount,
    bonus_coins,
    total_coins,
    payment_method,
    payment_reference
  )
  values (
    v_user_id,
    v_package.id,
    v_package.price_usd,
    v_package.coins_amount,
    v_package.bonus_coins,
    v_package.total_coins,
    v_method,
    nullif(trim(coalesce(p_payment_reference, '')), '')
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_recharge_transaction"("p_package_id" "uuid", "p_payment_method" "text", "p_payment_reference" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."red_envelopes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "room_id" "uuid" NOT NULL,
    "sender_id" "uuid" NOT NULL,
    "total_coins" integer NOT NULL,
    "envelope_count" integer NOT NULL,
    "claimed_count" integer DEFAULT 0 NOT NULL,
    "is_expired" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:05:00'::interval) NOT NULL,
    "is_super" boolean DEFAULT false NOT NULL,
    CONSTRAINT "red_envelopes_envelope_count_check" CHECK (("envelope_count" >= 1)),
    CONSTRAINT "red_envelopes_total_coins_check" CHECK (("total_coins" >= 10))
);

ALTER TABLE ONLY "public"."red_envelopes" REPLICA IDENTITY FULL;


ALTER TABLE "public"."red_envelopes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_red_envelope"("p_room_id" "uuid", "p_total_coins" integer, "p_count" integer) RETURNS "public"."red_envelopes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_wallet public.wallets;
  v_env    public.red_envelopes;
BEGIN
  IF v_uid IS NULL        THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_total_coins < 10   THEN RAISE EXCEPTION 'min_coins_10'; END IF;
  IF p_count < 1          THEN RAISE EXCEPTION 'min_count_1'; END IF;
  IF p_count > p_total_coins THEN RAISE EXCEPTION 'count_exceeds_coins'; END IF;

  -- Validate room exists.
  IF NOT EXISTS (SELECT 1 FROM public.rooms WHERE id = p_room_id) THEN
    RAISE EXCEPTION 'room_not_found';
  END IF;

  -- Sender must be in the room.
  IF NOT EXISTS (
    SELECT 1 FROM public.room_members
    WHERE room_id = p_room_id AND user_id = v_uid AND left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'not_room_member';
  END IF;

  -- Ensure wallet row exists, then lock it.
  INSERT INTO public.wallets (user_id) VALUES (v_uid)
  ON CONFLICT (user_id) DO NOTHING;

  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_uid
  FOR UPDATE;

  IF v_wallet.coins_balance < p_total_coins THEN
    RAISE EXCEPTION 'insufficient_balance';
  END IF;

  -- Deduct coins.
  UPDATE public.wallets
  SET coins_balance        = coins_balance - p_total_coins,
      lifetime_coins_spent = lifetime_coins_spent + p_total_coins,
      updated_at           = now()
  WHERE user_id = v_uid
  RETURNING * INTO v_wallet;

  -- Record wallet transaction.
  INSERT INTO public.wallet_transactions (
    user_id, type, direction, coins_delta,
    balance_coins_after, balance_diamonds_after,
    related_room_id, note
  ) VALUES (
    v_uid, 'red_envelope_sent', 'debit', -p_total_coins,
    v_wallet.coins_balance, v_wallet.diamonds_balance,
    p_room_id,
    'Red envelope (' || p_count || ' × ~' || (p_total_coins / p_count) || ' coins)'
  );

  -- Create envelope.
  INSERT INTO public.red_envelopes (room_id, sender_id, total_coins, envelope_count)
  VALUES (p_room_id, v_uid, p_total_coins, p_count)
  RETURNING * INTO v_env;

  RETURN v_env;
END;
$$;


ALTER FUNCTION "public"."create_red_envelope"("p_room_id" "uuid", "p_total_coins" integer, "p_count" integer) OWNER TO "postgres";


