CREATE OR REPLACE FUNCTION "public"."deactivate_my_push_token"("p_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  update public.user_push_tokens
  set is_active = false,
      invalidated_at = now(),
      updated_at = now()
  where user_id = v_uid
    and token = trim(coalesce(p_token, ''));
end;
$$;


ALTER FUNCTION "public"."deactivate_my_push_token"("p_token" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."deactivate_my_push_token"("p_token" "text") IS 'Deactivates only the authenticated user''s matching FCM token before logout.';



CREATE OR REPLACE FUNCTION "public"."delete_room_music_track"("p_track_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_track public.room_music_tracks;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;

  select *
  into v_track
  from public.room_music_tracks
  where id = p_track_id
  for update;

  if v_track.id is null then raise exception 'track_not_found'; end if;
  if v_uid <> v_track.uploaded_by
     and not public.is_room_manager(v_track.room_id, v_uid) then
    raise exception 'forbidden';
  end if;

  update public.room_music_tracks
  set is_active = false
  where id = p_track_id;

  return v_track.storage_path;
end;
$$;


ALTER FUNCTION "public"."delete_room_music_track"("p_track_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."do_spin"("p_phone" "text", "p_wheel_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_wheel         spin_wheels%ROWTYPE;
  v_segment       spin_segments%ROWTYPE;
  v_last_spin_at  timestamptz;
  v_spins_today   integer;
  v_next_spin     timestamptz;
  v_total         numeric;
  v_rand          numeric;
  v_cum           numeric := 0;
  v_result_id     uuid;
BEGIN
  IF p_wheel_id IS NOT NULL THEN
    SELECT * INTO v_wheel FROM spin_wheels WHERE id = p_wheel_id AND active = true;
  ELSE
    SELECT * INTO v_wheel FROM spin_wheels WHERE active = true ORDER BY created_at LIMIT 1;
  END IF;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No active wheel found');
  END IF;

  IF v_wheel.reset_rule = 'daily' THEN
    SELECT COUNT(*) INTO v_spins_today FROM spin_results
    WHERE phone = p_phone AND wheel_id = v_wheel.id
      AND created_at >= date_trunc('day', now() AT TIME ZONE 'UTC');
    IF v_spins_today >= v_wheel.daily_spin_limit THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'daily_limit',
        'next_spin_at', (date_trunc('day', now() AT TIME ZONE 'UTC') + interval '1 day')::text
      );
    END IF;
  ELSE
    SELECT created_at INTO v_last_spin_at FROM spin_results
    WHERE phone = p_phone AND wheel_id = v_wheel.id
    ORDER BY created_at DESC LIMIT 1;
    IF v_last_spin_at IS NOT NULL THEN
      v_next_spin := v_last_spin_at + (v_wheel.cooldown_minutes * interval '1 minute');
      IF v_next_spin > now() THEN
        RETURN jsonb_build_object(
          'ok', false, 'error', 'cooldown',
          'next_spin_at', v_next_spin::text
        );
      END IF;
    END IF;
  END IF;

  SELECT COALESCE(SUM(chance_percentage), 0) INTO v_total
  FROM spin_segments
  WHERE wheel_id = v_wheel.id AND active = true
    AND (start_at IS NULL OR start_at <= now())
    AND (end_at   IS NULL OR end_at   >= now())
    AND (stock_remaining IS NULL OR stock_remaining > 0);

  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No eligible prizes configured');
  END IF;

  v_rand := random() * v_total;
  v_cum  := 0;
  FOR v_segment IN
    SELECT * FROM spin_segments
    WHERE wheel_id = v_wheel.id AND active = true
      AND (start_at IS NULL OR start_at <= now())
      AND (end_at   IS NULL OR end_at   >= now())
      AND (stock_remaining IS NULL OR stock_remaining > 0)
    ORDER BY display_order ASC, created_at ASC
  LOOP
    v_cum := v_cum + v_segment.chance_percentage;
    EXIT WHEN v_rand < v_cum;
  END LOOP;

  IF v_segment.id IS NULL THEN
    SELECT * INTO v_segment FROM spin_segments
    WHERE wheel_id = v_wheel.id AND active = true ORDER BY display_order ASC LIMIT 1;
  END IF;
  IF v_segment.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Could not select a winner');
  END IF;

  IF v_segment.stock_remaining IS NOT NULL THEN
    UPDATE spin_segments
    SET stock_remaining = GREATEST(0, stock_remaining - 1), updated_at = now()
    WHERE id = v_segment.id;
  END IF;

  INSERT INTO spin_results (phone, wheel_id, segment_id, reward_type, points_awarded)
  VALUES (
    p_phone, v_wheel.id, v_segment.id, v_segment.reward_type,
    CASE WHEN v_segment.reward_type = 'points' THEN v_segment.points_value ELSE 0 END
  )
  RETURNING id INTO v_result_id;

  IF v_segment.reward_type = 'points' AND v_segment.points_value > 0 THEN
    PERFORM increment_points(p_phone, v_segment.points_value);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'result_id', v_result_id,
    'wheel', jsonb_build_object('id', v_wheel.id, 'title', v_wheel.title),
    'segment', jsonb_build_object(
      'id',                v_segment.id,
      'title',             v_segment.title,
      'display_label',     v_segment.display_label,
      'description',       v_segment.description,
      'icon',              v_segment.icon,
      'color',             v_segment.color,
      'text_color',        v_segment.text_color,
      'reward_type',       v_segment.reward_type,
      'points_value',      v_segment.points_value,
      'prize_name',        v_segment.prize_name,
      'prize_description', v_segment.prize_description,
      'chance_percentage', v_segment.chance_percentage
    )
  );
END;
$$;


ALTER FUNCTION "public"."do_spin"("p_phone" "text", "p_wheel_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_message_not_blocked"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if exists (
    select 1 from public.user_blocks
    where (blocker_id = new.sender_id and blocked_id = new.receiver_id)
       or (blocker_id = new.receiver_id and blocked_id = new.sender_id)
  ) then
    raise exception 'user_blocked';
  end if;
  return new;
end;
$$;


