    "total_recharged_coins" bigint DEFAULT 0 NOT NULL,
    "total_spent_coins" bigint DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "user_wallets_coin_balance_check" CHECK (("coin_balance" >= 0)),
    CONSTRAINT "user_wallets_diamond_balance_check" CHECK (("diamond_balance" >= 0)),
    CONSTRAINT "user_wallets_total_recharged_coins_check" CHECK (("total_recharged_coins" >= 0)),
    CONSTRAINT "user_wallets_total_recharged_usd_check" CHECK (("total_recharged_usd" >= (0)::numeric)),
    CONSTRAINT "user_wallets_total_spent_coins_check" CHECK (("total_spent_coins" >= 0))
);


