CREATE OR REPLACE FUNCTION "public"."equip_avatar_frame"("p_frame_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_frame_key text;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select uaf.frame_key
  into v_frame_key
  from public.user_avatar_frames uaf
  where uaf.user_id = v_user_id
    and uaf.frame_id = p_frame_id
    and (uaf.expires_at is null or uaf.expires_at > now())
  limit 1;

  if v_frame_key is null then
    raise exception 'avatar_frame_not_owned';
  end if;

  update public.user_avatar_frames set is_equipped = false where user_id = v_user_id;
  update public.user_avatar_frames set is_equipped = true where user_id = v_user_id and frame_id = p_frame_id;
  update public.profiles set selected_avatar_frame_key = v_frame_key where id = v_user_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."equip_avatar_frame"("p_frame_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equip_backpack_item"("p_backpack_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid:=auth.uid(); v_item backpack_items%rowtype; v_frame_key text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_item from backpack_items where id=p_backpack_item_id and user_id=v_uid;
  if not found then raise exception 'backpack_item_not_found'; end if;
  update backpack_items set equipped=false where user_id=v_uid and item_type=v_item.item_type;
  update backpack_items set equipped=true where id=v_item.id;
  if v_item.item_type='avatar_frame' then
    v_frame_key:=v_item.metadata->>'frame_key';
    if v_frame_key is not null then
      update profiles set selected_avatar_frame_key=v_frame_key,updated_at=now() where id=v_uid;
    end if;
  end if;
  return jsonb_build_object('equipped',true,'item_type',v_item.item_type,'frame_key',v_item.metadata->>'frame_key');
end;$$;


ALTER FUNCTION "public"."equip_backpack_item"("p_backpack_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."equip_user_badge"("p_badge_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if not exists (
    select 1
    from public.user_badges ub
    where ub.user_id = v_user_id
      and ub.badge_id = p_badge_id
      and (ub.expires_at is null or ub.expires_at > now())
  ) then
    raise exception 'badge_not_owned';
  end if;

  update public.user_badges
  set is_equipped = false
  where user_id = v_user_id;

  update public.user_badges
  set is_equipped = true
  where user_id = v_user_id
    and badge_id = p_badge_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."equip_user_badge"("p_badge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_old_vips"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_count int;
BEGIN
  UPDATE public.user_vip_subscriptions SET is_active = false WHERE is_active = true AND ends_at < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  UPDATE public.profiles p SET vip_level = 0, vip_expires_at = NULL, vip_started_at = NULL
  WHERE p.vip_level > 0
    AND p.vip_expires_at IS NOT NULL AND p.vip_expires_at < now()
    AND NOT EXISTS (SELECT 1 FROM public.user_vip_subscriptions s WHERE s.user_id = p.id AND s.is_active = true);
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."expire_old_vips"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_room_team_pk"("p_pk_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_session   public.room_team_pk_sessions;
begin
  -- Unauthenticated callers are allowed only if session has expired.
  -- (For client-triggered finish after timer expires, auth is present anyway.)

  select * into v_session
  from public.room_team_pk_sessions
  where id = p_pk_session_id;

  if v_session is null then raise exception 'session_not_found'; end if;

  -- If still active and not yet expired, require manager auth.
  if v_session.status = 'active' and v_session.ends_at > now() then
    if v_caller_id is null or not public.is_room_manager(v_session.room_id, v_caller_id) then
      raise exception 'not_authorized';
    end if;
  end if;

  -- Delegate to internal helper (handles idempotency).
  v_session := public._finish_team_pk_internal(p_pk_session_id);

  return row_to_json(v_session)::jsonb;
end;
$$;


ALTER FUNCTION "public"."finish_room_team_pk"("p_pk_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fish_hunt_get_leaderboard"("p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "total_payout" bigint, "total_bet" bigint, "net_winnings" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  return query
  select s.user_id,
         sum(s.payout_amount)::bigint as total_payout,
         sum(s.bet_amount)::bigint as total_bet,
         (sum(s.payout_amount) - sum(s.bet_amount))::bigint as net_winnings
  from public.fish_hunt_shots s
  join public.fish_hunt_rounds r on r.id = s.round_id
  where s.created_at > now() - interval '24 hours'
    and (p_room_id is null or r.room_id = p_room_id)
  group by s.user_id
  order by net_winnings desc
  limit 50;
end;
$$;


ALTER FUNCTION "public"."fish_hunt_get_leaderboard"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fish_hunt_get_state"("p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id  uuid := auth.uid();
  v_round    public.fish_hunt_rounds;
  v_balance  integer;
  v_fish     json;
  v_shots    json;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select *
  into v_round
  from public.fish_hunt_rounds
  where status = 'active'
    and (p_room_id is null or room_id = p_room_id)
  order by started_at desc
  limit 1;

  select coalesce(json_agg(
           json_build_object(
             'fish_id', f.id,
             'fish_type', f.fish_type,
             'reward_multiplier', f.reward_multiplier,
             'hit_probability', f.hit_probability,
             'spawned_at', f.spawned_at,
             'expires_at', f.expires_at
           )
           order by f.spawned_at
         ), '[]'::json)
  into v_fish
  from public.fish_hunt_fish f
  where v_round.id is not null
    and f.round_id = v_round.id
    and f.status = 'alive'
    and f.expires_at > now();

  select coins_balance
  into v_balance
  from public.wallets
  where user_id = v_user_id;

  select coalesce(json_agg(
           json_build_object(
             'shot_id', s.id,
             'fish_id', s.fish_id,
             'bet_amount', s.bet_amount,
             'result', s.result,
             'payout_amount', s.payout_amount,
             'created_at', s.created_at
           )
           order by s.created_at desc
         ), '[]'::json)
  into v_shots
  from (
    select *
    from public.fish_hunt_shots
    where user_id = v_user_id
    order by created_at desc
    limit 20
  ) s;

  return json_build_object(
    'round_id', v_round.id,
    'room_id', v_round.room_id,
    'round_status', v_round.status,
    'fish', v_fish,
    'balance', coalesce(v_balance, 0),
    'recent_shots', v_shots,
    'server_now', now()
  );
end;
$$;


ALTER FUNCTION "public"."fish_hunt_get_state"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fish_hunt_place_shot"("p_room_id" "uuid", "p_fish_id" "uuid", "p_bet_amount" bigint, "p_client_shot_id" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_existing    public.fish_hunt_shots;
  v_round       public.fish_hunt_rounds;
  v_fish        public.fish_hunt_fish;
  v_new_balance integer;
  v_result      text;
  v_payout      bigint := 0;
  v_shot_id     uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_client_shot_id is null or length(trim(p_client_shot_id)) = 0 then
    raise exception 'invalid_client_shot_id';
  end if;

  select *
  into v_existing
  from public.fish_hunt_shots
  where client_shot_id = p_client_shot_id;

  if found then
    return json_build_object(
      'result', v_existing.result,
      'payout_amount', v_existing.payout_amount,
      'fish_id', v_existing.fish_id,
      'new_balance', (
        select coins_balance from public.wallets where user_id = v_user_id
      )
    );
  end if;

  if p_bet_amount is null
     or p_bet_amount not in (100, 500, 1000, 5000, 10000, 20000, 100000) then
    raise exception 'invalid_bet_amount';
  end if;

  -- Lock the round first to keep round/fish/wallet lock order consistent
  -- with every other money-moving RPC in this codebase.
  select *
  into v_round
  from public.fish_hunt_rounds
  where id = (
    select round_id from public.fish_hunt_fish where id = p_fish_id
  )
  for update;

  if not found or v_round.status <> 'active' then
    raise exception 'round_not_found';
  end if;

  if p_room_id is not null and v_round.room_id is not null
     and v_round.room_id <> p_room_id then
    raise exception 'room_mismatch';
  end if;

  select *
  into v_fish
  from public.fish_hunt_fish
  where id = p_fish_id
  for update;

  if not found then
    raise exception 'fish_not_found';
  end if;

  if v_fish.status <> 'alive' or v_fish.expires_at <= now() then
    raise exception 'fish_unavailable';
  end if;

  update public.wallets
  set coins_balance = coins_balance - p_bet_amount,
      lifetime_coins_spent = lifetime_coins_spent + p_bet_amount,
      updated_at = now()
  where user_id = v_user_id
    and coins_balance >= p_bet_amount
  returning coins_balance into v_new_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.wallet_transactions (
    user_id, type, direction, coins_delta, diamonds_delta,
    balance_coins_after, note, metadata
  )
  values (
    v_user_id, 'fish_hunt_bet', 'debit', -p_bet_amount, 0,
    v_new_balance, 'Fish Hunt shot',
    jsonb_build_object('fish_id', v_fish.id, 'round_id', v_round.id)
  );

  if random() < v_fish.hit_probability then
    v_result := 'hit';
    v_payout := floor(p_bet_amount * v_fish.reward_multiplier)::bigint;

    update public.fish_hunt_fish
    set status = 'killed',
        killed_by = v_user_id
    where id = v_fish.id;

    if v_payout > 0 then
      update public.wallets
      set coins_balance = coins_balance + v_payout,
          updated_at = now()
      where user_id = v_user_id
      returning coins_balance into v_new_balance;

      insert into public.wallet_transactions (
        user_id, type, direction, coins_delta, diamonds_delta,
        balance_coins_after, note, metadata
      )
      values (
        v_user_id, 'fish_hunt_reward', 'credit', v_payout, 0,
        v_new_balance, 'Fish Hunt reward',
        jsonb_build_object('fish_id', v_fish.id, 'round_id', v_round.id)
      );
    end if;
  else
    v_result := 'miss';
  end if;

  insert into public.fish_hunt_shots (
    client_shot_id, user_id, round_id, fish_id, bet_amount, result,
    payout_amount
  )
  values (
    p_client_shot_id, v_user_id, v_round.id, v_fish.id, p_bet_amount,
    v_result, v_payout
  )
  returning id into v_shot_id;

  return json_build_object(
    'result', v_result,
    'payout_amount', v_payout,
    'new_balance', v_new_balance,
    'fish_id', v_fish.id
  );
end;
$$;


ALTER FUNCTION "public"."fish_hunt_place_shot"("p_room_id" "uuid", "p_fish_id" "uuid", "p_bet_amount" bigint, "p_client_shot_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."friends_count"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)::int
  from public.user_follows a
  join public.user_follows b
    on a.following_id = b.follower_id
   and a.follower_id = b.following_id
  where a.follower_id = p_user_id;
$$;


ALTER FUNCTION "public"."friends_count"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_5digit_room_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_candidate text;
  v_attempts  int := 0;
begin
  loop
    v_attempts := v_attempts + 1;
    if v_attempts > 100 then
      raise exception 'generate_5digit_room_code: no unique code found after 100 attempts';
    end if;

    -- 10000 to 99999, no leading zero
    v_candidate := (floor(random() * 90000) + 10000)::bigint::text;

    exit when not exists (
      select 1 from public.rooms where public_room_code = v_candidate
    );
  end loop;

  return v_candidate;
end;
$$;


ALTER FUNCTION "public"."generate_5digit_room_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_6digit_public_user_id"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_candidate text;
  v_attempts  int := 0;
begin
  loop
    v_attempts := v_attempts + 1;
    if v_attempts > 50 then
      raise exception 'generate_6digit_public_user_id: could not find unique ID after 50 attempts';
    end if;

    -- 100000 to 999999, no leading zero
    v_candidate := (floor(random() * 900000) + 100000)::bigint::text;

    exit when not exists (
      select 1 from public.profiles where public_user_id = v_candidate
    );
  end loop;

  return v_candidate;
end;
$$;


ALTER FUNCTION "public"."generate_6digit_public_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_public_user_id"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  candidate text;
  tries int := 0;
begin
  loop
    candidate := (floor(random() * 900000 + 100000))::int::text;

    if not exists (
      select 1
      from public.profiles
      where public_user_id = candidate
    ) then
      return candidate;
    end if;

    tries := tries + 1;

    if tries > 50 then
      raise exception 'could_not_generate_unique_public_user_id';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."generate_unique_public_user_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_crash_rocket_round"("p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_round public.crash_rocket_rounds;
  v_wallet integer;
  v_bets jsonb;
  v_feed jsonb;
  v_history jsonb;
begin
  perform public._crash_rocket_assert_room_access(p_room_id);
  perform public.advance_crash_rocket_round(p_room_id);

  select * into v_round from public.crash_rocket_rounds
  where room_id is not distinct from p_room_id
  order by round_number desc limit 1;
  select coalesce(coins_balance,0) into v_wallet from public.wallets
  where user_id=v_uid;
  select coalesce(jsonb_agg(to_jsonb(b) order by b.bet_slot),'[]')
  into v_bets from public.crash_rocket_bets b
  where b.round_id=v_round.id and b.user_id=v_uid;
  select coalesce(jsonb_agg(x.payload order by x.created_at desc),'[]')
  into v_feed from (
    select e.created_at, e.payload from public.crash_rocket_round_events e
    where e.round_id=v_round.id
      and e.event_type in ('bet_placed','bet_cashed_out')
    order by e.created_at desc limit 30
  ) x;
  select coalesce(jsonb_agg(jsonb_build_object(
    'round_number',h.round_number,'crash_multiplier',h.crash_multiplier,
    'crashed_at',h.crashed_at
  ) order by h.round_number desc),'[]')
  into v_history from (
    select * from public.crash_rocket_rounds
    where room_id is not distinct from p_room_id and crash_multiplier is not null
    order by round_number desc limit 12
  ) h;

  return jsonb_build_object(
    'server_now',clock_timestamp(),
    'wallet_balance',coalesce(v_wallet,0),
    'round',to_jsonb(v_round),
    'my_bets',v_bets,
    'public_feed',v_feed,
    'history',v_history
  );
end;
$$;


ALTER FUNCTION "public"."get_active_crash_rocket_round"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_member_counts"("p_room_ids" "uuid"[]) RETURNS TABLE("room_id" "uuid", "active_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Empty input returns zero rows without touching any data.
  select
    rm.room_id,
    count(*)::integer as active_count
  from public.room_members rm
  where rm.room_id = any(p_room_ids)
    and rm.left_at is null
    and rm.last_seen_at >= now() - interval '45 seconds'
  group by rm.room_id;
$$;


