COMMENT ON FUNCTION "public"."get_active_member_counts"("p_room_ids" "uuid"[]) IS 'Returns active member counts grouped by room_id for the requested rooms only. Active = left_at IS NULL AND last_seen_at within the last 45 seconds. Replaces the client-side full-scan aggregation in getActiveMemberCounts().';



CREATE OR REPLACE FUNCTION "public"."get_active_room_game_round"("p_room_id" "uuid", "p_game_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_round record;
  v_bets  jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  -- Verify room membership
  if not exists (
    select 1 from public.room_members rm
    where rm.room_id = p_room_id
      and rm.user_id = v_uid
      and rm.left_at is null
  ) then
    raise exception 'not_room_member';
  end if;

  select r.* into v_round
  from public.room_game_rounds r
  where r.room_id  = p_room_id
    and r.game_code = p_game_code
    and r.status   not in ('finished','cancelled')
  order by r.created_at desc
  limit 1;

  if not found then
    return jsonb_build_object('active_round', null);
  end if;

  -- User's own bets for this round
  select coalesce(jsonb_agg(to_jsonb(b.*) order by b.created_at), '[]'::jsonb)
  into v_bets
  from public.room_game_bets b
  where b.round_id = v_round.id and b.user_id = v_uid;

  return jsonb_build_object(
    'active_round', jsonb_build_object(
      'id',                 v_round.id,
      'room_id',            v_round.room_id,
      'game_code',          v_round.game_code,
      'round_number',       v_round.round_number,
      'status',             v_round.status,
      'seed_hash',          v_round.seed_hash,
      'result_json',        case
                              when v_round.status in ('revealed','finished')
                              then v_round.result_json
                              else null
                            end,
      'betting_opens_at',   v_round.betting_opens_at,
      'betting_closes_at',  v_round.betting_closes_at,
      'started_at',         v_round.started_at,
      'reveal_at',          v_round.reveal_at,
      'finished_at',        v_round.finished_at,
      'created_at',         v_round.created_at
    ),
    'my_bets', v_bets
  );
end;
$$;


ALTER FUNCTION "public"."get_active_room_game_round"("p_room_id" "uuid", "p_game_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_room_team_pk"("p_room_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session  public.room_team_pk_sessions;
  v_members  jsonb;
  v_remaining_seconds bigint;
begin
  -- Find the most recent non-cancelled session for this room.
  select * into v_session
  from public.room_team_pk_sessions
  where room_id = p_room_id
    and status in ('active', 'finished')
  order by created_at desc
  limit 1;

  if v_session is null then
    return null;
  end if;

  -- Lazily finish if active but expired.
  if v_session.status = 'active' and v_session.ends_at <= now() then
    v_session := public._finish_team_pk_internal(v_session.id);
  end if;

  -- Compute remaining seconds (0 if finished/expired).
  v_remaining_seconds := greatest(
    0,
    extract(epoch from (v_session.ends_at - now()))::bigint
  );

  -- Fetch current member assignments.
  select jsonb_agg(row_to_json(m))
  into v_members
  from public.room_team_pk_members m
  where m.pk_session_id = v_session.id;

  return jsonb_build_object(
    'session',            row_to_json(v_session),
    'members',            coalesce(v_members, '[]'::jsonb),
    'remaining_seconds',  v_remaining_seconds
  );
end;
$$;


ALTER FUNCTION "public"."get_active_room_team_pk"("p_room_id" "uuid") OWNER TO "postgres";


