CREATE OR REPLACE FUNCTION "public"."get_crash_round_status"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_round       public.crash_rounds%rowtype;
  v_elapsed     numeric;
  v_current_m   numeric;
  v_bet         public.crash_bets%rowtype;
  v_bet_results jsonb    := '[]'::jsonb;
  v_auto_win    integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  -- Lock round row to serialize concurrent settle attempts
  select * into v_round
  from public.crash_rounds
  where id = p_round_id and user_id = v_user_id
  for update;

  if not found then raise exception 'round_not_found'; end if;

  -- Already settled — return cached bet results
  if v_round.status = 'crashed' then
    for v_bet in
      select * from public.crash_bets
      where round_id = p_round_id and user_id = v_user_id
    loop
      v_bet_results := v_bet_results || jsonb_build_array(jsonb_build_object(
        'bet_id',             v_bet.id,
        'status',             v_bet.status,
        'cashout_multiplier', v_bet.cashout_multiplier,
        'win_amount',         coalesce(v_bet.win_amount, 0)
      ));
    end loop;
    return jsonb_build_object(
      'status',           'crashed',
      'crash_multiplier', v_round.crash_multiplier,
      'bets',             v_bet_results
    );
  end if;

  -- Compute server-side multiplier
  v_elapsed   := greatest(0, extract(epoch from (now() - v_round.started_at)));
  v_current_m := round(exp(0.15 * v_elapsed)::numeric, 2);

  -- Still flying
  if v_current_m < v_round.crash_multiplier then
    return jsonb_build_object('status', 'flying');
  end if;

  -- ── CRASH DETECTED — settle now ───────────────────────────────────────────

  -- Auto-cashout bets: mode='auto' with target below crash point
  for v_bet in
    select * from public.crash_bets
    where round_id = p_round_id
      and user_id  = v_user_id
      and status   = 'running'
      and mode     = 'auto'
      and auto_cashout_multiplier is not null
      and auto_cashout_multiplier < v_round.crash_multiplier
  loop
    v_auto_win := floor(v_bet.bet_amount * v_bet.auto_cashout_multiplier)::integer;

    update public.crash_bets
    set status             = 'cashed_out',
        cashout_multiplier = v_bet.auto_cashout_multiplier,
        win_amount         = v_auto_win
    where id = v_bet.id;

    update public.wallets
    set coins_balance = coins_balance + v_auto_win, updated_at = now()
    where user_id = v_user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_user_id, 'crash_rocket_win', 'credit', v_auto_win, 0,
       'Crash Rocket auto-cashout at ' || v_bet.auto_cashout_multiplier || '×',
       jsonb_build_object('round_id', p_round_id, 'bet_id', v_bet.id,
                          'multiplier', v_bet.auto_cashout_multiplier));
  end loop;

  -- Remaining running bets are lost
  update public.crash_bets
  set status = 'lost', win_amount = 0
  where round_id = p_round_id and user_id = v_user_id and status = 'running';

  -- Mark round as crashed (reveals crash_multiplier to client)
  update public.crash_rounds
  set status     = 'crashed',
      crashed_at = now()
  where id = p_round_id;

  -- Build final bet results
  for v_bet in
    select * from public.crash_bets
    where round_id = p_round_id and user_id = v_user_id
  loop
    v_bet_results := v_bet_results || jsonb_build_array(jsonb_build_object(
      'bet_id',             v_bet.id,
      'status',             v_bet.status,
      'cashout_multiplier', v_bet.cashout_multiplier,
      'win_amount',         coalesce(v_bet.win_amount, 0)
    ));
  end loop;

  return jsonb_build_object(
    'status',           'crashed',
    'crash_multiplier', v_round.crash_multiplier,
    'bets',             v_bet_results
  );
end;
$$;


ALTER FUNCTION "public"."get_crash_round_status"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_loto_draw"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id  uuid := auth.uid();
  v_draw     public.loto_draws;
  v_s        public.loto_settings;
  v_balance  integer;
  v_tickets  jsonb;
BEGIN
  -- Load active or most-recent draw
  SELECT * INTO v_draw
  FROM public.loto_draws
  WHERE status IN ('open', 'closed', 'drawing')
  ORDER BY draw_at DESC
  LIMIT 1;

  -- Load settings
  SELECT * INTO v_s FROM public.loto_settings LIMIT 1;

  -- User balance
  SELECT coins_balance INTO v_balance
  FROM public.wallets WHERE user_id = v_user_id;

  -- User tickets for this draw
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',            t.id,
    'numbers',       t.numbers,
    'status',        t.status,
    'matched_count', t.matched_count,
    'prize_coins',   t.prize_coins,
    'created_at',    t.created_at
  ) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_tickets
  FROM public.loto_tickets t
  WHERE t.draw_id = v_draw.id AND t.user_id = v_user_id;

  RETURN jsonb_build_object(
    'draw', CASE WHEN v_draw.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id',                  v_draw.id,
      'draw_number',         v_draw.draw_number,
      'status',              v_draw.status,
      'opens_at',            v_draw.opens_at,
      'closes_at',           v_draw.closes_at,
      'draw_at',             v_draw.draw_at,
      'total_tickets',       v_draw.total_tickets,
      'total_sales_coins',   v_draw.total_sales_coins,
      'jackpot_pool_before', v_draw.jackpot_pool_before
    ) END,
    'settings', jsonb_build_object(
      'is_enabled',                  v_s.is_enabled,
      'ticket_price_coins',          v_s.ticket_price_coins,
      'number_min',                  v_s.number_min,
      'number_max',                  v_s.number_max,
      'numbers_per_ticket',          v_s.numbers_per_ticket,
      'match_3_prize',               v_s.match_3_prize,
      'match_4_prize',               v_s.match_4_prize,
      'match_5_prize',               v_s.match_5_prize,
      'match_6_prize',               v_s.match_6_prize,
      'progressive_jackpot_enabled', v_s.progressive_jackpot_enabled,
      'jackpot_pool_coins',          v_s.jackpot_pool_coins,
      'jackpot_contribution_pct',    v_s.jackpot_contribution_pct,
      'responsible_notice_ar',       v_s.responsible_notice_ar,
      'responsible_notice_en',       v_s.responsible_notice_en
    ),
    'my_tickets',          v_tickets,
    'user_balance',        coalesce(v_balance, 0),
    'seconds_until_draw',  greatest(0, extract(epoch from (v_draw.draw_at - now()))::integer),
    'seconds_until_close', greatest(0, extract(epoch from (v_draw.closes_at - now()))::integer)
  );
END;
$$;


ALTER FUNCTION "public"."get_current_loto_draw"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_reward_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_cfg   public.daily_reward_config;
  v_row   public.user_daily_rewards;
  v_today date := (now() at time zone 'utc')::date;
  v_claim_day integer;
  v_claimed_today boolean;
  v_can_claim boolean;
  v_rules jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_cfg from public.daily_reward_config where id = 1;
  select * into v_row from public.user_daily_rewards where user_id = v_uid;

  v_claimed_today := v_row.last_claim_date is not null and v_row.last_claim_date = v_today;

  -- The day that would be claimed today (or that was claimed today).
  if v_claimed_today then
    v_claim_day := v_row.current_day;
  elsif v_row.last_claim_date is not null
        and v_row.last_claim_date = (v_today - 1)
        and v_row.current_day between 1 and 6 then
    v_claim_day := v_row.current_day + 1;          -- streak continues
  else
    v_claim_day := 1;                              -- new cycle / missed / first time
  end if;

  v_can_claim := coalesce(v_cfg.enabled, false) and not v_claimed_today;

  select coalesce(jsonb_agg(jsonb_build_object(
           'day_number',    r.day_number,
           'enabled',       r.enabled,
           'reward_type',   r.reward_type,
           'title',         r.title,
           'description',   r.description,
           'amount',        r.amount,
           'duration_days', r.duration_days,
           'image_url',     r.image_url
         ) order by r.day_number), '[]'::jsonb)
  into v_rules
  from public.daily_reward_rules r;

  return jsonb_build_object(
    'enabled',         coalesce(v_cfg.enabled, false),
    'popup_enabled',   coalesce(v_cfg.popup_enabled, false),
    'can_claim_today', v_can_claim,
    'claimed_today',   v_claimed_today,
    'claim_day',       v_claim_day,
    'current_day',     coalesce(v_row.current_day, 0),
    'streak_count',    coalesce(v_row.streak_count, 0),
    'last_claim_date', to_char(v_row.last_claim_date, 'YYYY-MM-DD'),
    'next_claim_date', case when v_claimed_today then to_char(v_today + 1, 'YYYY-MM-DD') else to_char(v_today, 'YYYY-MM-DD') end,
    'rules',           v_rules
  );
end;
$$;


ALTER FUNCTION "public"."get_daily_reward_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_follow_list"("p_user_id" "uuid", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_viewer uuid := auth.uid();
  v_result jsonb;
begin
  if v_viewer is null then raise exception 'not_authenticated'; end if;
  if p_kind not in ('followers', 'following', 'friends') then
    raise exception 'invalid_kind';
  end if;

  with target_ids as (
    select case when p_kind = 'followers' then uf.follower_id
                else uf.following_id end as uid
    from public.user_follows uf
    where (p_kind = 'followers' and uf.following_id = p_user_id)
       or (p_kind in ('following', 'friends') and uf.follower_id = p_user_id)
  ),
  filtered as (
    select distinct t.uid
    from target_ids t
    where p_kind <> 'friends'
       or exists (
            select 1 from public.user_follows b
            where b.follower_id = t.uid and b.following_id = p_user_id
          )
  )
  select coalesce(jsonb_agg(row_to_json(x) order by x.display_name), '[]'::jsonb)
  into v_result
  from (
    select
      p.id,
      p.display_name,
      p.avatar_url,
      p.public_user_id,
      p.gender,
      p.vip_level,
      p.vip_expires_at,
      exists (
        select 1 from public.user_follows vf
        where vf.follower_id = v_viewer and vf.following_id = p.id
      ) as viewer_follows
    from filtered f
    join public.profiles p on p.id = f.uid          -- excludes missing profiles
    where not exists (                              -- exclude blocked (either way)
        select 1 from public.user_blocks ub
        where (ub.blocker_id = v_viewer and ub.blocked_id = p.id)
           or (ub.blocker_id = p.id      and ub.blocked_id = v_viewer)
      )
  ) x;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_follow_list"("p_user_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_gold_ladder_recent_winners"("p_limit" integer DEFAULT 10) RETURNS TABLE("display_name" "text", "entry_fee" integer, "cashout_amount" integer, "multiplier" numeric, "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  select
    coalesce(pr.display_name, 'Player') as display_name,
    r.entry_fee,
    r.cashout_amount,
    case when r.entry_fee > 0 then round(r.cashout_amount::numeric / r.entry_fee, 1) else 0 end as multiplier,
    r.status,
    r.created_at
  from public.gold_ladder_runs r
  left join public.profiles pr on pr.id = r.user_id
  where r.status in ('completed','cashed_out','eliminated')
    and r.cashout_amount > 0
  order by r.created_at desc
  limit p_limit;
end;
$$;


