CREATE OR REPLACE FUNCTION "public"."get_my_agency_membership"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  select jsonb_build_object(
    'role', 'host',
    'status', h.status,
    'joined_at', h.joined_at,
    'agencies', jsonb_build_object(
      'id', a.id,
      'name', a.name,
      'country', a.country,
      'commission_rate', a.commission_rate,
      'monthly_target_coins', a.monthly_target_coins,
      'monthly_target_hours', a.monthly_target_hours
    )
  )
  into v_result
  from public.agency_hosts h
  join public.agencies a on a.id = h.agency_id
  where h.host_user_id = v_uid
    and h.status = 'active'
    and a.status = 'active'
  order by h.joined_at desc
  limit 1;

  return v_result;
end;
$$;


