CREATE OR REPLACE FUNCTION "public"."get_my_backpack"() RETURNS TABLE("id" "uuid", "item_id" "uuid", "item_type" "text", "equipped" boolean, "acquired_at" timestamp with time zone, "expires_at" timestamp with time zone, "expired" boolean, "metadata" "jsonb", "item" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    b.id,
    b.item_id,
    i.item_type,
    b.equipped,
    b.acquired_at,
    b.expires_at,
    b.expires_at is not null and b.expires_at <= now() as expired,
    b.metadata,
    jsonb_build_object(
      'id', i.id,
      'name', i.name,
      'name_ar', i.name_ar,
      'description', i.description,
      'description_ar', i.description_ar,
      'item_type', i.item_type,
      'price_coins', i.price_coins,
      'price_diamonds', i.price_diamonds,
      'rarity', i.rarity,
      'image_url', i.image_url,
      'icon', i.icon,
      'required_vip_level', i.required_vip_level,
      'metadata', coalesce(i.metadata, '{}'::jsonb)
        || jsonb_strip_nulls(
          jsonb_build_object(
            'rarity', i.rarity,
            'image_url', i.image_url,
            'icon', i.icon,
            'vip_level', i.required_vip_level
          )
        ),
      'is_active', i.is_active,
      'sort_order', i.sort_order,
      'owned', true
    ) as item
  from public.gamification_backpack_items b
  join public.gamification_store_items i on i.id = b.item_id
  where b.user_id = (select auth.uid())
    and (select auth.uid()) is not null
  order by b.equipped desc, b.acquired_at desc, b.id;
$$;


