CREATE OR REPLACE FUNCTION "public"."get_my_charm_level"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_row        public.user_charm;
  v_curr_rule  public.charm_level_rules;
  v_next_rule  public.charm_level_rules;
  v_band_start bigint;
  v_band_size  bigint;
  v_progress   numeric;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  insert into public.user_charm (user_id) values (v_user_id)
  on conflict (user_id) do nothing;

  select * into v_row from public.user_charm where user_id = v_user_id;
  select * into v_curr_rule from public.charm_level_rules where level = v_row.charm_level;
  select * into v_next_rule from public.charm_level_rules where level = v_row.charm_level + 1;

  if v_next_rule.level is not null then
    v_band_start := v_curr_rule.required_xp;
    v_band_size  := v_next_rule.required_xp - v_band_start;
    v_progress   := case when v_band_size > 0
                         then greatest(0.0, least(1.0, (v_row.charm_xp - v_band_start)::numeric / v_band_size))
                         else 1.0 end;
  else
    v_progress := 1.0;
  end if;

  return json_build_object(
    'charm_level',            v_row.charm_level,
    'charm_xp',               v_row.charm_xp,
    'tier_number',            v_row.tier_number,
    'tier_name',              v_curr_rule.tier_name,
    'color_hex',              v_curr_rule.color_hex,
    'badge_key',              v_curr_rule.badge_key,
    'next_level',             v_next_rule.level,
    'next_level_required_xp', v_next_rule.required_xp,
    'xp_to_next_level',       case when v_next_rule.level is not null
                                   then greatest(0, v_next_rule.required_xp - v_row.charm_xp)
                                   else null end,
    'level_progress',         v_progress,
    'last_xp_at',             to_char(v_row.last_xp_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
end;
$$;


ALTER FUNCTION "public"."get_my_charm_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_checkin_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_state    jsonb;
  v_dates    jsonb;
  v_schedule jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  v_state := public.get_daily_reward_state();

  -- Build last_7_dates list from the audit ledger.
  select coalesce(
    jsonb_agg(to_char(claimed_date, 'YYYY-MM-DD') order by claimed_date desc),
    '[]'::jsonb
  )
  into v_dates
  from public.daily_reward_claims
  where user_id = v_uid
    and claimed_date >= (now() at time zone 'utc')::date - 6;

  -- Reshape rules array → CheckinReward format.
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'day',           (r->>'day_number')::integer,
        'reward_type',   r->>'reward_type',
        'reward_amount', (r->>'amount')::integer
      ) order by (r->>'day_number')::integer
    ),
    '[]'::jsonb
  )
  into v_schedule
  from jsonb_array_elements(v_state->'rules') as r;

  return jsonb_build_object(
    'today_claimed',  v_state->'claimed_today',
    'streak',         v_state->'streak_count',
    'streak_day',     v_state->'claim_day',
    'last_7_dates',   v_dates,
    'reward_schedule', v_schedule
  );
end;
$$;


ALTER FUNCTION "public"."get_my_checkin_status"() OWNER TO "postgres";


