CREATE OR REPLACE FUNCTION "public"."get_my_level"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_ul           record;
  v_cur_rule     record;
  v_next_rule    record;
  v_xp_in_tier   bigint;
  v_xp_tier_span bigint;
  v_progress     numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.user_levels (user_id)
  VALUES (v_uid)
  ON CONFLICT (user_id) DO UPDATE SET updated_at = public.user_levels.updated_at;

  SELECT * INTO v_ul
  FROM   public.user_levels
  WHERE  user_id = v_uid;

  SELECT * INTO v_cur_rule
  FROM   public.level_rules
  WHERE  level = v_ul.level AND is_active = true
  LIMIT  1;

  SELECT * INTO v_next_rule
  FROM   public.level_rules
  WHERE  level > v_ul.level AND is_active = true
  ORDER  BY level ASC
  LIMIT  1;

  IF v_next_rule IS NOT NULL THEN
    v_xp_in_tier   := v_ul.xp - COALESCE(v_cur_rule.required_xp, 0);
    v_xp_tier_span := v_next_rule.required_xp - COALESCE(v_cur_rule.required_xp, 0);
    v_progress := CASE
      WHEN v_xp_tier_span <= 0 THEN 1.0
      ELSE LEAST(1.0, GREATEST(0.0, v_xp_in_tier::numeric / v_xp_tier_span::numeric))
    END;
  ELSE
    v_progress := 1.0;  -- max level
  END IF;

  RETURN jsonb_build_object(
    'user_id',                    v_uid,
    'level',                      v_ul.level,
    'xp',                         v_ul.xp,
    'total_spent_coins',          v_ul.total_spent_coins,
    'total_received_gifts_value', v_ul.total_received_gifts_value,
    'total_room_minutes',         v_ul.total_room_minutes,
    'total_gifts_sent',           v_ul.total_gifts_sent,
    'total_gifts_received',       v_ul.total_gifts_received,
    'last_xp_at',                 v_ul.last_xp_at,
    'current_level_title',        COALESCE(v_cur_rule.title,      'Level ' || v_ul.level),
    'current_level_color',        COALESCE(v_cur_rule.color_name, 'bronze'),
    'current_level_badge_key',    v_cur_rule.badge_key,
    'current_level_required_xp',  COALESCE(v_cur_rule.required_xp, 0),
    'next_level',                 v_next_rule.level,
    'next_level_title',           v_next_rule.title,
    'next_level_required_xp',     v_next_rule.required_xp,
    'xp_to_next_level',           CASE
                                    WHEN v_next_rule IS NOT NULL
                                    THEN GREATEST(0, v_next_rule.required_xp - v_ul.xp)
                                    ELSE 0
                                  END,
    'level_progress',             v_progress
  );
END;
$$;


ALTER FUNCTION "public"."get_my_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_tasks"() RETURNS TABLE("id" "uuid", "title" "text", "title_ar" "text", "description" "text", "description_ar" "text", "task_type" "text", "requirement_type" "text", "requirement_count" integer, "reward_type" "text", "reward_amount" bigint, "reset_period" "text", "metadata" "jsonb", "sort_order" integer, "progress" integer, "completed" boolean, "claimed" boolean, "completed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    t.id,
    t.title,
    t.title_ar,
    t.description,
    t.description_ar,
    t.task_type,
    t.requirement_type,
    t.requirement_count,
    t.reward_type,
    t.reward_amount,
    t.reset_period,
    t.metadata,
    t.sort_order,
    coalesce(p.progress, 0) as progress,
    (
      p.completed_at is not null
      or coalesce(p.progress, 0) >= t.requirement_count
    ) as completed,
    p.claimed_at is not null as claimed,
    p.completed_at
  from public.gamification_tasks t
  left join public.gamification_task_progress p
    on p.user_id = (select auth.uid())
   and p.task_id = t.id
   and p.period_started_at = case t.reset_period
     when 'daily' then date_trunc('day', now())
     when 'weekly' then date_trunc('week', now())
     else '1970-01-01 00:00:00+00'::timestamptz
   end
  where (select auth.uid()) is not null
    and t.is_active
  order by t.sort_order, t.id;
$$;


ALTER FUNCTION "public"."get_my_tasks"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_tasks"() IS 'Returns active tasks with progress only for the authenticated user and current reset period.';



CREATE OR REPLACE FUNCTION "public"."get_my_vip"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid             uuid        := auth.uid();
  v_now             timestamptz := now();
  v_profile         record;
  v_cur_tier        record;   -- vip_levels row for current tier
  v_next_tier_exp   bigint;   -- required_recharge_exp for next tier
  v_exp_to_next     bigint;
  v_exp_to_maintain bigint;
  v_level           int;
  v_lifetime_exp    bigint;
  v_monthly_exp     bigint;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;

  SELECT
    p.id,
    p.vip_level,
    p.vip_started_at,
    p.vip_expires_at,
    p.vip_title,
    p.is_golden_id,
    p.golden_id_expires_at,
    COALESCE(p.vip_recharge_exp, 0)  AS vip_recharge_exp,
    COALESCE(p.vip_monthly_exp,  0)  AS vip_monthly_exp,
    p.vip_cycle_started_at,
    p.vip_last_recharge_at
  INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_uid;

  IF NOT FOUND THEN RETURN NULL; END IF;

  v_level        := COALESCE(v_profile.vip_level, 0);
  v_lifetime_exp := v_profile.vip_recharge_exp;
  v_monthly_exp  := v_profile.vip_monthly_exp;

  -- ── Look up current tier thresholds ──────────────────────────────────────
  -- NULL when user has no active VIP tier (level = 0).
  IF v_level > 0 THEN
    SELECT
      vl.required_recharge_exp,
      COALESCE(vl.monthly_maintain_exp, vl.required_recharge_exp) AS monthly_maintain_exp
    INTO v_cur_tier
    FROM public.vip_levels vl
    WHERE vl.level = v_level
      AND vl.is_active = true
    LIMIT 1;
  END IF;

  -- ── Look up next tier threshold ───────────────────────────────────────────
  -- NULL at VIP 9 (max tier) or when no tier is defined above current.
  SELECT vl.required_recharge_exp
  INTO   v_next_tier_exp
  FROM   public.vip_levels vl
  WHERE  vl.level > v_level
    AND  vl.is_active = true
    AND  vl.required_recharge_exp IS NOT NULL
  ORDER  BY vl.level ASC
  LIMIT  1;

  -- ── Compute progress values ───────────────────────────────────────────────
  -- exp_to_next_tier: how many more lifetime EXP to reach the next tier.
  --   0 if already at or past the threshold, NULL if no next tier.
  IF v_next_tier_exp IS NOT NULL THEN
    v_exp_to_next := GREATEST(0, v_next_tier_exp - v_lifetime_exp);
  END IF;

  -- exp_to_maintain: how many more monthly EXP to secure current-tier renewal.
  --   0 if already met, NULL if no current tier or no maintain threshold.
  IF v_level > 0 AND v_cur_tier IS NOT NULL AND v_cur_tier.monthly_maintain_exp IS NOT NULL THEN
    v_exp_to_maintain := GREATEST(0, v_cur_tier.monthly_maintain_exp - v_monthly_exp);
  END IF;

  RETURN jsonb_build_object(
    -- ── Existing fields (unchanged) ─────────────────────────────────────────
    'user_id',               v_profile.id,
    'vip_level',             v_level,
    'vip_started_at',        v_profile.vip_started_at,
    'vip_expires_at',        v_profile.vip_expires_at,
    'vip_title',             v_profile.vip_title,
    'is_active',             (
      v_level > 0
      AND (v_profile.vip_expires_at IS NULL OR v_profile.vip_expires_at > v_now)
    ),
    'is_golden_id',          COALESCE(v_profile.is_golden_id, false),
    'golden_id_expires_at',  v_profile.golden_id_expires_at,
    -- ── New EXP progress fields ─────────────────────────────────────────────
    'vip_recharge_exp',          v_lifetime_exp,
    'vip_monthly_exp',           v_monthly_exp,
    'vip_cycle_started_at',      v_profile.vip_cycle_started_at,
    'vip_last_recharge_at',      v_profile.vip_last_recharge_at,
    'current_tier_required_exp', CASE WHEN v_level > 0 THEN v_cur_tier.required_recharge_exp ELSE NULL END,
    'next_tier_required_exp',    v_next_tier_exp,
    'monthly_maintain_exp',      CASE WHEN v_level > 0 THEN v_cur_tier.monthly_maintain_exp  ELSE NULL END,
    'exp_to_next_tier',          v_exp_to_next,
    'exp_to_maintain',           v_exp_to_maintain
  );
END;
$$;


ALTER FUNCTION "public"."get_my_vip"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_wealth_level"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_row        public.user_wealth;
  v_curr_rule  public.wealth_level_rules;
  v_next_rule  public.wealth_level_rules;
  v_band_start bigint;
  v_band_size  bigint;
  v_progress   numeric;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  -- Ensure the row exists.
  insert into public.user_wealth (user_id) values (v_user_id)
  on conflict (user_id) do nothing;

  select * into v_row from public.user_wealth where user_id = v_user_id;

  -- Current level rule.
  select * into v_curr_rule
  from   public.wealth_level_rules
  where  level = v_row.wealth_level;

  -- Next level rule (null at level 100).
  select * into v_next_rule
  from   public.wealth_level_rules
  where  level = v_row.wealth_level + 1;

  -- Progress within current level band (0.0 - 1.0).
  if v_next_rule.level is not null then
    v_band_start := v_curr_rule.required_xp;
    v_band_size  := v_next_rule.required_xp - v_band_start;
    v_progress   := case when v_band_size > 0
                         then least(1.0, (v_row.wealth_xp - v_band_start)::numeric / v_band_size)
                         else 1.0 end;
  else
    v_progress := 1.0;
  end if;

  return json_build_object(
    'wealth_level',        v_row.wealth_level,
    'wealth_xp',           v_row.wealth_xp,
    'tier_number',         v_row.tier_number,
    'tier_name',           v_curr_rule.tier_name,
    'color_hex',           v_curr_rule.color_hex,
    'badge_key',           v_curr_rule.badge_key,
    'next_level',          v_next_rule.level,
    'next_level_required_xp', v_next_rule.required_xp,
    'xp_to_next_level',   case when v_next_rule.level is not null
                               then greatest(0, v_next_rule.required_xp - v_row.wealth_xp)
                               else null end,
    'level_progress',      v_progress,
    'total_recharged_xp',  v_row.total_recharged_xp,
    'total_spent_gift_xp', v_row.total_spent_gift_xp,
    'last_xp_at',          to_char(v_row.last_xp_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );
end;
$$;


ALTER FUNCTION "public"."get_my_wealth_level"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_hungry_cat_round"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_round   public.hungry_cat_global_rounds;
  v_expired public.hungry_cat_global_rounds;
  v_now     timestamptz := now();
  v_rnum    bigint;
  c_dur     constant int := 12; -- seconds per betting window
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  perform pg_advisory_xact_lock(hashtext('hungry_cat_global_round'));

  -- Return existing active round if it still has time remaining
  select * into v_round
  from public.hungry_cat_global_rounds
  where status = 'betting'
  order by created_at desc
  limit 1;

  if v_round.id is not null and v_round.betting_ends_at > v_now then
    return json_build_object(
      'round_id',           v_round.id,
      'round_number',       v_round.round_number,
      'status',             v_round.status,
      'betting_starts_at',  v_round.betting_starts_at,
      'betting_ends_at',    v_round.betting_ends_at,
      'winning_food_id',    v_round.winning_food_id,
      'winning_food_icon',  v_round.winning_food_icon,
      'winning_food_name',  v_round.winning_food_name,
      'winning_multiplier', v_round.winning_multiplier,
      'server_now',         v_now
    );
  end if;

  -- Settle any expired betting rounds that clients missed
  for v_expired in
    select * from public.hungry_cat_global_rounds
    where status = 'betting' and betting_ends_at <= v_now
    order by created_at asc
  loop
    begin
      -- Uses the settle function which is itself idempotent
      perform public.settle_hungry_cat_global_round(v_expired.id);
    exception when others then
      -- Non-fatal: log and continue; the round stays with pending bets
      -- rather than blocking new-round creation.
      raise warning 'get_or_create: could not settle expired round %: %', v_expired.id, sqlerrm;
    end;
  end loop;

  -- Create a new round
  v_rnum := nextval('public.hungry_cat_round_seq');

  insert into public.hungry_cat_global_rounds
    (round_number, status, betting_starts_at, betting_ends_at)
  values
    (v_rnum, 'betting', v_now, v_now + (c_dur || ' seconds')::interval)
  returning * into v_round;

  return json_build_object(
    'round_id',           v_round.id,
    'round_number',       v_round.round_number,
    'status',             v_round.status,
    'betting_starts_at',  v_round.betting_starts_at,
    'betting_ends_at',    v_round.betting_ends_at,
    'winning_food_id',    null,
    'winning_food_icon',  null,
    'winning_food_name',  null,
    'winning_multiplier', null,
    'server_now',         v_now
  );
end;
$$;


ALTER FUNCTION "public"."get_or_create_hungry_cat_round"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_magic_srood_round"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_round   public.magic_srood_global_rounds;
  v_expired public.magic_srood_global_rounds;
  v_now     timestamptz := now();
  v_number  bigint;
  c_duration constant interval := interval '30 seconds';
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  perform pg_advisory_xact_lock(hashtext('magic_srood_global_round'));

  -- Adopt and settle any expired rounds that may have been created by the
  -- pre-migration production functions. This preserves all pending wagers.
  for v_expired in
    select *
    from public.magic_srood_global_rounds
    where status = 'betting'
      and betting_ends_at <= v_now
    order by betting_ends_at, id
  loop
    perform public.settle_magic_srood_global_round(v_expired.id);
  end loop;

  select *
  into v_round
  from public.magic_srood_global_rounds
  where status = 'betting'
    and betting_ends_at > v_now
  order by created_at desc
  limit 1;

  if v_round.id is null then
    v_number := nextval('public.magic_srood_round_seq');
    insert into public.magic_srood_global_rounds (
      round_number, status, betting_starts_at, betting_ends_at
    )
    values (v_number, 'betting', v_now, v_now + c_duration)
    returning * into v_round;
  end if;

  return json_build_object(
    'round_id', v_round.id,
    'round_number', v_round.round_number,
    'status', v_round.status,
    'betting_starts_at', v_round.betting_starts_at,
    'betting_ends_at', v_round.betting_ends_at,
    'winning_food_id', v_round.winning_food_id,
    'winning_food_icon', v_round.winning_food_icon,
    'winning_food_name', v_round.winning_food_name,
    'winning_multiplier', v_round.winning_multiplier,
    'server_now', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_or_create_magic_srood_round"() OWNER TO "postgres";


