CREATE OR REPLACE FUNCTION "public"."get_or_create_my_room"() RETURNS "public"."rooms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_room       public.rooms%rowtype;
  v_lk_name    text;
  v_profile_code text;
  v_country_code text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Return existing personal room (may be open or closed — caller decides)
  SELECT * INTO v_room
  FROM public.rooms
  WHERE owner_id = v_uid AND is_personal_room = true
  LIMIT 1;

  IF FOUND THEN RETURN v_room; END IF;

  -- Generate unique LiveKit room name
  v_lk_name := 'srood_' || EXTRACT(EPOCH FROM NOW())::bigint::text
             || '_' || SUBSTRING(v_uid::text FROM 1 FOR 8);

  -- Try to get country_code from owner's profile for discoverability
  SELECT country_code INTO v_profile_code
  FROM public.profiles
  WHERE id = v_uid
  LIMIT 1;

  IF v_profile_code IS NOT NULL AND v_profile_code <> '' THEN
    v_country_code := UPPER(TRIM(v_profile_code));
  END IF;

  BEGIN
    INSERT INTO public.rooms (
      owner_id, name, description, language, max_seats,
      livekit_room_name, is_personal_room, country_code
    ) VALUES (
      v_uid, 'SrOOd Room', NULL, 'ar', 12,
      v_lk_name, true, v_country_code
    )
    RETURNING * INTO v_room;

    RETURN v_room;
  EXCEPTION
    WHEN unique_violation THEN
      -- Race: another concurrent call already created it — just fetch it.
      SELECT * INTO v_room
      FROM public.rooms
      WHERE owner_id = v_uid AND is_personal_room = true
      LIMIT 1;
      RETURN v_room;
  END;
END;
$$;


ALTER FUNCTION "public"."get_or_create_my_room"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_rocket_crash_round"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_round  public.rocket_crash_global_rounds;
  v_now    timestamptz := now();
  v_rnum   bigint;
  c_bet_s  constant int := 8;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  perform pg_advisory_xact_lock(hashtext('rocket_crash_global_round'));

  -- Current betting round (not expired)
  select * into v_round
  from public.rocket_crash_global_rounds
  where status = 'betting' and betting_ends_at > v_now
  order by created_at desc
  limit 1;

  if v_round.id is null then
    -- Current flying round (not stale — max flight ~95s for 200x crash)
    select * into v_round
    from public.rocket_crash_global_rounds
    where status = 'flying'
      and flight_starts_at > v_now - interval '120 seconds'
    order by created_at desc
    limit 1;
  end if;

  if v_round.id is not null then
    return json_build_object(
      'round_id',          v_round.id,
      'round_number',      v_round.round_number,
      'status',            v_round.status,
      'betting_ends_at',   extract(epoch from v_round.betting_ends_at) * 1000,
      'flight_starts_at',  case when v_round.flight_starts_at is not null
                               then extract(epoch from v_round.flight_starts_at) * 1000
                               else null end,
      -- Fairness: never reveal the crash point before the round has crashed.
      'crash_multiplier',  case when v_round.status = 'crashed'
                               then v_round.crash_multiplier
                               else null end,
      'server_now',        extract(epoch from v_now) * 1000
    );
  end if;

  -- Create new betting round
  v_rnum := nextval('public.rocket_crash_round_seq');
  insert into public.rocket_crash_global_rounds
    (round_number, status, betting_starts_at, betting_ends_at)
  values
    (v_rnum, 'betting', v_now, v_now + (c_bet_s || ' seconds')::interval)
  returning * into v_round;

  return json_build_object(
    'round_id',         v_round.id,
    'round_number',     v_round.round_number,
    'status',           'betting',
    'betting_ends_at',  extract(epoch from v_round.betting_ends_at) * 1000,
    'flight_starts_at', null,
    'crash_multiplier', null,
    'server_now',       extract(epoch from v_now) * 1000
  );
end;
$$;


ALTER FUNCTION "public"."get_or_create_rocket_crash_round"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recent_crash_rounds"("p_limit" integer DEFAULT 20) RETURNS TABLE("crash_multiplier" numeric, "crashed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  select r.crash_multiplier, r.crashed_at
  from public.crash_rounds r
  where r.status = 'crashed'
  order by r.crashed_at desc
  limit p_limit;
end;
$$;


