CREATE OR REPLACE FUNCTION "public"."get_srood_blocks_daily_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_vip_level  int  := 0;
  v_free_plays int;
  v_plays_used int  := 0;
  v_xp_today   int  := 0;
  v_play_date  date;
  v_coins_bal  bigint := 0;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  -- VIP level
  select coalesce(vip_level, 0) into v_vip_level
  from public.profiles where id = v_user_id;

  -- free plays by VIP tier
  v_free_plays := case
    when v_vip_level >= 3 then 6
    when v_vip_level = 2  then 5
    when v_vip_level = 1  then 4
    else 3
  end;

  -- daily record (may not exist yet)
  select plays_used, xp_earned, play_date
  into v_plays_used, v_xp_today, v_play_date
  from public.srood_blocks_daily_limits
  where user_id = v_user_id;

  -- reset if stale date
  if v_play_date is null or v_play_date < current_date then
    v_plays_used := 0;
    v_xp_today   := 0;
  end if;

  -- coin balance
  select coalesce(coins_balance, 0) into v_coins_bal
  from public.wallets where user_id = v_user_id;

  return jsonb_build_object(
    'free_plays',    v_free_plays,
    'plays_used',    v_plays_used,
    'xp_today',      v_xp_today,
    'xp_cap',        100,
    'coins_balance', v_coins_bal,
    'extra_play_cost', 50
  );
end;
$$;


ALTER FUNCTION "public"."get_srood_blocks_daily_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_srood_blocks_weekly_leaderboard"("p_limit" integer DEFAULT 50) RETURNS TABLE("rank" bigint, "user_id" "uuid", "display_name" "text", "avatar_url" "text", "best_score" integer, "total_lines" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_week_start date := date_trunc('week', current_date)::date;
begin
  return query
  with best as (
    select
      s.user_id,
      max(s.score)          as best_score,
      sum(s.lines_cleared)  as total_lines
    from public.srood_blocks_scores s
    where s.week_start = v_week_start
    group by s.user_id
  )
  select
    row_number() over (order by b.best_score desc, b.total_lines desc) as rank,
    b.user_id,
    coalesce(p.display_name, p.username, 'Player')::text,
    p.avatar_url::text,
    b.best_score::integer,
    b.total_lines
  from best b
  left join public.profiles p on p.id = b.user_id
  order by b.best_score desc, b.total_lines desc
  limit least(p_limit, 100);
end;
$$;


ALTER FUNCTION "public"."get_srood_blocks_weekly_leaderboard"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_store_items"() RETURNS TABLE("id" "uuid", "name" "text", "name_ar" "text", "description" "text", "description_ar" "text", "item_type" "text", "price_coins" bigint, "price_diamonds" bigint, "rarity" "text", "image_url" "text", "icon" "text", "required_vip_level" integer, "metadata" "jsonb", "is_active" boolean, "sort_order" integer, "owned" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    i.id,
    i.name,
    i.name_ar,
    i.description,
    i.description_ar,
    i.item_type,
    i.price_coins,
    i.price_diamonds,
    i.rarity,
    i.image_url,
    i.icon,
    i.required_vip_level,
    coalesce(i.metadata, '{}'::jsonb)
      || jsonb_strip_nulls(
        jsonb_build_object(
          'rarity', i.rarity,
          'image_url', i.image_url,
          'icon', i.icon,
          'vip_level', i.required_vip_level
        )
      ) as metadata,
    i.is_active,
    i.sort_order,
    exists (
      select 1
      from public.gamification_backpack_items b
      where b.user_id = (select auth.uid())
        and b.item_id = i.id
        and (b.expires_at is null or b.expires_at > now())
    ) as owned
  from public.gamification_store_items i
  where (select auth.uid()) is not null
    and i.is_active
  order by i.sort_order, i.id;
$$;


ALTER FUNCTION "public"."get_store_items"() OWNER TO "postgres";


