CREATE OR REPLACE FUNCTION "public"."get_user_level"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_level  int;
  v_rule   record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT ul.level
  INTO   v_level
  FROM   public.user_levels ul
  WHERE  ul.user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT lr.title, lr.color_name, lr.badge_key
  INTO   v_rule
  FROM   public.level_rules lr
  WHERE  lr.level     = v_level
    AND  lr.is_active = true
  LIMIT 1;

  RETURN jsonb_build_object(
    'user_id',    p_user_id,
    'level',      v_level,
    'title',      COALESCE(v_rule.title,      'Level ' || v_level),
    'color_name', COALESCE(v_rule.color_name, 'bronze'),
    'badge_key',  v_rule.badge_key
  );
END;
$$;


