CREATE OR REPLACE FUNCTION "public"."get_user_vip"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_now timestamptz := now();
BEGIN
  SELECT p.id, p.vip_level, p.vip_started_at, p.vip_expires_at, p.vip_title, p.is_golden_id, p.golden_id_expires_at
  INTO v_row FROM public.profiles p WHERE p.id = p_user_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN json_build_object(
    'user_id', v_row.id,
    'vip_level', COALESCE(v_row.vip_level, 0),
    'vip_started_at', v_row.vip_started_at,
    'vip_expires_at', v_row.vip_expires_at,
    'vip_title', v_row.vip_title,
    'is_active', (COALESCE(v_row.vip_level, 0) > 0 AND (v_row.vip_expires_at IS NULL OR v_row.vip_expires_at > v_now)),
    'is_golden_id', COALESCE(v_row.is_golden_id, false),
    'golden_id_expires_at', v_row.golden_id_expires_at
  );
END;
$$;


