CREATE OR REPLACE FUNCTION "public"."grant_room_xp"("p_room_id" "uuid", "p_xp" bigint, "p_source" "text" DEFAULT 'gift'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_room          record;
  v_actual_xp     bigint := p_xp;
  v_passive_cap   bigint := 50000;
  v_new_xp        bigint;
  v_new_level     smallint;
  v_leveled_up    boolean := false;
begin
  select room_xp, room_level, xp_today_gift, xp_today_passive,
         xp_week, daily_streak, streak_multiplier, last_active_date
  into v_room
  from public.rooms
  where id = p_room_id
  for update;

  if not found then
    return jsonb_build_object('error', 'room_not_found');
  end if;

  -- Enforce passive daily cap (non-gift sources)
  if p_source <> 'gift' then
    if v_room.xp_today_passive >= v_passive_cap then
      return jsonb_build_object('capped', true, 'room_xp', v_room.room_xp, 'room_level', v_room.room_level);
    end if;
    v_actual_xp := least(p_xp, v_passive_cap - v_room.xp_today_passive);
  end if;

  -- Apply streak multiplier (only to non-gift to prevent abuse inflation)
  if p_source <> 'gift' then
    v_actual_xp := ceil(v_actual_xp::numeric * v_room.streak_multiplier);
  end if;

  v_new_xp := v_room.room_xp + v_actual_xp;

  -- Compute new level from thresholds
  select coalesce(max(level), 1) into v_new_level
  from public.room_level_thresholds
  where xp_required <= v_new_xp;

  v_leveled_up := v_new_level > v_room.room_level;

  update public.rooms set
    room_xp          = v_new_xp,
    room_level       = v_new_level,
    xp_today_gift    = case when p_source = 'gift'  then xp_today_gift  + v_actual_xp else xp_today_gift  end,
    xp_today_passive = case when p_source <> 'gift' then xp_today_passive + v_actual_xp else xp_today_passive end,
    xp_week          = xp_week + v_actual_xp,
    last_xp_at       = now(),
    last_active_date = current_date
  where id = p_room_id;

  return jsonb_build_object(
    'room_xp',    v_new_xp,
    'room_level', v_new_level,
    'leveled_up', v_leveled_up,
    'xp_granted', v_actual_xp
  );
end;
$$;


ALTER FUNCTION "public"."grant_room_xp"("p_room_id" "uuid", "p_xp" bigint, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_vip"("p_user_id" "uuid", "p_vip_level" integer, "p_duration_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_now timestamptz := now();
  v_expires_at timestamptz;
  v_sub_id uuid;
begin
  if not public._vip_caller_is_admin() then
    raise exception 'permission_denied: admin role required'
      using errcode = 'insufficient_privilege';
  end if;

  if p_vip_level < 0 or p_vip_level > 9 then
    raise exception 'invalid_vip_level: must be 0-9'
      using errcode = 'invalid_parameter_value';
  end if;

  if p_vip_level = 0 then
    update public.user_vip_subscriptions
    set is_active = false,
        updated_at = now()
    where user_id = p_user_id
      and is_active = true;

    update public.profiles
    set vip_level = 0,
        vip_expires_at = null,
        vip_started_at = null,
        updated_at = now()
    where id = p_user_id;

    return jsonb_build_object(
      'user_id', p_user_id,
      'vip_level', 0,
      'action', 'revoked'
    );
  end if;

  v_expires_at := v_now + (greatest(coalesce(p_duration_days, 30), 1) * interval '1 day');

  update public.user_vip_subscriptions
  set is_active = false,
      updated_at = now()
  where user_id = p_user_id
    and is_active = true;

  insert into public.user_vip_subscriptions (
    user_id,
    vip_level,
    starts_at,
    ends_at,
    is_active,
    payment_source,
    created_by_admin
  )
  values (
    p_user_id,
    p_vip_level,
    v_now,
    v_expires_at,
    true,
    'admin_grant',
    v_caller
  )
  returning id into v_sub_id;

  update public.profiles
  set vip_level = p_vip_level,
      vip_started_at = v_now,
      vip_expires_at = v_expires_at,
      updated_at = now()
  where id = p_user_id;

  return jsonb_build_object(
    'user_id', p_user_id,
    'vip_level', p_vip_level,
    'expires_at', v_expires_at,
    'subscription_id', v_sub_id,
    'action', 'granted'
  );
end;
$$;


ALTER FUNCTION "public"."grant_vip"("p_user_id" "uuid", "p_vip_level" integer, "p_duration_days" integer) OWNER TO "postgres";


