CREATE OR REPLACE FUNCTION "public"."has_admin_permission"("p_permission" "text", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role        text;
  v_permissions jsonb;
  v_default     boolean := false;
BEGIN
  -- Fetch role + permissions override
  SELECT role, permissions
  INTO   v_role, v_permissions
  FROM   public.admin_users
  WHERE  user_id  = p_user_id
    AND  is_active = true
  LIMIT  1;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  -- Check jsonb override first (explicit grant or deny)
  IF v_permissions ? p_permission THEN
    RETURN (v_permissions ->> p_permission)::boolean;
  END IF;

  -- Default sets
  v_default := CASE v_role
    WHEN 'o_super_admin' THEN true  -- all permissions
    WHEN 'p_super_admin' THEN p_permission NOT IN (
      'users.unban',
      'users.delete',
      'wallet.debit',
      'wallet.prices',
      'gifts.prices',
      'settings.manage',
      'admins.create',
      'admins.remove',
      'admins.change_roles',
      'draw.force_settle',
      'draw.void_refund',
      'treasure.prize_settings'
    )
    WHEN 'super_admin' THEN p_permission IN (
      'users.view',
      'users.edit',
      'users.temp_ban',
      'users.permanent_ban',
      'rooms.view',
      'rooms.close',
      'reports.view',
      'reports.manage',
      'content.remove',
      'agencies.view',
      'hosts.manage',
      'charisma.agency_manage',
      'charisma.crown_winner',
      'games.logs',
      'analytics.view',
      'banners.manage',
      'notifications.send',
      'audit_logs.view'
    )
    WHEN 'admin' THEN p_permission IN (
      'users.view',
      'users.temp_ban',
      'rooms.view',
      'rooms.close',
      'reports.view',
      'reports.manage',
      'content.remove'
    )
    ELSE false
  END;

  RETURN v_default;
END;
$$;


ALTER FUNCTION "public"."has_admin_permission"("p_permission" "text", "p_user_id" "uuid") OWNER TO "postgres";


