CREATE OR REPLACE FUNCTION "public"."has_app_role"("p_role" "text") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.admin_users au
    where au.user_id = auth.uid()
      and au.is_active = true
      and (
        -- Owner roles pass everything.
        au.role = 'o_super_admin'

        -- Platform super admin passes old super_admin checks.
        or (
          au.role = 'p_super_admin'
          and lower(coalesce(p_role, '')) in (
            'super_admin',
            'admin',
            'support_admin',
            'content_admin',
            'finance_admin',
            'bd_admin',
            'room_admin',
            'moderator'
          )
        )

        -- Normal super admin passes old super_admin and lower admin checks.
        or (
          au.role = 'super_admin'
          and lower(coalesce(p_role, '')) in (
            'super_admin',
            'admin',
            'support_admin',
            'content_admin',
            'finance_admin',
            'bd_admin',
            'room_admin',
            'moderator'
          )
        )

        -- Admin passes admin-level operational checks.
        or (
          au.role = 'admin'
          and lower(coalesce(p_role, '')) in (
            'admin',
            'support_admin',
            'content_admin',
            'room_admin',
            'moderator'
          )
        )

        -- Exact match fallback for older custom roles still stored in admin_users.
        or au.role = lower(coalesce(p_role, ''))
      )
  );
$$;


ALTER FUNCTION "public"."has_app_role"("p_role" "text") OWNER TO "postgres";


