CREATE OR REPLACE FUNCTION "public"."increment_task_progress"("p_requirement_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid:=auth.uid();
  v_daily_key text:=to_char(current_date,'YYYY-MM-DD');
  v_weekly_key text:=to_char(current_date,'IYYY-"W"IW');
  v_task tasks%rowtype; v_period_key text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  for v_task in select * from tasks where requirement_type=p_requirement_type and is_active=true loop
    v_period_key:=case v_task.task_type when 'daily' then v_daily_key when 'weekly' then v_weekly_key else v_daily_key end;
    insert into user_task_progress(user_id,task_id,period_key,progress,completed)
    values(v_uid,v_task.id,v_period_key,0,false) on conflict(user_id,task_id,period_key) do nothing;
    update user_task_progress set
      progress=least(progress+1,v_task.requirement_count),
      completed=(progress+1>=v_task.requirement_count),
      completed_at=case when completed then completed_at when progress+1>=v_task.requirement_count then now() else null end
    where user_id=v_uid and task_id=v_task.id and period_key=v_period_key and not completed;
  end loop;
end;$$;


ALTER FUNCTION "public"."increment_task_progress"("p_requirement_type" "text") OWNER TO "postgres";


