CREATE OR REPLACE FUNCTION "public"."join_room_with_password"("p_room_id" "uuid", "p_password" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_user_id      uuid;
  v_owner_id     uuid;
  v_is_locked    boolean;
  v_is_closed    boolean;
  v_password_hash text;
  v_role         text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select owner_id, is_locked, coalesce(is_closed, false), room_password_hash
  into   v_owner_id, v_is_locked, v_is_closed, v_password_hash
  from   public.rooms
  where  id = p_room_id;

  if v_owner_id is null then
    raise exception 'room_not_found';
  end if;

  if v_is_closed then
    raise exception 'closed_room';
  end if;

  if v_owner_id = v_user_id then
    v_role := 'host';
  else
    v_role := 'listener';
  end if;

  if v_is_locked and v_role = 'listener' then
    if v_password_hash is null then
      raise exception 'locked_room';
    end if;

    if p_password is null or extensions.crypt(trim(p_password), v_password_hash) <> v_password_hash then
      raise exception 'wrong_room_password';
    end if;
  end if;

  insert into public.room_members (
    room_id,
    user_id,
    role,
    is_muted,
    left_at,
    last_seen_at
  )
  values (
    p_room_id,
    v_user_id,
    v_role,
    true,
    null,
    now()
  )
  on conflict (room_id, user_id)
  do update set
    role        = excluded.role,
    is_muted    = true,
    force_muted = false,
    seat_number = null,
    left_at     = null,
    last_seen_at = now();
end;
$$;


ALTER FUNCTION "public"."join_room_with_password"("p_room_id" "uuid", "p_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_room_and_maybe_close"("p_room_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id      uuid := auth.uid();
  v_owner_id     uuid;
  v_is_personal  boolean;
  v_active_count integer;
  v_was_closed   boolean := false;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Soft-remove caller from room.
  UPDATE public.room_members
  SET left_at = now(), last_seen_at = now(), is_muted = true
  WHERE room_id = p_room_id AND user_id = v_user_id AND left_at IS NULL;

  -- Fetch room ownership and personal-room flag.
  SELECT owner_id, is_personal_room INTO v_owner_id, v_is_personal
  FROM public.rooms
  WHERE id = p_room_id AND is_closed = false;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('closed', false, 'was_owner', false);
  END IF;

  -- Auto-close only for non-personal rooms when the owner is the last to leave.
  IF v_owner_id = v_user_id AND NOT v_is_personal THEN
    SELECT count(*) INTO v_active_count
    FROM public.room_members
    WHERE room_id = p_room_id AND left_at IS NULL;

    IF v_active_count = 0 THEN
      UPDATE public.rooms
      SET
        is_closed     = true,
        closed_at     = now(),
        closed_by     = v_user_id,
        closed_reason = 'owner_left_empty'
      WHERE id = p_room_id;
      v_was_closed := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'closed',    v_was_closed,
    'was_owner', (v_owner_id = v_user_id)
  );
END;
$$;


ALTER FUNCTION "public"."leave_room_and_maybe_close"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lock_room_game_round"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid    uuid := auth.uid();
  v_round  record;
  v_secret record;
  v_food   record;
  v_result jsonb;
  -- settle variables
  v_bet    record;
  v_win    bigint;
  v_new_bal bigint;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select r.* into v_round
  from public.room_game_rounds r
  where r.id = p_round_id
  for update;

  if not found then raise exception 'round_not_found'; end if;

  -- Only host can lock
  if not exists (
    select 1 from public.rooms where id = v_round.room_id and owner_id = v_uid
  ) then
    raise exception 'not_room_host';
  end if;

  if v_round.status != 'betting_open' then
    raise exception 'round_not_in_betting';
  end if;

  -- Read pre-committed secret
  select * into v_secret from public.room_game_round_secrets
  where round_id = p_round_id;

  if not found then raise exception 'secret_not_found'; end if;

  -- Ã¢â€â‚¬Ã¢â€â‚¬ Hungry Cat: reveal + settle immediately Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  if v_round.game_code = 'hungry_cat' then
    select * into v_food
    from public.hungry_cat_config
    where food_id = v_secret.winning_food_id;

    if not found then raise exception 'winning_food_not_found'; end if;

    v_result := jsonb_build_object(
      'winning_food_id',    v_food.food_id,
      'winning_food_icon',  v_food.icon,
      'winning_food_name',  v_food.name,
      'winning_multiplier', v_food.multiplier,
      'rarity',             v_food.rarity
    );

    -- Settle all bets
    for v_bet in
      select * from public.room_game_bets
      where round_id = p_round_id and status = 'pending'
    loop
      if (v_bet.bet_json->>'food_id') = v_food.food_id then
        v_win := floor(v_bet.bet_amount::float * v_food.multiplier::float)::bigint;
        update public.room_game_bets
        set status = 'won', payout_amount = v_win, settled_at = now()
        where id = v_bet.id;

        update public.wallets
        set coins_balance = coins_balance + v_win, updated_at = now()
        where user_id = v_bet.user_id
        returning coins_balance into v_new_bal;

        insert into public.wallet_transactions
          (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
        values
          (v_bet.user_id, 'room_game_win', 'credit', v_win, 0,
           'Room Hungry Cat win Ã¢â‚¬â€ ' || v_food.name || ' Ãƒâ€”' || v_food.multiplier,
           jsonb_build_object('round_id', p_round_id, 'bet_id', v_bet.id,
                              'food_id', v_food.food_id, 'multiplier', v_food.multiplier));
      else
        update public.room_game_bets
        set status = 'lost', payout_amount = 0, settled_at = now()
        where id = v_bet.id;
      end if;
    end loop;

    -- Reveal seed for provably-fair audit
    update public.room_game_rounds
    set status      = 'finished',
        result_json = v_result,
        seed        = v_secret.raw_seed, -- now revealed
        started_at  = now(),
        finished_at = now(),
        updated_at  = now()
    where id = p_round_id;

    return jsonb_build_object('status', 'finished', 'result', v_result);
  end if;

  -- Ã¢â€â‚¬Ã¢â€â‚¬ Crash Rocket: transition to 'running' (rocket launches) Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
  if v_round.game_code = 'crash_rocket' then
    -- Mark all pending bets as running
    update public.room_game_bets
    set status = 'running'
    where round_id = p_round_id and status = 'pending';

    update public.room_game_rounds
    set status     = 'running',
        started_at = now(),
        updated_at = now()
    where id = p_round_id;

    return jsonb_build_object('status', 'running', 'started_at', now());
  end if;

  raise exception 'unsupported_game_code';
end;
$$;


ALTER FUNCTION "public"."lock_room_game_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_moderation_event"("p_room_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'chat'::"text", "p_violation_type" "text" DEFAULT 'other'::"text", "p_severity" integer DEFAULT 1, "p_original_text" "text" DEFAULT NULL::"text", "p_normalized_text" "text" DEFAULT NULL::"text", "p_matched_rule" "text" DEFAULT NULL::"text", "p_action_taken" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id  uuid := auth.uid();
  v_event_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  insert into public.moderation_events
    (user_id, room_id, source, violation_type, severity,
     original_text, normalized_text, matched_rule, action_taken)
  values
    (v_user_id, p_room_id, p_source, p_violation_type, p_severity,
     p_original_text, p_normalized_text, p_matched_rule, p_action_taken)
  returning id into v_event_id;

  -- Upsert score
  insert into public.moderation_user_scores
    (user_id, score, last_violation_at,
     warning_count, mute_count, updated_at)
  values
    (v_user_id, p_severity, now(),
     case when p_severity = 1 then 1 else 0 end,
     case when p_severity >= 2 then 1 else 0 end,
     now())
  on conflict (user_id) do update set
    score             = public.moderation_user_scores.score + p_severity,
    last_violation_at = now(),
    warning_count     = public.moderation_user_scores.warning_count
                        + case when p_severity = 1 then 1 else 0 end,
    mute_count        = public.moderation_user_scores.mute_count
                        + case when p_severity >= 2 then 1 else 0 end,
    updated_at        = now();

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."log_moderation_event"("p_room_id" "uuid", "p_source" "text", "p_violation_type" "text", "p_severity" integer, "p_original_text" "text", "p_normalized_text" "text", "p_matched_rule" "text", "p_action_taken" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loto_buy_ticket"("p_numbers" integer[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id  uuid    := auth.uid();
  v_s        record;
  v_draw     record;
  v_wallet   record;
  v_ticket_id uuid;
  v_n        integer;
  v_seen     integer[];
  v_contrib  bigint;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_s from public.loto_settings where game_key = 'srood_loto' limit 1;
  if not found or not v_s.is_enabled then
    raise exception 'game_disabled';
  end if;

  -- Validate ticket numbers
  if array_length(p_numbers, 1) is distinct from v_s.numbers_per_ticket then
    raise exception 'invalid_count: expected % numbers', v_s.numbers_per_ticket;
  end if;

  v_seen := '{}';
  foreach v_n in array p_numbers loop
    if v_n < v_s.number_min or v_n > v_s.number_max then
      raise exception 'number_out_of_range: % must be between % and %', v_n, v_s.number_min, v_s.number_max;
    end if;
    if v_n = any(v_seen) then
      raise exception 'duplicate_number: % appears more than once', v_n;
    end if;
    v_seen := v_seen || v_n;
  end loop;

  -- Find current open draw with tickets still open
  select * into v_draw
  from public.loto_draws
  where status = 'open' and draw_at > now() and closes_at > now()
  order by draw_at asc limit 1;

  if not found then
    raise exception 'draw_closed: no open draw available';
  end if;

  -- Lock wallet row and check balance
  select * into v_wallet
  from public.wallets
  where user_id = v_user_id
  for update;

  if not found or v_wallet.coins_balance < v_s.ticket_price_coins then
    raise exception 'insufficient_balance: need % coins', v_s.ticket_price_coins;
  end if;

  -- Deduct ticket price
  update public.wallets
  set coins_balance = coins_balance - v_s.ticket_price_coins,
      updated_at    = now()
  where user_id = v_user_id;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'srood_loto_ticket', 'debit', -v_s.ticket_price_coins, 0,
     'Srood Loto ticket – Draw #' || v_draw.draw_number,
     jsonb_build_object('draw_id', v_draw.id, 'numbers', p_numbers));

  -- Progressive jackpot contribution
  if v_s.progressive_jackpot_enabled and v_s.jackpot_contribution_pct > 0 then
    v_contrib := floor(v_s.ticket_price_coins * v_s.jackpot_contribution_pct / 100.0)::bigint;
    update public.loto_settings
    set jackpot_pool_coins = jackpot_pool_coins + v_contrib, updated_at = now()
    where game_key = 'srood_loto';
    -- Also update the current draw's jackpot snapshot
    update public.loto_draws
    set jackpot_pool_before = jackpot_pool_before + v_contrib
    where id = v_draw.id;
  end if;

  -- Create ticket (numbers sorted ascending for consistent display)
  insert into public.loto_tickets (draw_id, user_id, numbers, ticket_price_coins, status)
  values (v_draw.id, v_user_id,
          array(select unnest(p_numbers) order by 1),
          v_s.ticket_price_coins, 'active')
  returning id into v_ticket_id;

  -- Update draw counters
  update public.loto_draws
  set total_tickets    = total_tickets + 1,
      total_sales_coins = total_sales_coins + v_s.ticket_price_coins
  where id = v_draw.id;

  return jsonb_build_object(
    'ticket_id',      v_ticket_id,
    'draw_id',        v_draw.id,
    'draw_number',    v_draw.draw_number,
    'numbers',        array(select unnest(p_numbers) order by 1),
    'ticket_price',   v_s.ticket_price_coins,
    'new_balance',    (select coins_balance from public.wallets where user_id = v_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."loto_buy_ticket"("p_numbers" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loto_create_next_draw_if_needed"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_s            record;
  v_draw_id      uuid;
  v_base         timestamptz;
  v_next_draw_at timestamptz;
  v_closes_at    timestamptz;
begin
  select * into v_s from public.loto_settings where game_key = 'srood_loto' limit 1;
  if not found or not v_s.is_enabled then return null; end if;

  -- Return existing future open draw
  select id into v_draw_id
  from public.loto_draws
  where status = 'open' and draw_at > now()
  order by draw_at asc limit 1;
  if found then return v_draw_id; end if;

  -- Next hour boundary (UTC)
  v_base         := date_trunc('hour', now() at time zone 'UTC') at time zone 'UTC';
  v_next_draw_at := v_base + (interval '1 minute' * v_s.draw_interval_minutes);
  while v_next_draw_at <= now() + interval '90 seconds' loop
    v_next_draw_at := v_next_draw_at + (interval '1 minute' * v_s.draw_interval_minutes);
  end loop;

  v_closes_at := v_next_draw_at - (interval '1 minute' * v_s.ticket_close_minutes_before);

  insert into public.loto_draws (status, opens_at, closes_at, draw_at, jackpot_pool_before)
  values ('open', now(), v_closes_at, v_next_draw_at, coalesce(v_s.jackpot_pool_coins, 0))
  returning id into v_draw_id;

  return v_draw_id;
end;
$$;


ALTER FUNCTION "public"."loto_create_next_draw_if_needed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loto_get_current_draw"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id  uuid := auth.uid();
  v_draw     record;
  v_s        record;
  v_balance  integer;
  v_tickets  jsonb;
  v_draw_id  uuid;
begin
  -- Settle any overdue draws and ensure a draw exists
  perform public.loto_settle_due_draws();
  perform public.loto_create_next_draw_if_needed();

  select * into v_s from public.loto_settings where game_key = 'srood_loto' limit 1;

  -- Current draw: the nearest future open draw
  select * into v_draw
  from public.loto_draws
  where status = 'open' and draw_at > now()
  order by draw_at asc limit 1;

  if not found then
    return jsonb_build_object('draw', null, 'settings', row_to_json(v_s));
  end if;

  -- User balance
  select coalesce(coins_balance, 0) into v_balance
  from public.wallets where user_id = v_user_id;

  -- User tickets for this draw
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          t.id,
    'numbers',     t.numbers,
    'status',      t.status,
    'matched_count', t.matched_count,
    'prize_coins', t.prize_coins,
    'created_at',  t.created_at
  ) order by t.created_at desc), '[]'::jsonb)
  into v_tickets
  from public.loto_tickets t
  where t.draw_id = v_draw.id and t.user_id = v_user_id;

  return jsonb_build_object(
    'draw', jsonb_build_object(
      'id',                 v_draw.id,
      'draw_number',        v_draw.draw_number,
      'status',             v_draw.status,
      'opens_at',           v_draw.opens_at,
      'closes_at',          v_draw.closes_at,
      'draw_at',            v_draw.draw_at,
      'total_tickets',      v_draw.total_tickets,
      'total_sales_coins',  v_draw.total_sales_coins,
      'jackpot_pool_before',v_draw.jackpot_pool_before
    ),
    'settings', jsonb_build_object(
      'is_enabled',                 v_s.is_enabled,
      'ticket_price_coins',         v_s.ticket_price_coins,
      'number_min',                 v_s.number_min,
      'number_max',                 v_s.number_max,
      'numbers_per_ticket',         v_s.numbers_per_ticket,
      'match_3_prize',              v_s.match_3_prize,
      'match_4_prize',              v_s.match_4_prize,
      'match_5_prize',              v_s.match_5_prize,
      'match_6_prize',              v_s.match_6_prize,
      'progressive_jackpot_enabled',v_s.progressive_jackpot_enabled,
      'jackpot_pool_coins',         v_s.jackpot_pool_coins,
      'responsible_notice_ar',      v_s.responsible_notice_ar,
      'responsible_notice_en',      v_s.responsible_notice_en
    ),
    'my_tickets',           v_tickets,
    'user_balance',         coalesce(v_balance, 0),
    'seconds_until_draw',   greatest(0, extract(epoch from (v_draw.draw_at - now()))::integer),
    'seconds_until_close',  greatest(0, extract(epoch from (v_draw.closes_at - now()))::integer)
  );
end;
$$;


ALTER FUNCTION "public"."loto_get_current_draw"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loto_get_my_tickets"("p_draw_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',            t.id,
      'draw_id',       t.draw_id,
      'numbers',       t.numbers,
      'ticket_price_coins', t.ticket_price_coins,
      'status',        t.status,
      'matched_count', t.matched_count,
      'prize_coins',   t.prize_coins,
      'created_at',    t.created_at,
      'draw_number',   d.draw_number,
      'draw_at',       d.draw_at,
      'winning_numbers', d.winning_numbers
    ) order by t.created_at desc)
    from public.loto_tickets t
    join public.loto_draws d on d.id = t.draw_id
    where t.draw_id = p_draw_id and t.user_id = v_user_id
  ), '[]'::jsonb);
end;
$$;


