CREATE OR REPLACE FUNCTION "public"."owner_close_room"("p_room_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Only the owner can force-close
  IF NOT EXISTS (
    SELECT 1 FROM public.rooms
    WHERE id = p_room_id AND owner_id = v_user_id AND is_closed = false
  ) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  -- Mark all active members as left
  UPDATE public.room_members
  SET
    left_at      = now(),
    last_seen_at = now(),
    is_muted     = true
  WHERE room_id = p_room_id AND left_at IS NULL;

  -- Close the room
  UPDATE public.rooms
  SET
    is_closed     = true,
    closed_at     = now(),
    closed_by     = v_user_id,
    closed_reason = 'owner_closed'
  WHERE id = p_room_id;
END;
$$;


ALTER FUNCTION "public"."owner_close_room"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_close_room_with_pin"("p_room_id" "uuid", "p_pin" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_owner   uuid;
  v_enabled boolean;
  v_hash    text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT owner_id, room_pin_enabled, room_pin_hash
  INTO   v_owner, v_enabled, v_hash
  FROM   public.rooms
  WHERE  id = p_room_id AND is_closed = false;
  IF NOT FOUND THEN RAISE EXCEPTION 'room_not_found'; END IF;
  IF v_owner <> auth.uid() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_enabled AND v_hash IS NOT NULL THEN
    IF p_pin IS NULL OR
       encode(sha256(convert_to(p_pin, 'UTF8')), 'hex') <> v_hash
    THEN
      RAISE EXCEPTION 'wrong_pin';
    END IF;
  END IF;
  UPDATE public.room_members
  SET left_at = now(), last_seen_at = now(), is_muted = true
  WHERE room_id = p_room_id AND left_at IS NULL;
  UPDATE public.rooms
  SET is_closed = true, closed_at = now(), closed_by = auth.uid(),
      closed_reason = 'owner_closed'
  WHERE id = p_room_id;
END;
$$;


ALTER FUNCTION "public"."owner_close_room_with_pin"("p_room_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_get_audit_log"("p_game_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller   uuid := auth.uid();
  v_is_owner boolean;
  v_rows     jsonb;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  select jsonb_agg(to_jsonb(l.*) order by l.created_at desc)
  into v_rows
  from (
    select * from owner_game_control_audit_logs
    where (p_game_type is null or game_type = p_game_type)
    order by created_at desc
    limit p_limit
  ) l;

  return coalesce(v_rows, '[]'::jsonb);
end;
$$;


