CREATE OR REPLACE FUNCTION "public"."owner_set_game_config"("p_game_key" "text", "p_is_enabled" boolean DEFAULT NULL::boolean, "p_test_mode" boolean DEFAULT NULL::boolean, "p_risk_mode" "text" DEFAULT NULL::"text", "p_event_mode" boolean DEFAULT NULL::boolean, "p_event_multiplier_boost" numeric DEFAULT NULL::numeric, "p_max_bet" integer DEFAULT NULL::integer, "p_max_payout" integer DEFAULT NULL::integer, "p_daily_payout_cap" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller   uuid := auth.uid();
  v_is_owner boolean;
  v_old      jsonb;
  v_new      jsonb;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  if p_game_key not in ('hungry_cat', 'crash_rocket', 'gold_ladder', 'spin_wheel') then
    raise exception 'invalid_game_key';
  end if;

  -- Snapshot old values
  select to_jsonb(gs.*) into v_old from game_settings gs where gs.game_key = p_game_key;

  -- Insert row if it does not exist yet
  insert into game_settings (game_key) values (p_game_key) on conflict do nothing;

  update game_settings
  set
    is_enabled            = coalesce(p_is_enabled,            is_enabled),
    test_mode             = coalesce(p_test_mode,             test_mode),
    risk_mode             = coalesce(p_risk_mode,             risk_mode),
    event_mode            = coalesce(p_event_mode,            event_mode),
    event_multiplier_boost = coalesce(p_event_multiplier_boost, event_multiplier_boost),
    max_bet               = coalesce(p_max_bet,               max_bet),
    max_payout            = coalesce(p_max_payout,            max_payout),
    daily_payout_cap      = coalesce(p_daily_payout_cap,      daily_payout_cap),
    updated_at            = now()
  where game_key = p_game_key;

  select to_jsonb(gs.*) into v_new from game_settings gs where gs.game_key = p_game_key;

  insert into owner_game_control_audit_logs
    (owner_user_id, action, game_type, old_value, new_value)
  values
    (v_caller, 'update_game_config', p_game_key, v_old, v_new);
end;
$$;


ALTER FUNCTION "public"."owner_set_game_config"("p_game_key" "text", "p_is_enabled" boolean, "p_test_mode" boolean, "p_risk_mode" "text", "p_event_mode" boolean, "p_event_multiplier_boost" numeric, "p_max_bet" integer, "p_max_payout" integer, "p_daily_payout_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_set_hungry_cat_forced_result"("p_outcome_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller    uuid := auth.uid();
  v_is_owner  boolean;
  v_test_mode boolean;
  v_open_bets int;
  v_food      record;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  -- Must be in test mode
  select test_mode into v_test_mode
  from game_settings where game_key = 'hungry_cat';

  if not coalesce(v_test_mode, false) then
    raise exception 'not_in_test_mode'
      using hint = 'Enable test mode before forcing a result';
  end if;

  -- Block if active bets exist
  select count(*) into v_open_bets
  from hungry_cat_bets b
  join hungry_cat_rounds r on r.id = b.round_id
  where r.status in ('betting', 'locked') and b.status = 'pending';

  if v_open_bets > 0 then
    raise exception 'open_bets_exist'
      using hint = 'Cannot force result while bets are open';
  end if;

  -- Validate food exists and is active
  select * into v_food
  from hungry_cat_config
  where food_id = p_outcome_key and is_active = true;

  if v_food is null then
    raise exception 'food_not_found'
      using hint = 'Food ID not found or inactive: ' || p_outcome_key;
  end if;

  -- Store forced result with 30-minute expiry
  update game_settings
  set
    forced_next_result            = p_outcome_key,
    forced_next_result_expires_at = now() + interval '30 minutes',
    forced_next_result_by         = v_caller,
    updated_at                    = now()
  where game_key = 'hungry_cat';

  insert into owner_game_control_audit_logs
    (owner_user_id, action, game_type, old_value, new_value)
  values
    (v_caller, 'set_hungry_cat_forced_result', 'hungry_cat',
     null,
     jsonb_build_object('outcome_key', p_outcome_key, 'food_name', v_food.name,
                        'multiplier', v_food.multiplier,
                        'expires_at', now() + interval '30 minutes'));

  return jsonb_build_object(
    'ok', true,
    'food_id', v_food.food_id,
    'food_name', v_food.name,
    'icon', v_food.icon,
    'multiplier', v_food.multiplier,
    'expires_at', now() + interval '30 minutes'
  );
end;
$$;


ALTER FUNCTION "public"."owner_set_hungry_cat_forced_result"("p_outcome_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_set_rocket_crash_forced_multiplier"("p_multiplier" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller   uuid := auth.uid();
  v_is_owner boolean;
  v_test_mode boolean;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  select test_mode into v_test_mode
  from game_settings where game_key = 'crash_rocket';

  if not coalesce(v_test_mode, false) then
    raise exception 'not_in_test_mode'
      using hint = 'Enable test mode before forcing a crash multiplier';
  end if;

  if p_multiplier < 1.01 or p_multiplier > 1000 then
    raise exception 'invalid_multiplier'
      using hint = 'Multiplier must be between 1.01 and 1000';
  end if;

  -- Ensure row exists
  insert into game_settings (game_key) values ('crash_rocket') on conflict do nothing;

  update game_settings
  set
    forced_crash_multiplier            = p_multiplier,
    forced_crash_multiplier_expires_at = now() + interval '30 minutes',
    forced_crash_multiplier_by         = v_caller,
    updated_at                         = now()
  where game_key = 'crash_rocket';

  insert into owner_game_control_audit_logs
    (owner_user_id, action, game_type, old_value, new_value)
  values
    (v_caller, 'set_crash_forced_multiplier', 'crash_rocket',
     null,
     jsonb_build_object('multiplier', p_multiplier,
                        'expires_at', now() + interval '30 minutes'));

  return jsonb_build_object(
    'ok', true,
    'multiplier', p_multiplier,
    'expires_at', now() + interval '30 minutes'
  );
end;
$$;


ALTER FUNCTION "public"."owner_set_rocket_crash_forced_multiplier"("p_multiplier" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_update_hungry_cat_food_odds"("p_food_id" "text", "p_weight" numeric DEFAULT NULL::numeric, "p_is_active" boolean DEFAULT NULL::boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller   uuid := auth.uid();
  v_is_owner boolean;
  v_old      jsonb;
  v_new      jsonb;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  select to_jsonb(hc.*) into v_old
  from hungry_cat_config hc where hc.food_id = p_food_id;

  if v_old is null then
    raise exception 'food_not_found' using hint = p_food_id;
  end if;

  if p_weight is not null and (p_weight < 0.1 or p_weight > 1000) then
    raise exception 'invalid_weight' using hint = 'Weight must be 0.1–1000';
  end if;

  update hungry_cat_config
  set
    weight    = coalesce(p_weight,    weight),
    is_active = coalesce(p_is_active, is_active),
    updated_at = now()
  where food_id = p_food_id;

  select to_jsonb(hc.*) into v_new
  from hungry_cat_config hc where hc.food_id = p_food_id;

  insert into owner_game_control_audit_logs
    (owner_user_id, action, game_type, old_value, new_value)
  values
    (v_caller, 'update_hungry_cat_food_odds', 'hungry_cat', v_old, v_new);
end;
$$;


ALTER FUNCTION "public"."owner_update_hungry_cat_food_odds"("p_food_id" "text", "p_weight" numeric, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_void_hungry_cat_round"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller     uuid := auth.uid();
  v_is_owner   boolean;
  v_round      record;
  v_refunded   int := 0;
  v_total_refund bigint := 0;
  v_bet        record;
begin
  select exists (
    select 1 from owner_control_users
    where user_id = v_caller and enabled = true
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'not_owner' using hint = 'Owner access required';
  end if;

  select * into v_round from hungry_cat_rounds
  where id = p_round_id for update;

  if v_round is null then
    raise exception 'round_not_found';
  end if;

  if v_round.status = 'voided' then
    raise exception 'already_voided';
  end if;

  -- Refund each pending bet
  for v_bet in
    select * from hungry_cat_bets
    where round_id = p_round_id and status = 'pending'
    for update
  loop
    update hungry_cat_bets
    set status = 'refunded'
    where id = v_bet.id;

    -- Restore wallet
    update wallets
    set coins = coins + v_bet.bet_amount
    where user_id = v_bet.user_id;

    insert into wallet_transactions
      (user_id, type, coins_delta, description)
    values
      (v_bet.user_id, 'hungry_cat_refund', v_bet.bet_amount,
       'Round voided by owner — refund');

    v_refunded   := v_refunded + 1;
    v_total_refund := v_total_refund + v_bet.bet_amount;
  end loop;

  update hungry_cat_rounds
  set status = 'voided', completed_at = now()
  where id = p_round_id;

  insert into owner_game_control_audit_logs
    (owner_user_id, action, game_type, old_value, new_value)
  values
    (v_caller, 'void_hungry_cat_round', 'hungry_cat',
     jsonb_build_object('round_id', p_round_id, 'status', v_round.status),
     jsonb_build_object('refunded_bets', v_refunded, 'total_refund', v_total_refund));

  return jsonb_build_object(
    'ok', true,
    'refunded_bets', v_refunded,
    'total_refund', v_total_refund
  );
end;
$$;


ALTER FUNCTION "public"."owner_void_hungry_cat_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_crash_rocket_bet"("p_room_id" "uuid", "p_bet_slot" integer, "p_amount" integer, "p_auto_cashout_multiplier" numeric, "p_client_bet_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_round public.crash_rocket_rounds;
  v_bet public.crash_rocket_bets;
  v_balance integer;
begin
  perform public._crash_rocket_assert_room_access(p_room_id);
  if p_bet_slot not in (1,2) then raise exception 'invalid_bet_slot'; end if;
  if p_amount not between 100 and 1000000 then raise exception 'invalid_bet_amount'; end if;
  if p_auto_cashout_multiplier is not null and
     p_auto_cashout_multiplier not between 1.01 and 1000 then
    raise exception 'invalid_auto_cashout';
  end if;
  if length(trim(coalesce(p_client_bet_id,''))) not between 8 and 100 then
    raise exception 'invalid_client_bet_id';
  end if;

  select * into v_bet from public.crash_rocket_bets
  where user_id=v_uid and client_bet_id=p_client_bet_id;
  if v_bet.id is not null then
    select coins_balance into v_balance from public.wallets where user_id=v_uid;
    return jsonb_build_object('bet',to_jsonb(v_bet),
      'wallet_balance',coalesce(v_balance,0),'idempotent',true);
  end if;

  perform public.advance_crash_rocket_round(p_room_id);
  select * into v_round from public.crash_rocket_rounds
  where room_id is not distinct from p_room_id
  order by round_number desc limit 1 for update;
  if v_round.status <> 'betting_open' or clock_timestamp() >= v_round.betting_closes_at then
    raise exception 'betting_closed';
  end if;

  insert into public.wallets(user_id) values(v_uid) on conflict(user_id) do nothing;
  select coins_balance into v_balance from public.wallets
  where user_id=v_uid for update;
  if v_balance < p_amount then raise exception 'insufficient_balance'; end if;
  update public.wallets set coins_balance=coins_balance-p_amount,updated_at=now()
  where user_id=v_uid returning coins_balance into v_balance;

  insert into public.crash_rocket_bets(
    round_id,user_id,bet_slot,amount,auto_cashout_multiplier,client_bet_id
  ) values (
    v_round.id,v_uid,p_bet_slot,p_amount,p_auto_cashout_multiplier,
    trim(p_client_bet_id)
  ) returning * into v_bet;
  insert into public.wallet_transactions(
    user_id,type,direction,coins_delta,diamonds_delta,
    balance_coins_after,note,metadata
  ) values (
    v_uid,'crash_rocket_bet','debit',-p_amount,0,v_balance,
    'Srood Rocket bet',jsonb_build_object(
      'round_id',v_round.id,'bet_id',v_bet.id,'bet_slot',p_bet_slot
    )
  );
  insert into public.crash_rocket_round_events(round_id,event_type,payload)
  values (v_round.id,'bet_placed',jsonb_build_object(
    'bet_id',v_bet.id,'user_id',v_uid,'bet_slot',p_bet_slot,
    'amount',p_amount,'display_name',coalesce(
      (select nullif(trim(p.display_name),'') from public.profiles p where p.id=v_uid),
      'Srood Player'
    ),'avatar_url',(select p.avatar_url from public.profiles p where p.id=v_uid)
  ));
  return jsonb_build_object('bet',to_jsonb(v_bet),
    'wallet_balance',v_balance,'idempotent',false);
exception when unique_violation then
  select * into v_bet from public.crash_rocket_bets
  where user_id=v_uid and client_bet_id=p_client_bet_id;
  if v_bet.id is null then raise; end if;
  select coins_balance into v_balance from public.wallets where user_id=v_uid;
  return jsonb_build_object('bet',to_jsonb(v_bet),
    'wallet_balance',coalesce(v_balance,0),'idempotent',true);
end;
$$;


ALTER FUNCTION "public"."place_crash_rocket_bet"("p_room_id" "uuid", "p_bet_slot" integer, "p_amount" integer, "p_auto_cashout_multiplier" numeric, "p_client_bet_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_hungry_cat_bet"("p_round_id" "uuid", "p_food_id" "text", "p_amount" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_round      public.hungry_cat_rounds;
  v_food       public.hungry_cat_config;
  v_new_balance integer;
  v_bet_id     uuid := gen_random_uuid();
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;
  if p_amount <= 0 then raise exception 'invalid_bet_amount'; end if;

  -- Validate round
  select * into v_round
  from public.hungry_cat_rounds
  where id = p_round_id and user_id = v_user_id
  for update;

  if not found then raise exception 'round_not_found'; end if;
  if v_round.status != 'betting' then raise exception 'betting_closed'; end if;
  if now() > v_round.betting_ends_at then raise exception 'betting_closed'; end if;

  -- Validate food exists
  select * into v_food
  from public.hungry_cat_config
  where food_id = p_food_id and is_active = true;

  if not found then raise exception 'invalid_food'; end if;

  -- Deduct bet from wallet
  update public.wallets
  set    coins_balance        = coins_balance - p_amount,
         lifetime_coins_spent = lifetime_coins_spent + p_amount,
         updated_at           = now()
  where  user_id = v_user_id
  and    coins_balance >= p_amount
  returning coins_balance into v_new_balance;

  if not found then raise exception 'insufficient_coins'; end if;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'hungry_cat_bet', 'debit', -p_amount, 0,
     'Hungry Cat bet on ' || v_food.name,
     jsonb_build_object('round_id', p_round_id, 'food_id', p_food_id, 'bet_id', v_bet_id));

  insert into public.hungry_cat_bets
    (id, round_id, user_id, food_id, food_name, food_icon, multiplier_at_bet, bet_amount, status)
  values
    (v_bet_id, p_round_id, v_user_id,
     p_food_id, v_food.name, v_food.icon, v_food.multiplier, p_amount, 'pending');

  return jsonb_build_object(
    'bet_id',      v_bet_id,
    'food_id',     p_food_id,
    'amount',      p_amount,
    'new_balance', v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."place_hungry_cat_bet"("p_round_id" "uuid", "p_food_id" "text", "p_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_hungry_cat_global_bet"("p_round_id" "uuid", "p_food_id" "text", "p_amount" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_round       public.hungry_cat_global_rounds;
  v_food        public.hungry_cat_config;
  v_wallet      public.wallets;
  v_bet_id      uuid;
  v_new_balance integer;
  c_min constant integer := 100;
  c_max constant integer := 100000;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  if not exists (
    select 1 from public.game_settings
    where game_key = 'hungry_cat' and is_enabled
  ) then
    raise exception 'game_disabled';
  end if;

  if p_amount is null or p_amount < c_min or p_amount > c_max then
    raise exception 'invalid_bet_amount';
  end if;

  select * into v_round
  from public.hungry_cat_global_rounds
  where id = p_round_id;

  if v_round.id is null then raise exception 'round_not_found'; end if;

  if v_round.status <> 'betting' or v_round.betting_ends_at <= now() then
    raise exception 'betting_closed';
  end if;

  select * into v_food
  from public.hungry_cat_config
  where food_id = p_food_id and is_active;

  if v_food.id is null then raise exception 'invalid_food'; end if;

  select * into v_wallet
  from public.wallets
  where user_id = v_user_id
  for update;

  if v_wallet is null or v_wallet.coins_balance < p_amount then
    raise exception 'insufficient_coins';
  end if;

  update public.wallets
  set coins_balance        = coins_balance - p_amount,
      lifetime_coins_spent = lifetime_coins_spent + p_amount,
      updated_at           = now()
  where user_id = v_user_id
  returning coins_balance into v_new_balance;

  insert into public.hungry_cat_global_bets
    (round_id, user_id, food_id, food_name, food_icon, multiplier_at_bet, bet_amount, status)
  values
    (p_round_id, v_user_id, p_food_id,
     v_food.name, v_food.icon, v_food.multiplier, p_amount, 'pending')
  returning id into v_bet_id;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'hungry_cat_bet', 'debit', -p_amount, 0,
     'Hungry Cat bet on ' || v_food.name,
     jsonb_build_object('bet_id', v_bet_id, 'round_id', p_round_id, 'food_id', p_food_id));

  return json_build_object(
    'bet_id',      v_bet_id,
    'new_balance', v_new_balance
  );
end;
$$;


