CREATE OR REPLACE FUNCTION "public"."purchase_avatar_frame"("p_frame_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_frame public.avatar_frames;
  v_wallet public.user_wallets;
  v_before bigint;
  v_owned_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_frame from public.avatar_frames where id = p_frame_id and is_active limit 1;
  if not found then
    raise exception 'avatar_frame_not_found';
  end if;

  if coalesce(v_frame.required_vip_level, 0) > coalesce((select vip_level from public.profiles where id = v_user_id), 0) then
    raise exception 'vip_level_required';
  end if;

  perform public.ensure_user_wallet(v_user_id);
  select * into v_wallet from public.user_wallets where user_id = v_user_id for update;

  if v_wallet.coin_balance < coalesce(v_frame.price_coins, 0) then
    raise exception 'insufficient_coins';
  end if;

  v_before := v_wallet.coin_balance;

  update public.user_wallets
  set coin_balance = coin_balance - coalesce(v_frame.price_coins, 0),
      total_spent_coins = total_spent_coins + coalesce(v_frame.price_coins, 0),
      updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  insert into public.user_avatar_frames (user_id, frame_id, frame_key, source)
  values (v_user_id, v_frame.id, v_frame.frame_key, 'purchase')
  on conflict (user_id, frame_id) do update
    set purchased_at = public.user_avatar_frames.purchased_at
  returning id into v_owned_id;

  insert into public.coin_transactions (
    user_id, transaction_type, amount, balance_before, balance_after,
    source_type, source_id, description, created_by
  )
  values (
    v_user_id, 'frame_purchase', -coalesce(v_frame.price_coins, 0), v_before, v_wallet.coin_balance,
    'avatar_frames', v_frame.id, 'Avatar frame purchase: ' || v_frame.name, v_user_id
  );

  return v_owned_id;
end;
$$;


ALTER FUNCTION "public"."purchase_avatar_frame"("p_frame_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_store_item"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid:=auth.uid(); v_item store_items%rowtype;
  v_wallet wallets%rowtype; v_bp_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_item from store_items where id=p_item_id and is_active=true;
  if not found then raise exception 'item_not_found'; end if;
  if exists(select 1 from backpack_items where user_id=v_uid and item_id=p_item_id) then
    raise exception 'item_already_owned';
  end if;
  select * into v_wallet from wallets where user_id=v_uid for update;
  if not found then raise exception 'wallet_not_found'; end if;
  if v_item.price_coins>0 then
    if v_wallet.coins_balance<v_item.price_coins then raise exception 'insufficient_coins'; end if;
    update wallets set coins_balance=coins_balance-v_item.price_coins,
      lifetime_coins_spent=lifetime_coins_spent+v_item.price_coins,updated_at=now()
    where user_id=v_uid;
    insert into wallet_transactions(user_id,type,direction,coins_delta,note)
    values(v_uid,'system','debit',-v_item.price_coins,'Store purchase: '||v_item.name);
  elsif v_item.price_diamonds>0 then
    if v_wallet.diamonds_balance<v_item.price_diamonds then raise exception 'insufficient_diamonds'; end if;
    update wallets set diamonds_balance=diamonds_balance-v_item.price_diamonds,updated_at=now()
    where user_id=v_uid;
    insert into wallet_transactions(user_id,type,direction,diamonds_delta,note)
    values(v_uid,'system','debit',-v_item.price_diamonds,'Store purchase (diamonds): '||v_item.name);
  end if;
  insert into backpack_items(user_id,item_id,item_type,metadata)
  values(v_uid,p_item_id,v_item.item_type,v_item.metadata) returning id into v_bp_id;
  return jsonb_build_object('backpack_item_id',v_bp_id,'item_type',v_item.item_type,'item_name',v_item.name);
end;$$;


ALTER FUNCTION "public"."purchase_store_item"("p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_vip_plan"("p_vip_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_plan public.vip_plans;
  v_wallet public.user_wallets;
  v_before bigint;
  v_subscription_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_plan from public.vip_plans where id = p_vip_plan_id and is_active limit 1;
  if not found then
    raise exception 'vip_plan_not_found';
  end if;

  perform public.ensure_user_wallet(v_user_id);
  select * into v_wallet from public.user_wallets where user_id = v_user_id for update;

  if v_wallet.coin_balance < v_plan.price_coins then
    raise exception 'insufficient_coins';
  end if;

  v_before := v_wallet.coin_balance;

  update public.user_wallets
  set coin_balance = coin_balance - v_plan.price_coins,
      total_spent_coins = total_spent_coins + v_plan.price_coins,
      updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  update public.profiles
  set vip_level = greatest(coalesce(vip_level, 0), v_plan.level),
      vip_started_at = now(),
      vip_expires_at = now() + make_interval(days => v_plan.duration_days),
      vip_title = v_plan.name
  where id = v_user_id;

  insert into public.user_vip_subscriptions (user_id, vip_plan_id, ends_at)
  values (v_user_id, v_plan.id, now() + make_interval(days => v_plan.duration_days))
  returning id into v_subscription_id;

  insert into public.coin_transactions (
    user_id, transaction_type, amount, balance_before, balance_after,
    source_type, source_id, description, created_by
  )
  values (
    v_user_id, 'vip_purchase', -v_plan.price_coins, v_before, v_wallet.coin_balance,
    'vip_plans', v_plan.id, 'VIP purchase: ' || v_plan.name, v_user_id
  );

  return v_subscription_id;
end;
$$;


ALTER FUNCTION "public"."purchase_vip_plan"("p_vip_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_team_pk_gift_support"("p_room_id" "uuid", "p_sender_user_id" "uuid", "p_receiver_user_id" "uuid", "p_gift_transaction_id" "uuid", "p_gift_code" "text", "p_coins_value" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session_id  uuid;
  v_team        text;
  v_pk_points   bigint;
begin
  -- Fast no-op if no active (non-expired) PK in this room.
  select id into v_session_id
  from public.room_team_pk_sessions
  where room_id = p_room_id
    and status  = 'active'
    and ends_at > now()
  limit 1;

  if v_session_id is null then
    return jsonb_build_object('scored', false, 'reason', 'no_active_pk');
  end if;

  -- Check if receiver is assigned to a team in this session.
  select team into v_team
  from public.room_team_pk_members
  where pk_session_id = v_session_id
    and user_id       = p_receiver_user_id;

  if v_team is null then
    return jsonb_build_object('scored', false, 'reason', 'receiver_not_assigned');
  end if;

  -- 1 gift coin = 1 PK point (configurable later via admin multiplier).
  v_pk_points := p_coins_value;

  -- Insert support log. ON CONFLICT on gift_transaction_id prevents double-scoring.
  begin
    insert into public.room_team_pk_support_logs (
      pk_session_id,
      room_id,
      sender_user_id,
      receiver_user_id,
      receiver_team,
      gift_transaction_id,
      gift_code,
      coins_value,
      pk_points
    ) values (
      v_session_id,
      p_room_id,
      p_sender_user_id,
      p_receiver_user_id,
      v_team,
      p_gift_transaction_id,
      p_gift_code,
      p_coins_value,
      v_pk_points
    );
  exception when unique_violation then
    -- This gift was already scored (duplicate call guard).
    return jsonb_build_object('scored', false, 'reason', 'already_scored');
  end;

  -- Atomically increment team score + gift count on the session row.
  if v_team = 'a' then
    update public.room_team_pk_sessions
    set team_a_score      = team_a_score + v_pk_points,
        team_a_gift_count = team_a_gift_count + 1,
        updated_at        = now()
    where id = v_session_id;
  else
    update public.room_team_pk_sessions
    set team_b_score      = team_b_score + v_pk_points,
        team_b_gift_count = team_b_gift_count + 1,
        updated_at        = now()
    where id = v_session_id;
  end if;

  return jsonb_build_object(
    'scored',      true,
    'team',        v_team,
    'pk_points',   v_pk_points,
    'session_id',  v_session_id
  );

exception when others then
  -- PK scoring must never corrupt the wallet/gift flow.
  -- Silently absorb unexpected errors and return failure flag.
  return jsonb_build_object(
    'scored', false,
    'reason', 'internal_error',
    'detail', sqlerrm
  );
end;
$$;


ALTER FUNCTION "public"."record_team_pk_gift_support"("p_room_id" "uuid", "p_sender_user_id" "uuid", "p_receiver_user_id" "uuid", "p_gift_transaction_id" "uuid", "p_gift_code" "text", "p_coins_value" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_crash_bet"("p_bet_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_bet         crash_bets;
  v_new_balance integer;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  select * into v_bet
  from public.crash_bets
  where id = p_bet_id
    and user_id = v_uid
  for update;

  if not found then
    raise exception 'bet_not_found';
  end if;

  -- Refund is only allowed before flight starts.
  -- The previous version allowed 'running', which could refund during flight.
  if v_bet.status <> 'pending' then
    raise exception 'not_refundable';
  end if;

  update public.wallets
  set coins_balance = coins_balance + v_bet.bet_amount
  where user_id = v_uid
  returning coins_balance into v_new_balance;

  update public.crash_bets
  set status = 'refunded'
  where id = p_bet_id;

  return json_build_object(
    'refunded_amount', v_bet.bet_amount,
    'new_balance', v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."refund_crash_bet"("p_bet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_hungry_cat_round_bets"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id       uuid := auth.uid();
  v_round         public.hungry_cat_rounds;
  v_refund_total  integer := 0;
  v_new_balance   integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  select * into v_round
  from public.hungry_cat_rounds
  where id = p_round_id and user_id = v_user_id
  for update;

  if not found then raise exception 'round_not_found'; end if;
  if v_round.status != 'betting' then raise exception 'betting_closed'; end if;

  select coalesce(sum(bet_amount), 0) into v_refund_total
  from public.hungry_cat_bets
  where round_id = p_round_id and user_id = v_user_id and status = 'pending';

  if v_refund_total > 0 then
    update public.wallets
    set coins_balance = coins_balance + v_refund_total, updated_at = now()
    where user_id = v_user_id
    returning coins_balance into v_new_balance;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_user_id, 'hungry_cat_refund', 'credit', v_refund_total, 0,
       'Hungry Cat bets cleared',
       jsonb_build_object('round_id', p_round_id));

    update public.hungry_cat_bets
    set status = 'refunded'
    where round_id = p_round_id and user_id = v_user_id and status = 'pending';
  else
    select coins_balance into v_new_balance
    from public.wallets where user_id = v_user_id;
  end if;

  return jsonb_build_object(
    'refunded_amount', v_refund_total,
    'new_balance',     v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."refund_hungry_cat_round_bets"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_payout_request"("p_request_id" "uuid", "p_admin_reply" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request public.payout_requests;
begin
  if v_admin_id is null then
    raise exception 'not_authenticated';
  end if;
  if not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select * into v_request from public.payout_requests where id = p_request_id for update;
  if not found then
    raise exception 'payout_request_not_found';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'payout_request_not_pending';
  end if;

  insert into public.income_accounts (user_id)
  values (v_request.user_id)
  on conflict (user_id) do nothing;

  update public.income_accounts
  set pending_balance_usd = greatest(coalesce(pending_balance_usd, 0) - v_request.amount_usd, 0),
      available_balance_usd = coalesce(available_balance_usd, 0) + v_request.amount_usd,
      updated_at = now()
  where user_id = v_request.user_id;

  update public.payout_requests
  set status = 'rejected',
      admin_reply = nullif(trim(coalesce(p_admin_reply, '')), ''),
      updated_at = now()
  where id = v_request.id;

  perform public.admin_record_audit(
    'reject_payout', 'payout_requests', v_request.id::text, v_request.user_id,
    jsonb_build_object('amount_usd', v_request.amount_usd, 'reason', p_admin_reply)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."reject_payout_request"("p_request_id" "uuid", "p_admin_reply" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_recharge_request"("p_request_id" "uuid", "p_reject_reason" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_request public.recharge_requests;
begin
  if v_admin_id is null then
    raise exception 'not_authenticated';
  end if;

  if not public.has_finance_access() then
    raise exception 'not_authorized';
  end if;

  select *
  into v_request
  from public.recharge_requests rr
  where rr.id = p_request_id
  for update;

  if not found then
    raise exception 'recharge_request_not_found';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'recharge_request_not_pending';
  end if;

  update public.recharge_requests
  set status = 'rejected',
      admin_user_id = v_admin_id,
      reject_reason = nullif(trim(coalesce(p_reject_reason, '')), ''),
      rejected_at = now(),
      updated_at = now()
  where id = v_request.id;

  return true;
end;
$$;


ALTER FUNCTION "public"."reject_recharge_request"("p_request_id" "uuid", "p_reject_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_room_member"("p_room_id" "uuid", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_room record;
  v_now timestamptz := now();
begin
  if v_caller_id is null then
    raise exception 'not_authenticated';
  end if;

  -- Verify room exists and caller is the owner
  select id, owner_id into v_room
  from public.rooms
  where id = p_room_id;

  if v_room is null then
    raise exception 'room_not_found';
  end if;

  if v_room.owner_id != v_caller_id then
    raise exception 'not_room_owner';
  end if;

  -- Verify target member exists in room
  if not exists (
    select 1 from public.room_members
    where room_id = p_room_id
      and user_id = p_user_id
      and left_at is null
  ) then
    raise exception 'member_not_in_room';
  end if;

  -- Mark member as left
  update public.room_members
  set is_muted = true,
      seat_number = null,
      left_at = v_now,
      last_seen_at = v_now,
      updated_at = v_now
  where room_id = p_room_id
    and user_id = p_user_id
    and left_at is null;
end;
$$;


ALTER FUNCTION "public"."remove_room_member"("p_room_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_room_member"("p_room_id" "uuid", "p_user_id" "uuid") IS 'Safe RPC function for room owners to remove members from rooms. Verifies room ownership before proceeding. Always use this instead of direct UPDATE.';



CREATE OR REPLACE FUNCTION "public"."remove_room_message"("p_message_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id  UUID := auth.uid();
  v_room_id    UUID;
  v_is_owner   BOOLEAN := false;
  v_is_mod     BOOLEAN := false;
  v_is_admin   BOOLEAN := false;
BEGIN
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Look up the message to get its room_id
  SELECT room_id INTO v_room_id
  FROM public.room_messages
  WHERE id = p_message_id;

  IF v_room_id IS NULL THEN
    RAISE EXCEPTION 'message_not_found';
  END IF;

  -- Admin check
  SELECT public.has_admin_access() INTO v_is_admin;

  IF NOT v_is_admin THEN
    -- Room owner check
    SELECT EXISTS (
      SELECT 1 FROM public.rooms
      WHERE id = v_room_id AND owner_id = v_caller_id
    ) INTO v_is_owner;

    IF NOT v_is_owner THEN
      -- Room moderator check
      SELECT EXISTS (
        SELECT 1 FROM public.room_moderators
        WHERE room_id = v_room_id AND user_id = v_caller_id
      ) INTO v_is_mod;
    END IF;
  END IF;

  IF NOT (v_is_admin OR v_is_owner OR v_is_mod) THEN
    RAISE EXCEPTION 'insufficient_permissions';
  END IF;

  -- Mark as removed
  UPDATE public.room_messages
  SET is_removed    = true,
      removed_by    = v_caller_id,
      removed_at    = now(),
      remove_reason = p_reason
  WHERE id = p_message_id
    AND is_removed = false;  -- idempotent

  -- Log moderation event
  PERFORM public.log_moderation_event(
    p_room_id        := v_room_id,
    p_source         := 'admin',
    p_violation_type := 'message_removed',
    p_severity       := 2,
    p_original_text  := p_reason,
    p_normalized_text:= NULL,
    p_matched_rule   := NULL,
    p_action_taken   := 'message_removed'
  );
END;
$$;


ALTER FUNCTION "public"."remove_room_message"("p_message_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_my_room"() RETURNS "public"."rooms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_room public.rooms;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Close any other active non-personal rooms owned by this user so the
  -- uniq_one_active_room_per_owner index doesn't conflict on the reopen.
  UPDATE public.rooms
  SET
    is_closed     = true,
    closed_at     = now(),
    closed_by     = v_uid,
    closed_reason = 'replaced_by_personal_room'
  WHERE owner_id = v_uid
    AND is_closed = false
    AND is_personal_room = false;

  UPDATE public.rooms
  SET
    is_closed     = false,
    closed_at     = NULL,
    closed_by     = NULL,
    closed_reason = NULL,
    updated_at    = now()
  WHERE owner_id = v_uid AND is_personal_room = true
  RETURNING * INTO v_room;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_personal_room';
  END IF;

  RETURN v_room;
END;
$$;


ALTER FUNCTION "public"."reopen_my_room"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_user"("p_reported_user_id" "uuid", "p_reason" "text", "p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;
  if p_reported_user_id is null or p_reported_user_id = v_user_id then
    raise exception 'invalid_target';
  end if;
  if v_reason is null then
    raise exception 'missing_reason';
  end if;

  insert into public.user_reports (reporter_id, reported_user_id, room_id, reason)
  values (v_user_id, p_reported_user_id, p_room_id, v_reason)
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."report_user"("p_reported_user_id" "uuid", "p_reason" "text", "p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_account_deletion"("p_reason" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_uid       uuid := auth.uid();
  v_request   uuid;
  v_col       text;
  v_pii_cols  text[] := array[
    'avatar_url', 'bio', 'phone', 'email', 'username',
    'country', 'gender', 'birthdate'
  ];
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select id into v_request
  from public.account_deletion_requests
  where user_id = v_uid
  order by requested_at desc
  limit 1;
  if v_request is not null then
    return json_build_object('status', 'already_requested', 'request_id', v_request);
  end if;

  insert into public.account_deletion_requests (user_id, status, reason, anonymized_at)
  values (v_uid, 'anonymized', left(coalesce(p_reason, ''), 500), now())
  returning id into v_request;

  if exists (select 1 from information_schema.columns
             where table_schema='public' and table_name='profiles' and column_name='display_name') then
    execute 'update public.profiles set display_name = $1 where id = $2'
      using 'Deleted User', v_uid;
  end if;

  foreach v_col in array array['is_deleted', 'deleted_at', 'status', 'account_status'] loop
    if exists (select 1 from information_schema.columns
               where table_schema='public' and table_name='profiles' and column_name=v_col) then
      if v_col = 'is_deleted' then
        execute 'update public.profiles set is_deleted = true where id = $1' using v_uid;
      elsif v_col = 'deleted_at' then
        execute 'update public.profiles set deleted_at = now() where id = $1' using v_uid;
      else
        execute format('update public.profiles set %I = $1 where id = $2', v_col)
          using 'deleted', v_uid;
      end if;
    end if;
  end loop;

  foreach v_col in array v_pii_cols loop
    if exists (select 1 from information_schema.columns
               where table_schema='public' and table_name='profiles' and column_name=v_col) then
      execute format('update public.profiles set %I = null where id = $1', v_col) using v_uid;
    end if;
  end loop;

  delete from public.user_push_tokens where user_id = v_uid;

  return json_build_object('status', 'anonymized', 'request_id', v_request, 'server_now', now());
end;
$_$;


ALTER FUNCTION "public"."request_account_deletion"("p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."request_account_deletion"("p_reason" "text") IS 'Self-service account deletion: anonymizes PII on the caller''s profile, records an audit row, and removes push tokens. Financial ledger rows are intentionally preserved (now anonymized) for accounting/legal retention; hard auth.users deletion is left to privileged service_role tooling.';



CREATE OR REPLACE FUNCTION "public"."request_payout"("p_amount_usd" numeric, "p_method" "text", "p_account_details" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid        uuid    := auth.uid();
  v_available  numeric;
  v_request_id uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if p_amount_usd is null or p_amount_usd < 1.0 then
    raise exception 'amount_below_minimum';
  end if;

  if coalesce(trim(p_method), '') = '' then
    raise exception 'missing_method';
  end if;

  -- Re-read server-side balance with a row lock to prevent race conditions.
  select available_balance_usd
  into   v_available
  from   public.income_accounts
  where  user_id = v_uid
  for update;

  if not found then
    raise exception 'no_income_account';
  end if;

  if p_amount_usd > v_available then
    raise exception 'amount_exceeds_available_balance';
  end if;

  insert into public.payout_requests
    (user_id, amount_usd, method, account_details, status)
  values
    (v_uid, p_amount_usd, p_method, p_account_details, 'pending')
  returning id into v_request_id;

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."request_payout"("p_amount_usd" numeric, "p_method" "text", "p_account_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_recharge"("p_requested_coins" integer, "p_method" "text", "p_requested_amount_usd" numeric DEFAULT NULL::numeric, "p_reference_code" "text" DEFAULT NULL::"text", "p_agent_code" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_public_user_id text;
  v_agent public.recharge_agents;
  v_request_id uuid;
  v_method text := lower(trim(coalesce(p_method, '')));
  v_agent_code text := nullif(trim(coalesce(p_agent_code, '')), '');
  -- 2,500,000 coins = $100 base + 25% bonus headroom at 20,000 coins/USD
  c_max_coins constant integer := 2500000;
  -- 20,000 coins = 1 USD minimum
  c_min_coins constant integer := 20000;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_requested_coins is null or p_requested_coins <= 0 then
    raise exception 'invalid_requested_coins';
  end if;

  if p_requested_coins < c_min_coins then
    raise exception 'requested_coins_below_minimum';
  end if;

  if p_requested_coins > c_max_coins then
    raise exception 'requested_coins_exceeds_maximum';
  end if;

  if v_method not in ('omt', 'wish', 'usdt', 'agent', 'cash', 'admin_manual') then
    raise exception 'invalid_recharge_method';
  end if;

  select p.public_user_id
  into v_public_user_id
  from public.profiles p
  where p.id = v_user_id;

  if v_agent_code is not null then
    select *
    into v_agent
    from public.recharge_agents ra
    where lower(ra.code) = lower(v_agent_code)
      and ra.is_active
    limit 1;
  end if;

  insert into public.recharge_requests (
    user_id,
    public_user_id,
    requested_coins,
    requested_amount_usd,
    method,
    reference_code,
    agent_code,
    agent_id,
    agency_id
  )
  values (
    v_user_id,
    v_public_user_id,
    p_requested_coins,
    p_requested_amount_usd,
    v_method,
    nullif(trim(coalesce(p_reference_code, '')), ''),
    v_agent_code,
    v_agent.id,
    v_agent.agency_id
  )
  returning id into v_request_id;

  return v_request_id;
end;
$_$;


ALTER FUNCTION "public"."request_recharge"("p_requested_coins" integer, "p_method" "text", "p_requested_amount_usd" numeric, "p_reference_code" "text", "p_agent_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_withdrawal"("p_diamonds" integer, "p_method" "text", "p_account_details" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id       uuid := auth.uid();
  v_wallet        public.wallets;
  v_agency_id     uuid;
  v_agency_owner  uuid;
  v_rate          numeric;
  v_request_id    uuid;
  v_gross_usd     numeric(12,2);
  v_host_usd      numeric(12,2);
  v_agency_usd    numeric(12,2);
  v_platform_usd  numeric(12,2);
  v_agency_diamonds integer := 0;
  v_method        text := lower(trim(coalesce(p_method, '')));
  c_diamonds_per_usd constant integer := 20000;   -- 20,000 diamonds = 1 USD gross
  c_min_diamonds     constant integer := 100000;  -- min 100,000 diamonds = 5 USD
  c_platform_agency  constant numeric := 0.10;     -- platform share, agency host
  c_platform_solo    constant numeric := 0.12;     -- platform share, independent
  c_rate_cap         constant numeric := 0.80;     -- host always keeps >= 10%
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;
  if p_diamonds is null or p_diamonds < c_min_diamonds then
    raise exception 'diamonds_below_minimum';
  end if;
  if v_method not in ('bank', 'paypal', 'wise') then
    raise exception 'invalid_withdrawal_method';
  end if;
  if nullif(trim(coalesce(p_account_details, '')), '') is null then
    raise exception 'account_details_required';
  end if;

  -- Row-lock the wallet FIRST so concurrent requests for this user serialize
  -- here; the duplicate-pending check below is then race-free.
  select * into v_wallet
  from public.wallets
  where user_id = v_user_id
  for update;
  if v_wallet is null or v_wallet.diamonds_balance < p_diamonds then
    raise exception 'insufficient_diamonds';
  end if;

  -- Duplicate-withdrawal safety: at most one pending request at a time.
  if exists (
    select 1 from public.withdrawal_requests
    where user_id = v_user_id and status = 'pending'
  ) then
    raise exception 'withdrawal_already_pending';
  end if;

  -- Agency derived SERVER-SIDE from the authoritative active agency_hosts
  -- membership. Only a DIFFERENT-owner, ACTIVE agency counts; an inactive
  -- agency (or none) => the host is treated as independent.
  select ah.agency_id, a.owner_user_id, a.commission_rate
  into v_agency_id, v_agency_owner, v_rate
  from public.agency_hosts ah
  join public.agencies a on a.id = ah.agency_id
  where ah.host_user_id = v_user_id
    and ah.status = 'active'
    and a.status = 'active'
    and a.owner_user_id is not null
    and a.owner_user_id <> v_user_id
  order by ah.joined_at desc
  limit 1;

  v_gross_usd := round(p_diamonds::numeric / c_diamonds_per_usd, 2);

  if v_agency_id is not null then
    -- Agency host: agency = commission_rate × gross, platform = 10% × gross,
    -- host = remainder. commission_rate is clamped to [0, 0.80].
    v_rate := least(greatest(coalesce(v_rate, 0), 0), c_rate_cap);
    v_agency_usd   := round(v_gross_usd * v_rate, 2);
    v_platform_usd := round(v_gross_usd * c_platform_agency, 2);
    v_host_usd     := v_gross_usd - v_agency_usd - v_platform_usd;
    v_agency_diamonds := floor(p_diamonds::numeric * v_rate)::integer;
  else
    -- Independent host: 88% / 12% (preserved separately, unchanged).
    v_host_usd     := round(v_gross_usd * (1 - c_platform_solo), 2);
    v_agency_usd   := 0;
    v_platform_usd := v_gross_usd - v_host_usd;
    v_agency_id    := null;
    v_agency_owner := null;
    v_agency_diamonds := 0;
  end if;

  -- Hold the diamonds immediately.
  update public.wallets
  set diamonds_balance = diamonds_balance - p_diamonds, updated_at = now()
  where user_id = v_user_id;

  insert into public.wallet_transactions (
    user_id, type, direction, coins_delta, diamonds_delta, note, metadata
  )
  values (
    v_user_id, 'withdrawal', 'debit', 0, -p_diamonds, 'Withdrawal request hold',
    jsonb_build_object(
      'gross_usd', v_gross_usd, 'host_usd', v_host_usd,
      'agency_usd', v_agency_usd, 'platform_usd', v_platform_usd,
      'agency_id', v_agency_id,
      'commission_rate', case when v_agency_id is not null then v_rate else null end)
  );

  insert into public.withdrawal_requests (
    user_id, diamonds, method, account_details, notes,
    gross_usd, host_share_usd, agency_share_usd, platform_share_usd,
    agency_id, agency_owner_user_id, agency_share_diamonds, estimated_usd, status
  )
  values (
    v_user_id, p_diamonds, v_method,
    trim(p_account_details), nullif(trim(coalesce(p_notes, '')), ''),
    v_gross_usd, v_host_usd, v_agency_usd, v_platform_usd,
    v_agency_id, v_agency_owner, v_agency_diamonds, v_host_usd, 'pending'
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."request_withdrawal"("p_diamonds" integer, "p_method" "text", "p_account_details" "text", "p_notes" "text") OWNER TO "postgres";


