CREATE OR REPLACE FUNCTION "public"."roulette_place_bet"("p_round_id" "uuid", "p_bet_zone" "text", "p_bet_amount" bigint, "p_client_bet_id" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_existing    public.roulette_bets;
  v_round       public.roulette_rounds;
  v_multiplier  numeric;
  v_new_balance bigint;
  v_bet_id      uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_client_bet_id is null or length(trim(p_client_bet_id)) = 0 then
    raise exception 'invalid_client_bet_id';
  end if;

  select *
  into v_existing
  from public.roulette_bets
  where client_bet_id = p_client_bet_id;

  if found then
    return json_build_object(
      'bet_id', v_existing.id,
      'new_balance', (
        select coins_balance from public.wallets where user_id = v_user_id
      ),
      'bet_zone', v_existing.bet_zone,
      'bet_amount', v_existing.bet_amount,
      'round_id', v_existing.round_id
    );
  end if;

  if p_bet_zone is null or p_bet_zone not in (
    'straight_zero', 'low', 'mid', 'high', 'red', 'black', 'even', 'odd'
  ) then
    raise exception 'invalid_bet_zone';
  end if;

  if p_bet_amount is null
     or p_bet_amount not in (100, 1000, 5000, 10000, 20000, 100000) then
    raise exception 'invalid_bet_amount';
  end if;

  v_multiplier := case p_bet_zone
    when 'straight_zero' then 36
    when 'low' then 3
    when 'mid' then 3
    when 'high' then 3
    when 'red' then 2
    when 'black' then 2
    when 'even' then 2
    when 'odd' then 2
  end;

  select *
  into v_round
  from public.roulette_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'round_not_found';
  end if;

  if v_round.status <> 'betting_open' then
    raise exception 'betting_closed';
  end if;

  if v_round.betting_closes_at <= now() then
    raise exception 'betting_closed';
  end if;

  update public.wallets
  set coins_balance = coins_balance - p_bet_amount,
      lifetime_coins_spent = lifetime_coins_spent + p_bet_amount,
      updated_at = now()
  where user_id = v_user_id
    and coins_balance >= p_bet_amount
  returning coins_balance into v_new_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.roulette_bets (
    client_bet_id, round_id, user_id, bet_zone, bet_amount, payout_multiplier
  )
  values (
    p_client_bet_id, v_round.id, v_user_id, p_bet_zone, p_bet_amount, v_multiplier
  )
  returning id into v_bet_id;

  insert into public.wallet_transactions (
    user_id, type, direction, coins_delta, diamonds_delta,
    balance_coins_after, note, metadata
  )
  values (
    v_user_id, 'roulette_bet', 'debit', -p_bet_amount, 0,
    v_new_balance, 'Srood Roulette bet',
    jsonb_build_object('round_id', v_round.id, 'bet_zone', p_bet_zone, 'bet_id', v_bet_id)
  );

  return json_build_object(
    'bet_id', v_bet_id,
    'new_balance', v_new_balance,
    'bet_zone', p_bet_zone,
    'bet_amount', p_bet_amount,
    'round_id', v_round.id
  );
end;
$$;


ALTER FUNCTION "public"."roulette_place_bet"("p_round_id" "uuid", "p_bet_zone" "text", "p_bet_amount" bigint, "p_client_bet_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_host_availability"("p_schedule" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;
  if not exists (
    select 1 from public.approved_hosts
    where user_id = v_uid and status = 'active'
  ) then
    raise exception 'host_not_approved';
  end if;
  if p_schedule is null
     or jsonb_typeof(p_schedule) <> 'array'
     or jsonb_array_length(p_schedule) <> 7 then
    raise exception 'invalid_schedule';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_schedule) entry
    where jsonb_typeof(entry) <> 'object'
      or jsonb_typeof(entry -> 'enabled') <> 'boolean'
      or coalesce(entry ->> 'start', '') !~
        '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or coalesce(entry ->> 'end', '') !~
        '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  ) then
    raise exception 'invalid_schedule';
  end if;

  insert into public.host_availability (user_id, schedule, updated_at)
  values (v_uid, p_schedule, now())
  on conflict (user_id) do update
    set schedule = excluded.schedule,
        updated_at = now();

  return p_schedule;
end;
$_$;


ALTER FUNCTION "public"."save_my_host_availability"("p_schedule" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_my_host_availability"("p_schedule" "jsonb") IS 'Validates and saves a seven-day schedule for an approved host.';



CREATE OR REPLACE FUNCTION "public"."send_gift_with_wallet"("p_room_id" "uuid", "p_receiver_id" "uuid", "p_gift_id" "uuid", "p_quantity" integer DEFAULT 1) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sender_id           uuid    := auth.uid();
  v_quantity            integer := GREATEST(COALESCE(p_quantity, 1), 1);
  v_gift                record;
  v_total_cost          integer;
  v_diamonds_earned     integer;
  v_sender_wallet       public.wallets;
  v_receiver_wallet     public.wallets;
  v_gift_transaction_id uuid;
BEGIN
  -- ── Auth & validation ─────────────────────────────────────────────────────
  IF v_sender_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_receiver_id IS NULL OR p_receiver_id = v_sender_id THEN
    RAISE EXCEPTION 'invalid_receiver';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.room_members rm
    WHERE rm.room_id = p_room_id
      AND rm.user_id = v_sender_id
      AND rm.left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'sender_not_in_room';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.room_members rm
    WHERE rm.room_id = p_room_id
      AND rm.user_id = p_receiver_id
      AND rm.left_at IS NULL
  ) THEN
    RAISE EXCEPTION 'receiver_not_in_room';
  END IF;

  -- ── Gift lookup ───────────────────────────────────────────────────────────
  SELECT g.id, g.code, g.name, g.price_coins
  INTO   v_gift
  FROM   public.gifts g
  WHERE  g.id = p_gift_id
    AND  COALESCE(g.is_active, true)
  LIMIT  1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'gift_not_found';
  END IF;

  v_total_cost      := v_gift.price_coins::integer * v_quantity;
  v_diamonds_earned := v_total_cost;

  IF v_total_cost <= 0 THEN
    RAISE EXCEPTION 'invalid_gift_price';
  END IF;

  -- ── Ensure wallets exist ──────────────────────────────────────────────────
  INSERT INTO public.wallets (user_id) VALUES (v_sender_id)
    ON CONFLICT (user_id) DO NOTHING;
  INSERT INTO public.wallets (user_id) VALUES (p_receiver_id)
    ON CONFLICT (user_id) DO NOTHING;

  -- ── Lock sender wallet and check balance ──────────────────────────────────
  SELECT * INTO v_sender_wallet
  FROM   public.wallets
  WHERE  user_id = v_sender_id
  FOR UPDATE;

  IF v_sender_wallet.coins_balance < v_total_cost THEN
    RAISE EXCEPTION 'insufficient_coins';
  END IF;

  -- ── Debit sender / credit receiver ───────────────────────────────────────
  UPDATE public.wallets
  SET    coins_balance        = coins_balance        - v_total_cost,
         lifetime_coins_spent = lifetime_coins_spent + v_total_cost,
         updated_at           = now()
  WHERE  user_id = v_sender_id
  RETURNING * INTO v_sender_wallet;

  UPDATE public.wallets
  SET    diamonds_balance         = diamonds_balance         + v_diamonds_earned,
         lifetime_diamonds_earned = lifetime_diamonds_earned + v_diamonds_earned,
         updated_at               = now()
  WHERE  user_id = p_receiver_id
  RETURNING * INTO v_receiver_wallet;

  -- ── Record gift transaction ───────────────────────────────────────────────
  INSERT INTO public.gift_transactions (
    room_id, sender_id, receiver_id,
    gift_id, gift_code, gift_name, gift_price_coins
  ) VALUES (
    p_room_id, v_sender_id, p_receiver_id,
    v_gift.id, v_gift.code, v_gift.name, v_total_cost
  )
  RETURNING id INTO v_gift_transaction_id;

  -- ── Wallet transaction ledger — sender ────────────────────────────────────
  INSERT INTO public.wallet_transactions (
    user_id, type, direction, coins_delta,
    balance_coins_after, balance_diamonds_after,
    related_user_id, related_room_id, related_gift_id,
    related_gift_transaction_id, note, metadata
  ) VALUES (
    v_sender_id, 'gift_sent', 'debit', -v_total_cost,
    v_sender_wallet.coins_balance, v_sender_wallet.diamonds_balance,
    p_receiver_id, p_room_id, v_gift.id,
    v_gift_transaction_id, 'Gift sent',
    jsonb_build_object('quantity', v_quantity, 'gift_code', v_gift.code)
  );

  -- ── Wallet transaction ledger — receiver ──────────────────────────────────
  INSERT INTO public.wallet_transactions (
    user_id, type, direction, diamonds_delta,
    balance_coins_after, balance_diamonds_after,
    related_user_id, related_room_id, related_gift_id,
    related_gift_transaction_id, note, metadata
  ) VALUES (
    p_receiver_id, 'gift_received', 'credit', v_diamonds_earned,
    v_receiver_wallet.coins_balance, v_receiver_wallet.diamonds_balance,
    v_sender_id, p_room_id, v_gift.id,
    v_gift_transaction_id, 'Gift received',
    jsonb_build_object('quantity', v_quantity, 'gift_code', v_gift.code)
  );

  -- ── Team PK scoring side-effect ───────────────────────────────────────────
  BEGIN
    PERFORM public.record_team_pk_gift_support(
      p_room_id,
      v_sender_id,
      p_receiver_id,
      v_gift_transaction_id,
      v_gift.code,
      v_total_cost::bigint
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- ── User Level XP side-effect (Phase L3) ─────────────────────────────────
  BEGIN
    PERFORM public.add_user_xp(
      v_sender_id,
      v_total_cost::bigint,
      'gift_sent'
    );

    UPDATE public.user_levels
    SET    total_gifts_sent = total_gifts_sent + v_quantity,
           updated_at       = now()
    WHERE  user_id = v_sender_id;

    INSERT INTO public.user_levels (user_id, total_gifts_received)
    VALUES (p_receiver_id, v_quantity)
    ON CONFLICT (user_id) DO UPDATE
      SET total_gifts_received = public.user_levels.total_gifts_received + v_quantity,
          updated_at           = now();

  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- ── Wealth XP side-effect ─────────────────────────────────────────────────
  BEGIN
    PERFORM public.add_wealth_xp(
      v_sender_id,
      v_total_cost::bigint,
      'gift_sent'
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- ── Room XP side-effect ───────────────────────────────────────────────────
  BEGIN
    PERFORM public.grant_room_xp(
      p_room_id,
      (v_total_cost * (CASE
        WHEN v_total_cost > 2000 THEN 1.5
        WHEN v_total_cost > 500  THEN 1.2
        ELSE 1.0
      END))::bigint,
      'gift'
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN v_gift_transaction_id;
END;
$$;


ALTER FUNCTION "public"."send_gift_with_wallet"("p_room_id" "uuid", "p_receiver_id" "uuid", "p_gift_id" "uuid", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_room_image_message"("p_room_id" "uuid", "p_image_url" "text", "p_image_path" "text", "p_sender_role" "text" DEFAULT 'listener'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_message_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  -- VIP 7 gate (unchanged).
  if not public.can_user_send_chat_image(v_user_id) then
    raise exception 'image_messages_unlock_at_vip_7';
  end if;

  -- Moderation guard: muted (chat_mute / force_muted) or room-banned users
  -- cannot send images, mirroring the text path's mute enforcement.
  if (public.check_user_active_mute(p_room_id) ->> 'muted')::boolean then
    raise exception 'user_muted';
  end if;

  if p_room_id is null then
    raise exception 'missing_room_id';
  end if;

  if coalesce(trim(p_image_url), '') = '' then
    raise exception 'missing_image_url';
  end if;

  -- path owner check: first segment must be the caller's user_id
  if split_part(coalesce(p_image_path, ''), '/', 1) <> v_user_id::text then
    raise exception 'invalid_image_path_owner';
  end if;

  -- room existence guard
  if not exists (select 1 from public.rooms where id = p_room_id) then
    raise exception 'room_not_found';
  end if;

  insert into public.room_messages
    (room_id, sender_id, message, message_type, image_url, image_path, metadata)
  values
    (p_room_id, v_user_id, '', 'image', p_image_url, p_image_path,
     jsonb_build_object('role', coalesce(nullif(p_sender_role, ''), 'listener')))
  returning id into v_message_id;

  return jsonb_build_object(
    'id',         v_message_id,
    'room_id',    p_room_id,
    'image_url',  p_image_url,
    'image_path', p_image_path
  );
end;
$$;


ALTER FUNCTION "public"."send_room_image_message"("p_room_id" "uuid", "p_image_url" "text", "p_image_path" "text", "p_sender_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_custom_golden_id"("p_user_id" "uuid", "p_public_user_id" "text", "p_enabled" boolean DEFAULT true, "p_duration_days" integer DEFAULT NULL::integer, "p_style" "text" DEFAULT 'gold'::"text", "p_frame" "text" DEFAULT 'classic'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_public_user_id text;
  v_style          text;
  v_frame          text;
  v_expires_at     timestamptz;
  v_result         jsonb;
BEGIN
  -- ── Auth ──────────────────────────────────────────────────────────────────
  IF NOT public._vip_caller_is_admin() THEN
    RAISE EXCEPTION 'permission_denied: admin role required';
  END IF;

  -- ── Normalise ─────────────────────────────────────────────────────────────
  v_public_user_id := trim(coalesce(p_public_user_id, ''));
  v_style          := trim(lower(coalesce(p_style, 'gold')));
  v_frame          := trim(lower(coalesce(p_frame, 'classic')));

  -- ── Disable path ─────────────────────────────────────────────────────────
  IF NOT coalesce(p_enabled, true) THEN
    UPDATE public.profiles
    SET
      is_golden_id          = false,
      golden_id_expires_at  = NULL,
      golden_id_style       = 'gold',
      golden_id_frame       = 'classic',
      updated_at            = now()
    WHERE id = p_user_id;

    RETURN jsonb_build_object(
      'user_id',              p_user_id,
      'public_user_id',       (SELECT public_user_id FROM public.profiles WHERE id = p_user_id),
      'is_golden_id',         false,
      'golden_id_expires_at', NULL,
      'golden_id_style',      'gold',
      'golden_id_frame',      'classic'
    );
  END IF;

  -- ── Enable path — validate ────────────────────────────────────────────────

  -- ID format
  IF v_public_user_id !~ '^[A-Za-z0-9_-]{2,20}$' THEN
    RAISE EXCEPTION 'invalid_golden_id: must be 2–20 alphanumeric/dash/underscore characters';
  END IF;

  -- Uniqueness (exclude target user)
  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE public_user_id = v_public_user_id
      AND id <> p_user_id
  ) THEN
    RAISE EXCEPTION 'golden_id_taken';
  END IF;

  -- Style
  IF v_style NOT IN ('gold', 'diamond', 'royal', 'neon', 'fire', 'purple') THEN
    RAISE EXCEPTION 'invalid_golden_id_style: allowed values are gold, diamond, royal, neon, fire, purple';
  END IF;

  -- Frame
  IF v_frame NOT IN ('classic', 'crown', 'wings', 'glow', 'shield', 'luxury') THEN
    RAISE EXCEPTION 'invalid_golden_id_frame: allowed values are classic, crown, wings, glow, shield, luxury';
  END IF;

  -- Expiry
  v_expires_at := CASE
    WHEN p_duration_days IS NULL OR p_duration_days <= 0 THEN NULL
    ELSE now() + (p_duration_days || ' days')::interval
  END;

  -- ── Update ────────────────────────────────────────────────────────────────
  UPDATE public.profiles
  SET
    public_user_id       = v_public_user_id,
    is_golden_id         = true,
    golden_id_expires_at = v_expires_at,
    golden_id_style      = v_style,
    golden_id_frame      = v_frame,
    updated_at           = now()
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'user_not_found';
  END IF;

  -- ── Return ────────────────────────────────────────────────────────────────
  RETURN jsonb_build_object(
    'user_id',              p_user_id,
    'public_user_id',       v_public_user_id,
    'is_golden_id',         true,
    'golden_id_expires_at', v_expires_at,
    'golden_id_style',      v_style,
    'golden_id_frame',      v_frame
  );
END;
$_$;


ALTER FUNCTION "public"."set_custom_golden_id"("p_user_id" "uuid", "p_public_user_id" "text", "p_enabled" boolean, "p_duration_days" integer, "p_style" "text", "p_frame" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_golden_id"("p_user_id" "uuid", "p_enabled" boolean, "p_duration_days" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expires_at timestamptz;
BEGIN
  -- Admin check reuses the existing helper from centralized_vip_system migration.
  IF NOT public._vip_caller_is_admin() THEN
    RAISE EXCEPTION 'permission_denied: admin role required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_enabled THEN
    v_expires_at := CASE
      WHEN p_duration_days IS NOT NULL AND p_duration_days > 0
        THEN now() + (p_duration_days * interval '1 day')
      ELSE NULL
    END;

    UPDATE public.profiles
    SET
      is_golden_id         = true,
      golden_id_expires_at = v_expires_at
    WHERE id = p_user_id;
  ELSE
    UPDATE public.profiles
    SET
      is_golden_id         = false,
      golden_id_expires_at = NULL
    WHERE id = p_user_id;
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'user_id',             p.id,
      'is_golden_id',        p.is_golden_id,
      'golden_id_expires_at', p.golden_id_expires_at
    )
    FROM public.profiles p
    WHERE p.id = p_user_id
  );
END;
$$;


ALTER FUNCTION "public"."set_golden_id"("p_user_id" "uuid", "p_enabled" boolean, "p_duration_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_hungry_cat_forced_next_result"("p_outcome_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin      uuid := auth.uid();
  v_settings   public.game_settings;
  v_food       public.hungry_cat_config;
  v_active_bets integer;
begin
  -- ── Auth ──
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  -- ── Read config ──
  select * into v_settings
  from public.game_settings
  where game_key = 'hungry_cat'
  for update;

  -- ── test_mode guard ──
  if not v_settings.test_mode then
    raise exception 'test_mode_disabled: forced results are only allowed when game_settings.test_mode = true for hungry_cat';
  end if;

  -- ── Validate outcome key ──
  select * into v_food
  from public.hungry_cat_config
  where food_id = p_outcome_key and is_active = true;

  if not found then
    raise exception 'invalid_outcome_key';
  end if;

  -- ── No active betting/running rounds with accepted bets ──
  -- "Active" = any round in status 'betting' or 'locked' that has pending bets.
  -- We intentionally do NOT block if a round exists with zero bets placed yet,
  -- since the force will only apply to the *next* round that gets created.
  select coalesce(sum(b.bet_amount), 0) into v_active_bets
  from public.hungry_cat_rounds r
  join public.hungry_cat_bets b on b.round_id = r.id
  where r.status in ('betting', 'locked')
    and b.status = 'pending';

  if v_active_bets > 0 then
    raise exception 'active_bets_exist: cannot force result while a round has accepted bets';
  end if;

  -- ── Set forced result (expires in 30 minutes — auto-clears if unused) ──
  update public.game_settings
  set forced_next_result              = p_outcome_key,
      forced_next_result_expires_at   = now() + interval '30 minutes',
      forced_next_result_by           = v_admin,
      updated_at                      = now()
  where game_key = 'hungry_cat';

  -- ── Audit ──
  insert into public.admin_audit_logs
    (admin_user_id, action, entity_type, entity_id, metadata)
  values
    (v_admin, 'hungry_cat_forced_result_set', 'game_settings', 'hungry_cat',
     jsonb_build_object(
       'outcome_key', p_outcome_key,
       'food_name',   v_food.name,
       'multiplier',  v_food.multiplier,
       'warning',     'TEST MODE ONLY — forced result queued for next round'
     ));

  return jsonb_build_object(
    'ok',          true,
    'outcome_key', p_outcome_key,
    'food_name',   v_food.name,
    'icon',        v_food.icon,
    'multiplier',  v_food.multiplier,
    'expires_at',  now() + interval '30 minutes',
    'warning',     'TEST MODE ONLY. This forced result will be consumed by the next Hungry Cat round.'
  );
end;
$$;


ALTER FUNCTION "public"."set_hungry_cat_forced_next_result"("p_outcome_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_room_mute_status"("p_room_id" "uuid", "p_is_muted" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_force_muted boolean;
begin
  -- If the user wants to unmute, check whether they are force-muted by owner.
  if not p_is_muted then
    select force_muted
    into   v_force_muted
    from   public.room_members
    where  room_id = p_room_id
      and  user_id = auth.uid()
      and  left_at is null;

    if v_force_muted = true then
      raise exception 'force_muted';
    end if;
  end if;

  update public.room_members
  set    is_muted     = p_is_muted,
         last_seen_at = now()
  where  room_id  = p_room_id
    and  user_id  = auth.uid()
    and  left_at  is null;

  if not found then
    raise exception 'no_active_member';
  end if;
end;
$$;


ALTER FUNCTION "public"."set_my_room_mute_status"("p_room_id" "uuid", "p_is_muted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_vip_setting"("p_key" "text", "p_enabled" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid        uuid        := auth.uid();
  v_level      int;
  v_expires_at timestamptz;
  v_min_level  int;
  v_now        timestamptz := now();
BEGIN
  -- ── Auth check ────────────────────────────────────────────────────────────
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- ── Read caller VIP status ────────────────────────────────────────────────
  SELECT p.vip_level, p.vip_expires_at
  INTO   v_level, v_expires_at
  FROM   public.profiles p
  WHERE  p.id = v_uid;

  -- Treat expired VIP as level 0
  IF v_expires_at IS NOT NULL AND v_expires_at < v_now THEN
    v_level := 0;
  END IF;
  v_level := COALESCE(v_level, 0);

  -- ── Validate key + resolve min level ──────────────────────────────────────
  v_min_level := CASE p_key
    WHEN 'not_being_followed' THEN 5
    WHEN 'anti_entering_room' THEN 6
    WHEN 'private_browsing'   THEN 6
    WHEN 'do_not_disturb'     THEN 7
    WHEN 'anti_kick'          THEN 8
    WHEN 'invisibility'       THEN 8
    ELSE NULL
  END;

  IF v_min_level IS NULL THEN
    RAISE EXCEPTION 'invalid_key: %', p_key
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- ── Enforce level requirement ──────────────────────────────────────────────
  IF v_level < v_min_level THEN
    RAISE EXCEPTION 'vip_level_required: % requires VIP % (caller is VIP %)',
      p_key, v_min_level, v_level
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ── Upsert row then set the column ────────────────────────────────────────
  -- Ensure the row exists first (no-op if it already does).
  INSERT INTO public.user_vip_settings (user_id, updated_at)
  VALUES (v_uid, v_now)
  ON CONFLICT (user_id) DO NOTHING;

  -- Dynamic column update — safe because p_key is validated against the
  -- fixed CASE above; no user-supplied column name reaches format().
  EXECUTE format(
    'UPDATE public.user_vip_settings SET %I = $1, updated_at = $2 WHERE user_id = $3',
    p_key
  ) USING p_enabled, v_now, v_uid;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."set_my_vip_setting"("p_key" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rocket_crash_forced_next_multiplier"("p_multiplier" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin       uuid := auth.uid();
  v_settings    public.game_settings;
  v_active_bets integer;
begin
  if not public.has_app_role('super_admin') then
    raise exception 'not_authorized';
  end if;

  -- Validate range: 1.01 – 100.00
  if p_multiplier is null or p_multiplier < 1.01 or p_multiplier > 100.00 then
    raise exception 'invalid_multiplier: must be between 1.01 and 100.00';
  end if;

  select * into v_settings
  from public.game_settings
  where game_key = 'crash_rocket'
  for update;

  if not v_settings.test_mode then
    raise exception 'test_mode_disabled: forced multiplier only allowed when test_mode = true for crash_rocket';
  end if;

  -- Block if any round has pending or running bets
  select coalesce(count(*), 0) into v_active_bets
  from public.crash_bets
  where status in ('pending', 'running');

  if v_active_bets > 0 then
    raise exception 'active_bets_exist: cannot force multiplier while rounds have accepted bets';
  end if;

  update public.game_settings
  set forced_crash_multiplier            = p_multiplier,
      forced_crash_multiplier_expires_at = now() + interval '30 minutes',
      forced_crash_multiplier_by         = v_admin,
      updated_at                         = now()
  where game_key = 'crash_rocket';

  insert into public.admin_audit_logs
    (admin_user_id, action, entity_type, entity_id, metadata)
  values
    (v_admin, 'rocket_crash_forced_multiplier_set', 'game_settings', 'crash_rocket',
     jsonb_build_object(
       'multiplier', p_multiplier,
       'warning',    'TEST MODE ONLY — forced multiplier queued for next round'
     ));

  return jsonb_build_object(
    'ok',          true,
    'multiplier',  p_multiplier,
    'expires_at',  now() + interval '30 minutes',
    'warning',     'TEST MODE ONLY. Forced multiplier will be consumed by the next Rocket Crash round.'
  );
end;
$$;


ALTER FUNCTION "public"."set_rocket_crash_forced_next_multiplier"("p_multiplier" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_access_mode"("p_room_id" "uuid", "p_access_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_mode text := case when p_access_mode = 'watch' then 'watch' else 'open' end;
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not exists (
    select 1
    from public.rooms r
    where r.id = p_room_id
      and (
        r.owner_id = v_uid
        or exists (
          select 1
          from public.room_members rm
          where rm.room_id = p_room_id
            and rm.user_id = v_uid
            and rm.left_at is null
            and rm.role = 'host'
        )
        or exists (
          select 1
          from public.room_moderators mod
          where mod.room_id = p_room_id
            and mod.user_id = v_uid
        )
      )
  ) then
    raise exception 'room_mode_not_allowed';
  end if;

  if v_mode = 'watch'
     and not public._room_video_mode_vip_allowed(v_uid) then
    raise exception 'room_mode_vip6_required';
  end if;

  update public.rooms
  set access_mode = v_mode,
      updated_at = now()
  where id = p_room_id
  returning to_jsonb(rooms.*) into v_result;

  if v_result is null then
    raise exception 'room_not_found';
  end if;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_room_access_mode"("p_room_id" "uuid", "p_access_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_lock"("p_room_id" "uuid", "p_is_locked" boolean, "p_password" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_user_id uuid;
  v_owner_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select owner_id
  into v_owner_id
  from public.rooms
  where id = p_room_id;

  if v_owner_id is null then
    raise exception 'room_not_found';
  end if;

  if v_owner_id <> v_user_id then
    raise exception 'only_host_can_lock_room';
  end if;

  if p_is_locked then
    if p_password is null or length(trim(p_password)) < 3 then
      raise exception 'room_password_required';
    end if;

    update public.rooms
    set
      is_locked = true,
      room_password_hash = extensions.crypt(trim(p_password), extensions.gen_salt('bf'))
    where id = p_room_id;
  else
    update public.rooms
    set
      is_locked = false,
      room_password_hash = null
    where id = p_room_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_room_lock"("p_room_id" "uuid", "p_is_locked" boolean, "p_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_music_state"("p_room_id" "uuid", "p_track_id" "text", "p_track_title" "text", "p_track_artist" "text", "p_track_url" "text", "p_is_playing" boolean, "p_position_seconds" integer DEFAULT 0) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_now         timestamptz := now();
  v_started_at  timestamptz;
  v_paused_at   timestamptz;
  v_result      json;
begin
  -- Auth guard
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  -- Permission guard
  if not public.is_room_manager(p_room_id, v_uid) then
    raise exception 'not_room_manager';
  end if;

  -- Derive timestamps
  if p_is_playing then
    -- Anchor started_at so clients can compute currentPosition =
    --   p_position_seconds + (now - started_at)
    v_started_at := v_now;
    v_paused_at  := null;
  else
    v_started_at := null;
    v_paused_at  := v_now;
  end if;

  insert into public.room_music_state (
    room_id, track_id, track_title, track_artist, track_url,
    is_playing, started_at, paused_at, position_seconds,
    updated_by, updated_at
  )
  values (
    p_room_id, p_track_id, p_track_title, p_track_artist, p_track_url,
    p_is_playing, v_started_at, v_paused_at, p_position_seconds,
    v_uid, v_now
  )
  on conflict (room_id) do update set
    track_id         = excluded.track_id,
    track_title      = excluded.track_title,
    track_artist     = excluded.track_artist,
    track_url        = excluded.track_url,
    is_playing       = excluded.is_playing,
    started_at       = excluded.started_at,
    paused_at        = excluded.paused_at,
    position_seconds = excluded.position_seconds,
    updated_by       = excluded.updated_by,
    updated_at       = excluded.updated_at
  returning to_json(room_music_state.*) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_room_music_state"("p_room_id" "uuid", "p_track_id" "text", "p_track_title" "text", "p_track_artist" "text", "p_track_url" "text", "p_is_playing" boolean, "p_position_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_music_state"("p_room_id" "uuid", "p_track_id" "text", "p_track_title" "text", "p_track_artist" "text", "p_track_url" "text", "p_is_playing" boolean, "p_position_seconds" integer DEFAULT 0, "p_auto_replay" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_state public.room_music_state;
  v_controller_active boolean := false;
  v_controller uuid;
  v_result json;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;
  if not public.is_room_manager(p_room_id, v_uid) then
    raise exception 'not_room_manager';
  end if;
  if nullif(trim(coalesce(p_track_url, '')), '') is null
     or p_track_url !~ '^https?://' then
    raise exception 'invalid_track_url';
  end if;
  if length(coalesce(p_track_title, '')) > 200
     or length(coalesce(p_track_artist, '')) > 200
     or length(p_track_url) > 2048 then
    raise exception 'invalid_track_metadata';
  end if;
  if coalesce(p_position_seconds, 0) < 0
     or coalesce(p_position_seconds, 0) > 86400 then
    raise exception 'invalid_position';
  end if;

  select *
  into v_state
  from public.room_music_state
  where room_id = p_room_id
  for update;

  if v_state.controller_user_id is not null then
    select exists (
      select 1
      from public.room_members rm
      where rm.room_id = p_room_id
        and rm.user_id = v_state.controller_user_id
        and rm.left_at is null
    ) into v_controller_active;
  end if;

  if v_state.id is null
     or v_state.controller_user_id is null
     or not v_controller_active then
    v_controller := v_uid;
  elsif v_state.controller_user_id = v_uid
        or public.is_super_admin(v_uid) then
    v_controller := v_state.controller_user_id;
  else
    raise exception 'not_music_controller';
  end if;

  insert into public.room_music_state (
    room_id, track_id, track_title, track_artist, track_url,
    is_playing, started_at, paused_at, position_seconds,
    controller_user_id, auto_replay, updated_by, updated_at
  )
  values (
    p_room_id,
    nullif(trim(coalesce(p_track_id, '')), ''),
    nullif(trim(coalesce(p_track_title, '')), ''),
    nullif(trim(coalesce(p_track_artist, '')), ''),
    trim(p_track_url),
    p_is_playing,
    case when p_is_playing then v_now else null end,
    case when p_is_playing then null else v_now end,
    coalesce(p_position_seconds, 0),
    v_controller,
    p_auto_replay,
    v_uid,
    v_now
  )
  on conflict (room_id) do update set
    track_id = excluded.track_id,
    track_title = excluded.track_title,
    track_artist = excluded.track_artist,
    track_url = excluded.track_url,
    is_playing = excluded.is_playing,
    started_at = excluded.started_at,
    paused_at = excluded.paused_at,
    position_seconds = excluded.position_seconds,
    controller_user_id = excluded.controller_user_id,
    auto_replay = excluded.auto_replay,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at
  returning to_json(room_music_state.*) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_room_music_state"("p_room_id" "uuid", "p_track_id" "text", "p_track_title" "text", "p_track_artist" "text", "p_track_url" "text", "p_is_playing" boolean, "p_position_seconds" integer, "p_auto_replay" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_muted"("p_room_id" "uuid", "p_is_muted" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Caller must be owner or an active moderator/host
  if not exists (
    select 1
    from   public.room_members
    where  room_id = p_room_id
      and  user_id = auth.uid()
      and  role    in ('host', 'moderator')
      and  status  = 'active'
  ) then
    raise exception 'set_room_muted: caller is not owner or moderator';
  end if;

  update public.rooms
  set    is_room_muted = p_is_muted,
         updated_at    = now()
  where  id = p_room_id;
end;
$$;


ALTER FUNCTION "public"."set_room_muted"("p_room_id" "uuid", "p_is_muted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_pin"("p_room_id" "uuid", "p_pin" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.rooms WHERE id = p_room_id AND owner_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;
  UPDATE public.rooms
  SET room_pin_enabled = (p_pin IS NOT NULL AND p_pin <> ''),
      room_pin_hash    = CASE
                           WHEN p_pin IS NOT NULL AND p_pin <> ''
                           THEN encode(sha256(convert_to(p_pin, 'UTF8')), 'hex')
                           ELSE NULL
                         END
  WHERE id = p_room_id;
END;
$$;


