CREATE OR REPLACE FUNCTION "public"."set_room_youtube_state"("p_room_id" "uuid", "p_video_id" "text", "p_video_url" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_is_playing" boolean DEFAULT true, "p_position_seconds" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_position integer := greatest(coalesce(p_position_seconds, 0), 0);
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if nullif(trim(coalesce(p_video_id, '')), '') is null then
    raise exception 'invalid_youtube_video';
  end if;

  if not exists (
    select 1
    from public.room_members rm
    where rm.room_id = p_room_id
      and rm.user_id = v_uid
      and rm.left_at is null
  ) then
    raise exception 'not_in_room';
  end if;

  if not public._room_youtube_is_manager(p_room_id) then
    raise exception 'room_youtube_not_allowed';
  end if;

  insert into public.room_youtube_state (
    room_id,
    video_id,
    video_url,
    title,
    is_playing,
    position_seconds,
    started_at,
    controller_user_id,
    updated_at
  )
  values (
    p_room_id,
    trim(p_video_id),
    nullif(trim(coalesce(p_video_url, '')), ''),
    nullif(trim(coalesce(p_title, '')), ''),
    coalesce(p_is_playing, true),
    v_position,
    case when coalesce(p_is_playing, true) then now() else null end,
    v_uid,
    now()
  )
  on conflict (room_id) do update
    set video_id = excluded.video_id,
        video_url = excluded.video_url,
        title = excluded.title,
        is_playing = excluded.is_playing,
        position_seconds = excluded.position_seconds,
        started_at = excluded.started_at,
        controller_user_id = excluded.controller_user_id,
        updated_at = now()
  returning to_jsonb(room_youtube_state.*) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."set_room_youtube_state"("p_room_id" "uuid", "p_video_id" "text", "p_video_url" "text", "p_title" "text", "p_is_playing" boolean, "p_position_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_room_youtube_state"("p_room_id" "uuid", "p_video_id" "text", "p_video_url" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_thumbnail_url" "text" DEFAULT NULL::"text", "p_is_playing" boolean DEFAULT true, "p_position_seconds" integer DEFAULT 0, "p_last_action" "text" DEFAULT 'load'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_position integer := greatest(coalesce(p_position_seconds, 0), 0);
  v_action text := lower(coalesce(nullif(trim(p_last_action), ''), 'load'));
  v_controller_name text;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if nullif(trim(coalesce(p_video_id, '')), '') is null then
    raise exception 'invalid_youtube_video';
  end if;

  if v_action not in ('load', 'play', 'pause', 'seek', 'stop', 'clear', 'sync') then
    raise exception 'invalid_youtube_action';
  end if;

  if not exists (
    select 1
    from public.room_members rm
    where rm.room_id = p_room_id
      and rm.user_id = v_uid
      and rm.left_at is null
  ) then
    raise exception 'not_in_room';
  end if;

  if not public._room_youtube_is_manager(p_room_id) then
    raise exception 'room_youtube_not_allowed';
  end if;

  if not public._room_video_mode_vip_allowed(v_uid) then
    raise exception 'room_youtube_vip6_required';
  end if;

  select coalesce(nullif(trim(p.display_name), ''), nullif(trim(p.username), ''), 'Host')
    into v_controller_name
  from public.profiles p
  where p.id = v_uid;

  insert into public.room_youtube_state (
    room_id,
    video_id,
    video_url,
    title,
    thumbnail_url,
    is_playing,
    position_seconds,
    started_at,
    controlled_by_user_id,
    controlled_by_name,
    last_action,
    updated_at
  )
  values (
    p_room_id,
    trim(p_video_id),
    nullif(trim(coalesce(p_video_url, '')), ''),
    nullif(trim(coalesce(p_title, '')), ''),
    nullif(trim(coalesce(p_thumbnail_url, '')), ''),
    coalesce(p_is_playing, true),
    v_position,
    case when coalesce(p_is_playing, true) then now() else null end,
    v_uid,
    coalesce(v_controller_name, 'Host'),
    v_action,
    now()
  )
  on conflict (room_id) do update
    set video_id = excluded.video_id,
        video_url = excluded.video_url,
        title = excluded.title,
        thumbnail_url = excluded.thumbnail_url,
        is_playing = excluded.is_playing,
        position_seconds = excluded.position_seconds,
        started_at = excluded.started_at,
        controlled_by_user_id = excluded.controlled_by_user_id,
        controlled_by_name = excluded.controlled_by_name,
        last_action = excluded.last_action,
        updated_at = now()
  returning to_jsonb(room_youtube_state.*) into v_result;

  return v_result;
end;
$$;


