CREATE OR REPLACE FUNCTION "public"."settle_hungry_cat_global_round"("p_round_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id      uuid := auth.uid();
  v_round        public.hungry_cat_global_rounds;
  v_food         public.hungry_cat_config;
  v_settings     public.game_settings;
  v_total_weight numeric;
  v_roll         numeric;
  v_bet          record;
  v_win_amount   integer;
  v_forced_food  text;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  select * into v_round
  from public.hungry_cat_global_rounds
  where id = p_round_id
  for update;

  if v_round.id is null then raise exception 'round_not_found'; end if;

  -- Idempotent: already settled — return early without re-paying
  if v_round.status = 'settled' then
    return json_build_object(
      'round_id',           v_round.id,
      'status',             'settled',
      'winning_food_id',    v_round.winning_food_id,
      'winning_food_icon',  v_round.winning_food_icon,
      'winning_food_name',  v_round.winning_food_name,
      'winning_multiplier', v_round.winning_multiplier,
      'server_now',         now()
    );
  end if;

  if v_round.betting_ends_at > now() then
    raise exception 'betting_still_open';
  end if;

  -- ── Check for forced result (test mode only) ──────────────────────────────
  select * into v_settings
  from public.game_settings
  where game_key = 'hungry_cat';

  v_forced_food := null;
  if v_settings.test_mode
     and v_settings.forced_next_result is not null
     and (v_settings.forced_next_result_expires_at is null
          or v_settings.forced_next_result_expires_at > now())
  then
    -- Validate the forced food is still active
    select * into v_food
    from public.hungry_cat_config
    where food_id = v_settings.forced_next_result and is_active;

    if v_food.id is not null then
      v_forced_food := v_settings.forced_next_result;
      -- Clear immediately so it is used only once
      update public.game_settings
      set forced_next_result             = null,
          forced_next_result_expires_at  = null,
          forced_next_result_by          = null,
          updated_at                     = now()
      where game_key = 'hungry_cat';
    end if;
  end if;

  -- ── Weighted-random food selection (when not forced) ──────────────────────
  if v_forced_food is null then
    select coalesce(sum(weight), 0) into v_total_weight
    from public.hungry_cat_config
    where is_active and weight > 0;

    if v_total_weight <= 0 then raise exception 'invalid_food_config'; end if;

    v_roll := random() * v_total_weight;

    select * into v_food
    from (
      select c.*,
             sum(c.weight) over (order by c.sort_order, c.food_id) as cum_weight
      from public.hungry_cat_config c
      where c.is_active and c.weight > 0
    ) ranked
    where ranked.cum_weight >= v_roll
    order by ranked.cum_weight
    limit 1;

    -- Fallback: last active food if roll somehow exceeds total
    if v_food.id is null then
      select c.* into v_food
      from public.hungry_cat_config c
      where c.is_active and c.weight > 0
      order by c.sort_order desc
      limit 1;
    end if;
  end if;

  if v_food.id is null then raise exception 'invalid_food_config'; end if;

  -- ── Pay out all winning bets; mark losers ─────────────────────────────────
  for v_bet in
    select b.id, b.user_id, b.bet_amount, b.food_id
    from public.hungry_cat_global_bets b
    where b.round_id = p_round_id and b.status = 'pending'
  loop
    if v_bet.food_id = v_food.food_id then
      v_win_amount := floor(v_bet.bet_amount * v_food.multiplier)::integer;

      update public.wallets
      set coins_balance = coins_balance + v_win_amount,
          updated_at    = now()
      where user_id = v_bet.user_id;

      update public.hungry_cat_global_bets
      set status = 'won', win_amount = v_win_amount
      where id = v_bet.id;

      insert into public.wallet_transactions
        (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
      values
        (v_bet.user_id, 'hungry_cat_reward', 'credit', v_win_amount, 0,
         'Hungry Cat win: ' || v_food.name || ' x' || v_food.multiplier,
         jsonb_build_object('bet_id', v_bet.id, 'round_id', p_round_id,
                            'food_id', v_food.food_id,
                            'multiplier', v_food.multiplier,
                            'forced', v_forced_food is not null));
    else
      update public.hungry_cat_global_bets
      set status = 'lost'
      where id = v_bet.id;
    end if;
  end loop;

  -- ── Mark round settled ────────────────────────────────────────────────────
  update public.hungry_cat_global_rounds
  set status             = 'settled',
      result_reveals_at  = now(),
      winning_food_id    = v_food.food_id,
      winning_food_icon  = v_food.icon,
      winning_food_name  = v_food.name,
      winning_multiplier = v_food.multiplier
  where id = p_round_id;

  return json_build_object(
    'round_id',           p_round_id,
    'status',             'settled',
    'winning_food_id',    v_food.food_id,
    'winning_food_icon',  v_food.icon,
    'winning_food_name',  v_food.name,
    'winning_multiplier', v_food.multiplier,
    'server_now',         now()
  );
end;
$$;


ALTER FUNCTION "public"."settle_hungry_cat_global_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_hungry_cat_round"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id        uuid := auth.uid();
  v_round          public.hungry_cat_rounds;
  v_food           public.hungry_cat_config;
  v_total_weight   numeric;
  v_roll           numeric;
  v_cumulative     numeric := 0;
  v_found          boolean := false;
  v_user_total_bet integer;
  v_user_win       integer := 0;
  v_new_balance    integer;
  v_round_win_amt  integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  select * into v_round
  from public.hungry_cat_rounds
  where id = p_round_id and user_id = v_user_id
  for update;

  if not found then raise exception 'round_not_found'; end if;

  -- Idempotent: already settled
  if v_round.status = 'completed' then
    select coalesce(sum(case when status='won' then bet_amount else 0 end), 0)
    into v_user_total_bet
    from public.hungry_cat_bets
    where round_id = p_round_id and user_id = v_user_id;

    select coins_balance into v_new_balance from public.wallets where user_id = v_user_id;

    return jsonb_build_object(
      'winning_food_id',     v_round.winning_food_id,
      'winning_food_icon',   v_round.winning_food_icon,
      'winning_food_name',   v_round.winning_food_name,
      'winning_multiplier',  v_round.winning_multiplier,
      'rarity',              v_round.winning_food_rarity,
      'user_total_bet',      v_user_total_bet,
      'user_win_amount',     0,
      'new_balance',         v_new_balance
    );
  end if;

  -- Lock round
  update public.hungry_cat_rounds set status = 'locked' where id = p_round_id;

  -- Weighted random food selection
  select sum(weight) into v_total_weight from public.hungry_cat_config where is_active = true;
  if v_total_weight is null or v_total_weight <= 0 then
    raise exception 'no_active_foods';
  end if;
  v_roll := random() * v_total_weight;

  for v_food in (
    select * from public.hungry_cat_config
    where is_active = true
    order by sort_order
  ) loop
    v_cumulative := v_cumulative + v_food.weight;
    if v_roll <= v_cumulative then
      v_found := true;
      exit;
    end if;
  end loop;

  if not v_found then
    select * into v_food from public.hungry_cat_config
    where is_active = true order by sort_order limit 1;
  end if;

  -- Sum user bets on winning food
  select coalesce(sum(bet_amount), 0) into v_user_total_bet
  from public.hungry_cat_bets
  where round_id = p_round_id and user_id = v_user_id;

  -- Compute win for bets on the winning food
  select coalesce(sum(bet_amount), 0) into v_round_win_amt
  from public.hungry_cat_bets
  where round_id = p_round_id
    and user_id = v_user_id
    and food_id = v_food.food_id
    and status = 'pending';

  v_user_win := (v_round_win_amt * v_food.multiplier)::integer;

  -- Settle all bets
  update public.hungry_cat_bets
  set status   = case when food_id = v_food.food_id then 'won' else 'lost' end,
      win_amount = case when food_id = v_food.food_id
                        then (bet_amount * v_food.multiplier)::integer else 0 end
  where round_id = p_round_id and user_id = v_user_id and status = 'pending';

  -- Credit winnings if any
  if v_user_win > 0 then
    update public.wallets
    set coins_balance = coins_balance + v_user_win, updated_at = now()
    where user_id = v_user_id
    returning coins_balance into v_new_balance;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_user_id, 'hungry_cat_reward', 'credit', v_user_win, 0,
       'Hungry Cat win — ' || v_food.name || ' ×' || v_food.multiplier,
       jsonb_build_object('round_id', p_round_id, 'food_id', v_food.food_id));
  else
    select coins_balance into v_new_balance from public.wallets where user_id = v_user_id;
  end if;

  -- Complete round
  update public.hungry_cat_rounds
  set status              = 'completed',
      winning_food_id     = v_food.food_id,
      winning_food_icon   = v_food.icon,
      winning_food_name   = v_food.name,
      winning_food_rarity = v_food.rarity,
      winning_multiplier  = v_food.multiplier,
      completed_at        = now()
  where id = p_round_id;

  return jsonb_build_object(
    'winning_food_id',     v_food.food_id,
    'winning_food_icon',   v_food.icon,
    'winning_food_name',   v_food.name,
    'winning_multiplier',  v_food.multiplier,
    'rarity',              v_food.rarity,
    'user_total_bet',      v_user_total_bet,
    'user_win_amount',     v_user_win,
    'new_balance',         v_new_balance
  );
end;
$$;


ALTER FUNCTION "public"."settle_hungry_cat_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_magic_srood_global_round"("p_round_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id      uuid := auth.uid();
  v_round        public.magic_srood_global_rounds;
  v_food         public.magic_srood_config;
  v_total_weight numeric;
  v_roll         numeric;
  v_food_id      uuid;
  v_result_config jsonb;
  v_total_pool   bigint;
  v_total_payout bigint;
  v_payout       record;
  v_new_balance  integer;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select *
  into v_round
  from public.magic_srood_global_rounds
  where id = p_round_id
  for update;

  if not found then
    raise exception 'round_not_found';
  end if;

  if v_round.status = 'settled' then
    return json_build_object(
      'round_id', v_round.id,
      'status', v_round.status,
      'winning_food_id', v_round.winning_food_id,
      'winning_food_icon', v_round.winning_food_icon,
      'winning_food_name', v_round.winning_food_name,
      'winning_multiplier', v_round.winning_multiplier,
      'total_pool', v_round.total_pool,
      'total_payout', v_round.total_payout,
      'settled_at', v_round.settled_at,
      'server_now', now()
    );
  end if;

  if v_round.betting_ends_at > now() then
    raise exception 'betting_still_open';
  end if;

  select coalesce(sum(weight), 0),
         jsonb_agg(
           jsonb_build_object(
             'food_id', food_id,
             'name', name,
             'icon', icon,
             'multiplier', multiplier,
             'weight', weight,
             'rarity', rarity,
             'sort_order', sort_order
           )
           order by sort_order, food_id
         )
  into v_total_weight, v_result_config
  from public.magic_srood_config
  where is_active and weight > 0;

  if v_total_weight <= 0 then
    raise exception 'invalid_game_config';
  end if;

  v_roll := random() * v_total_weight;

  select ranked.id
  into v_food_id
  from (
    select c.*,
           sum(c.weight) over (order by c.sort_order, c.food_id) as cumulative_weight
    from public.magic_srood_config c
    where c.is_active and c.weight > 0
  ) ranked
  where ranked.cumulative_weight >= v_roll
  order by ranked.cumulative_weight
  limit 1;

  if v_food_id is null then
    select id
    into v_food_id
    from public.magic_srood_config
    where is_active and weight > 0
    order by sort_order desc, food_id desc
    limit 1;
  end if;

  select *
  into v_food
  from public.magic_srood_config
  where id = v_food_id;

  if not found then
    raise exception 'invalid_game_config';
  end if;

  select coalesce(sum(bet_amount), 0)
  into v_total_pool
  from public.magic_srood_global_bets
  where round_id = p_round_id;

  select coalesce(
    sum(floor(bet_amount * multiplier_at_bet)),
    0
  )
  into v_total_payout
  from public.magic_srood_global_bets
  where round_id = p_round_id
    and status = 'pending'
    and food_id = v_food.food_id;

  -- Aggregate by user so each wallet is locked and updated once, in stable
  -- UUID order. Individual bets are still retained for audit/history.
  for v_payout in
    select b.user_id,
           sum(floor(b.bet_amount * b.multiplier_at_bet))::integer as amount
    from public.magic_srood_global_bets b
    where b.round_id = p_round_id
      and b.status = 'pending'
      and b.food_id = v_food.food_id
    group by b.user_id
    order by b.user_id
  loop
    update public.wallets
    set coins_balance = coins_balance + v_payout.amount,
        updated_at = now()
    where user_id = v_payout.user_id
    returning coins_balance into v_new_balance;

    if not found then
      raise exception 'wallet_not_found';
    end if;

    insert into public.wallet_transactions (
      user_id, type, direction, coins_delta, diamonds_delta,
      balance_coins_after, note, metadata
    )
    values (
      v_payout.user_id, 'magic_srood_reward', 'credit', v_payout.amount, 0,
      v_new_balance, 'Magic Srood round reward',
      jsonb_build_object(
        'round_id', p_round_id,
        'food_id', v_food.food_id,
        'multiplier', v_food.multiplier
      )
    );
  end loop;

  update public.magic_srood_global_bets
  set status = case when food_id = v_food.food_id then 'won' else 'lost' end,
      win_amount = case
        when food_id = v_food.food_id
          then floor(bet_amount * multiplier_at_bet)::integer
        else 0
      end
  where round_id = p_round_id
    and status = 'pending';

  update public.magic_srood_global_rounds
  set status = 'settled',
      result_reveals_at = now(),
      winning_food_id = v_food.food_id,
      winning_food_icon = v_food.icon,
      winning_food_name = v_food.name,
      winning_multiplier = v_food.multiplier,
      winning_rarity = v_food.rarity,
      total_pool = v_total_pool,
      total_payout = v_total_payout,
      result_roll = v_roll,
      result_total_weight = v_total_weight,
      result_config = v_result_config,
      result_algorithm = 'weighted_v1',
      settled_at = now()
  where id = p_round_id;

  return json_build_object(
    'round_id', p_round_id,
    'status', 'settled',
    'winning_food_id', v_food.food_id,
    'winning_food_icon', v_food.icon,
    'winning_food_name', v_food.name,
    'winning_multiplier', v_food.multiplier,
    'total_pool', v_total_pool,
    'total_payout', v_total_payout,
    'settled_at', now(),
    'server_now', now()
  );
end;
$$;


ALTER FUNCTION "public"."settle_magic_srood_global_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_rocket_crash_round"("p_round_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_round  public.rocket_crash_global_rounds;
  v_bet    record;
  v_win    integer;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  select * into v_round
  from public.rocket_crash_global_rounds
  where id = p_round_id for update;

  if v_round.id is null then raise exception 'round_not_found'; end if;

  -- Idempotent
  if v_round.status = 'crashed' then
    return json_build_object('status', 'crashed', 'crash_multiplier', v_round.crash_multiplier);
  end if;

  if v_round.status <> 'flying' then raise exception 'round_not_flying'; end if;

  -- Pay auto-cashout bets whose target is at or below the crash multiplier
  for v_bet in
    select b.* from public.rocket_crash_global_bets b
    where b.round_id = p_round_id
      and b.status = 'active'
      and b.auto_cashout_multiplier is not null
      and b.auto_cashout_multiplier <= v_round.crash_multiplier
  loop
    v_win := floor(v_bet.bet_amount * v_bet.auto_cashout_multiplier)::integer;

    update public.rocket_crash_global_bets
    set status             = 'cashed_out',
        cashout_multiplier = v_bet.auto_cashout_multiplier,
        win_amount         = v_win,
        cashed_out_at      = now()
    where id = v_bet.id;

    update public.wallets
    set coins_balance = coins_balance + v_win, updated_at = now()
    where user_id = v_bet.user_id;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_bet.user_id, 'crash_rocket_win', 'credit', v_win, 0,
       'Rocket Crash auto-cashout at ' || v_bet.auto_cashout_multiplier || '×',
       jsonb_build_object('bet_id', v_bet.id, 'round_id', p_round_id,
                          'multiplier', v_bet.auto_cashout_multiplier, 'auto', true));
  end loop;

  -- Mark remaining active bets as lost
  update public.rocket_crash_global_bets
  set status = 'lost'
  where round_id = p_round_id and status = 'active';

  update public.rocket_crash_global_rounds
  set status     = 'crashed',
      crashed_at = now()
  where id = p_round_id;

  return json_build_object('status', 'crashed', 'crash_multiplier', v_round.crash_multiplier);
end;
$$;


ALTER FUNCTION "public"."settle_rocket_crash_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_roulette_round"("p_round_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_round   public.roulette_rounds;
  v_bet     record;
  v_is_win  boolean;
  v_payout  bigint;
  v_new_bal bigint;
begin
  select *
  into v_round
  from public.roulette_rounds
  where id = p_round_id
  for update;

  if not found or v_round.status <> 'spinning' or v_round.winning_number is null then
    return;
  end if;

  for v_bet in
    select *
    from public.roulette_bets
    where round_id = p_round_id
      and status = 'active'
    for update
  loop
    v_is_win := case v_bet.bet_zone
      when 'straight_zero' then v_round.winning_number = 0
      when 'low'           then v_round.winning_number between 1 and 12
      when 'mid'           then v_round.winning_number between 13 and 24
      when 'high'          then v_round.winning_number between 25 and 36
      when 'red'           then public.roulette_is_red(v_round.winning_number)
      when 'black'         then v_round.winning_number <> 0
                                 and not public.roulette_is_red(v_round.winning_number)
      when 'even'          then v_round.winning_number <> 0
                                 and v_round.winning_number % 2 = 0
      when 'odd'           then v_round.winning_number <> 0
                                 and v_round.winning_number % 2 = 1
      else false
    end;

    if v_is_win then
      v_payout := floor(v_bet.bet_amount * v_bet.payout_multiplier)::bigint;

      update public.wallets
      set coins_balance = coins_balance + v_payout,
          updated_at = now()
      where user_id = v_bet.user_id
      returning coins_balance into v_new_bal;

      insert into public.wallet_transactions (
        user_id, type, direction, coins_delta, diamonds_delta,
        balance_coins_after, note, metadata
      )
      values (
        v_bet.user_id, 'roulette_win', 'credit', v_payout, 0,
        v_new_bal, 'Srood Roulette win',
        jsonb_build_object(
          'round_id', p_round_id, 'bet_id', v_bet.id,
          'bet_zone', v_bet.bet_zone, 'winning_number', v_round.winning_number
        )
      );

      update public.roulette_bets
      set status = 'won',
          payout_amount = v_payout
      where id = v_bet.id;
    else
      update public.roulette_bets
      set status = 'lost',
          payout_amount = 0
      where id = v_bet.id;
    end if;
  end loop;

  update public.roulette_rounds
  set status = 'settled',
      settled_at = now()
  where id = p_round_id;
end;
$$;


ALTER FUNCTION "public"."settle_roulette_round"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spin_wheel"("p_client_spin_id" "text" DEFAULT NULL::"text") RETURNS TABLE("prize_label" "text", "coins_won" integer, "diamonds_won" integer, "new_coins_balance" integer, "new_diamonds_balance" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid        uuid := auth.uid();
  c_spin_cost  constant integer := 50;
  v_existing   public.spin_wheel_spins;
  v_prize      public.spin_wheel_prizes;
  v_total      integer;
  v_roll       integer;
  v_coins_bal  integer;
  v_diamonds_bal integer;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('spin_wheel:' || v_uid::text || ':' || coalesce(p_client_spin_id, ''))
  );

  if p_client_spin_id is not null then
    select * into v_existing
    from public.spin_wheel_spins
    where user_id = v_uid and client_spin_id = p_client_spin_id;

    if v_existing.id is not null then
      select coins_balance, diamonds_balance into v_coins_bal, v_diamonds_bal
      from public.wallets where user_id = v_uid;
      return query select
        v_existing.prize_label,
        greatest(v_existing.coins_delta, 0),
        greatest(v_existing.diamonds_delta, 0),
        coalesce(v_coins_bal, 0),
        coalesce(v_diamonds_bal, 0);
      return;
    end if;
  end if;

  update public.wallets
  set coins_balance        = coins_balance - c_spin_cost,
      lifetime_coins_spent = lifetime_coins_spent + c_spin_cost,
      updated_at           = now()
  where user_id = v_uid
    and coins_balance >= c_spin_cost
  returning coins_balance, diamonds_balance into v_coins_bal, v_diamonds_bal;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta,
     balance_coins_after, balance_diamonds_after, note, metadata)
  values
    (v_uid, 'spin_wheel_bet', 'debit', -c_spin_cost, 0,
     v_coins_bal, v_diamonds_bal, 'Spin Wheel spin',
     jsonb_build_object('cost', c_spin_cost, 'client_spin_id', p_client_spin_id));

  select coalesce(sum(weight), 0) into v_total
  from public.spin_wheel_prizes where is_active;
  if v_total <= 0 then
    raise exception 'no_active_prizes';
  end if;

  v_roll := floor(random() * v_total)::integer;

  select p.* into v_prize
  from (
    select *, sum(weight) over (order by sort_order
                                rows between unbounded preceding and current row) as cum
    from public.spin_wheel_prizes
    where is_active
  ) p
  where v_roll < p.cum
  order by p.sort_order
  limit 1;

  if v_prize.label is null then
    raise exception 'prize_selection_failed';
  end if;

  if v_prize.reward_kind = 'coins' and v_prize.reward_amount > 0 then
    update public.wallets
    set coins_balance = coins_balance + v_prize.reward_amount,
        updated_at    = now()
    where user_id = v_uid
    returning coins_balance, diamonds_balance into v_coins_bal, v_diamonds_bal;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta,
       balance_coins_after, balance_diamonds_after, note, metadata)
    values
      (v_uid, 'spin_wheel_reward', 'credit', v_prize.reward_amount, 0,
       v_coins_bal, v_diamonds_bal, 'Spin Wheel reward: ' || v_prize.label,
       jsonb_build_object('prize', v_prize.label, 'client_spin_id', p_client_spin_id));

  elsif v_prize.reward_kind = 'diamonds' and v_prize.reward_amount > 0 then
    update public.wallets
    set diamonds_balance         = diamonds_balance + v_prize.reward_amount,
        lifetime_diamonds_earned = lifetime_diamonds_earned + v_prize.reward_amount,
        updated_at               = now()
    where user_id = v_uid
    returning coins_balance, diamonds_balance into v_coins_bal, v_diamonds_bal;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta,
       balance_coins_after, balance_diamonds_after, note, metadata)
    values
      (v_uid, 'spin_wheel_reward', 'credit', 0, v_prize.reward_amount,
       v_coins_bal, v_diamonds_bal, 'Spin Wheel reward: ' || v_prize.label,
       jsonb_build_object('prize', v_prize.label, 'client_spin_id', p_client_spin_id));
  end if;

  insert into public.spin_wheel_spins
    (user_id, client_spin_id, prize_label, cost, coins_delta, diamonds_delta)
  values
    (v_uid, p_client_spin_id, v_prize.label, c_spin_cost,
     case when v_prize.reward_kind = 'coins'    then v_prize.reward_amount else 0 end,
     case when v_prize.reward_kind = 'diamonds' then v_prize.reward_amount else 0 end);

  return query select
    v_prize.label,
    case when v_prize.reward_kind = 'coins'    then v_prize.reward_amount else 0 end,
    case when v_prize.reward_kind = 'diamonds' then v_prize.reward_amount else 0 end,
    coalesce(v_coins_bal, 0),
    coalesce(v_diamonds_bal, 0);
end;
$$;


ALTER FUNCTION "public"."spin_wheel"("p_client_spin_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."spin_wheel"("p_client_spin_id" "text") IS 'Server-authoritative Spin Wheel: debits the cost, picks the weighted winning segment, credits the reward, and records an idempotent audit row. The only path that mutates wallets for a spin; the client is never trusted for result or payout.';



CREATE OR REPLACE FUNCTION "public"."start_crash_round"("p_bets" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id     uuid    := auth.uid();
  v_round_id    uuid    := gen_random_uuid();
  v_total_bet   integer;
  v_new_balance integer;
  v_rand        numeric;
  v_crash_at    numeric;
  v_started_at  timestamptz := now();
  v_bet_ids     jsonb   := '[]'::jsonb;
  v_bet_id      uuid;
  v_i           integer;
  v_bet_amount  integer;
  v_bet_mode    text;
  v_auto_target numeric;
  v_settings    public.game_settings;
  v_used_forced boolean := false;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  -- Load settings (includes test_mode + forced_crash_multiplier)
  select * into v_settings
  from public.game_settings
  where game_key = 'crash_rocket'
  for update;

  -- Kill-switch check
  if v_settings.is_enabled = false then
    raise exception 'game_disabled';
  end if;

  if p_bets is null or jsonb_array_length(p_bets) = 0 then
    raise exception 'no_bets';
  end if;
  if jsonb_array_length(p_bets) > 2 then
    raise exception 'too_many_bets';
  end if;

  -- Sum total bet
  select coalesce(sum((val->>'bet_amount')::integer), 0)
  into v_total_bet
  from jsonb_array_elements(p_bets) as val;

  if v_total_bet <= 0 then raise exception 'invalid_bet_amount'; end if;

  -- Deduct from real wallet atomically
  update public.wallets
  set coins_balance        = coins_balance - v_total_bet,
      lifetime_coins_spent = lifetime_coins_spent + v_total_bet,
      updated_at           = now()
  where user_id = v_user_id
    and coins_balance >= v_total_bet
  returning coins_balance into v_new_balance;

  if not found then raise exception 'insufficient_coins'; end if;

  -- ── Crash point selection ──────────────────────────────────────────────────
  -- test_mode + valid forced multiplier → use it; else provably-fair random.

  if v_settings.test_mode
     and v_settings.forced_crash_multiplier is not null
     and (v_settings.forced_crash_multiplier_expires_at is null
          or now() <= v_settings.forced_crash_multiplier_expires_at)
  then
    v_crash_at    := v_settings.forced_crash_multiplier;
    v_used_forced := true;

    -- Clear forced multiplier immediately (single-use)
    update public.game_settings
    set forced_crash_multiplier            = null,
        forced_crash_multiplier_expires_at = null,
        forced_crash_multiplier_by         = null,
        updated_at                         = now()
    where game_key = 'crash_rocket';

    insert into public.admin_audit_logs
      (admin_user_id, action, entity_type, entity_id, metadata)
    values
      (null, 'rocket_crash_forced_multiplier_consumed', 'game_settings', 'crash_rocket',
       jsonb_build_object(
         'multiplier',       v_crash_at,
         'consumed_by_user', v_user_id,
         'test_mode',        true
       ));
  else
    -- Provably-fair: 1% instant crash; otherwise 0.99 / (1 - rand), capped 1000×
    v_rand := random();
    if v_rand < 0.01 then
      v_crash_at := 1.00;
    else
      v_crash_at := round((0.99 / (1.0 - v_rand))::numeric, 2);
      if v_crash_at < 1.00  then v_crash_at := 1.00;    end if;
      if v_crash_at > 1000  then v_crash_at := 1000.00; end if;
    end if;
  end if;

  -- Create round
  insert into public.crash_rounds(id, user_id, status, crash_multiplier, started_at)
  values (v_round_id, v_user_id, 'flying', v_crash_at, v_started_at);

  -- Wallet transaction for total bet
  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'crash_rocket_bet', 'debit', -v_total_bet, 0,
     'Crash Rocket bet',
     jsonb_build_object('round_id', v_round_id, 'total_bet', v_total_bet,
                        'forced', v_used_forced));

  -- Individual bet records
  for v_i in 0..jsonb_array_length(p_bets) - 1 loop
    v_bet_id     := gen_random_uuid();
    v_bet_amount := (p_bets->v_i->>'bet_amount')::integer;
    v_bet_mode   := coalesce(p_bets->v_i->>'mode', 'manual');
    v_auto_target := (p_bets->v_i->>'auto_cashout_multiplier')::numeric;

    insert into public.crash_bets
      (id, round_id, user_id, bet_amount, mode, auto_cashout_multiplier, status)
    values
      (v_bet_id, v_round_id, v_user_id, v_bet_amount, v_bet_mode, v_auto_target, 'running');

    v_bet_ids := v_bet_ids || jsonb_build_array(jsonb_build_object('id', v_bet_id));
  end loop;

  return jsonb_build_object(
    'round_id',    v_round_id,
    'started_at',  v_started_at,
    'new_balance', v_new_balance,
    'bets',        v_bet_ids,
    'forced',      v_used_forced
  );
end;
$$;


ALTER FUNCTION "public"."start_crash_round"("p_bets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_gold_ladder_run"("p_entry_fee" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_run_id     uuid := gen_random_uuid();
  v_new_balance integer;
  v_question_ids uuid[];
  v_first_q    record;
  v_ladder     jsonb;
  v_prizes     numeric[] := array[1,1.5,2,3,5,7,10,15,20,30,50,100];
  i            integer;
  v_ladder_arr jsonb[] := array[]::jsonb[];
  v_safe_qs    integer[] := array[5,10];
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_entry_fee not in (100, 500, 1000) then
    raise exception 'invalid_entry_fee';
  end if;

  -- Deduct entry fee atomically
  update public.wallets
  set    coins_balance         = coins_balance - p_entry_fee,
         lifetime_coins_spent  = lifetime_coins_spent + p_entry_fee,
         updated_at            = now()
  where  user_id = v_user_id
  and    coins_balance >= p_entry_fee
  returning coins_balance into v_new_balance;

  if not found then
    raise exception 'insufficient_coins';
  end if;

  -- Record wallet transaction
  insert into public.wallet_transactions
    (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
  values
    (v_user_id, 'gold_ladder_entry', 'debit', -p_entry_fee, 0,
     'Gold Ladder Quiz entry fee',
     jsonb_build_object('run_id', v_run_id, 'entry_fee', p_entry_fee));

  -- Select 12 questions: 4 easy (Q1-4), 4 medium (Q5-8), 4 hard (Q9-12)
  select array_agg(q_id order by random()) into v_question_ids
  from (
    (select id as q_id from public.gold_ladder_questions
     where difficulty = 'easy' and is_active = true order by random() limit 4)
    union all
    (select id from public.gold_ladder_questions
     where difficulty = 'medium' and is_active = true order by random() limit 4)
    union all
    (select id from public.gold_ladder_questions
     where difficulty = 'hard' and is_active = true order by random() limit 4)
  ) q;

  -- Check we have enough questions
  if array_length(v_question_ids, 1) < 12 then
    -- Refund and abort
    update public.wallets
    set coins_balance = coins_balance + p_entry_fee, updated_at = now()
    where user_id = v_user_id;
    raise exception 'insufficient_questions';
  end if;

  -- Create run
  insert into public.gold_ladder_runs
    (id, user_id, entry_fee, question_ids, status, powers_remaining)
  values
    (v_run_id, v_user_id, p_entry_fee, v_question_ids, 'active',
     '{"remove_two":1,"crowd_pulse":1,"second_chance":1}'::jsonb);

  -- Fetch first question (no correct_option sent)
  select id, text, text_ar,
         option_a, option_b, option_c, option_d,
         option_a_ar, option_b_ar, option_c_ar, option_d_ar,
         difficulty
  into v_first_q
  from public.gold_ladder_questions
  where id = v_question_ids[1];

  -- Build ladder with prizes
  for i in 1..12 loop
    v_ladder_arr := v_ladder_arr || jsonb_build_object(
      'q',          i,
      'multiplier', v_prizes[i],
      'prize',      (p_entry_fee * v_prizes[i])::integer,
      'safe',       (i = any(v_safe_qs))
    );
  end loop;
  v_ladder := array_to_json(v_ladder_arr)::jsonb;

  return jsonb_build_object(
    'run_id',        v_run_id,
    'entry_fee',     p_entry_fee,
    'balance',       v_new_balance,
    'question_number', 1,
    'current_prize', (p_entry_fee * v_prizes[1])::integer,
    'question', jsonb_build_object(
      'id',         v_first_q.id,
      'text',       v_first_q.text,
      'text_ar',    v_first_q.text_ar,
      'option_a',   v_first_q.option_a,
      'option_b',   v_first_q.option_b,
      'option_c',   v_first_q.option_c,
      'option_d',   v_first_q.option_d,
      'option_a_ar',v_first_q.option_a_ar,
      'option_b_ar',v_first_q.option_b_ar,
      'option_c_ar',v_first_q.option_c_ar,
      'option_d_ar',v_first_q.option_d_ar,
      'difficulty', v_first_q.difficulty
    ),
    'ladder',        v_ladder,
    'powers_remaining', '{"remove_two":1,"crowd_pulse":1,"second_chance":1}'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."start_gold_ladder_run"("p_entry_fee" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_hungry_cat_round"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_round_id uuid := gen_random_uuid();
  v_ends_at  timestamptz := now() + interval '12 seconds';
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  -- Check game is enabled
  if exists (
    select 1 from public.game_settings
    where game_key = 'hungry_cat' and is_enabled = false
  ) then
    raise exception 'game_disabled';
  end if;

  insert into public.hungry_cat_rounds
    (id, user_id, status, betting_ends_at)
  values
    (v_round_id, v_user_id, 'betting', v_ends_at);

  return jsonb_build_object(
    'round_id',       v_round_id,
    'betting_ends_at', v_ends_at
  );
end;
$$;


