CREATE OR REPLACE FUNCTION "public"."start_rocket_crash_flight"("p_round_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_round  public.rocket_crash_global_rounds;
  v_rand   numeric;
  v_crash  numeric;
  v_now    timestamptz := now();
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  select * into v_round
  from public.rocket_crash_global_rounds
  where id = p_round_id for update;

  if v_round.id is null then raise exception 'round_not_found'; end if;

  -- Idempotent: already flying
  if v_round.status = 'flying' then
    return json_build_object(
      'flight_starts_at', extract(epoch from v_round.flight_starts_at) * 1000,
      'crash_multiplier', v_round.crash_multiplier,
      'server_now',       extract(epoch from v_now) * 1000
    );
  end if;

  if v_round.status = 'crashed' then raise exception 'round_already_crashed'; end if;

  -- Generate crash multiplier (same distribution as JS genCrash)
  v_rand := random();
  if v_rand < 0.04 then
    v_crash := 1.00;
  elsif v_rand < 0.08 then
    v_crash := round((1.00 + random() * 0.04)::numeric, 2);
  else
    v_crash := round(greatest(1.01, least(200.00, 0.96 / (1 - v_rand)))::numeric, 2);
  end if;

  update public.rocket_crash_global_rounds
  set status           = 'flying',
      flight_starts_at = v_now,
      crash_multiplier = v_crash
  where id = p_round_id;

  return json_build_object(
    'flight_starts_at', extract(epoch from v_now) * 1000,
    'crash_multiplier', v_crash,
    'server_now',       extract(epoch from v_now) * 1000
  );
end;
$$;


ALTER FUNCTION "public"."start_rocket_crash_flight"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_room_team_pk"("p_room_id" "uuid", "p_duration_seconds" integer, "p_auto_assign" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id  uuid := auth.uid();
  v_session_id uuid;
  v_session    public.room_team_pk_sessions;
  v_members    jsonb;
  v_mic_users  record;
  v_idx        integer := 0;
  v_team       text;
  v_mic_list   uuid[];
  v_mic_count  integer;
begin
  if v_caller_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_duration_seconds not in (300, 600, 1800) then
    raise exception 'invalid_duration — allowed: 300, 600, 1800 seconds';
  end if;

  if not public.is_room_manager(p_room_id, v_caller_id) then
    raise exception 'not_authorized';
  end if;

  if exists (
    select 1 from public.room_team_pk_sessions
    where room_id = p_room_id and status = 'active'
  ) then
    raise exception 'pk_already_active';
  end if;

  -- Create the session.
  insert into public.room_team_pk_sessions (
    room_id, created_by, duration_seconds, ends_at
  ) values (
    p_room_id,
    v_caller_id,
    p_duration_seconds,
    now() + make_interval(secs => p_duration_seconds)
  )
  returning * into v_session;

  v_session_id := v_session.id;

  -- Auto-assign mic members to teams if requested.
  if p_auto_assign then
    -- Collect current mic occupants (host + speaker), ordered by seat_number.
    select array_agg(user_id order by coalesce(seat_number, 999), user_id)
    into v_mic_list
    from public.room_members
    where room_id = p_room_id
      and role    in ('host', 'speaker')
      and left_at is null;

    v_mic_count := coalesce(array_length(v_mic_list, 1), 0);

    for i in 1..v_mic_count loop
      -- First half (ceil) → Team A, second half → Team B.
      v_team := case when i <= ceil(v_mic_count::numeric / 2) then 'a' else 'b' end;

      insert into public.room_team_pk_members (
        pk_session_id, room_id, user_id, seat_index, team, assigned_by
      )
      select
        v_session_id,
        p_room_id,
        v_mic_list[i],
        rm.seat_number,
        v_team,
        v_caller_id
      from public.room_members rm
      where rm.room_id = p_room_id
        and rm.user_id = v_mic_list[i]
        and rm.left_at is null
      on conflict (pk_session_id, user_id) do nothing;
    end loop;
  end if;

  -- Fetch members for return payload.
  select jsonb_agg(row_to_json(m))
  into v_members
  from public.room_team_pk_members m
  where m.pk_session_id = v_session_id;

  return jsonb_build_object(
    'session', row_to_json(v_session),
    'members', coalesce(v_members, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."start_room_team_pk"("p_room_id" "uuid", "p_duration_seconds" integer, "p_auto_assign" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_srood_blocks_play"("p_is_paid" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_vip_level  int  := 0;
  v_free_plays int;
  v_plays_used int  := 0;
  v_xp_today   int  := 0;
  v_play_date  date;
  v_coins_bal  bigint;
  v_bal_after  bigint;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select coalesce(vip_level, 0) into v_vip_level
  from public.profiles where id = v_user_id;

  v_free_plays := case
    when v_vip_level >= 3 then 6
    when v_vip_level = 2  then 5
    when v_vip_level = 1  then 4
    else 3
  end;

  -- upsert daily record
  insert into public.srood_blocks_daily_limits (user_id, play_date, plays_used, xp_earned)
  values (v_user_id, current_date, 0, 0)
  on conflict (user_id) do update
    set play_date  = case when srood_blocks_daily_limits.play_date < current_date then current_date else srood_blocks_daily_limits.play_date end,
        plays_used = case when srood_blocks_daily_limits.play_date < current_date then 0            else srood_blocks_daily_limits.plays_used end,
        xp_earned  = case when srood_blocks_daily_limits.play_date < current_date then 0            else srood_blocks_daily_limits.xp_earned end,
        updated_at = now();

  select plays_used, xp_earned, play_date
  into v_plays_used, v_xp_today, v_play_date
  from public.srood_blocks_daily_limits where user_id = v_user_id;

  if p_is_paid then
    -- deduct 50 coins
    select coalesce(coins_balance, 0) into v_coins_bal
    from public.wallets where user_id = v_user_id;

    if v_coins_bal < 50 then
      raise exception 'insufficient_coins';
    end if;

    update public.wallets
    set coins_balance          = coins_balance - 50,
        lifetime_coins_spent   = coalesce(lifetime_coins_spent, 0) + 50,
        updated_at             = now()
    where user_id = v_user_id
    returning coins_balance into v_bal_after;

    insert into public.wallet_transactions
      (user_id, type, direction, coins_delta, diamonds_delta, note, metadata)
    values
      (v_user_id, 'blocks_play', 'debit', -50, 0, 'Srood Blocks extra play',
       jsonb_build_object('is_paid', true));
  else
    if v_plays_used >= v_free_plays then
      raise exception 'no_free_plays_left';
    end if;

    update public.srood_blocks_daily_limits
    set plays_used = plays_used + 1, updated_at = now()
    where user_id = v_user_id;
  end if;

  -- record active play
  insert into public.srood_blocks_active_plays (user_id, started_at, is_paid)
  values (v_user_id, now(), p_is_paid)
  on conflict (user_id) do update set started_at = now(), is_paid = p_is_paid;

  return jsonb_build_object('ok', true, 'is_paid', p_is_paid);
end;
$$;


ALTER FUNCTION "public"."start_srood_blocks_play"("p_is_paid" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_room_music"("p_room_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_state public.room_music_state;
  v_controller_active boolean := false;
  v_result json;
begin
  if v_uid is null then raise exception 'unauthenticated'; end if;

  select *
  into v_state
  from public.room_music_state
  where room_id = p_room_id
  for update;

  if v_state.id is null or v_state.controller_user_id is null then
    return json_build_object(
      'room_id', p_room_id, 'is_playing', false,
      'track_id', null, 'controller_user_id', null, 'updated_at', now()
    );
  end if;

  select exists (
    select 1
    from public.room_members rm
    where rm.room_id = p_room_id
      and rm.user_id = v_state.controller_user_id
      and rm.left_at is null
  ) into v_controller_active;

  if v_state.controller_user_id <> v_uid
     and not public.is_super_admin(v_uid)
     and not (
       not v_controller_active
       and public.is_room_manager(p_room_id, v_uid)
     ) then
    raise exception 'not_music_controller';
  end if;

  update public.room_music_state
  set is_playing = false,
      started_at = null,
      paused_at = null,
      position_seconds = 0,
      track_id = null,
      track_title = null,
      track_artist = null,
      track_url = null,
      controller_user_id = null,
      auto_replay = false,
      updated_by = v_uid,
      updated_at = now()
  where room_id = p_room_id
  returning to_json(room_music_state.*) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."stop_room_music"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_room_youtube"("p_room_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not public._room_youtube_is_manager(p_room_id) then
    raise exception 'room_youtube_not_allowed';
  end if;

  update public.room_youtube_state
  set is_playing = false,
      started_at = null,
      updated_at = now()
  where room_id = p_room_id
  returning to_jsonb(room_youtube_state.*) into v_result;

  return coalesce(v_result, jsonb_build_object('room_id', p_room_id, 'is_playing', false));
end;
$$;


ALTER FUNCTION "public"."stop_room_youtube"("p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stop_room_youtube"("p_room_id" "uuid", "p_clear" boolean DEFAULT false, "p_position_seconds" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_controller_name text;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not public._room_youtube_is_manager(p_room_id) then
    raise exception 'room_youtube_not_allowed';
  end if;

  if not public._room_video_mode_vip_allowed(v_uid) then
    raise exception 'room_youtube_vip6_required';
  end if;

  select coalesce(nullif(trim(p.display_name), ''), nullif(trim(p.username), ''), 'Host')
    into v_controller_name
  from public.profiles p
  where p.id = v_uid;

  update public.room_youtube_state
  set video_id = case when coalesce(p_clear, false) then null else video_id end,
      video_url = case when coalesce(p_clear, false) then null else video_url end,
      title = case when coalesce(p_clear, false) then null else title end,
      thumbnail_url = case when coalesce(p_clear, false) then null else thumbnail_url end,
      is_playing = false,
      started_at = null,
      position_seconds = case when coalesce(p_clear, false) then 0 else greatest(coalesce(p_position_seconds, 0), 0) end,
      controlled_by_user_id = v_uid,
      controlled_by_name = coalesce(v_controller_name, 'Host'),
      last_action = case when coalesce(p_clear, false) then 'clear' else 'stop' end,
      updated_at = now()
  where room_id = p_room_id
  returning to_jsonb(room_youtube_state.*) into v_result;

  return coalesce(
    v_result,
    jsonb_build_object(
      'room_id', p_room_id,
      'is_playing', false,
      'last_action', case when coalesce(p_clear, false) then 'clear' else 'stop' end,
      'updated_at', now()
    )
  );
end;
$$;


ALTER FUNCTION "public"."stop_room_youtube"("p_room_id" "uuid", "p_clear" boolean, "p_position_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_srood_blocks_score"("p_score" integer, "p_lines" integer, "p_level" integer, "p_duration_sec" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id   uuid := auth.uid();
  v_started   timestamptz;
  v_is_paid   boolean;
  v_xp_today  int := 0;
  v_xp_cap    int := 100;
  v_xp_earn   int := 0;
  v_xp_avail  int;
  v_week_start date;
  v_play_date  date;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  -- must have an active play session
  select started_at, is_paid into v_started, v_is_paid
  from public.srood_blocks_active_plays where user_id = v_user_id;

  if v_started is null then
    raise exception 'no_active_play';
  end if;

  -- server-side min duration check
  if p_duration_sec < 30 then
    raise exception 'play_too_short';
  end if;

  -- sanity: score can't exceed ~40 points/line * 10 lines/s * duration
  if p_score > (p_duration_sec * 400) then
    raise exception 'score_rejected';
  end if;

  -- week start (Monday)
  v_week_start := date_trunc('week', current_date)::date;

  -- XP calculation
  -- base: 5 XP per play
  -- milestones: +5 per score milestone (100/250/500/1000/2500/5000)
  v_xp_earn := 5;
  if p_score >=  100 then v_xp_earn := v_xp_earn + 5; end if;
  if p_score >=  250 then v_xp_earn := v_xp_earn + 5; end if;
  if p_score >=  500 then v_xp_earn := v_xp_earn + 5; end if;
  if p_score >= 1000 then v_xp_earn := v_xp_earn + 10; end if;
  if p_score >= 2500 then v_xp_earn := v_xp_earn + 10; end if;
  if p_score >= 5000 then v_xp_earn := v_xp_earn + 10; end if;

  -- cap by daily remaining
  select coalesce(xp_earned, 0), coalesce(play_date, current_date)
  into v_xp_today, v_play_date
  from public.srood_blocks_daily_limits where user_id = v_user_id;

  if v_play_date < current_date then v_xp_today := 0; end if;

  v_xp_avail := greatest(0, v_xp_cap - v_xp_today);
  v_xp_earn  := least(v_xp_earn, v_xp_avail);

  -- save score
  insert into public.srood_blocks_scores
    (user_id, score, lines_cleared, level, duration_sec, xp_earned, week_start)
  values
    (v_user_id, p_score, p_lines, p_level, p_duration_sec, v_xp_earn, v_week_start);

  -- update daily XP
  update public.srood_blocks_daily_limits
  set xp_earned  = case when play_date < current_date then v_xp_earn else xp_earned + v_xp_earn end,
      play_date  = current_date,
      updated_at = now()
  where user_id = v_user_id;

  -- award XP via existing system
  if v_xp_earn > 0 then
    perform public.add_user_xp(v_user_id, v_xp_earn, 'srood_blocks');
  end if;

  -- clear active play
  delete from public.srood_blocks_active_plays where user_id = v_user_id;

  return jsonb_build_object(
    'ok',       true,
    'xp_earned', v_xp_earn,
    'score',     p_score
  );
end;
$$;


ALTER FUNCTION "public"."submit_srood_blocks_score"("p_score" integer, "p_lines" integer, "p_level" integer, "p_duration_sec" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_user_report_with_evidence"("p_reported_user_id" "uuid", "p_room_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'other'::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reporter_id           uuid    := auth.uid();
  v_report_id             uuid;
  v_msg                   record;
  v_sender_name           text;

  -- Trusted room context — read from DB, never from client
  v_reported_role         text;
  v_reported_seat         integer;
  v_reported_is_muted     boolean;
  v_reported_force_muted  boolean;
  v_reported_is_mod       boolean := false;
  v_reported_is_owner     boolean := false;
  v_reporter_role         text;
begin
  if v_reporter_id is null then
    raise exception 'auth_required';
  end if;

  if v_reporter_id = p_reported_user_id then
    raise exception 'cannot_report_self';
  end if;

  -- Rate-limit: max 5 reports per user per hour
  if (
    select count(*) from public.user_reports
    where  reporter_id = v_reporter_id
      and  created_at >= now() - interval '1 hour'
  ) >= 5 then
    raise exception 'rate_limited: max 5 reports per hour';
  end if;

  -- ── Trusted room context snapshot ───────────────────────────────────────────
  if p_room_id is not null then
    -- Reported user's active room_members row
    select role, seat_number, is_muted, force_muted
    into   v_reported_role, v_reported_seat, v_reported_is_muted, v_reported_force_muted
    from   public.room_members
    where  room_id = p_room_id
      and  user_id = p_reported_user_id
      and  left_at is null;

    -- Reporter's active role
    select role
    into   v_reporter_role
    from   public.room_members
    where  room_id = p_room_id
      and  user_id = v_reporter_id
      and  left_at is null;

    -- Whether reported user is a room moderator
    select exists(
      select 1 from public.room_moderators
      where  room_id = p_room_id
        and  user_id = p_reported_user_id
    ) into v_reported_is_mod;

    -- Whether reported user is the room owner
    select (owner_id = p_reported_user_id)
    into   v_reported_is_owner
    from   public.rooms
    where  id = p_room_id;
  end if;

  -- Insert the report
  insert into public.user_reports
    (reporter_id, target_type, target_id, reason, details)
  values
    (v_reporter_id, 'user', p_reported_user_id::text, p_reason, p_description)
  returning id into v_report_id;

  -- Capture last 10 room messages as evidence (server-side only)
  if p_room_id is not null then
    for v_msg in (
      select rm.id, rm.sender_id, rm.message, rm.created_at
      from   public.room_messages rm
      where  rm.room_id = p_room_id
        and  rm.created_at <= now()
      order  by rm.created_at desc
      limit  10
    ) loop
      select coalesce(p.display_name, p.username, null)
      into   v_sender_name
      from   public.profiles p
      where  p.id = v_msg.sender_id;

      insert into public.moderation_report_evidence
        (report_id, room_id, reporter_id, reported_user_id,
         evidence_type, message_id, sender_id, sender_display_name,
         message_text, message_created_at, is_reported_user,
         metadata)
      values
        (v_report_id, p_room_id, v_reporter_id, p_reported_user_id,
         'chat_snapshot', v_msg.id, v_msg.sender_id, v_sender_name,
         v_msg.message, v_msg.created_at,
         (v_msg.sender_id = p_reported_user_id),
         jsonb_build_object(
           -- Report content
           'report_reason',           p_reason,
           'report_description',      p_description,
           -- Reported user context (trusted server-side)
           'reported_role',           v_reported_role,
           'reported_seat_number',    v_reported_seat,
           'reported_is_muted',       v_reported_is_muted,
           'reported_force_muted',    v_reported_force_muted,
           'reported_is_moderator',   v_reported_is_mod,
           'reported_is_owner',       v_reported_is_owner,
           -- Reporter context
           'reporter_role',           v_reporter_role
         ));
    end loop;
  end if;

  return v_report_id;
end;
$$;


ALTER FUNCTION "public"."submit_user_report_with_evidence"("p_reported_user_id" "uuid", "p_room_id" "uuid", "p_reason" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_adjust_wealth_xp"("p_target_user_id" "uuid", "p_action" "text", "p_amount" bigint, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id  uuid := auth.uid();
  v_xp_before bigint;
  v_xp_after  bigint;
BEGIN
  -- Permission gate: o_super_admin only.
  IF NOT public.is_o_super_admin() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF p_action NOT IN ('add', 'remove') THEN
    RAISE EXCEPTION 'invalid_action: must be add or remove';
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount: must be positive';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  -- Read current XP (0 if no row yet).
  SELECT COALESCE(wealth_xp, 0)
    INTO v_xp_before
    FROM public.user_wealth
   WHERE user_id = p_target_user_id;

  v_xp_before := COALESCE(v_xp_before, 0);

  IF p_action = 'add' THEN
    v_xp_after := v_xp_before + p_amount;
  ELSE
    v_xp_after := GREATEST(0, v_xp_before - p_amount);
  END IF;

  -- Upsert user_wealth with recalculated level.
  INSERT INTO public.user_wealth (user_id, wealth_xp, wealth_level, tier_number, updated_at)
  VALUES (
    p_target_user_id,
    v_xp_after,
    COALESCE((
      SELECT level FROM public.wealth_level_rules
       WHERE required_xp <= v_xp_after AND is_active = true
       ORDER BY required_xp DESC LIMIT 1
    ), 1),
    COALESCE((
      SELECT tier_number FROM public.wealth_level_rules
       WHERE required_xp <= v_xp_after AND is_active = true
       ORDER BY required_xp DESC LIMIT 1
    ), 1),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
    SET wealth_xp    = EXCLUDED.wealth_xp,
        wealth_level = EXCLUDED.wealth_level,
        tier_number  = EXCLUDED.tier_number,
        updated_at   = now();

  -- Write audit row.
  INSERT INTO public.wealth_admin_adjustments
    (admin_user_id, target_user_id, action, amount, xp_before, xp_after, reason)
  VALUES
    (v_admin_id, p_target_user_id, p_action, p_amount, v_xp_before, v_xp_after, trim(p_reason));
END;
$$;


ALTER FUNCTION "public"."super_admin_adjust_wealth_xp"("p_target_user_id" "uuid", "p_action" "text", "p_amount" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."super_admin_set_wealth_xp"("p_target_user_id" "uuid", "p_xp" bigint, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id  uuid := auth.uid();
  v_xp_before bigint;
  v_xp_after  bigint;
BEGIN
  IF NOT public.is_o_super_admin() THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF p_xp < 0 THEN
    RAISE EXCEPTION 'invalid_amount: xp cannot be negative';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  SELECT COALESCE(wealth_xp, 0)
    INTO v_xp_before
    FROM public.user_wealth
   WHERE user_id = p_target_user_id;

  v_xp_before := COALESCE(v_xp_before, 0);
  v_xp_after  := p_xp;

  INSERT INTO public.user_wealth (user_id, wealth_xp, wealth_level, tier_number, updated_at)
  VALUES (
    p_target_user_id,
    v_xp_after,
    COALESCE((
      SELECT level FROM public.wealth_level_rules
       WHERE required_xp <= v_xp_after AND is_active = true
       ORDER BY required_xp DESC LIMIT 1
    ), 1),
    COALESCE((
      SELECT tier_number FROM public.wealth_level_rules
       WHERE required_xp <= v_xp_after AND is_active = true
       ORDER BY required_xp DESC LIMIT 1
    ), 1),
    now()
  )
  ON CONFLICT (user_id) DO UPDATE
    SET wealth_xp    = EXCLUDED.wealth_xp,
        wealth_level = EXCLUDED.wealth_level,
        tier_number  = EXCLUDED.tier_number,
        updated_at   = now();

  INSERT INTO public.wealth_admin_adjustments
    (admin_user_id, target_user_id, action, amount, xp_before, xp_after, reason)
  VALUES
    (v_admin_id, p_target_user_id, 'set', v_xp_after, v_xp_before, v_xp_after, trim(p_reason));
END;
$$;


ALTER FUNCTION "public"."super_admin_set_wealth_xp"("p_target_user_id" "uuid", "p_xp" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_charm_xp_on_gift"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.receiver_id is not null and coalesce(new.total_cost_coins, 0) >= 10 then
    begin
      perform public.add_charm_xp(new.receiver_id, (new.total_cost_coins / 10)::bigint);
    exception when others then
      null; -- never break gifting
    end;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."tg_charm_xp_on_gift"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_room_seat_closed"("p_room_id" "uuid", "p_seat_number" integer) RETURNS integer[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller      uuid := auth.uid();
  v_owner_id    uuid;
  v_max_seats   integer;
  v_is_closed   boolean;
  v_closed_arr  integer[];
  v_is_mod      boolean;
  v_currently_closed boolean;
begin
  if v_caller is null then
    raise exception 'not_authenticated';
  end if;

  select owner_id, max_seats, is_closed
  into   v_owner_id, v_max_seats, v_is_closed
  from   public.rooms
  where  id = p_room_id;

  if v_owner_id is null then
    raise exception 'room_not_found';
  end if;

  if v_is_closed then
    raise exception 'room_closed';
  end if;

  if p_seat_number < 1 or p_seat_number > v_max_seats then
    raise exception 'invalid_seat_number';
  end if;

  -- Permission check: owner or active moderator.
  if v_caller != v_owner_id then
    select exists(
      select 1 from public.room_moderators
      where  room_id = p_room_id
        and  user_id = v_caller
    ) into v_is_mod;

    if not v_is_mod then
      raise exception 'not_authorized';
    end if;
  end if;

  -- Determine whether seat is currently in the closed list.
  select closed_seats
  into   v_closed_arr
  from   public.rooms
  where  id = p_room_id;

  v_closed_arr := coalesce(v_closed_arr, '{}');
  v_currently_closed := p_seat_number = any(v_closed_arr);

  if v_currently_closed then
    -- Re-open: remove from array.
    v_closed_arr := array_remove(v_closed_arr, p_seat_number);
  else
    -- Close: add to array, evict any current occupant of this seat.
    update public.room_members
    set    role        = 'listener',
           seat_number = null,
           updated_at  = now()
    where  room_id     = p_room_id
      and  seat_number = p_seat_number
      and  left_at     is null;

    v_closed_arr := array_append(v_closed_arr, p_seat_number);
  end if;

  -- Persist updated array.
  update public.rooms
  set    closed_seats = v_closed_arr,
         updated_at   = now()
  where  id = p_room_id
  returning closed_seats into v_closed_arr;

  return v_closed_arr;
end;
$$;


