CREATE OR REPLACE FUNCTION "public"."update_my_profile"("p_username" "text", "p_display_name" "text", "p_date_of_birth" "text", "p_bio" "text", "p_country" "text", "p_gender" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_row public.profiles;
  v_new_country text := nullif(trim(coalesce(p_country, '')), '');
  v_new_gender  text := nullif(trim(coalesce(p_gender,  '')), '');
  v_dob         date;
  v_set_country boolean := false;
  v_set_gender  boolean := false;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_row from public.profiles where id = v_uid for update;
  if not found then raise exception 'profile_not_found'; end if;

  -- Parse optional date of birth.
  begin
    v_dob := nullif(trim(coalesce(p_date_of_birth, '')), '')::date;
  exception when others then
    v_dob := v_row.date_of_birth; -- keep existing on bad input
  end;

  -- Gender: consume the one allowed change only when it actually differs.
  if v_new_gender is distinct from v_row.gender then
    if v_row.gender_changed_once then
      raise exception 'gender_locked';
    end if;
    v_set_gender := true;
  end if;

  -- Country: same rule.
  if v_new_country is distinct from v_row.country then
    if v_row.country_changed_once then
      raise exception 'country_locked';
    end if;
    v_set_country := true;
  end if;

  update public.profiles set
    username      = coalesce(nullif(trim(coalesce(p_username, '')), ''),
                             nullif(trim(coalesce(p_display_name, '')), ''),
                             username),
    display_name  = coalesce(nullif(trim(coalesce(p_display_name, '')), ''), display_name),
    date_of_birth = v_dob,
    bio           = nullif(trim(coalesce(p_bio, '')), ''),
    country       = case when v_set_country then v_new_country else country end,
    gender        = case when v_set_gender  then v_new_gender  else gender  end,
    country_changed_once = case when v_set_country then true  else country_changed_once end,
    country_changed_at   = case when v_set_country then now() else country_changed_at end,
    gender_changed_once  = case when v_set_gender  then true  else gender_changed_once end,
    gender_changed_at    = case when v_set_gender  then now() else gender_changed_at end,
    updated_at = now()
  where id = v_uid
  returning * into v_row;

  return jsonb_build_object(
    'gender',               v_row.gender,
    'country',              v_row.country,
    'gender_changed_once',  v_row.gender_changed_once,
    'country_changed_once', v_row.country_changed_once
  );
end;
$$;


ALTER FUNCTION "public"."update_my_profile"("p_username" "text", "p_display_name" "text", "p_date_of_birth" "text", "p_bio" "text", "p_country" "text", "p_gender" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_my_profile"("p_username" "text", "p_display_name" "text", "p_date_of_birth" "text", "p_bio" "text", "p_country" "text", "p_gender" "text", "p_country_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid         uuid := auth.uid();
  v_row         public.profiles;
  v_new_country text := nullif(trim(coalesce(p_country, '')), '');
  v_new_country_code text := nullif(trim(upper(coalesce(p_country_code, ''))), '');
  v_new_gender  text := nullif(trim(coalesce(p_gender,  '')), '');
  v_dob         date;
  v_set_country boolean := false;
  v_set_gender  boolean := false;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  select * into v_row from public.profiles where id = v_uid for update;
  if not found then raise exception 'profile_not_found'; end if;

  begin
    v_dob := nullif(trim(coalesce(p_date_of_birth, '')), '')::date;
  exception when others then
    v_dob := v_row.date_of_birth;
  end;

  if v_new_gender is distinct from v_row.gender then
    if v_row.gender_changed_once then
      raise exception 'gender_locked';
    end if;
    v_set_gender := true;
  end if;

  if v_new_country is distinct from v_row.country then
    if v_row.country_changed_once then
      raise exception 'country_locked';
    end if;
    v_set_country := true;
  end if;

  update public.profiles set
    username      = coalesce(nullif(trim(coalesce(p_username, '')), ''),
                             nullif(trim(coalesce(p_display_name, '')), ''),
                             username),
    display_name  = coalesce(nullif(trim(coalesce(p_display_name, '')), ''), display_name),
    date_of_birth = v_dob,
    bio           = nullif(trim(coalesce(p_bio, '')), ''),
    country       = case when v_set_country then v_new_country      else country      end,
    country_code  = case when v_set_country then v_new_country_code else country_code end,
    gender        = case when v_set_gender  then v_new_gender        else gender       end,
    country_changed_once = case when v_set_country then true  else country_changed_once end,
    country_changed_at   = case when v_set_country then now() else country_changed_at end,
    gender_changed_once  = case when v_set_gender  then true  else gender_changed_once end,
    gender_changed_at    = case when v_set_gender  then now() else gender_changed_at end,
    updated_at = now()
  where id = v_uid
  returning * into v_row;

  return jsonb_build_object(
    'gender',               v_row.gender,
    'country',              v_row.country,
    'country_code',         v_row.country_code,
    'gender_changed_once',  v_row.gender_changed_once,
    'country_changed_once', v_row.country_changed_once
  );
end;
$$;


ALTER FUNCTION "public"."update_my_profile"("p_username" "text", "p_display_name" "text", "p_date_of_birth" "text", "p_bio" "text", "p_country" "text", "p_gender" "text", "p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_room_member_role"("p_room_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_seat_number" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_room record;
begin
  if v_caller_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_role not in ('speaker', 'listener') then
    raise exception 'invalid_role';
  end if;

  -- Verify room exists and caller is the owner
  select id, owner_id into v_room
  from public.rooms
  where id = p_room_id;

  if v_room is null then
    raise exception 'room_not_found';
  end if;

  if v_room.owner_id != v_caller_id then
    raise exception 'not_room_owner';
  end if;

  -- Verify target member exists in room
  if not exists (
    select 1 from public.room_members
    where room_id = p_room_id
      and user_id = p_user_id
      and left_at is null
  ) then
    raise exception 'member_not_in_room';
  end if;

  -- Update member role and seat if needed
  update public.room_members
  set role = p_role,
      seat_number = case when p_role = 'speaker' then p_seat_number else null end,
      updated_at = now()
  where room_id = p_room_id
    and user_id = p_user_id;
end;
$$;


ALTER FUNCTION "public"."update_room_member_role"("p_room_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_seat_number" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_room_member_role"("p_room_id" "uuid", "p_user_id" "uuid", "p_role" "text", "p_seat_number" integer) IS 'Safe RPC function for room owners to update member roles. Verifies room ownership before proceeding. Always use this instead of direct UPDATE.';



CREATE OR REPLACE FUNCTION "public"."update_room_member_seat"("p_room_id" "uuid", "p_user_id" "uuid", "p_seat_number" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_room record;
begin
  if v_caller_id is null then
    raise exception 'not_authenticated';
  end if;

  -- Verify room exists and caller is the owner
  select id, owner_id into v_room
  from public.rooms
  where id = p_room_id;

  if v_room is null then
    raise exception 'room_not_found';
  end if;

  if v_room.owner_id != v_caller_id then
    raise exception 'not_room_owner';
  end if;

  -- Verify target member exists in room
  if not exists (
    select 1 from public.room_members
    where room_id = p_room_id
      and user_id = p_user_id
      and left_at is null
  ) then
    raise exception 'member_not_in_room';
  end if;

  -- Update seat number
  update public.room_members
  set seat_number = p_seat_number,
      updated_at = now()
  where room_id = p_room_id
    and user_id = p_user_id;
end;
$$;


