COMMENT ON FUNCTION "public"."update_room_member_seat"("p_room_id" "uuid", "p_user_id" "uuid", "p_seat_number" integer) IS 'Safe RPC function for room owners to update member seat positions. Verifies room ownership before proceeding. Always use this instead of direct UPDATE.';



CREATE OR REPLACE FUNCTION "public"."update_room_streaks"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Reset daily passive cap counters for all rooms
  update public.rooms set xp_today_gift = 0, xp_today_passive = 0;

  -- Streak: active yesterday → increment, otherwise reset
  update public.rooms set
    daily_streak = case
      when last_active_date = current_date - 1 then daily_streak + 1
      when last_active_date = current_date     then daily_streak  -- already ran today
      else 0
    end,
    streak_multiplier = case
      when last_active_date = current_date - 1 then
        case
          when daily_streak + 1 >= 30 then 2.00
          when daily_streak + 1 >= 14 then 1.50
          when daily_streak + 1 >= 7  then 1.25
          when daily_streak + 1 >= 3  then 1.10
          else 1.00
        end
      when last_active_date = current_date then streak_multiplier
      else 1.00
    end
  where last_active_date is not null;
end;
$$;


ALTER FUNCTION "public"."update_room_streaks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_push_token"("p_token" "text", "p_platform" "text" DEFAULT 'android'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  p_token := trim(coalesce(p_token, ''));
  if p_token = '' or length(p_token) > 4096 then
    raise exception 'invalid_token';
  end if;

  if p_platform not in ('android', 'ios', 'web') then
    p_platform := 'android';
  end if;

  insert into public.user_push_tokens (
    user_id,
    token,
    platform,
    last_seen_at,
    is_active,
    invalidated_at
  )
  values (
    v_uid,
    p_token,
    p_platform,
    now(),
    true,
    null
  )
  on conflict (token) do update
    set user_id       = excluded.user_id,
        platform      = excluded.platform,
        last_seen_at  = now(),
        updated_at    = now(),
        is_active     = true,
        invalidated_at = null;
end;
$$;


ALTER FUNCTION "public"."upsert_push_token"("p_token" "text", "p_platform" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_gold_ladder_power"("p_run_id" "uuid", "p_question_id" "uuid", "p_power_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id    uuid := auth.uid();
  v_run        public.gold_ladder_runs;
  v_correct    char(1);
  v_wrong_opts text[];
  v_elim       text[];
  v_total      integer;
  v_dist       jsonb;
  v_pcts       integer[] := array[0,0,0,0];
  v_remainder  integer;
  v_correct_idx integer;
  v_opts       text[] := array['a','b','c','d'];
  i            integer;
begin
  if v_user_id is null then raise exception 'not_authenticated'; end if;

  if p_power_type not in ('remove_two','crowd_pulse','second_chance') then
    raise exception 'invalid_power_type';
  end if;

  select * into v_run
  from public.gold_ladder_runs
  where id = p_run_id and user_id = v_user_id
  for update;

  if not found then raise exception 'run_not_found'; end if;
  if v_run.status != 'active' then raise exception 'run_not_active'; end if;

  if v_run.question_ids[v_run.current_question_num] != p_question_id then
    raise exception 'wrong_question';
  end if;

  -- Check power available
  if coalesce((v_run.powers_remaining->>p_power_type)::integer, 0) < 1 then
    raise exception 'power_not_available';
  end if;

  -- Deduct power
  update public.gold_ladder_runs
  set powers_remaining = jsonb_set(
    powers_remaining,
    array[p_power_type],
    to_jsonb(coalesce((powers_remaining->>p_power_type)::integer, 1) - 1)
  )
  where id = p_run_id;

  select correct_option into v_correct
  from public.gold_ladder_questions where id = p_question_id;

  if p_power_type = 'remove_two' then
    -- Pick 2 of the 3 wrong options to eliminate
    select array_agg(opt order by random()) into v_elim
    from unnest(v_opts) as opt
    where opt != v_correct
    limit 2;

    return jsonb_build_object(
      'power_type',       'remove_two',
      'eliminated_options', to_jsonb(v_elim)
    );

  elsif p_power_type = 'crowd_pulse' then
    -- Give correct answer ~50-70% of the audience, spread rest randomly
    v_correct_idx := array_position(v_opts, v_correct::text);

    -- Correct: 50-70%
    v_pcts[v_correct_idx] := 50 + floor(random() * 21)::integer;
    v_remainder := 100 - v_pcts[v_correct_idx];

    -- Distribute remainder across the other 3 options
    declare
      v_split1 integer := floor(random() * (v_remainder - 3))::integer + 1;
      v_split2 integer := floor(random() * (v_remainder - v_split1 - 2))::integer + 1;
      v_split3 integer := v_remainder - v_split1 - v_split2;
      v_others integer[] := array[]::integer[];
      j integer;
    begin
      v_others := array[v_split1, v_split2, v_split3];
      j := 1;
      for i in 1..4 loop
        if i != v_correct_idx then
          v_pcts[i] := v_others[j];
          j := j + 1;
        end if;
      end loop;
    end;

    return jsonb_build_object(
      'power_type', 'crowd_pulse',
      'distribution', jsonb_build_object(
        'a', v_pcts[1],
        'b', v_pcts[2],
        'c', v_pcts[3],
        'd', v_pcts[4]
      )
    );

  else -- second_chance
    update public.gold_ladder_runs
    set second_chance_active = true
    where id = p_run_id;

    return jsonb_build_object(
      'power_type', 'second_chance',
      'confirmed',  true
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."use_gold_ladder_power"("p_run_id" "uuid", "p_question_id" "uuid", "p_power_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_active_restriction"("p_restriction_type" "text", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.admin_user_restrictions r
    where r.user_id = coalesce(p_user_id, auth.uid())
      and r.restriction_type = lower(trim(p_restriction_type))
      and r.is_active
      and (r.expires_at is null or r.expires_at > now())
  );
$$;


