CREATE OR REPLACE FUNCTION "public"."verify_room_pin"("p_room_id" "uuid", "p_pin" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enabled boolean;
  v_hash    text;
BEGIN
  SELECT room_pin_enabled, room_pin_hash
  INTO   v_enabled, v_hash
  FROM   public.rooms
  WHERE  id = p_room_id;

  IF NOT FOUND OR NOT v_enabled OR v_hash IS NULL THEN
    RETURN true;
  END IF;

  RETURN v_hash = encode(sha256(convert_to(p_pin, 'UTF8')), 'hex');
END;
$$;


