CREATE OR REPLACE FUNCTION "public"."vip_privilege_active"("p_user_id" "uuid", "p_privilege" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $_$
declare
  v_result boolean;
begin
  execute format(
    'select coalesce(s.%I, false) from public.user_vip_settings s where s.user_id = $1',
    p_privilege
  )
  into v_result
  using p_user_id;
  return coalesce(v_result, false);
end;
$_$;


