CREATE OR REPLACE FUNCTION "public"."your_function_name"("p_bet_id" "uuid", "p_multiplier" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_bet record;
begin
  select *
  into v_bet
  from public.crash_bets
  where id = p_bet_id;

  if v_bet is null then
    raise exception 'Bet not found';
  end if;

  if p_multiplier > v_bet.crash_multiplier then
    raise exception 'Cashout multiplier is higher than crash multiplier';
  end if;

  -- your update here
  update public.crash_bets
  set
    cashout_multiplier = p_multiplier,
    status = 'cashed_out'
  where id = p_bet_id;
end;
$$;


