ALTER TABLE "public"."wealth_level_rules" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."withdrawal_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "diamonds" integer NOT NULL,
    "method" "text" NOT NULL,
    "account_details" "text" NOT NULL,
    "notes" "text",
    "gross_usd" numeric(12,2) DEFAULT 0 NOT NULL,
    "host_share_usd" numeric(12,2) DEFAULT 0 NOT NULL,
    "agency_share_usd" numeric(12,2) DEFAULT 0 NOT NULL,
    "platform_share_usd" numeric(12,2) DEFAULT 0 NOT NULL,
    "agency_id" "uuid",
    "agency_owner_user_id" "uuid",
    "agency_share_diamonds" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "admin_note" "text",
    "estimated_usd" numeric(12,2),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "processed_at" timestamp with time zone,
    "processed_by" "uuid",
    CONSTRAINT "withdrawal_requests_diamonds_check" CHECK (("diamonds" > 0)),
    CONSTRAINT "withdrawal_requests_method_check" CHECK (("method" = ANY (ARRAY['bank'::"text", 'paypal'::"text", 'wise'::"text"]))),
    CONSTRAINT "withdrawal_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text", 'paid'::"text"])))
);


ALTER TABLE "public"."withdrawal_requests" OWNER TO "postgres";


