-- ─────────────────────────────────────────────────────────────────────────────
-- [3] storage.objects RLS policies (27, verbatim from prod). Idempotent-guarded
--     so re-application does not error on an existing policy.
-- ─────────────────────────────────────────────────────────────────────────────
do $mig$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage.objects absent; skipping storage policies (validation env without storage)';
    return;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Authenticated users can update room backgrounds') then
    execute $pol$CREATE POLICY "Authenticated users can update room backgrounds" ON "storage"."objects" FOR UPDATE TO "authenticated" USING (("bucket_id" = 'room-backgrounds'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Authenticated users can upload room backgrounds') then
    execute $pol$CREATE POLICY "Authenticated users can upload room backgrounds" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK (("bucket_id" = 'room-backgrounds'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Avatar images are publicly readable') then
    execute $pol$CREATE POLICY "Avatar images are publicly readable" ON "storage"."objects" FOR SELECT TO "authenticated", "anon" USING (("bucket_id" = 'avatars'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Public read for room backgrounds') then
    execute $pol$CREATE POLICY "Public read for room backgrounds" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'room-backgrounds'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Public read room_music') then
    execute $pol$CREATE POLICY "Public read room_music" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'room_music'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Room music: authenticated can read') then
    execute $pol$CREATE POLICY "Room music: authenticated can read" ON "storage"."objects" FOR SELECT TO "authenticated" USING (("bucket_id" = 'room_music'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Room music: managers can insert') then
    execute $pol$CREATE POLICY "Room music: managers can insert" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'room_music'::"text") AND (("storage"."foldername"("name"))[1] = (( SELECT "auth"."uid"() AS "uid"))::"text") AND (COALESCE(("storage"."foldername"("name"))[2], ''::"text") ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'::"text") AND "public"."is_room_manager"((("storage"."foldername"("name"))[2])::"uuid", ( SELECT "auth"."uid"() AS "uid"))));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Room music: uploader can delete') then
    execute $pol$CREATE POLICY "Room music: uploader can delete" ON "storage"."objects" FOR DELETE TO "authenticated" USING ((("bucket_id" = 'room_music'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Room music: uploader can update') then
    execute $pol$CREATE POLICY "Room music: uploader can update" ON "storage"."objects" FOR UPDATE TO "authenticated" USING ((("bucket_id" = 'room_music'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Users can delete their own avatar') then
    execute $pol$CREATE POLICY "Users can delete their own avatar" ON "storage"."objects" FOR DELETE TO "authenticated" USING ((("bucket_id" = 'avatars'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Users can update their own avatar') then
    execute $pol$CREATE POLICY "Users can update their own avatar" ON "storage"."objects" FOR UPDATE TO "authenticated" USING ((("bucket_id" = 'avatars'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text"))) WITH CHECK ((("bucket_id" = 'avatars'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='Users can upload their own avatar') then
    execute $pol$CREATE POLICY "Users can upload their own avatar" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'avatars'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='admin_assets_delete') then
    execute $pol$CREATE POLICY "admin_assets_delete" ON "storage"."objects" FOR DELETE TO "authenticated" USING ((("bucket_id" = 'admin-assets'::"text") AND ("public"."has_app_role"('super_admin'::"text") OR "public"."has_app_role"('content_admin'::"text"))));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='admin_assets_insert') then
    execute $pol$CREATE POLICY "admin_assets_insert" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'admin-assets'::"text") AND ("public"."has_app_role"('super_admin'::"text") OR "public"."has_app_role"('content_admin'::"text"))));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='admin_assets_select') then
    execute $pol$CREATE POLICY "admin_assets_select" ON "storage"."objects" FOR SELECT TO "authenticated" USING (("bucket_id" = 'admin-assets'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='admin_assets_update') then
    execute $pol$CREATE POLICY "admin_assets_update" ON "storage"."objects" FOR UPDATE TO "authenticated" USING ((("bucket_id" = 'admin-assets'::"text") AND ("public"."has_app_role"('super_admin'::"text") OR "public"."has_app_role"('content_admin'::"text"))));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_avatars_delete') then
    execute $pol$CREATE POLICY "room_avatars_delete" ON "storage"."objects" FOR DELETE TO "authenticated" USING (("bucket_id" = 'room_avatars'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_avatars_insert') then
    execute $pol$CREATE POLICY "room_avatars_insert" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK (("bucket_id" = 'room_avatars'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_avatars_select') then
    execute $pol$CREATE POLICY "room_avatars_select" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'room_avatars'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_avatars_update') then
    execute $pol$CREATE POLICY "room_avatars_update" ON "storage"."objects" FOR UPDATE TO "authenticated" USING (("bucket_id" = 'room_avatars'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_chat_images_delete_own') then
    execute $pol$CREATE POLICY "room_chat_images_delete_own" ON "storage"."objects" FOR DELETE TO "authenticated" USING ((("bucket_id" = 'room_chat_images'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text")));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_chat_images_read') then
    execute $pol$CREATE POLICY "room_chat_images_read" ON "storage"."objects" FOR SELECT TO "authenticated", "anon" USING (("bucket_id" = 'room_chat_images'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_chat_images_upload_vip7') then
    execute $pol$CREATE POLICY "room_chat_images_upload_vip7" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK ((("bucket_id" = 'room_chat_images'::"text") AND (("storage"."foldername"("name"))[1] = ("auth"."uid"())::"text") AND "public"."can_user_send_chat_image"("auth"."uid"())));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_covers_delete') then
    execute $pol$CREATE POLICY "room_covers_delete" ON "storage"."objects" FOR DELETE TO "authenticated" USING (("bucket_id" = 'room_covers'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_covers_insert') then
    execute $pol$CREATE POLICY "room_covers_insert" ON "storage"."objects" FOR INSERT TO "authenticated" WITH CHECK (("bucket_id" = 'room_covers'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_covers_select') then
    execute $pol$CREATE POLICY "room_covers_select" ON "storage"."objects" FOR SELECT USING (("bucket_id" = 'room_covers'::"text"));$pol$;
  end if;
  if not exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='room_covers_update') then
    execute $pol$CREATE POLICY "room_covers_update" ON "storage"."objects" FOR UPDATE TO "authenticated" USING (("bucket_id" = 'room_covers'::"text"));$pol$;
  end if;
end $mig$;

-- ─────────────────────────────────────────────────────────────────────────────
-- [4] storage buckets + cron jobs + realtime publication (config rows)
--     Source of truth: 080_storage_cron.sql (exact prod values, idempotent).
-- ─────────────────────────────────────────────────────────────────────────────
-- ── 8 storage buckets (exact public/limit/mime config) ───────────────────────
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('admin-assets','admin-assets',true, null, null),
  ('app_releases','app_releases',true, 600000000, array['application/vnd.android.package-archive','application/octet-stream']),
  ('avatars','avatars',true, 5242880, array['image/jpeg','image/png','image/webp','image/gif']),
  ('room_avatars','room_avatars',true, 2097152, array['image/jpeg','image/png','image/webp']),
  ('room_chat_images','room_chat_images',true, 5242880, array['image/jpeg','image/png','image/webp','image/jpg']),
  ('room_covers','room_covers',true, 5242880, array['image/jpeg','image/png','image/webp']),
  ('room_music','room_music',true, 15728640, array['audio/mpeg','audio/mp3','audio/wav','audio/aac','audio/mp4','audio/m4a','audio/ogg']),
  ('room-backgrounds','room-backgrounds',true, 10485760, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;
-- Storage POLICIES are already reproduced verbatim by the schema dump (DDL);
-- none are added here to avoid duplication.

-- ── 5 cron jobs (exact name / schedule / command; active) ────────────────────
-- cron.schedule(name,...) upserts by name (no duplicates). Registration only —
-- it does NOT invoke the job functions during baseline application. Guarded so
-- it is a no-op when pg_cron is unavailable (e.g. bare validation container).
do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.schedule('cleanup-cron-history','0 3 1 * *',
      $cron$ delete from cron.job_run_details where start_time < now() - interval '90 days'; $cron$);
    perform cron.schedule('fish_hunt_auto_advance','5 seconds', $cron$ select public.advance_fish_hunt_round(); $cron$);
    perform cron.schedule('reset-room-streaks','0 0 * * *', $cron$ select public.update_room_streaks() $cron$);
    perform cron.schedule('reset-room-week-xp','5 0 * * 1', $cron$ select public.reset_room_weekly_xp() $cron$);
    perform cron.schedule('roulette_auto_advance','3 seconds', $cron$ select public.advance_roulette_round(); $cron$);
  else
    raise notice 'cron schema not present; skipping cron registration (validation env)';
  end if;
end $$;

-- ── Realtime publication membership (exact 25 public tables; no broadening) ───
-- The platform owns `supabase_realtime`; ensure it exists locally, then add ONLY
-- the exact production tables, skipping any already a member (no duplicate error).
do $$
declare v_tbl text;
begin
  if not exists (select 1 from pg_publication where pubname='supabase_realtime') then
    create publication supabase_realtime;  -- local validation only; platform provides in prod
  end if;
  foreach v_tbl in array array[
    'rooms','room_members','gift_transactions','wc_matches','wc_predictions','room_messages',
    'room_team_pk_sessions','room_team_pk_members','room_team_pk_support_logs','room_game_rounds',
    'room_game_bets','room_music_state','room_music_tracks','red_envelopes','red_envelope_claims',
    'hungry_cat_global_rounds','rocket_crash_global_rounds','user_wealth','room_reads',
    'magic_srood_global_rounds','fish_hunt_rounds','fish_hunt_fish','crash_rocket_rounds',
    'crash_rocket_round_events','room_youtube_state'
  ] loop
    if to_regclass('public.'||v_tbl) is not null
       and not exists (select 1 from pg_publication_tables
                       where pubname='supabase_realtime' and schemaname='public' and tablename=v_tbl) then
      execute format('alter publication supabase_realtime add table public.%I', v_tbl);
    end if;
  end loop;
end $$;
-- supabase_realtime_messages_publication is platform/realtime-managed
-- (realtime.messages_* partitions); intentionally NOT reproduced here.

